  \begin{scope}[shift={(#2)}, yscale={#3}]
    \coordinate (#1-left) at (-0.7,0.4);
    \coordinate (#1-right) at (0.7,0.4);
    \coordinate (#1-tip) at (0,-0.8);
    \ifthenelse{\equal{#4}{true}}{
