% An eraser
\newcommand{\eraser}[4]{
  \begin{scope}[shift={(#2)}, yscale={#3}]
    \def\r{0.3}
    \def\diag{1.41421356237*\r/2}
    \coordinate (#1-tip) at (0,-\r);
    \ifthenelse{\equal{#4}{true}}{
      \draw[line width=1.4pt] (0,0) circle (\r);
      \draw[line width=1.4pt] (\diag,\diag) --  (-\diag,-\diag);
      \draw[line width=1.4pt] (\diag,-\diag) --  (-\diag,\diag);
    }{false};
  \end{scope}
}

