\section{Preliminaries}
\begin{proposition}
    (Chernoff Inequality). Let \( G_1, \dots, G_m \) be independent (though not necessarily identically distributed) 1-subGaussian random variables. For any \( \delta \in (0,1) \), it holds that
    \begin{align*}
        \Pr \left[ \left|\frac{1}{m} \mathbb{E} \left[ \sum_{i=1}^{m} G_i \right] - \frac{1}{m} \sum_{i=1}^{m} G_i\right|\leq \sqrt{\frac{2 \log(k/\delta)}{m}} \right] \geq 1 - \frac{\delta}{k},
    \end{align*}
\end{proposition}
We consider an identifiable class of bandit models of the form:
\begin{equation}\label{instances}
    \mathcal{M}=\{v=(v_{1},v_{2},\ldots,v_{k}):v_{i}\in \mathcal{P},\mu^{\text{on}}(1)>\mu^{\text{on}}(2)\geq \ldots\geq \mu^{\text{on}}(k)\}
\end{equation}
For all instances in set $\mathcal{M}$, $I^{*}=1$. Let $\mathcal{A}=((\pi_{t}),\tau,\hat{I}^{*})$ be a $\delta$-PAC algorithm. 

Let $I_P = (P^{\mathrm{off}}, P^{\mathrm{on}})$ and $I_Q = (Q^{\mathrm{off}}, Q^{\mathrm{on}})$ be two problem instances defined over a common finite arm set $A$. Both instances share the same offline sample sizes $\{T_S(i)\}_{i\in A}$ and confidence level $\delta$, but may differ in their offline and online reward distributions. 
%For each arm $i$, let $N_S(i)$ be the (random) number of offline samples used during the algorithm, and 
Let $\tau_{\delta}(Q, i)$ be the (random) number of online samples drawn from arm $i$ under instance $I_Q$ before the stopping time $\tau_\delta$; we write $\mathbb{E}[\tau_{\delta}(Q, i)]$ for its expectation. The probability that an event $\mathcal{E}$ occurs under instance $I_Q$ and instance $I_P$ at stopping time $\sigma$ are written as $\mathbb{P}_{\sigma}(Q, \mathcal{E})$ and $\mathbb{P}_{\sigma}(P, \mathcal{E})$ respectively. The Kullback-Leibler (KL) divergence between distributions $P$ and $Q$ is written as $\mathrm{KL}(P, Q)$, and $d(p, q)$ denotes the KL divergence measure between Bernoulli distributions with means $p$ and $q$. We assume that the stopping time $\sigma$ is adapted to the filtration $\{\mathcal{F}_t\}_{t \geq 0}$ and is almost surely finite. To establish the theoretical results, we first introduce the following lemma.

\begin{lemma}\label{ChangeofDistribution}
Let $\mathcal{E} \in \mathcal{F}_\sigma$ be any event measurable with respect to the stopping time $\sigma$. For any non-anticipatory policy $\pi$, the following inequality holds:
\begin{align}
\sum_{i=1}^{k} \mathbb{E}[N_{\sigma}(i)] \, \mathrm{KL}\bigl(Q^{\mathrm{on}}(i), P^{\mathrm{on}}(i)\bigr) + \sum_{i=1}^{k} T_{S}(i)\, \mathrm{KL}\bigl(Q^{\mathrm{off}}(i), P^{\mathrm{off}}(i)\bigr) \geq d\bigl(\mathbb{P}_{\sigma}(Q, \mathcal{E}), \mathbb{P}_{\sigma}(P, \mathcal{E})\bigr).
\end{align}
\end{lemma}

\emph{Proof}:
The log-likelihood ratio for the sequence of observations observed by time $t$ under an algorithm $\mathcal{A}$ is
\begin{align*}
    L_{t}=L(\{X_{s}(i)\}_{s=1}^{T_{S}(i)}, A_{1},\ldots,A_{t}, Y_{A_{1}}, \ldots,Y_{A_{t}})\coloneqq\sum_{i=1}^{k}\sum_{l=1}^{t}\mathbbm{1}\{A_{l}=i\}\log\left(\frac{Q^{\mathrm{on}}_{i}(Y_{A_{l}})}{P^{\mathrm{on}}_{i}(Y_{A_{l}})}\right)+\sum_{i=1}^{k}\sum_{s=1}^{T_{S}(i)}\log\left(\frac{Q^{\mathrm{off}}_{i}(X_{s})}{P^{\mathrm{off}}_{i}(X_s)}\right).
\end{align*}
Recall that $\{X_{s}(i)\}_{s=1}^{T_{S}(i)}$ are i.i.d.\ samples from the offline distribution $P^{\mathrm{off}}_{i}$, while $\{Y_{l}(i)\}_{l=1}^{N_{\sigma}(i)}$ are i.i.d. samples from the online distribution $P^{\mathrm{on}}_{i}$. We can rewritten $L_{\sigma}$ as
\begin{align*}
    L_{\sigma}=\sum_{i=1}^{k}\sum_{l=1}^{N_{\sigma}(i)}\log\left(\frac{Q^{\mathrm{on}}_{i}(Y_{A_{l}})}{P^{\mathrm{on}}_{i}(Y_{A_{l}})}\right)+\sum_{i=1}^{k}\sum_{s=1}^{T_{S}(i)}\log\left(\frac{Q^{\mathrm{off}}_{i}(X_{s})}{P^{\mathrm{off}}_{i}(X_s)}\right).
\end{align*}
Since $\mathbb{E}_{Q}\left[\log\left(\frac{Q^{\mathrm{on}}_{i}(Y_{A_{l}})}{P^{\mathrm{on}}_{i}(Y_{A_{l}})}\right)\right]=\mathrm{KL}(Q^{\mathrm{on}}(i), P^{\mathrm{on}}(i))$ and $\mathbb{E}_{Q}\left[\log\left(\frac{Q^{\mathrm{off}}_{i}(X_{s})}{P^{\mathrm{off}}_{i}(X_s)}\right)\right]=\mathrm{KL}(Q^{\mathrm{off}}(i), P^{\mathrm{off}}(i))$, by Wald's Lemma \citep{wald2004sequential},
\begin{align}\label{ex}
    \mathbb{E}_{Q}[L_{\sigma}]=\sum_{i=1}^{k} \mathbb{E}[N_{\sigma}(i)] \, \mathrm{KL}\bigl(Q^{\mathrm{on}}(i), P^{\mathrm{on}}(i)\bigr) + \sum_{i=1}^{k} T_{S}(i)\, \mathrm{KL}\bigl(Q^{\mathrm{off}}(i), P^{\mathrm{off}}(i)\bigr).
\end{align}
By Lemma 19 in \citet{kaufmann2016complexity}, we have
\begin{align}\label{19}
    \mathbb{E}_{Q}[L_{\sigma}]\geq d\bigl(\mathbb{P}_{\sigma}(Q, \mathcal{E}), \mathbb{P}_{\sigma}(P, \mathcal{E})\bigr).
\end{align}
Combining (\ref{ex}) and (\ref{19}) completes the proof.

%Note that the offline KL term for arm $i$, i.e., $\mathrm{KL}(Q^{\mathrm{off}}(i), P^{\mathrm{off}}(i))$, contributes only when historical data is used for that arm. If no offline data is used in a given round, we denote $\mathrm{KL}(Q^{\mathrm{off}}(i), P^{\mathrm{off}}(i))=0$.


