\section{Proof of Theorem \ref{thm: 4.1}} \label{app:proof_ach}
To prove Theorem \ref{thm: 4.1}, we  first state a lemma.
\begin{lemma}\label{confidence}
    The following events hold over all rounds $t=1,2,\ldots$ with probability at least $1-\delta/k$ :
    $$\bigg|\min(\mathrm{UCB}_t^S(i), \mathrm{UCB}_{t}(i))-\mu^{\mathrm{on}}(i)\bigg|\leq  \min\bigg(2\sqrt{\frac{2 \log(kt /\delta)}{N_t(i) + T_S(i)}} + \frac{T_S(i)}{N_t(i) + T_S(i)}  \cdot \eta(i) , 2\sqrt{\frac{2 \log(kt /\delta)}{N_t(i)}}\bigg)$$ 
    and \\
    $$\bigg|\mu^{\mathrm{on}}(i)-\max(\mathrm{LCB}_t^S(i), \mathrm{LCB}_{t}(i))\bigg|\leq  \min\bigg(2\sqrt{\frac{2 \log(kt /\delta)}{N_t(i) + T_S(i)}} + \frac{T_S(i)}{N_t(i) + T_S(i)}  \cdot \eta(i) , 2\sqrt{\frac{2 \log(kt /\delta)}{N_t(i)}}\bigg).$$
\end{lemma}

\emph{Proof}:
To prove this Lemma, it suffices to prove that 
\begin{align*}
    \mathbb{P}\left\{ \mu^{(\mathrm{on})} (i) \leq \mathrm{UCB}_t^S (i) \leq \mu^{(\mathrm{on})} (i) + 2\sqrt{\frac{2 \log(k t/\delta)}{N_t(i) + T_S(i)}} + \frac{T_S(i)}{N_t(i) + T_S(i)}  \cdot \eta(i)  \right\}\geq 1-\frac{\delta}{kt}.
\end{align*}
Indeed, the inequality implies 
\begin{align*}
    \mathbb{P}\left\{ \mu^{(\mathrm{on})} (i) \leq \mathrm{UCB}_t^S (i) \leq \mu^{(\mathrm{on})} (i) + 2\sqrt{\frac{2 \log(kt /\delta)}{N_t(i) }}  \right\}\geq 1-\frac{\delta}{kt}
\end{align*}
by setting $T_{S}(i)=0$.
\begin{align*}
    &\mathbb{P}[\mu^{(\mathrm{on})}(i) \leq \mathrm{UCB}_t^S(i)] \\
    &= \mathbb{P} \left[ \mu^{(\mathrm{on})}(i) \leq \frac{N_t(i) \cdot \hat{Y}_t(i) + T_S(i) \cdot \hat{X}(i)}{N_t(i) + T_S(i)} + \sqrt{\frac{2\log(kt /\delta)}{N_t^+(i) + T_S(i)}} + \frac{T_S(i)}{N_t^+(i) + T_S(i)} \cdot V(i) \right] \\
    &= \mathbb{P} \left[ \frac{N_t(i) \mu^{(\mathrm{on})}(i) + T_S(i) \mu^{(\mathrm{off})}(i)}{N_t(i) + T_S(i)} 
   \frac{T_S(i)(\mu^{(\mathrm{on})}(i) - \mu^{(\mathrm{off})}(i))}{N_t(i) + T_S(i)} 
    \leq \frac{N_t(i) \cdot \hat{Y}_t(i) + T_S(i) \cdot \hat{X}(i)}{N_t(i) + T_S(i)} \right.\\
    &\quad\left. + \sqrt{\frac{2\log(kt /\delta)}{N_t(i) + T_S(i)}} + \frac{T_S(i)}{N_t(i) + T_S(i)} \cdot V(i) \right] \\
    &\geq  \mathbb{P} \left[ \frac{N_t(i) \mu^{(\mathrm{on})}(i) + T_S(i) \mu^{(\mathrm{off})}(i)}{N_t(i) + T_S(i)} 
     \leq \frac{N_t(i) \cdot \hat{Y}_t(i) + T_S(i) \cdot \hat{X}(i)}{N_t(i) + T_S(i)} 
    + \sqrt{\frac{2\log(kt /\delta)}{N_t(i) + T_S(i)}} \right] \\
    &\geq \mathbb{P}_{Y_i \sim P^{(\mathrm{on})}(i)} \left[ \frac{n \mu^{(\mathrm{on})}(i) + T_S(i) \mu^{(\mathrm{off})}(i)}{n + T_S(i)} 
   \leq \frac{\sum_{i=1}^{n} Y_i + T_S(i) \cdot \hat{X}(i)}{n + T_S(i)} 
     + \sqrt{\frac{2\log(kt /\delta)}{n + T_S(i)}} \quad \mathrm{for }\quad n = 1,2,\dots,t \right] \\
    &\geq 1 -\frac{\delta}{k}
\end{align*}
and
\begin{align*}
    &\mathbb{P} \Bigg( \mathrm{UCB}_t^S(i) \leq \mu^{(\mathrm{on})}(i) + 2\sqrt{\frac{2 \log(kt /\delta)}{N_t(i) + T_S(i)}} + \frac{T_S(i)}{N_t(i) + T_S(i)}  \cdot \eta(i)  \Bigg) \\
    &= \mathbb{P} \Bigg( \frac{N_t(i) \cdot \hat{Y}_t(i) + T_S(i) \cdot \hat{X}(i)}{N_t(i) + T_S(i)} \leq \mu^{(\mathrm{on})}(i)  + \sqrt{\frac{2\log(kt/\delta)}{N_t^+(i) + T_S(i)}} + \frac{T_S(i) \cdot (\mu^{(\mathrm{off})}(i) - \mu^{(\mathrm{on})}(i))}{N_t^+(i) + T_S(i)} \Bigg) \\
    &= \mathbb{P} \Bigg( \frac{N_t(i) \cdot \hat{Y}_t(i) + T_S(i) \cdot \hat{X}(i)}{N_t(i) + T_S(i)} \leq \frac{N_t(i) \mu^{(\mathrm{on})}(i) + T_S(i) \mu^{(\mathrm{off})}(i)}{N_t(i) + T_S(i)} 
    + \sqrt{\frac{2\log(kt/\delta)}{N_t^+(i) + T_S(i)}} \Bigg) \\
    &\geq \mathbb{P}_{Y_i \sim P^{(\mathrm{on})}(i)} \Bigg[ \frac{\sum_{i=1}^{n} Y_i + T_S(i) \cdot \hat{X}(i)}{n + T_S(i)} \leq \frac{n \mu^{(\mathrm{on})}(i) + T_S(i) \mu^{(\mathrm{off})}(i)}{n + T_S(i)}  + \sqrt{\frac{2\log(kt/\delta)}{n + T_S(i)}} \quad \mathrm{for } \quad n = 1,2,\dots,t \Bigg] \\
    &\geq 1 -\frac{\delta}{k}.
\end{align*}
Then a union bound on the failure probabilities for $i\in A$ establishes the Lemma. We can obtain a similar bound for $\big|\mu^{\mathrm{on}}(i)-\max(\mathrm{LCB}_t^S(i), \mathrm{LCB}_{t}(i))\big|$. Clearly, the stopping condition guarantees that the probability of identifying the best arm is no less than $1 - \delta$.

In the following, we bound the total number of measurements.
Define $c=\frac{1}{2}[ \mu^{\mathrm{on}}(1)+\mu^{\mathrm{on}}(2)]$. We say that arm $i^*$ is BAD in round $t$, if $\mathrm{LCB}_{t}(i^*)<c$ and $\mathrm{LCB}_{t}^{S}(i^*)<c$, and an arm $i\neq i^*$ is BAD in round $t$, if $\mathrm{UCB}_{t}(i)>c$ and $\mathrm{UCB}_{t}^{S}(i)>c$. We claim that for all time $t\geq 1$, 
\begin{align*}
    \big\{\text{Events in Lemma } \ref{confidence} \text{ hold }\big\} \cap \big\{\max\{\mathrm{LCB}_{t}(i^*), \mathrm{LCB}_{t}^{S}(i^*)\}<\min\{\mathrm{UCB}_{t}(i), \mathrm{UCB}_{t}^{S}(i)\}\big\}\\
    \Rightarrow \{h_{t} \text{ is BAD }\} \cap \{l_{t} \text{ is BAD }\}.
\end{align*}

Assume that the events in  Lemma \ref{confidence} hold, then for any $i\neq i^*$ and $s\geq \tau_{i}$, where $\tau_{i}$ is the first integer such that arm $i$ is not BAD. Define $\tau_{i^*}=\tau_{2}$.
\begin{align*}%\label{UCBw}
        \mathrm{UCB}_{t}(i)&\leq \mu^{(\mathrm{on})}(i) + 2\ \mathrm{rad}_t(i)  \\
        &= c + 2\ \mathrm{rad}_t(i) + \frac{(\mu^{\mathrm{on}}(i)-\mu^{\mathrm{on}}(i^*))+(\mu^{\mathrm{on}}(i)-\mu^{\mathrm{on}}(2))}{2}\\
        &\leq c + 2\ \mathrm{rad}_t(i) - \frac{\Delta_{i}}{2}\leq c, 
\end{align*}
where $\Delta_{i}=\mu^{\mathrm{on}}(i^*)-\mu^{\mathrm{on}}(i)$.
\begin{align*}%\label{SUCB}
         \mathrm{UCB}_t^S(i) &\leq \mu^{(\mathrm{on})}(i) + \mathrm{rad}_t^S(i) + \left[ \sqrt{\frac{2 \log(kt / \delta)}{N_t(i) + T_S(i)}} + \frac{T_S(i) \cdot \left(\mu^{(\mathrm{off})}(i) - \mu^{(\mathrm{on})}(i)\right)}{N_t(i) + T_S(i)} \right]\\
       & =c -\frac{\Delta_{i}}{2} + 2\sqrt{\frac{2 \log(kt / \delta)}{N_t(i) + T_S(i)}} + \frac{T_S(i)}{N_t(i) + T_S(i)}  \cdot \eta(i) \leq c. 
\end{align*}
Since $\min \{ \mathrm{UCB}_{s}(i),\mathrm{UCB}_t^S(i) \} \leq c$, we have
\begin{align*}
    \min\bigg\{2\sqrt{\frac{2 \log(k t/\delta)}{N_t(i) + T_S(i)}} + \frac{T_S(i)}{N_t(i) + T_S(i)}  \cdot \eta(i) , 2\sqrt{\frac{2 \log(kt /\delta)}{N_t(i)}}\bigg\}\leq \frac{\Delta_{i}}{2}.
\end{align*}
Solving for $N_{t}(i)$, we find that
\begin{align*}
    N_{t}(i)>\frac{32}{\Delta_{i}^{2}}\log\Big(\frac{k}{\delta}\Big)-T_{S}(i)\cdot\max\Big\{1-\frac{4\eta(i)}{\Delta_{i}},0\Big\}.
\end{align*}
Since Lemma \ref{confidence} holds, the total number of rounds is observed to be no greater than
\begin{align*}
\sum_{t=1}^{\infty} \mathbbm{1}\{ h_t \text{ is } \mathrm{BAD} \text{ or } l_t \text{ is } \mathrm{BAD} \}
&= \sum_{t=1}^{\infty} \sum_{i=1}^{n} \mathbbm{1}\left\{ \{ h_t = i \text{ or } l_t = i \} \cap \{ i \text{ is } \textit{BAD} \} \right\} \\
&\leq \sum_{t=1}^{\infty} \sum_{i=1}^{n} \mathbbm{1}\left\{ \{ h_t = i \text{ or } l_t = i \} \cap \{ N_t(i) \leq \tau_i \} \right\} 
\leq \sum_{i=1}^{n} \tau_i
\end{align*}
%we can observe that the total number of samples does not exceed $\sum_{i=1}^{k}\tau_{i}$. 
Then LUCB-H algorithm obtains a sample complexity of order in Theorem $\ref{thm: 4.1}$.
