		P_{\mathrm{cov}}^{\textrm{T-S}}\! =& \left(1-\left(1-\frac{ r_{\textrm{max}}^2-H^2}{4(r_{\textrm{e}}+H)r_{\textrm{e}}}\right)^{N_{\textrm{S}}}\right) \sum_{n=1}^{N_{T\textrm{-}S}}(-1)^{ n+1} \binom{N_{T\textrm{-}S}}{n}
		\sum_{n_I=1}^{N_{\textrm{T}}-1}\! \binom{N_{\textrm{T}}-1}{n_I} \left(\frac{r_{\textrm{max}} \cos\big(\frac{\varphi_{\textrm{s}}}{2}\big) - H}{r_{\textrm{e}} - r_{\textrm{e}} \cos\big(\frac{R_{\textrm{c}}}{r_{\textrm{e}}}\big)}\right)^{n_I}\nonumber \\
		&\times \int_H^{r_{\textrm{max}}}\!\!\! \Bigg( \int_{H}^{r_{\textrm{max}}}\!\! \Bigg(\!\!\! \left(\!1\! + \!\frac{2n T_1r_m^{\alpha_1}\overline{D}}{(N_{T\textrm{-}S}!)^{\frac{1}{N_{T\textrm{-}S}}}r_n^{\alpha_1}\big(1-\cos\big(\frac{\varphi_{\textrm{s}}}{2}\big)\big)}\! \right)^{\!\! -N_{T\textrm{-}S}}\!\!\!\!\!\!\!\! \frac{\varphi_{\textrm{t}}}{2\pi} + \! \left(\! 1\! + \!\frac{2n T_1r_m^{\alpha_1}\overline{D} g_{\textrm t}}{(N_{T\textrm{-}S}!)^{\frac{1}{N_{T\textrm{-}S}}}r_n^{\alpha_1}G_{\textrm t}\big(1 - \cos\big(\frac{\varphi_{\textrm{s}}}{2}\big)\big)}\!\right)^{\!\! -N_{T\textrm{-}S}}\!\!\!\!\!\! \left(1-\frac{\varphi_{\textrm{t}}}{2\pi}\right)\! \Bigg) \nonumber \\ 
		& \times \frac{2r_n}{r_{\textrm{max}}^2\! -\! H^2} \mathrm{d} r_n\! \Bigg)^{n_I}\!\! \left(\! \frac{H\! +\! r_{\textrm{e}}\! -\! r_{\textrm{max}} \cos\big(\frac{\varphi_{\textrm{s}}}{2}\big) - r_{\textrm{e}} \cos\big(\frac{R_{\textrm{c}}}{r_{\textrm{e}}}\big)}{r_{\textrm{e}} - r_{\textrm{e}}\cos\big(\frac{R_{\textrm{c}}}{r_{\textrm{e}}}\big)}\right)^{N_{\textrm{T}}-1-n_I} \!\!\!\!\! N_{\textrm{S}} \left(1\! -\! \frac{r_m^2-H^2}{4(r_{\textrm{e}}\! +\! H)r_{\textrm{e}} }\right)^{\!\!N_{\textrm{S}}-1} \!\!\!\!\! \frac{r_m }{2(r_{\textrm{e}}\! +\!H)r_{\textrm{e}}} \mathrm{d}r_m. 	 
	\end{align} 
