We now formulate the CP under the Nakagami fading assumption for the service link.\setcounter{equation}{27}





\begin{Lemma}\label{L3}
	The Laplace transform of random variable $I_{\rm{T}}$ is 
	\begin{align}\label{eqLapTraI} % eq.30
		\mathcal{L}_{I_{\rm{T}}}(s)\! =& \mathbb{E}_{N_I,R_{T_n},D_{T_n\textrm{-}S}}\!\! \left[\! \prod_{T_n\in\Phi_{\rm{C}} {\backslash} T_m}\!\!\!\! \left(\!1\! +\! \frac{t_0 D_{T_n\textrm{-}S} }{N_{T\textrm{-}S}R_{T_n}^{\alpha_1}}\!\right)^{\!\!\!-N_{T\textrm{-}S}} \!\right]\!\! ,\!
	\end{align}
	with $t_0 = \frac{n\eta T_1r_m^{\alpha_1}\overline{D}}{D_{T_m\textrm{-}S}}$.
\end{Lemma}

\begin{proof}
	See Appendix~\ref{ApD}.
\end{proof}

The target IoT devices are located within the finite-size area $\mathcal{A}_{\textrm{T}}$. Once a target IoT device selects a service satellite, any other IoT devices within the satellite coverage $\mathcal{A}_{\textrm{C}}$ of the serving satellite are interfering devices. However, in reality, there exist IoT devices that are outside the finite-size area $\mathcal{A}_{\textrm{T}}$ but are also within the satellite coverage $\mathcal{A}_{\textrm{C}}$, hence becoming interfering nodes. Thus, we assume that when the satellite coverage  $\mathcal{A}_{\textrm{C}}$  partially intersects with $\mathcal{A}_{\textrm{T}}$, the distribution of IoT devices within  the intersection region still follows $\Phi_{\textrm{T}}$. Therefore, we have   
\begin{align} % eq.31
	&\mathcal{L}_{I_{\textrm{T}}}(s) \nonumber \\
	&= \mathbb{E}_{N_I,D_{T_n\textrm{-}S}} \! \!\left[ \!\prod_{T_n\in\Phi_{\textrm{C}} {\backslash} T_m} \!\!\!\int_{H}^{r_{\!\textrm{max}}}\!\!\! \left(\!1\!+\!\frac{t_0 D_{T_n\textrm{-}S} }{N_{T\textrm{-}S}r_n^{\alpha_1}}\!\right)^{\!\!\!-N_{T\textrm{-}S}}\!\!\!\!\!\! \frac{2r_n}{r_{\!\textrm{max}}^2\!-\!H^2} \mathrm{d} r_n \!\right] \nonumber
\end{align}
\begin{align}\label{L3-1} % eq.31
	&= \mathbb{E}_{N_I}\!\! \left[\! \prod_{T_n\in\Phi_{\textrm{C}} {\backslash} T_m} \!\!\!\int_{H}^{r_{\!\textrm{max}}}\!\!\!   \left( \left(\!1\!+\!\frac{t_0 G_{\rm t}G_{S} }{N_{T\textrm{-}S}r_n^{\alpha_1}}\!\right)^{\!\!\!-N_{T\textrm{-}S}} \!\!\!\frac{\varphi_{\textrm{t}}}{2\pi} \right.\right. \nonumber\\
	&\hspace*{3mm} + \left.\left. \left(\!1\!+\!\frac{t_0 g_{\rm t}G_{S} }{N_{T\textrm{-}S}r_n^{\alpha_1}}\!\right)^{\!\!\!-N_{T\textrm{-}S}}\!\!\! \Big(1-\frac{\varphi_{\textrm{t}}}{2\pi}\Big) \right) \frac{2r_n}{r_{\!\textrm{max}}^2\!-\!H^2} \mathrm{d} r_n \!\right] .
\end{align}

The point distribution of the interfering users can be described by a BPP. Therefore, the number of interfering users $N_I$ follows a binomial distribution with a certain probability of success. The probability of success can be expressed as
\begin{align}\label{L3-2} % eq.32
	P_I =& \frac{\mathcal{S}(\mathcal{A}_{\textrm{C}})}{\mathcal{S}(\mathcal{A}_{\textrm{T}})} = \frac{2\pi r_{\textrm{e}}^2(1-\cos(\theta_3))}{2\pi r_{\textrm{e}}^2(1-\cos(\theta_1))}=\frac{1-\cos(\theta_3)}{1-\cos(\theta_1)},
\end{align}
where $\cos(\theta_3)=\frac{H+r_{\textrm{e}}-r_{\textrm{max}} \cos\big(\frac{\varphi_{\textrm{s}}}{2}\big)}{r_{\textrm{e}}}$ and $r_{\textrm{max}}$ is given in (\ref{L0-4}).

Then $\mathcal{L}_{I_{\textrm{T}}}(s)$ can be derived as follows:
\begin{align} \label{L3-3}% eq.33
	&\mathcal{L}_{I_{\textrm{T}}}(s) {=} \sum_{n_I=1}^{N_{\textrm{T}}-1}\! \binom{N_{\textrm{T}}-1}{n_I} (P_I)^{n_I}\!\! \left(\int_{H}^{r_{\textrm{max}}} \!\!\left(\!\! \left(\!1\!+\!\frac{t_0 G_{\rm t}G_{S} }{N_{T\textrm{-}S}r_n^{\alpha_1}}\!\right)^{\!\!\!-N_{T\textrm{-}S}} \!\!\! \right.\right. \nonumber\\
	&{\times}\left.\left. \frac{\varphi_{\textrm{t}}}{2\pi} +\left(\!1\!+\!\frac{t_0 g_{\rm t}G_{S} }{N_{T\textrm{-}S}r_n^{\alpha_1}}\!\right)^{\!\!\!-N_{T\textrm{-}S}} \!\!\!\! \left(1-\frac{\varphi_{\textrm{t}}}{2\pi}\right)\!\! \right) 
	\frac{2r_n}{r_{\textrm{max}}^2-H^2} \mathrm{d} r_n\!\!\right)^{n_I} \nonumber\\
	&{\times}(1-P_I)^{N_{\textrm{T}}-1-n_I} .	 
\end{align}

\begin{Theorem}\label{T1}	
	The CP of the serving satellite to any IoT device is given as 
	\begin{align}\label{eqT1} % eq.28
		P_{\rm{cov}}^{\rm{T}\textrm{-}\rm{S}} =& (1-P_0)\, \mathbb{P}( \mathrm{SINR}_1\geq T_1|R_{T_m}\leq r_{\rm{max}}) ,
	\end{align}
	where $T_1$ is the SINR threshold of the T-S link and
	\begin{align}\label{eqT1.1} % eq.29
		& \mathbb{P}(\mathrm{SINR}_1\geq T_1|R_{T_m}\leq r_{\rm{max}}) \nonumber \\
		& \hspace*{2mm} = \int_H^{r_{\rm{max}}} \sum_{n=1}^{N_{T\textrm{-}S}}(-1)^{n+1} \binom{N_{T\textrm{-}S}}{n}\mathcal{L}_{I_{\textrm{T}}}(s) \nonumber \\ 
		& \hspace*{5mm} \times\! N_{\rm{S}} \left(\! 1-\frac{ r_m^2-H^2}{4(r_{\rm{e}} +H)r_{\rm{e}}}\right)^{\!N_{\rm{S}}-1} \!\! \frac{ r_m }{2(r_{\rm{e}}+H)r_{\rm{e}}}\mathrm{d}r_m ,	
	\end{align}
	with $\mathcal{L}_{I_{\textrm{T}}}(s)$ being given by (\ref{L3-3}), and $s = \frac{n \eta T_1 16 \pi^2 f_1^2  r_m^{\alpha_1}}{p_{\rm{t}} D_{T_m\textrm{-}S}\,c^2}$. The complete expression of $P_{\rm{cov}}^{\rm{T}\textrm{-}\rm{S}}$ of the T-S link is given by (\ref{cov1}). 
\end{Theorem}

\begin{proof}
	See Appendix~\ref{ApC}.
\end{proof}



\subsection{CP over the S-ES Link}\label{S4.2}

\begin{Lemma}\label{L4}
	The Laplace transform of random variable $I_{\textrm{S}}$ is given by\setcounter{equation}{34}
	\begin{align} \label{eqL4} % eq.36
		\mathcal{L}_{I_{\rm{S}}}({s}') =& \sum_{n_I=1}^{N_{\rm{S}}-1} \binom{N_{\rm{S}}}{n_I}\left(\frac{1-\cos(\theta_3)}{2}\right)^{n_I} \nonumber \\
		&\times \int_{H}^{r_{\rm{max}}} \frac{(2\bar{c}q)^q(1+2\bar{c}{t_0}'  r_n'^{-\alpha_2})^{q-1}}{\big((2\bar{c}q+\Omega )(1+2\bar{c}{t_0}' r_n'^{-\alpha_2})-\Omega\big)^q} \nonumber \\
		&\times \frac{2r_n'}{r_{\rm{max}}^2\! -\! H^2}\mathrm{d}r_n' \left(\frac{1\! +\! \cos(\theta_3)}{2}\right)^{N_{\rm{S}}-n_I-1}\!\!\!,
	\end{align}
	where	$t_0'\! =\! \frac{t\,\zeta(\beta-\delta)\, T_2 p_n D_{S_n\textrm{-}ES}\,r_m'^{\alpha}}{p_{\rm{s}} D_{S_m\textrm{-}ES}}$ and $\cos(\theta_3)\! =\!\frac{H+r_{\rm{e}}-r_{\rm{max}} \cos\big(\frac{\varphi_{\rm{s}}}{2}\big)}{r_{\rm{e}}}$ .
\end{Lemma}

\begin{proof}
	See Appendix~\ref{ApF}. 
\end{proof}


\begin{Theorem}\label{T2}
	The CP for an arbitrarily located satellite capable of communicating with the ES under the SR fading channel is given by
	\begin{align}	\label{eqT2} % eq.35
		P_{\rm{cov}}^{\rm{S}\textrm{-}\rm{ES}} &{\triangleq} \mathbb{P}( \mathrm{SINR}_2\geq T_2) \nonumber \\
		&\hspace*{-1mm}= 1 -\! \sum_{k=0}^{\infty } \frac{\Psi\left(k\right)}{(\beta-\delta) ^{k+1}} \Gamma (k+1)\sum_{t=0}^{k+1}\binom{k+1}{t}   \nonumber\\
		&\hspace*{2mm}	\times (-1)^t \int_H^{r_{\rm{max}}} \!\! 	\mathcal{L}_{I_{\rm{S}}}({s}') \frac{2r_m'}{r_{\rm{max}}^2\! -\!H^2} \mathrm{d}r_m',	
	\end{align}
	where $T_2$ is the SINR threshold of the S-ES link, $\Psi (k)\! =\! \frac{\left(-1\right)^{k}\kappa\delta^{k}}{\left(k!\right)^{2}} {\rm Ps}(1\! -\! q)_{k}$, with $\kappa$ from (\ref{eqSSF}),  ${s}'\! =\! \frac{t\,\zeta(\beta-\delta)\, T_2}{p_{\rm{s}} D_{\rm{S}_m\textrm{-}\rm{ES}} \,l_2(r_m')}$, $\zeta\! =\! (\Gamma(k+2))^{-\frac{1}{k+1}}$, 	$\mathcal{L}_{I_{\rm{S}}}({s}')$ is given by (\ref{eqL4}), $I_{\textrm{S}}$ is the interference power of the interfering satellites visible to the ES,  $r_{\rm{max}}$ is given in (\ref{L0-4}), and the complete exression of $P_{\rm{cov}}^{\rm{S}\textrm{-}\rm{ES}}$ for the S-ES link is given by (\ref{eqCPs-gw}).	
\end{Theorem}

\begin{proof}
	See Appendix~\ref{ApE}.
\end{proof}



\begin{figure*}[!tp]\setcounter{equation}{36}
	\vspace*{-1mm}
	\begin{align}\label{eqCPs-gw} % eq 37
		&	P_{\mathrm{cov}}^{\textrm{S-ES}} =1 -\! \sum_{k=0}^{\infty }\,\, \frac{\left(-1\right)^{k}\kappa\delta^{k}(1-q)_{k}}{\left(k!\right)^{2}(\beta-\delta) ^{k+1}}\,\, \Gamma (k+1)\,\,\sum_{t=0}^{k+1}\,\,\binom{k+1}{t} (-1)^t \sum_{n_I=1}^{N_{\textrm{S}}-1} \binom{N_{\textrm{S}}}{n_I}\left(\frac{r_{\textrm{max}} \cos(\frac{\varphi_{\textrm{s}}}{2})-H}{2r_{\textrm{e}}}\right)^{n_I} \nonumber \\
		&\hspace*{3mm}\times\! \left(\! \frac{H\! +\! 2r_{\textrm{e}}\! -\! r_{\textrm{max}} \cos(\frac{\varphi_{\textrm{s}}}{2})}{2r_{\textrm{e}}}\! \right)^{\! N_{\textrm{S}}-n_I-1}\!\!\! \int_{H}^{r_{\textrm{max}}}\!\!\! \int_{H}^{r_{\textrm{max}}}\!\!\!\! \frac{(2\bar{c}q)^q\left(1\! +\! \frac{2\bar{c} t\,\zeta(\beta-\delta) T_2 p_n r_m'^{\alpha}}{p_{\textrm{s}} r_n'^{\alpha_2}} \right)^{q-1}}{\left((2\bar{c}q\! +\! \Omega )\left(1\! +\! \frac{2\bar{c} t \zeta(\beta-\delta)\, T_2 p_n r_m'^{\alpha}}{p_{\textrm{s}} r_n'^{\alpha_2}} \right)^{q-1}\! -\! \Omega\right)^q} \frac{4r_m'r_n'}{(r_{\textrm{max}}^2-H^2)^2} \mathrm{d}r_n'\mathrm{d}r_m'.
