\subsection{E2E Coverage Probability}\label{S2.4}

In our model, the communication link is established from the ground IoT devices to the satellite, which then transparently forwards the signal to the ground station. Consequently, the E2E coverage probability is the product of the coverage probabilities for both the uplink from IoT devices to the satellite and the downlink from the satellite to the ES. Therefore, the E2E coverage probability can be expressed as:\setcounter{equation}{37}
\begin{align}\label{eqe2e} % eq.3l8
	P_{\textrm{cov}}^{\,{\textrm{E2E}}} =& \,P_{\textrm{cov}}^{\textrm{T-S}}\, P_{\textrm{cov}}^{\textrm{S-ES}} .
\end{align}

\begin{remark}\label{Rm2}
	The derived CP expression offers valuable insights for the overall system design. By modeling IoT devices within finite regions and considering satellite coverage limitations, we can more accurately assess how system parameters, such as the number of devices and  satellite coverage, affect the system's performance. This helps identify critical factors that influence communication reliability, guiding satellite constellation deployment and device distribution optimization. These insights enable a more efficient design of IoT-over-satellite systems, ensuring robust connectivity even in constrained environments. Additionally, this approach can be applied to other communication systems with similar spatial limitations, providing a flexible tool for network design.
\end{remark}

\section{Average Ergodic Rate}\label{S5}	

We now focus on the average achievable date rate. The AER, measured in bits/s/Hz, also known as the Shannon throughput, represents the mean data rate achievable over the system. It corresponds to the ergodic capacity for a fading communication link, normalized to a unit bandwidth. The AER is defined as follows\setcounter{equation}{38}
\begin{eqnarray}\label{eqAER}	% eq.39
	\bar{C} \triangleq \mathbb{E}\left[ \log_2\left(1+\text{SINR}\right) \right] .
\end{eqnarray}

\subsection{AER over the T-S Link}\label{S5.1}

\begin{Theorem}\label{T3}
	The average rate of an arbitrary IoT device in the service link of a Nakagami fading channel is given by
	\begin{align}\label{eqT3} % eq.40
		\bar{C}^{\rm{T}\textrm{-}\rm{S}} =& (1-P_0) \, \mathbb{E}[ \log_2(1+\mathrm{SINR}_1)|R_{T_m}\leq r_{\rm{max}}] , 
	\end{align}
	in which $P_0$ is given in (\ref{P0}) and
	\begin{align}\label{eqT1.2} % eq.41
		& \mathbb{E}[ \log_2(1+\mathrm{SINR}_1)|R_{T_m}\leq r_{\rm{max}}] \nonumber \\
		& \hspace*{2mm}= \int_{H}^{r_{\rm{max}}}\!\!\! \int_{t>0} \sum_{n=1}^{N_{T\textrm{-}S}}(-1)^{n+1} \binom{N_{T\textrm{-}S}}{n}	\mathcal{L}_{I_{\rm{T}}}(s_1) \nonumber \\
		&\hspace*{5mm}\times\! \left(\! 1\! -\! \frac{r_m^2-H^2}{4(r_{\rm{e}}\! +\! H)r_{\rm{e}}}\right)^{N_{\rm{S}}-1}\!\!\! \frac{N_{\rm{S}} r_m }{2(r_{\rm{e}}\! +\! H)r_{\rm{e}} } \mathrm{d}t \,\mathrm{d}r_{m}, 
	\end{align}
	where $s_1\! =\! \frac{n \eta (2^t\! -\! 1) 16 \pi^2 f_1^2  r_m^{\alpha_1}}{p_{\rm{t}} D_{T_m\textrm{-}S}\, c^2} $, and $\mathcal{L}_{I_{\rm{T}}}(s_1)$ is obtained by  replacing $s$ in $\mathcal{L}_{I_{\rm{T}}}(s)$ with $s_1$.
\end{Theorem}

\begin{proof}
	See Appendix~\ref{ApG}.
\end{proof}

\subsection{AER over the S-ES Link} \label{S5.2}

\begin{Theorem}\label{T4}
	The AER of an arbitrary satellite node in the feeder link of an SR fading channel is given by
	\begin{align}\label{eqT3-m} % eq.42
		& \bar{C}^{\rm{S}\textrm{-}\rm{ES}}\!\! =\!\! \int_{t>0}\!\! \left(\!\!1\! -\!\! \int_H^{r_{\rm{max}}}\!\!\!\! \!\mathbb{E}\!\left[ \sum_{k=0}^{\infty} \frac{\Psi\left(k\right)}{(\beta\! -\! \delta) ^{\,k+1}} \Gamma (k\! +\! 1)\frac{2r_m'}{r_{\rm{max}}^2\! -\! H^2} \right.\right. \nonumber \\ 	 
		&\times\!\! \left. \left. \sum_{u=0}^{k+1}\!\! \binom{k+1}{u} (-1)^u \mathbb{E}_{I_{\rm{S}}}\!\! \left[\! \exp(-{s}_1'(I_{\rm{S}}\! +\!\sigma^2)) \right]\! \right]\!	\mathrm{d}r_m'\!\! \right)\! \mathrm{d}t ,\!
	\end{align}
	where 
	\begin{align}\label{eqAdd} % eq.43
		\mathbb{E}_{I_{\rm{S}}}\! \! \left[ \exp\!\left(-s_1' {(I_{\rm{S}}\!+\!\sigma^2\!)}\!\right)\!\right]\!\! &=\!\mathbb{E}_{I_{\rm{S}}}\! \! \left[\exp\left(-s_1'\! {I_{\rm{S}}}\right)\right]\!\exp\left(-\!s_1'\! {\sigma^2}\right)\nonumber\\
		&=\mathcal{L}_{I_{\rm{S}}}({s_1}')\!\exp\left(-\!s_1'\! {\sigma^2}\right),
	\end{align} 
	with ${s}_1'\! =\!\frac{u\,\zeta(\beta-\delta)\, (2^t\! -\! 1)}{p_{\rm{s}} D_{S_m\textrm{-}ES} \,l_2(r_m')}$, and $\mathcal{L}_{I_{\rm{S}}}({s_1}')$ is obtained by replacing $s'$ in $\mathcal{L}_{I_{\rm{S}}}({s}')$ with $s_1'$.
\end{Theorem}

\begin{proof}
	See Appendix~\ref{ApH}.
\end{proof}	

\begin{remark}\label{Rm3}
	It is worth noting that when calculating the AER for the S-ES link, we must consider noise. This is because satellites are distributed according to a BPP model on a spherical surface at an altitude $H$ from the ground. In the field of view of the ES, there may be no interfering satellites present. In such cases, the presence of noise $\sigma^2$ is essential to give the AER calculation meaningful significance.
\end{remark}

