\subsection{Proof of Lemma~\ref{L1}}\label{ApA}

\begin{proof}
	Let $\mathcal{A}(x)$ represent the spherical cap with the radius $r_{\textrm{e}}\! +\! H$ such that the distance between any point on $\mathcal{A}(x)$ and the IoT device is equal to $x\! \in\! [H, \, 2r_{\rm{e}}\! + \!H]$, $a$ and $b$ signify the radius and height of $\mathcal{A}(x)$, respectively, and the surface area of $\mathcal{A}(x)$ be $\mathcal{S}(\mathcal{A}(x))$. If $x\! =\! H$, the surface area vanishes, i.e., $\mathcal{S}(\mathcal{A}(H))\! =\! 0$, while when $x\! =\! 2 r_{\textrm{e}}\! +\! H$, the surface area becomes a whole sphere with the radius $r_{\textrm{e}}\! +\! H$, which is the region where the satellites are located, i.e., $\mathcal{S}(\mathcal{A}( 2r_{\rm{e}}\! +\! H))\! =\! 4\pi (r_{\textrm{e}}\! +\! H)^2$. From basic geometry, we obtain 
	\begin{align} % eqs.44-46
		\mathcal{S}(\mathcal{A}(x)) =& 2 \pi (r_{\textrm{e}}+H) b,  \label{A1.1} \\
		\mathcal{S}(\mathcal{A}(x)) =& \pi (a^2+b^2), \label{A1.2} \\
		x^2 =& (H-b)^2+a^2. \label{A1.3}
	\end{align}
	Substituting (\ref{A1.1}) and (\ref{A1.2}) into (\ref{A1.3}) leads to the relationship expression between $x^2$ and $\mathcal{S}(\mathcal{A}(x))$ as 
	\begin{align}\label{A1.4} % eq.47
		x^2 =& \frac{\mathcal{S}(\mathcal{A}(x))}{\pi}-2H\frac{\mathcal{S}(\mathcal{A}(x))}{2\pi (r_{\textrm{e}}+H)}+H^2  \nonumber \\
		=& \mathcal{S}(\mathcal{A}(x)) \frac{r_{\textrm{e}}}{\pi (r_{\textrm{e}}+H)}+H^2.
	\end{align}
	Thus, we have
	\begin{align}\label{A1.5} % eq.48
		\mathcal{S}(\mathcal{A}(x)) =& \frac{\pi (r_{\textrm{e}}+H)(x^2 -H^2)}{r_{\textrm{e}}}.
	\end{align}

	The probability that the distance between satellite $S$ and IoT device $T$ is less than $r_\textrm{s}$ is equivalent to the probability of the satellite $S$ being within $\mathcal{A}(r_\textrm{s})$, denoted as the success probability for $\mathcal{A}(r_\textrm{s})$, with $r_\textrm{s}\! \in\! [H, \, 2r_{\rm{e}}\! + \!H]$. This is defined as the ratio of the surface area of $\mathcal{S}(\mathcal{A}(r_\textrm{s}))$ to $\mathcal{S}(\mathcal{A}(2r_{\rm{e}}\! +\! H))$:
	\begin{align}\label{A1.6} % eq.49
		\mathbb{P}(R_{\textrm{S}} \leq r_\textrm{s}) = \frac{\mathcal{S}(\mathcal{A}(r_\textrm{s}))}{\mathcal{S}(\mathcal{A}(2r_{\rm{e}} + H))}= \frac{r_\textrm{s}^2-H^2}{4(r_{\textrm{e}}+H)r_{\textrm{e}}},
	\end{align}
	for $H\le r_\textrm{s}\! \le\! 2r_{\rm{e}}\! +\! H$. Clearly $\mathbb{P}(R_{\textrm{S}}\! \leq\! r_\textrm{s})\! =\! 0$ for $r_\textrm{s}\! <\! H$, and $\mathbb{P}(R_{\textrm{S}}\! \leq\! r_\textrm{s})\! =\! 1$ for $r_\textrm{s}\! >\! 2r_{\rm{e}}\! +\! H$. This leads to (\ref{L1-1}).

	Differentiating (\ref{L1-1}) with respect to $r_\textrm{s}$ leads to (\ref{L1-2}).
\end{proof}

\subsection{Proof of Lemma~\ref{L2}} \label{ApB}

\begin{proof}
	Let $\mathcal{A}'(x')$ denote the spherical cap with the radius $r_{\textrm{e}}$ such that the distance between any point on $\mathcal{A}'(x')$ and the satellite is equal to $x'\! \in\! [H,\, 2r_{\rm{e}}\! +\! H]$, $a_1$ and $b_1$ signify the radius and height of $\mathcal{A}'(x')$, and the surface area of $\mathcal{A}'(x')$ be $\mathcal{S}(\mathcal{A}'(x'))$. If $x'\! =\! H$, $\mathcal{S}(\mathcal{A}'(H))\! =\! 0$. When $x'\! =\! 2 r_{\textrm{e}}\! +\! H$, the surface area becomes the surface of the Earth, i.e., $\mathcal{S}(\mathcal{A}'( 2r_{\rm{e}}\! +\! H))\! =\! 4\pi r_{\textrm{e}}^2$. From basic geometry, we can obtain 
	\begin{align} % eqs.50-52
		\mathcal{S}(\mathcal{A}'(x')) =& 2 \pi r_{\textrm{e}} b_1, \label{A2.1} \\
