\subsection{Proof of Theorem~\ref{T1}}\label{ApC}

\begin{proof}

	From Bayes rule, we have
	\begin{align}\label{eqApC1} % eq.54
		P_{\rm{cov}}^{\rm{T}\textrm{-}\rm{S}} =& \mathbb{P}(R_{T_m} > r_{\rm{max}}) \mathbb{P}( \mathrm{SINR}_1\geq T_1|R_{T_m}> r_{\rm{max}}) \nonumber \\
		& + \mathbb{P}(R_{T_m} \le r_{\rm{max}}) \mathbb{P}( \mathrm{SINR}_1\geq T_1|R_{T_m}\leq r_{\rm{max}})  \nonumber \\
		=& (1-P_0)\, \mathbb{P}( \mathrm{SINR}_1\geq T_1|R_{T_m}\leq r_{\rm{max}}).
	\end{align}
	Note that
	\begin{align}\label{eqApC2} % eq.55
		&	\mathbb{P}(\mathrm{SINR}_1\geq T_1|R_{T_m}\leq r_{\textrm{max}}) \nonumber \\
		&\hspace*{2mm}= \mathbb{E}_{R_{T_m}}\left[ \mathbb{P}\left(\mathrm{SINR}_1 \geq  T_1|R_{T_m}=r_m, R_{T_m}\leq r_{\textrm{max}}\right) \right] \nonumber \\
		&\hspace*{2mm}=\! \int_H^{r_{\textrm{max}}}\!\! \mathbb{P}\left(\mathrm{SINR}_1 \geq  T_1|R_{T_m}=r_m\right) f_{R_{T_m}}(r_m) \mathrm{d}r_m .
	\end{align}
	As $f_{R_{T_m}}(r_m)$ is given in (\ref{L1-4}), we only need to derive:
	\begin{align}\label{eqApC3} % eq.56
		& \text{$\mathbb{P}\left(\mathrm{SINR}_1 \geq T_1|R_{T_m}=r_m\right)$} \nonumber \\
		&\hspace*{2mm}= 1 - \mathbb{P}\!\left(|h_{T_m\textrm{-}S}|^2 \le\frac{T_1{I_{\textrm{T}}}}{p_{\textrm{t}} D_{T_m\textrm{-}S} \,l_1(r_m)} \right) \nonumber \\
		&\hspace*{2mm}\overset{\mathrm{(a)}}{>}  1 - \mathbb{E}\!\left[\!\left(1-\exp\!\left( \!\frac{-\eta T_1{I_{\textrm{T}}} }{p_{\textrm{t}} D_{T_m\textrm{-}S} \,l_1(r_m)}  \right) \! \right)^{\! N_{T\textrm{-}S}} \!\right] \nonumber \\
		&\hspace*{2mm}\overset{\mathrm{(b)}}{=} \sum_{n=1}^{N_{T\textrm{-}S}}(-1)^{n+1}\binom{N_{T\textrm{-}S}}{n}\mathbb{E}_{I_{\textrm{T}}}\! \left[\exp\!\left(\! \frac{-n \eta T_1{I_{\textrm{T}}} 16 \pi^2 f_1^2  r_m^{\alpha_1}} {p_{\textrm{t}} D_{T_m\textrm{-}S} c^2}\right) \!\right] \nonumber \\
