	Substituting (\ref{Ehx}) and (\ref{P_I'}) into (\ref{LISproof}) leads to (\ref{eqL4}).
\end{proof}	

\subsection{Proof of Theorem~\ref{T2}}\label{ApE}

\begin{proof}
	Using the Kummer’s transform of the hypergeometric function \cite{5313912}, the PDF of \emph{$|h|^{2}$} can be rewritten as $f_{\left|h\right|^{2}}(x)\! =\! \sum\limits_{k=0}^{\infty}\Psi\left(k\right)x^{k}\exp\left(-\left(\beta-\delta\right)x\right)$, where $\Psi (k)\! =\! \frac{\left(-1\right)^{k}\kappa\delta^{k}}{\left(k!\right)^{2}}(1-q)_{k}$. Then the CDF of \emph{$|h|^{2}$} can be expressed as
	\begin{align}\label{eq5} % eq.58
		F_{|h|^{2}}\left(x\right) =& \sum_{k=0}^{\infty} \Psi (k) \int_{0}^{x} t^{k}\exp(-(\beta-\delta)t) dt \nonumber \\
		=& \sum_{k=0}^{\infty} \frac{\Psi\left(k\right)}{\left(\beta-\delta\right)^{k+1}}\gamma\left(k+1,\left(\beta-\delta\right)x\right).
	\end{align}
	Hence, we can obtain $P_{\mathrm{cov}}^{\textrm{S-ES}}$ as
	\begin{align}\label{A5-2} % eq.59
		& P_{\mathrm{cov}}^{\textrm{S-ES}} \triangleq  \mathbb{P}\left[ \frac{p_{\textrm{s}} \left|h_{S_m\textrm{-} ES}\right|^2 D_{S_m\textrm{-} ES} l_2(R_{S_m})} {I_{\textrm{S}}} \geq T_2  \right] \nonumber \\
		& = 1\! -\! \int_H^{r_{\textrm{max}}}\!\!\! \mathbb{P}\left[\! \left|h_{S_m\textrm{-} ES}\right|^2\! \le\! \frac{T_2 I_{\textrm{S}}}{p_{\textrm{s}} D_{S_m\textrm{-} ES}\, l_2(r_m')} | R_{S_m}\! =\! r_m'\! \right] \nonumber \\
		&\hspace*{3mm}\times	\frac{2r_m'}{r_{\textrm{max}}^2-H^2}\mathrm{d}r_m'.
	\end{align}
	Now we derive $\mathbb{P}\left[\left|h_{S_m\textrm{-}ES}\right|^2 \le \frac{T_2 I_{\textrm{S}}}{p_{\textrm{s}} D_{S_m\textrm{-} ES}l_2(r_m')} | R_{S_m}=r_m'\! \right]$:
	\begin{align} %\label{A5-3} % eq.60
		& \mathbb{P}\left[ \left|h_{S_m\textrm{-}ES}\right|^2 \le \frac{T_2 I_{\textrm{S}}}{p_{\textrm{s}} D_{S_m\textrm{-} ES}\, l_2(r_m')} | R_{S_m}=r_m' \right] \nonumber \\
		&\hspace*{2mm} = \mathbb{E}\!\!\left[\! \sum_{k=0}^{\infty}\! \frac{\Psi\left(k\right)}{(\beta-\delta) ^{\,k+1}}  \gamma \!\!\left( k+1,(\beta - \delta) \frac{T_2 I_{\textrm{S}}}{p_{\textrm{s}} D_{S_m\textrm{-} ES}\, l_2(r_m')}\right)\! \right] \nonumber \\  
		&\hspace*{2mm} \overset{\mathrm{(a)}}{\approx} \mathbb{E} \left[ \sum_{k=0}^{\infty } \frac{\Psi\left(k\right)}{(\beta-\delta)^{k+1}} \Gamma (k\!+\!1) \right. \nonumber \\ 	
		&\hspace*{6mm} \times \left. \left(1-\exp\left(- \frac{\zeta(\beta-\delta) T_2 I_{\textrm{S}}}{p_{\textrm{s}} D_{S_m\textrm{-} ES} \,l_2(r_m')} \right)\right)^{k+1}\right] \nonumber \\
		&\hspace*{2mm} \overset{\mathrm{(b)}}{=} \sum_{k=0}^{\infty} \frac{\Psi\left(k\right)}{(\beta-\delta)^{k+1}} \Gamma (k+1) \sum_{t=0}^{k+1} \binom{k+1}{t} \nonumber \\
		&\hspace*{6mm}	\times(-1)^t \mathbb{E}\left[\exp(-{s}'I_{\textrm{S}})\right] \nonumber
			\end{align}	
				\begin{align}\label{A5-3} % eq.60
		&\hspace*{2.5mm} = \sum_{k=0}^{\infty} \frac{\Psi\left(k\right)}{(\beta-\delta)^{k+1}} \Gamma (k+1) \sum_{t=0}^{k+1} \binom{k+1}{t}(-1)^t 	\mathcal{L}_{I_{\rm{S}}}({s}'), 
	\end{align}	
	where (a) is approximated by using $\gamma(k\! +\! 1,x)\! <\! \Gamma (k\! +\! 1)(1\! -\! \exp(-\zeta x))^{k+1}$\cite{alzer1997some}, $\zeta\! =\! (\Gamma(k\! +\! 2))^{-\frac{1}{k+1}}$,  and (b) is obtained from binomial theorem with ${s}'\! =\! \frac{t \zeta(\beta\! -\! \delta) T_2}{p_{\textrm{s}} D_{S_m\textrm{-}ES} l_2(r_m')}$. 

	Substituting (\ref{A5-3})  into (\ref{A5-2}) leads to $P_{\mathrm{cov}}^{\textrm{S-ES}}$ (\ref{eqT2}).
\end{proof}



\subsection{Proof of Theorem~\ref{T3}}\label{ApG}

\begin{proof}
	From (\ref{eqAER}), Bayes rule and (\ref{eqS4-1-1}), we have
	\begin{align*} % \label{eqA7} % eq.64
		& \bar{C}^{\rm{T}\textrm{-}\rm{S}} \triangleq \mathbb{E}\left[\log_2(1 + \mathrm{SINR_1})|R_{T_m}\leq r_{\textrm{max}}\right] \nonumber \\
		& \overset{\mathrm{(a)}}=\! \int_{H}^{r_{\textrm{max}}}\!\!\!\! \int_{t>0}\!\!\!\! \mathbb{E}\left[\mathbb{P}\!\!\ \Big(\log_2 (1+ \mathrm{SINR_1} >t\Big)\right]\! f_{R_{T_m}}(r_m)\,\mathrm{d}t\,\mathrm{d}r_{m} \nonumber \\
		&=\! \int_{H}^{r_{\textrm{max}}}\!\!\!\! \int_{t>0}\!\!\! \mathbb{E}\! \left[\mathbb{P}\left( |h_{T_m \textrm{-} S}|^2\! >\! \frac{I_{\textrm{T}}(2^t\! -\! 1)}{p_{\textrm{t}}D_{T_m\textrm{-}S}l_1(r_m)}\right)\right] \nonumber \\
		&\hspace*{4mm}\times \left(1-\frac{r_m^2-H^2}{4(r_{\textrm{e}}+H)r_{\textrm{e}} }\right)^{N_{\textrm{S}}-1}\!\!\!\! \frac{N_{\textrm{S}}\, r_m }{2(r_{\textrm{e}}+H)r_{\textrm{e}} } \mathrm{d}t \,\mathrm{d}r_{m} %\nonumber\\
	\end{align*}
	\begin{align}\label{eqA7} % eq.64
		&\overset{\mathrm{(b)}}{\approx} \int_{H}^{r_{\textrm{max}}} \!\!\!\!\int_{t>0}\!\! \left(1-\mathbb{E}\!\left[\!\left(\!1\!-\!\exp\!\left( \frac{-\eta {I_{\textrm{T}}}(2^t\! -\! 1) } {p_{\textrm{t}} D_{T_m\textrm{-}S} \,l_1(r_m)}  \right)\! \right)^{\!\! N_{T\textrm{-}S}} \right] \right) \nonumber \\
		&\hspace*{4mm}\times \left(1-\frac{ r_m^2-H^2}{4(r_{\textrm{e}}+H)r_{\textrm{e}} }\right)^{N_{\textrm{S}}-1}\!\!\!\! \frac{N_{\textrm{S}}\, r_m }{2(r_{\textrm{e}}+H)r_{\textrm{e}} } \mathrm{d}t \,\mathrm{d}r_{m} \nonumber \\
		&\overset{\mathrm{(c)}}{=} \int_{H}^{r_{\textrm{max}}} \!\!\!\!\int_{t>0} \sum_{n=1}^{N_{T\textrm{-}S}}(-1)^{n+1}\binom{N_{T\textrm{-}S}}{n}\mathbb{E}_{I_{\textrm{T}}}\! \! \left[\exp\left(-s_1 {I_{\textrm{T}}}\right)\right] \nonumber \\
		&\hspace*{4mm}\times\! \left(\! 1-\frac{ r_m^2-H^2}{4(r_{\textrm{e}}+H)r_{\textrm{e}} }\right)^{N_{\textrm{S}}-1}\!\!\!\! \frac{N_{\textrm{S}}\, r_m}{2(r_{\textrm{e}}+H)r_{\textrm{e}}} \mathrm{d}t \,\mathrm{d}r_{m}\nonumber\\
		&\hspace*{0.5mm}= \int_{H}^{r_{\textrm{max}}} \!\!\!\!\int_{t>0} \sum_{n=1}^{N_{T\textrm{-}S}}(-1)^{n+1}\binom{N_{T\textrm{-}S}}{n}\mathcal{L}_{I_{\rm{T}}}(s_1) \nonumber \\
		&\hspace*{4mm}\times\! \left(\! 1-\frac{ r_m^2-H^2}{4(r_{\textrm{e}}+H)r_{\textrm{e}} }\right)^{N_{\textrm{S}}-1}\!\!\!\! \frac{N_{\textrm{S}}\, r_m}{2(r_{\textrm{e}}+H)r_{\textrm{e}}} \mathrm{d}t \,\mathrm{d}r_{m},
	\end{align}
	where (a)~follows form the fact that if the random variable $X$ involved is positive, $\mathbb{E}[X]\! =\! \int_{t>0}\mathbb{P}(X>t)\mathrm{d}t$, (b)~is obtained by the tight upper bound when $N_{T\textrm{-}S}$ is small \cite{alzer1997some}, that is, $\mathbb{P}\left[|h|^{2}\! <\! \psi\right]\! <\! \left(1\! -\! \exp(-\psi\eta)\right)^{N_{T\textrm{-}S}}$ with $\eta\! =\! N_{T\textrm{-}S}(N_{T\textrm{-}S}!)^{-\frac{1}{N_{T\textrm{-}S}}}$, and (c)~is obtained by binomial theorem and by denoting $s_1\! =\! \frac{n \eta (2^t\! -\! 1) 16 \pi^2 f_1^2  r_m^{\alpha_1}} {p_{\textrm{t}} D_{T_m\textrm{-}S} c^2} $.  This completes the proof.
\end{proof}	

\subsection{Proof of Theorem~\ref{T4}}\label{ApH}

\begin{proof}
	Starting from the definition (\ref{eqAER}), we have
	\begin{align} %\label{eqA8} % eq.64
		& \bar{C}^{\rm{S}\textrm{-}\rm{ES}} \triangleq \mathbb{E}\left[\log_2(1 + \mathrm{SINR}_2)\right] \nonumber \\
		& \overset{\mathrm{(a)}}=\! \mathbb{E}\!\!\left[\int_{t>0}\!\! \mathbb{P}\Big(\!\log_2 (1\!+\!\frac{p_{\textrm{s}} D_{S_m\textrm{-}ES}\!\left|h_{S_m\textrm{-}ES}\right|^2 \!l_2(r_m')} {I_{\textrm{S}}+\sigma^2}\!>\!t\!\Big)\mathrm{d}t \!\right] \nonumber \\
		&= \mathbb{E}\! \left[\int_{t>0}\!\!\! \mathbb{P}\Big( \left|h_{S_m\textrm{-}ES}\right|^2\! >\! \frac{ (I_{\textrm{S}}+\sigma^2)(2^t\! -\! 1)}{p_{\textrm{s}} D_{S_m\textrm{-}ES} \,l_2(r_m')}\Big)  \mathrm{d}t \right]\! \!\nonumber \\
		\end{align}
		\begin{align}\label{eqA8} % eq.64
		&= \int_{t>0}\!\!\! \left(1\!-\!\int_H^{r_{\textrm{max}}}\!\!\!\!\! E\left[\mathbb{P}\!\!\left(\left|h_{S_m\textrm{-} ES}\right|^2\! \le\!\! \frac{(I_{\textrm{S}}+\sigma^2) (2^t\! -\! 1) }{p_{\textrm{s}} D_{S_m\textrm{-}ES}\, l_2(r_m')}  \!\! \right)\!  \right]\right. \nonumber \\
		&\hspace*{5mm}\times  \left. \frac{2r_m'}{r_{\textrm{max}}^2-H^2}\mathrm{d}r_m' \right)\mathrm{d}t \nonumber \\
		&= \int_{t>0}\! \Bigg(1\! - \!\int_H^{r_{\textrm{max}}}\!\!\!\! \mathbb{E} \Bigg[ \sum_{k=0}^{\infty} \frac{\Psi\left(k\right)}{(\beta-\delta)^{\,k+1}} \nonumber \\ 
		&\hspace*{5mm}\times\!\gamma\! \left(\! k\! + \!1,(\beta\! -\! \delta) \frac{(I_{\textrm{S}}+\sigma^2)(2^t\! -\! 1)}{p_{\textrm{s}} D_{S_m\textrm{-}ES} l_2(r_m')}\! \right)\! \Bigg]\! \frac{2r_m'}{r_{\textrm{max}}^2\! -\! H^2}\mathrm{d}r_m' \!\! \Bigg) \mathrm{d}t \nonumber\\
		& \overset{\mathrm{(b)}}{\approx} \int_{t>0}\! \Bigg(1\! -\! \int_H^{r_{\textrm{max}}}\!\!\!\! \mathbb{E}\!\Bigg[ \sum_{k=0}^{\infty} \frac{\Psi\left(k\right)}{(\beta-\delta)^{\,k+1}} \Gamma (k+1)\frac{2r_m'}{r_{\textrm{max}}^2-H^2} \nonumber \\ 	 
		&\hspace*{5mm} \times\!\! \left(\! 1\! -\! \exp\! \left(\! - \frac{\zeta(\beta\! -\! \delta) (2^t\! -\! 1) (I_{\textrm{S}}\! +\!\sigma^2)}{p_{\textrm{s}} D_{S_m\textrm{-}ES}\,l_2(r_m')} \right)\right)^{k+1}\Bigg]	\mathrm{d}r_m'\Bigg) \mathrm{d}t \nonumber \\ 
		&\overset{\mathrm{(c)}}= \int_{t>0}\! \Bigg(1\! -\! \int_H^{r_{\textrm{max}}}\!\!\! \mathbb{E}\!\Bigg[ \sum_{k=0}^{\infty} \frac{\Psi\left(k\right)}{(\beta-\delta)^{\,k+1}} \Gamma (k+1)\frac{ 2r_m'	}{r_{\textrm{max}}^2-H^2} \nonumber \\ 	 
		&\hspace*{5mm} \times\!\! \sum_{u=0}^{k+1}\! \binom{k+1}{u} (-1)^u \mathbb{E}_{I_{\textrm{S}}}\! \left[ \exp(-{s}_1'(I_{\textrm{S}}+\sigma^2))\! \right]\! \Bigg]\!	\mathrm{d}r_m'\! \Bigg)\!\mathrm{d}t,   
	\end{align}
	where (a)~follows form the fact that if the random variable $X$ involved is positive, $\mathbb{E}[X]\! =\! \int_{t>0}\mathbb{P}(X\! >\! t)\mathrm{d}t$, (b)~is approximated by using $\gamma(k+1,x)\! <\! \Gamma (k+1)(1-\exp(-\zeta x))^{k+1}$ with $\zeta\! =\! (\Gamma(k\! +\! 2))^{-\frac{1}{k+1}}$ \cite{alzer1997some}, and (c)~is obtained from binomial theorem with ${s}_1'\! =\! \frac{u \zeta(\beta-\delta) (2^t\! -\! 1)}{p_{\textrm{s}} D_{S_m\textrm{-}ES} \,l_2(r_m')}$. 
\end{proof}	

