\begin{algorithm}[!b]
	\caption{Offline Training Strategy for the Denoising Neural Network \textit{Conditioned} on LR CF}
	\label{alg:train}
	\begin{algorithmic}[1]
		\REPEAT
		\STATE
		Load CF training data pairs $\left({ \boldsymbol{\dot{\mathsf{G}}}},\boldsymbol{\mathsf{G}}_0 \right) \sim p\left({ \boldsymbol{\dot{\mathsf{G}}}},\boldsymbol{\mathsf{G}}_0 \right) $ 
		\STATE
		Obtain time steps $t \sim {\rm{Uniform}}({1,...,T})$
		\STATE
		Randomly generate a noise tensor with the same dimensions as $\boldsymbol{\mathsf{G}}_0$, ${\boldsymbol{\varepsilon}_t} \sim \mathcal{N}\left( {\mathbf{0},\mathbf{I}} \right)$
		\STATE
		Add noise incrementally to the HR CF $\boldsymbol{\mathsf{G}}_0$ according to \eqref{eq:ht} to perform the diffusion process
		\STATE Input the corrupted HR CF ${{{\boldsymbol{\mathsf{G}}}_t}}$, LR CF ${\boldsymbol{\dot{\mathsf{G}}}}$, and time step $t$ into the model ${{{{{\boldsymbol{\varepsilon}}_{\boldsymbol{\theta }}} }}}\left( \cdot \right)$
		\STATE
		Perform gradient descent step on the objective function \eqref{eq:46} to update the model parameters ${\boldsymbol{\theta }}$:\\
		\quad $ \nabla_{\boldsymbol{\theta }} \big\| {{\boldsymbol{\varepsilon }}_t} - {{\boldsymbol{\varepsilon }}_{\boldsymbol{\theta }}}\big({{ \boldsymbol{\dot{\mathsf{G}}}}}, {\sqrt {{{\bar \alpha }_t}} {{{\boldsymbol{\mathsf{G}}}_0}} \!+\! \sqrt {1 - {{\bar \alpha }_t}} {{\boldsymbol{\varepsilon }}}},t \big) \big\|_2^2 $
		\UNTIL the objective function \eqref{eq:46} converges
	\end{algorithmic}
\end{algorithm}

\begin{algorithm}[!t]
	\caption{Inferring the HR CF in the reverse process \textit{conditioned} on the LR CF through $T$ iterative refinement steps}
	\label{alg:infer}
	\begin{algorithmic}[1]
		\STATE
		Load the pretrained model and its weights ${\boldsymbol{\theta }}$
		\STATE
		Obtain the completely corrupted HR CF ${{{\boldsymbol{\mathsf{G}}}_T}}\sim \mathcal{N}\left( {\mathbf{0},\mathbf{I}} \right)$, and LR CF ${\boldsymbol{\dot{\mathsf{G}}}}$
		\FOR{$t=T,..,1$}
		\STATE
		${\boldsymbol{\varepsilon}^*} \sim\mathcal{N}\left( {\mathbf{0},\mathbf{I}} \right)$ if $t>1$, else ${\boldsymbol{\varepsilon}^*} =0$
		\STATE
		Execute the refinement step according to \eqref{eq:48}:\\
		\quad ${{{\boldsymbol{\mathsf{G}}}_{t\!-\!1}}} \!\leftarrow\! \frac{1}{{\sqrt {{\alpha _t}} }}\!\!\left(\!\! {{{{\boldsymbol{\mathsf{G}}}}_t} \!\!-\!\! \frac{{1 - {\alpha _t}}}{{\sqrt {1 - {{\bar \alpha }_t}} }}{{\boldsymbol{\varepsilon}}_{\boldsymbol{\theta }}}\!\left(\!{{ \boldsymbol{\dot{\mathsf{G}}}}, {{\boldsymbol{\mathsf{G}}}_t},t} \!\right)} \!\!\right) \!+\! \sqrt { \frac{{1 \!-\! {{\bar \alpha }_{t \!-\! 1}}}}{{1 \!-\! {{\bar \alpha }_t}}}{\beta _t}} {\boldsymbol{\varepsilon}^*}$
		\ENDFOR
		\RETURN HR CF ${{\hat{{\boldsymbol{\mathsf{G}}}}_0}}$

	\end{algorithmic}
\end{algorithm}

