\subsection{Diffusion Process Starting with HR CF }
%\subsection{Forward Diffusion Process}
Consider an HR CF sample that is drawn from a distribution of interest, denoted as ${\boldsymbol{\mathsf{G}}_0}={\boldsymbol{\mathsf{G}}} \sim q( \boldsymbol{\mathsf{G}})$. The GDM utilizes a fixed diffusion process $q( {{\boldsymbol{\mathsf{G}}_{1:T}}| {{\boldsymbol{\mathsf{G}}_0}} } )$ for training, which involves relatively high-dimensional latent variables. This process defines a forward diffusion mechanism, a deterministic Markovian chain, where Gaussian noise is gradually introduced to the sample over $T$ steps. The noise level at each step is determined by a variance schedule $\{ {{\beta _t} \in ( {0,1} )} \}_{t = 1}^T$. Specifically, the forward diffusion process is defined as \cite{Ho11}
\begin{align}\label{eq:chmd}
	q\left( {{\boldsymbol{\mathsf{G}}_{1:T}}\left| {{\boldsymbol{\mathsf{G}}_0}} \right.} \right) &= \prod\limits_{t = 1}^T {q\left( {{\boldsymbol{\mathsf{G}}_t}\left| {{\boldsymbol{\mathsf{G}}_{t - 1}}} \right.} \right)}.
\end{align}
Therefore, the forward diffusion process does not involve trainable parameters. Instead, it is a fixed and predefined linear Gaussian model, which can be denoted as
\begin{align}
	\label{eq:marginal ddpm}
	q\left( {{\boldsymbol{\mathsf{G}}_t}\left| {{\boldsymbol{\mathsf{G}}_{t - 1}}} \right.} \right) &= \mathcal{N}\left( {{\boldsymbol{\mathsf{G}}_t};\sqrt {1 - {\beta _t}} {\boldsymbol{\mathsf{G}}_{t - 1}},{\beta _t}\mathbf{I}} \right),  \\
	\label{eq:Gt}
	{\boldsymbol{\mathsf{G}}_t} 
	%&= \sqrt {1 - {\beta _t}} {\boldsymbol{\mathsf{G}}_{t - 1}} + \mathcal{N}\left( {0,{\beta _t}{\mathbf{I}}} \right) \nonumber \\
	&= \sqrt {1 - {\beta _t}} {\boldsymbol{\mathsf{G}}_{t - 1}} + \sqrt {{\beta _t}} {\boldsymbol{\varepsilon}},
\end{align}
where $\boldsymbol{\varepsilon}$ denotes Gaussian noise with a distribution of $\mathcal{N}( {\boldsymbol{\varepsilon}; {\mathbf{0},\mathbf{I}} } )$. Define ${\alpha _t} = 1 - {\beta _t}$ and ${\overline \alpha  _t} = \prod\nolimits_{i = 1}^t {{\alpha_i}}$. Under the linear Gaussian assumption of the transition density $q( {{\boldsymbol{\mathsf{G}}_t}| {{\boldsymbol{\mathsf{G}}_{t - 1}}} } )$, and by combining \eqref{eq:marginal ddpm} and \eqref{eq:Gt}, we can utilize the reparameterization technique to sample $\boldsymbol{\mathsf{G}}_t$ in closed form at any given time step $t$:
\begin{align}
	\label{eq:ht}
	{{\boldsymbol{\mathsf{G}}}_t} 
	%&= \sqrt {{\alpha _t}} {{\boldsymbol{\mathsf{G}}}_{t - 1}} + \sqrt {1 - {\alpha _t}} {\boldsymbol{\varepsilon}_{t - 1}}\nonumber\\
	%&= \sqrt {{\alpha _t}} \left( {\sqrt {{\alpha _{t - 1}}} {{\boldsymbol{\mathsf{G}}}_{t - 2}} + \sqrt {1 - {\alpha _{t - 1}}} {\boldsymbol{\varepsilon}_{t - 2}}} \right) + \sqrt {1 - {\alpha _t}} {\boldsymbol{\varepsilon}_{t - 1}}\nonumber\\
	%&= \sqrt {{\alpha _t}{\alpha _{t - 1}}} {{\boldsymbol{\mathsf{G}}}_{t - 2}} + \sqrt {{\alpha _t} - {\alpha _t}{\alpha _{t - 1}}} {\boldsymbol{\varepsilon}_{t - 2}} + \sqrt {1 - {\alpha _t}} {\boldsymbol{\varepsilon}_{t - 1}}\nonumber\\
	%&=\sqrt {{\alpha _t}{\alpha _{t - 1}}} {{\boldsymbol{\mathsf{G}}}_{t - 2}} + \sqrt {{{\sqrt {{\alpha _t} - {\alpha _t}{\alpha _{t - 1}}} }^2} + {{\sqrt {1 - {\alpha _t}} }^2}} {\overline {\boldsymbol{\varepsilon}} _{t - 2}}\nonumber\\
	%&= ...... \nonumber\\
	&=\sqrt {{{\overline \alpha  }_t}} {{\boldsymbol{\mathsf{G}}}_0} + \sqrt {1 - {{\overline \alpha  }_t}} \boldsymbol{\varepsilon}, \\
    \label{eq:chmd}
	q\left( {{\boldsymbol{\mathsf{G}}_t}\left| {{\boldsymbol{\mathsf{G}}_0}} \right.} \right) &= \mathcal{N}\left( {{\boldsymbol{\mathsf{G}}_t};\sqrt {{{\overline \alpha  }_t}} {\boldsymbol{\mathsf{G}}_0},\left(1 - {{\overline \alpha  }_t}\right)  \mathbf{I}} \right).
\end{align}
Generally, the variance schedule is generally set as ${\beta _1} < {\beta _2} < ... < {\beta _T}$. When ${\beta _T}$ is set infinitely close to 1, ${{\boldsymbol{\mathsf{G}}}_T}$ converges to a standard Gaussian distribution for any initial state ${{{\boldsymbol{\mathsf{G}}}_0}}$, i.e., $q( {{{\boldsymbol{\mathsf{G}}}_T}| {{{\boldsymbol{\mathsf{G}}}_0}} } ) \approx \mathcal{N}( {{{\boldsymbol{\mathsf{G}}}_T};\mathbf{0},{\mathbf{I}}} )$.

%\subsection{Noise-Based Reverse Process}
\subsection{Reverse Diffusion Process Conditioned on LR CF}
For the traditional GDM \cite{Ho11}, the reverse process can be considered a decoding procedure, where at each time step $t$, ${\boldsymbol{\mathsf{G}}_{t}}$ is denoised and restored to ${\boldsymbol{\mathsf{G}}_{t-1}}$, with the transition probability for each step denoted as ${p( {{\boldsymbol{\mathsf{G}}_{t-1}}| {{\boldsymbol{\mathsf{G}}_{t}}} } )}$. Based on the Markov density transition properties, the joint distribution of the reverse process is expressed as 
\begin{align}\label{eq:}
	p\left( {{{{\boldsymbol{\mathsf{G}}}}_{0:T}}} \right){\text{ }} = p\left( {{{{\boldsymbol{\mathsf{G}}}}_T}} \right)\prod\limits_{t = 1}^T {p\left( {{{{\boldsymbol{\mathsf{G}}}}_{t - 1}}\left| {{{{\boldsymbol{\mathsf{G}}}}_t}} \right.} \right)}.
\end{align}
However, deriving the expression for $p( {{{\boldsymbol{\mathsf{G}}}_{t - 1}}| {{{\boldsymbol{\mathsf{G}}}_t}} } )$ utilizing Bayes' theorem reveals that its denominator contains an integral, which lacks a closed-form solution. Consequently, a denoising neural network with parameters ${{\boldsymbol{{\theta}}}}$ needs to be developed to approximate these conditional probabilities in order to execute the reverse process. Since the reverse process also functions as a Markov chain, it can be represented as
\begin{align}
	\label{eq:29}
	{p}\left( {{{\boldsymbol{\mathsf{G}}}_{0:T}}} \right) &= {p}\left( {{{\boldsymbol{\mathsf{G}}}_T}} \right)\prod\limits_{t = 1}^T {{p_{\boldsymbol{\theta }}}\left( {{{\boldsymbol{\mathsf{G}}}_{t - 1}}\left| {{{\boldsymbol{\mathsf{G}}}_t}} \right.} \right)},\\
	%\end{align}
	%\vspace{-0.45cm} 
	%\begin{align}
	\label{eq:30}
	{p_{{\boldsymbol{\theta}}} }\left( {{{\boldsymbol{\mathsf{G}}}_{t - 1}}\left| {{{\boldsymbol{\mathsf{G}}}_t}} \right.} \right) &= \mathcal{N}\left( {{{\boldsymbol{\mathsf{G}}}_{t - 1}};{{\boldsymbol{\mu}}_{{\boldsymbol{\theta}}} }\left( {{{\boldsymbol{\mathsf{G}}}_t},t} \right),\mathbf{\Sigma}_{{\boldsymbol{\theta}}} {\left( {{{\boldsymbol{\mathsf{G}}}_t},t} \right)} } \right).
\end{align}

\textit{Note that in our task, unlike the traditional GDM, the denoising model ${{{{{\boldsymbol{\varepsilon}}_{\boldsymbol{\theta }}} }}}( \cdot )$ is conditioned on side information in the form of an LR CF ${ \boldsymbol{\dot{\mathsf{G}}}}$, guiding it to progressively denoise from a Gaussian-distributed ${\boldsymbol{\mathsf{G}}_T}$ and generate the HR CF ${\boldsymbol{\mathsf{G}}_0}$. }Therefore, \eqref{eq:29} needs to be rewritten as
\begin{align}
	\label{eq:}
	{p}\left( {{{\boldsymbol{\mathsf{G}}}_{0:T}}} \left| {{ \boldsymbol{\dot{\mathsf{G}}}}} \right. \right) = {p}\left( {{{\boldsymbol{\mathsf{G}}}_T}} \right)\prod\limits_{t = 1}^T {{p_{\boldsymbol{\theta }}}\left( {{{\boldsymbol{\mathsf{G}}}_{t - 1}}\left| {{{\boldsymbol{\mathsf{G}}}_t}, { \boldsymbol{\dot{\mathsf{G}}}}} \right.} \right)},
	%\end{align}
	%\vspace{-0.45cm} 
	%\begin{align}
\end{align}
and the denoising model ${{{{{\boldsymbol{\varepsilon}}_{\boldsymbol{\theta }}} }}}( \cdot )$ is trained to approximate ${p_{{\boldsymbol{\theta}}} }( {{{\boldsymbol{\mathsf{G}}}_{t - 1}}| {{{\boldsymbol{\mathsf{G}}}_t},{ \boldsymbol{\dot{\mathsf{G}}}}} })$, which is defined as
\begin{align}	
	\label{eq:}
	{p_{{\boldsymbol{\theta}}} }\!\left(\! {{{\boldsymbol{\mathsf{G}}}_{t \!-\! 1}}\!\left| {{{\boldsymbol{\mathsf{G}}}_t},\!{ \boldsymbol{\dot{\mathsf{G}}}}} \right.} \!\right) \!\!=\! \mathcal{N}\!\left(\! {{{\boldsymbol{\mathsf{G}}}_{t \!-\! 1}};\!{{\boldsymbol{\mu}}_{{\boldsymbol{\theta}}} }\left({ \boldsymbol{\dot{\mathsf{G}}}}, {{{\boldsymbol{\mathsf{G}}}_t},t} \right)\!,\!\mathbf{\Sigma}_{{\boldsymbol{\theta}}} {\left({ \boldsymbol{\dot{\mathsf{G}}}},\! {{{\boldsymbol{\mathsf{G}}}_t},\!t} \right)} } \!\right)\!\!.
\end{align}

%\subsection{Optimizing the Conditional GDM}
\subsection{ELBO-Based Optimization of the CGDM}
To enable the network model ${{{{{\boldsymbol{\varepsilon}}_{\boldsymbol{\theta }}} }}}( \cdot )$ to effectively approximate the reverse process, the model parameters ${\boldsymbol{\theta}}$ need to be optimized with a specific objective. Mathematically, the latent variables ${{{\boldsymbol{\mathsf{G}}}_{1:T}}}$ and the observed sample ${{{\boldsymbol{\mathsf{G}}}_{0}}}$ \textit{conditioned} on ${ \boldsymbol{\dot{\mathsf{G}}}}$ can be represented utilizing a \textit{conditional} joint distribution $p( {{{{\boldsymbol{\mathsf{G}}}}_{0:T}}}| {{ \boldsymbol{\dot{\mathsf{G}}}}} )$. One common likelihood-based approach in generative modeling involves optimizing the model to maximize the \textit{conditional} joint probability distribution $p( {{{{\boldsymbol{\mathsf{G}}}}_{0:T}}}| {{ \boldsymbol{\dot{\mathsf{G}}}}} )$ of all observed samples. However, we only have access to the observed sample ${\boldsymbol{\mathsf{G}}_0}$ and the latent variables ${{{\boldsymbol{\mathsf{G}}}_{1:T}}}$ are unknown. Therefore, we seek to maximize the \textit{conditional} marginal distribution $p( {{{{\boldsymbol{\mathsf{G}}}}_{0}}}| {{ \boldsymbol{\dot{\mathsf{G}}}}} )$, which is given by
\begin{align}
    p\left( {{{\boldsymbol{\mathsf{G}}}_0}}\left| {{ \boldsymbol{\dot{\mathsf{G}}}}} \right. \right) = \int {p\left( {{{\boldsymbol{\mathsf{G}}}_{0:T}}}\left| {{ \boldsymbol{\dot{\mathsf{G}}}}} \right. \right)} d{{\boldsymbol{\mathsf{G}}}_{1:T}}.
\end{align}
Within the framework of variational inference, the likelihood of the observed sample ${{{\boldsymbol{\mathsf{G}}}_{0}}}$ \textit{conditioned} on ${ \boldsymbol{\dot{\mathsf{G}}}}$, known as the evidence, allows us to derive the ELBO as a proxy objective function, which can be used to optimize CGDM:
\begin{subequations}\label{eq:}
	\begin{align}
    \log p\left( {{{\boldsymbol{\mathsf{G}}}_0}}\left| {{ \boldsymbol{\dot{\mathsf{G}}}}} \right. \right) &= \log \int {p\left( {{{\boldsymbol{{\boldsymbol{\mathsf{G}}}}}_{0:T}}}\left| {{ \boldsymbol{\dot{\mathsf{G}}}}} \right. \right)} d{{\boldsymbol{{\boldsymbol{\mathsf{G}}}}}_{1:T}}\\ 
    %&\!\!= \log \int {\frac{{p\left( {{{\boldsymbol{\mathsf{G}}}_{0:T}}} \right)q\left( {{{\boldsymbol{\mathsf{G}}}_{1:T}}\left| {{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right)}}{{q\left( {{{\boldsymbol{\mathsf{G}}}_{1:T}}\left| {{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right)}}} d{{\boldsymbol{\mathsf{G}}}_{1:T}} \\ 
    %&\!\!= \log {\mathbb{E}_{q\left( {{{\boldsymbol{\mathsf{G}}}_{1:T}}\left| {{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right)}}\left( {\frac{{p\left( {{{\boldsymbol{\mathsf{G}}}_{0:T}}} \right)}}{{q\left( {{{\boldsymbol{\mathsf{G}}}_{1:T}}\left| {{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right)}}} \right)  \\
    &\mathop  \geqslant \limits^{(a)} {\mathbb{E}_{q\left( {{{\boldsymbol{\mathsf{G}}}_{1:T}}\left| {{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right)}}\left( {\log \frac{{p\left( {{{\boldsymbol{\mathsf{G}}}_{0:T}}}\left| {{ \boldsymbol{\dot{\mathsf{G}}}}} \right. \right)}}{{q\left( {{{\boldsymbol{\mathsf{G}}}_{1:T}}\left| {{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right)}}} \right), \label{eq:34f}
    %&\!\!= {\mathbb{E}_{q\left( {{{\boldsymbol{\mathsf{G}}}_{1:T}}\left| {{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right)}}\left( {\log \frac{{p\left( {{{\boldsymbol{\mathsf{G}}}_T}} \right)\prod\limits_{t = 1}^T {{p_{{\boldsymbol{\theta}}}}\left( {{{\boldsymbol{\mathsf{G}}}_{t - 1}}\left| {{{\boldsymbol{\mathsf{G}}}_t},{ \boldsymbol{\dot{\mathsf{G}}}}} \right.} \right)} }}{{\prod\limits_{t = 1}^T {q\left( {{{\boldsymbol{\mathsf{G}}}_t}\left| {{{\boldsymbol{\mathsf{G}}}_{t - 1}}} \right.} \right)} }}} \right)\\
    %&\!\!= {\mathbb{E}_{q\left( {{{\boldsymbol{\mathsf{G}}}_{1:T}}\left| {{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right)}}\!\!\left(\!\! {\log\! \frac{{p\left(\! {{{\boldsymbol{\mathsf{G}}}_T}} \!\right){\!p_{{\boldsymbol{\theta}}}}\!\!\left(\! {{{\boldsymbol{\mathsf{G}}}_0}\!\left|\! {{{\boldsymbol{\mathsf{G}}}_1},\!{ \boldsymbol{\dot{\mathsf{G}}}} } \right.} \!\!\right)\!\prod\limits_{t = 2}^T {{p_{{\boldsymbol{\theta}}}}\!\left(\! {{{\boldsymbol{\mathsf{G}}}_{t - 1}}\!\left| {{{\boldsymbol{\mathsf{G}}}_t},\!{ \boldsymbol{\dot{\mathsf{G}}}} } \right.} \!\right)} }}{{q\left( {{{\boldsymbol{\mathsf{G}}}_1}\left| {{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right)\prod\limits_{t = 2}^T {q\left( {{{\boldsymbol{\mathsf{G}}}_t}\left| {{{\boldsymbol{\mathsf{G}}}_{t - 1}},{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right)} }}} \!\!\right) \label{eq:34f}\!,
	\end{align}
\end{subequations}
where $\mathop  \geqslant \limits^{(a)} $ in \eqref{eq:34f} follows from Jensen's inequality. To further derive the ELBO, \eqref{eq:34f} can be rewritten as \eqref{eq:35e}, displayed at the top of the next page.
