		&\!\!\!\!\!= \underbrace {{\mathbb{E}_{q\left( {{{\boldsymbol{\mathsf{G}}}_1}\left| {{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right)}}\!\left(\! {\log {p_{{\boldsymbol{\theta}}}}\!\left(\! {{{\boldsymbol{\mathsf{G}}}_0}\!\left| {{{\boldsymbol{\mathsf{G}}}_1},\!{ \boldsymbol{\dot{\mathsf{G}}}} } \right.} \!\right)} \!\right)}_{{\mathcal{L}_{\mathbf{a}}}}\!\!-\!\! \underbrace {\sum\limits_{t = 2}^T {{\mathbb{E}_{q\left( {{{\boldsymbol{\mathsf{G}}}_t}\left| {{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right)}}\!\left(\! {{D_{{\text{KL}}}}\!\left(\! {\left. {q\!\left( {{{\boldsymbol{\mathsf{G}}}_{t \!-\! 1}}\!\left| {{{\boldsymbol{\mathsf{G}}}_t},\!{{\boldsymbol{\mathsf{G}}}_0}} \right.} \!\right)} \right\|{p_{\boldsymbol{\theta }}}\!\left(\! {{{\boldsymbol{\mathsf{G}}}_{t\! - \!1}}\!\left| {{{\boldsymbol{\mathsf{G}}}_t},\!{ \boldsymbol{\dot{\mathsf{G}}}} } \right.} \!\!\right)} \!\!\right)} \!\!\right)} }_{{\mathcal{L}_{\mathbf{b}}}} \!\!-\!\! \underbrace {{D_{\text{KL}}}\!\left(\! {\left. {q\!\left(\! {{{\boldsymbol{\mathsf{G}}}_T}\!\left| {{{\boldsymbol{\mathsf{G}}}_0}} \right.}\! \right)} \right\|\!p\!\left(\! {{{\boldsymbol{\mathsf{G}}}_T}} \!\right)} \!\right)}_{{\mathcal{L}_{\mathbf{c}}}}\!\!=\!\! \mathcal{L}_{\text{ELBO}}\!\left( {\boldsymbol{\theta}}  \right) \label{eq:35e}
	\end{align}
\end{subequations}
