Then, the parameters ${\boldsymbol{\theta}}$ of CGDM, can be learned by maximizing the ELBO:
\begin{align}\label{eq:36}
	\mathop {{\text{argmin}}}\limits_{\boldsymbol{\theta}} 
	\mathcal{L}\left( {{\boldsymbol{\theta}}} \right) = {\mathbb{E} }\left( { - {\mathcal{L}_{{\text{ELBO}}}}\left( {{\boldsymbol{\theta}}} \right)} \right) = {\mathbb{E}}\left( {{\mathcal{L}_{\mathbf{c}}} + {\mathcal{L}_{{\mathbf{b}}}} - {\mathcal{L}_{\mathbf{a}}}} \right),
\end{align}
where $\mathcal{L}( \boldsymbol{{\theta}})$ is the objective function for CGDM training, ${\mathcal{L}_{\mathbf{c}}}$ is constant from \eqref{eq:35e} and can be excluded from the optimization, and ${\mathcal{L}_{\mathbf{a}}}$ can be approximated and optimized via a Monte Carlo estimate \cite{Ho11}. From the above analysis, it is evident that the training objective of CGDM is primarily determined by $\mathcal{L}_{{\mathbf{b}}}$. It can be found that the training objective of CGDM is to approximate the transition density in the reverse process as closely as possible, thereby minimizing the Kullback-Leibler (KL) divergence between ${p_{{\boldsymbol{\theta}}} }\!\left(\! {{{\boldsymbol{\mathsf{G}}}_{t - 1}}\!\left| {{{\boldsymbol{\mathsf{G}}}_t},{ \boldsymbol{\dot{\mathsf{G}}}}} \right.} \!\right) = \mathcal{N}\left(\! {{{\boldsymbol{\mathsf{G}}}_{t - 1}};{{\boldsymbol{\mu}}_{{\boldsymbol{\theta}}} }\left({ \boldsymbol{\dot{\mathsf{G}}}}, {{{\boldsymbol{\mathsf{G}}}_t},t} \right),\mathbf{\Sigma}_{{\boldsymbol{\theta}}} {\left({ \boldsymbol{\dot{\mathsf{G}}}}, {{{\boldsymbol{\mathsf{G}}}_t},t} \right)} } \!\right)$ and $q\left( {{{\boldsymbol{\mathsf{G}}}_{t - 1}}\left| {{{\boldsymbol{\mathsf{G}}}_t},{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right) = \mathcal{N}\left( {{{\boldsymbol{\mathsf{G}}}_{t - 1}};{{{{\tilde {\boldsymbol{\mu}}_t} }}}\left( {{{\boldsymbol{\mathsf{G}}}_t},{{\boldsymbol{\mathsf{G}}}_0}} \right),{{\tilde \beta }_t}{\mathbf{I}}} \right)$.


Therefore, we need to obtain explicit expressions for the mean ${{{{\tilde {\boldsymbol{\mu}}_t} }}}( {{{\boldsymbol{\mathsf{G}}}_t},{{\boldsymbol{\mathsf{G}}}_0}})$ and variance ${{\tilde \beta }_t}{\mathbf{I}}$ of $q( {{{\boldsymbol{\mathsf{G}}}_{t - 1}}| {{{\boldsymbol{\mathsf{G}}}_t},{{\boldsymbol{\mathsf{G}}}_0}} } )$. Specifically, $q( {{{\boldsymbol{\mathsf{G}}}_{t - 1}}| {{{\boldsymbol{\mathsf{G}}}_t},{{\boldsymbol{\mathsf{G}}}_0}} } )$ can be expressed as
\begin{align}\label{eq:qt-1}
	q\left( {{{{\boldsymbol{\mathsf{G}}}}_{t - 1}}\left| {{{{\boldsymbol{\mathsf{G}}}}_t},{{{\boldsymbol{\mathsf{G}}}}_0}} \right.} \right) 
	%&= \frac{{q\left( {{{{\boldsymbol{\mathsf{G}}}}_{t - 1}},{{{\boldsymbol{\mathsf{G}}}}_t},{{{\boldsymbol{\mathsf{G}}}}_0}} \right)}}{{q\left( {{{{\boldsymbol{\mathsf{G}}}}_t},{{{\boldsymbol{\mathsf{G}}}}_0}} \right)}}\nonumber\\
	%&= \frac{{q\left( {{{{\boldsymbol{\mathsf{G}}}}_t}|{{{\boldsymbol{\mathsf{G}}}}_{t - 1}},{{{\boldsymbol{\mathsf{G}}}}_0}} \right)q\left( {{{{\boldsymbol{\mathsf{G}}}}_{t - 1}}|{{{\boldsymbol{\mathsf{G}}}}_0}} \right)q\left( {{{{\boldsymbol{\mathsf{G}}}}_0}} \right)}}{{q\left( {{{{\boldsymbol{\mathsf{G}}}}_t}|{{{\boldsymbol{\mathsf{G}}}}_0}} \right)q\left( {{{{\boldsymbol{\mathsf{G}}}}_0}} \right)}}\nonumber\\
	= \frac{{q\left( {{{{\boldsymbol{\mathsf{G}}}}_t}|{{{\boldsymbol{\mathsf{G}}}}_{t - 1}},{{{\boldsymbol{\mathsf{G}}}}_0}} \right)q\left( {{{{\boldsymbol{\mathsf{G}}}}_{t - 1}}|{{{\boldsymbol{\mathsf{G}}}}_0}} \right)}}{{q\left( {{{{\boldsymbol{\mathsf{G}}}}_t}|{{{\boldsymbol{\mathsf{G}}}}_0}} \right)}}.
\end{align}
Combining \eqref{eq:ht} and \eqref{eq:chmd}, \eqref{eq:qt-1} can be further rewritten as \eqref{eq:38e}, displayed at the top of this page.
