%\end{align}

Recall that the KL divergence is defined as 
\begin{align}\label{eq:kl}
	{D_{\rm{KL}}}&\left( {\mathcal{N}\left( {\bf{x};{{\boldsymbol{\mu }}_{\bf{x}}},{{\mathbf{\Sigma }}_{\bf{x}}}} \right)\left\| {\mathcal{N}\left( {{\bf{y}};{{\boldsymbol{\mu }}_{\bf{y}}},{{\mathbf{\Sigma }}_{\bf{y}}}} \right)} \right.} \right) = \frac{1}{2}\Big[\log \frac{{\left| {{{\mathbf{\Sigma }}_{\bf{y}}}} \right|}}{{\left| {{{\mathbf{\Sigma }}_{\bf{x}}}} \right|}} - d \nonumber\\
	&+ {\rm{tr}}\left( {{\mathbf{\Sigma }}_{\bf{y}}^{ - 1}{{\mathbf{\Sigma }}_{\bf{x}}}} \right) + {\left( {{{\boldsymbol{\mu }}_{\bf{y}}} - {{\boldsymbol{\mu }}_{\bf{x}}}} \right)^T}{\mathbf{\Sigma }}_{\bf{y}}^{ - 1}\left( {{{\boldsymbol{\mu }}_{\bf{y}}} - {{\boldsymbol{\mu }}_{\bf{x}}}} \right)\Big],
\end{align}
where $d$ represents the dimension of $\bf{x}$. Substituting \eqref{eq:41}, \eqref{eq:42}, and \eqref{eq:kl} into $\mathcal{L}_{{\mathbf{b}}}$ in \eqref{eq:35e}, yields
\begin{align}\label{eq:45}
  \!\mathcal{L}_{{\mathbf{b}}} 
  %&= \prod\limits_{t = 2}^T  {\mathbb{E}_{q\left( {{{\boldsymbol{\mathsf{G}}}_t}\left| {{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right)}}\left( {\frac{1}{{2\tilde \beta _t^2}}\left\| {{{{{\tilde {\boldsymbol{\mu}}_t} }}}\left( {{{\boldsymbol{\mathsf{G}}}_t},{{\boldsymbol{\mathsf{G}}}_0}} \right) - {{\boldsymbol{\mu}}_{\boldsymbol{\theta }}}\left( {{ \boldsymbol{\dot{\mathsf{G}}}} ,{{\boldsymbol{\mathsf{G}}}_t},t} \right)} \right\|_2^2} \right) \nonumber \\
  \!\!=\!\! \prod\limits_{t = 2}^T  \!{\mathbb{E}_{q\left( {{{\boldsymbol{\mathsf{G}}}_t}\left| {{{\boldsymbol{\mathsf{G}}}_0}} \right.} \right)}}\!\!\left(\! {\frac{{{{\left(\! {1 \!-\! {\alpha _t}} \!\right)}^2}}}{{2\tilde \beta _t^2{\alpha _t}\left(\! {1 \!-\! {{\bar \alpha }_t}} \!\right)}}\!\left\| {{{\boldsymbol{\varepsilon }}_t} \!-\! {{\boldsymbol{\varepsilon }}_{\boldsymbol{\theta }}}\left(\! {{ \boldsymbol{\dot{\mathsf{G}}}} ,{{\boldsymbol{\mathsf{G}}}_t},t} \!\right)} \right\|_2^2} \!\right)\!.
\end{align}
Substituting \eqref{eq:35e} and \eqref{eq:45} into \eqref{eq:36}, the objective function $\mathcal{L}( \boldsymbol{{\theta}})$ for the CGDM can be further simplified to
\begin{align}\label{eq:46} 
	\!\!\!\!\! {\underline {\mathcal{L}}} (\boldsymbol{\theta}) \!\!&:=\!\!\! \sum\limits_{t = 1}^T\!{\mathbb{E}_{{{{{\boldsymbol{\mathsf{G}}}_0}}}\!,{{\boldsymbol{\varepsilon }}_t} }}\!\Big( \!\big\| {{\boldsymbol{\varepsilon }}_t} \!\!-\!\! {{\boldsymbol{\varepsilon }}_{\boldsymbol{\theta }}}\big({{ \boldsymbol{\dot{\mathsf{G}}}}},\! \underbrace{\sqrt {{{\bar \alpha }_t}} {{{\boldsymbol{\mathsf{G}}}_0}} \!+\! \sqrt {1 \!-\! {{\bar \alpha }_t}} {{\boldsymbol{\varepsilon }}}}_{{{\boldsymbol{\mathsf{G}}}_t}},\!t \big) \big\|_2^2 \Big)\!.\!\!\!\!\!\!\!
\end{align}
Based on the trained CGDM, given any noise-contaminated CF ${{\boldsymbol{\mathsf{G}}}_t}$, the trained CGDM can leverage the side information in ${{ \boldsymbol{\dot{\mathsf{G}}}}}$ to predict the noise ${{\boldsymbol{\varepsilon }}_t}$ and subsequently obtain an approximation of the target CF ${{\hat{{\boldsymbol{\mathsf{G}}}}_0}}$ through transformation \eqref{eq:ht}, i.e., 
\begin{align}\label{eq:47}
	{{\hat{{\boldsymbol{\mathsf{G}}}}_0}} \!=\! \frac{1}{{\sqrt {{{\bar \alpha }_t}} }}\!\!\left(\!\! {{{{\boldsymbol{\mathsf{G}}}_t}} \!-\! \sqrt {1 \!-\! {{\bar \alpha }_t}} {{\boldsymbol{\varepsilon }}_{\boldsymbol{\theta }}}\big({{ \boldsymbol{\dot{\mathsf{G}}}}}, \underbrace{\sqrt {{{\bar \alpha }_t}} {{{\boldsymbol{\mathsf{G}}}_0}} \!+\! \sqrt {1 \!-\! {{\bar \alpha }_t}} {{\boldsymbol{\varepsilon }}}}_{{{\boldsymbol{\mathsf{G}}}_t}},t \big)} \!\!\right)\!.
\end{align}
Through reparameterization, \eqref{eq:47} represents the results of iterative refinements, with each iteration in our proposed CGDM being represented by 
\begin{align}\label{eq:48}
	\!\!\!\!\!{{{\boldsymbol{\mathsf{G}}}_{t\!-\!1}}} \!\leftarrow\! \frac{1}{{\sqrt {{\alpha _t}} }}\!\!\left(\!\! {{{{\boldsymbol{\mathsf{G}}}}_t} \!\!-\!\! \frac{{1 \!-\! {\alpha _t}}}{{\sqrt {1 \!-\! {{\bar \alpha }_t}} }}{{\boldsymbol{\varepsilon}}_{\boldsymbol{\theta }}}\!\left(\!{{ \boldsymbol{\dot{\mathsf{G}}}}, {{\boldsymbol{\mathsf{G}}}_t},t} \!\right)} \!\!\right) \!+\! \sqrt { \frac{{1 \!-\! {{\bar \alpha }_{t \!-\! 1}}}}{{1 \!-\! {{\bar \alpha }_t}}}{\beta _t}} {\boldsymbol{\varepsilon}^*},\!\!\!\!\!\!
\end{align}
where ${\boldsymbol{\varepsilon}^*} \sim\mathcal{N}( {\mathbf{0},\mathbf{I}})$. Note that the noise estimation step in \eqref{eq:48} is analogous to a step in Langevin dynamics within score-based generative models \cite{song2019generative}, which is equivalent to the estimation of the first derivative of the log-likelihood of the observed samples, also known as the gradient or Stein score. For clarity, we summarize the training process and iterative inference process of the proposed CGDM in \textbf{\alref{alg:train}} and \textbf{\alref{alg:infer}}, respectively. 

