\subsection{Network Architecture of the Proposed CGDM}\label{subsec:net}
In this subsection, we present the architecture of CGDM, a variant of the U-Net model, as illustrated in \figref{fig:model}. The network is composed of three primary stages: Dn, Mid, and Up. For clarity, we provide a concise overview of the key components in each stage, including the time embedding block, Res$^+$ block, self-attention block, downsampling block, and upsampling block.

\textit{1) Time Embedding Block:} 
In order to encode the time parameter $[1,..., t,...,T]$ in the diffusion process, sine and cosine functions with different frequencies are employed, akin to the sinusoidal positional encoding approach used in \cite{vaswani2017attention}. This approach results in the time embedding vector ${{\mathbf{\Gamma }}}_t$, which effectively captures the temporal characteristics. Let ${{{\Gamma }}}^j_t \in {\mathbb{R}}$ denote the $j$-th component of the time embedding vector at time step $t$, defined as 
\begin{align}\label{eq：}
	{{\Gamma}}_t^{(j)} = \left\{ \begin{gathered}
		\cos \left( {\frac{t}{{{{10000}^{{{2j} \mathord{\left/
									{\vphantom {{2j} {{c_{{\rm{time}}}}}}} \right.
									\kern-\nulldelimiterspace} {{c_{{\rm{time}}}}}}}}}}} \right),\text{ if}\quad j \quad \text{is odd}\hfill \\ 
	   \sin \left( {\frac{t}{{{{10000}^{{{2j} \mathord{\left/
	   							{\vphantom {{2j} {{c_{{\rm{time}}}}}}} \right.
	   							\kern-\nulldelimiterspace} {{c_{{\rm{time}}}}}}}}}}} \right),\text{ if}\quad j \quad \text{is even} \hfill \\
	\end{gathered}  \right.,
\end{align}
where $j = 0,1,2,...,{c_{{\rm{time}}}}/2-1$, $c_{{\rm{time}}}$ is the dimension of the time embedding vector. Then, the embedding vector for the time constant $t$ can be expressed as
\begin{align}\label{eq:50}
	{{\mathbf{\Gamma }}}_t &= \Big[\sin \big( {{w_0}t} \big),\cos \big( {{w_0}t} \big),\sin \big( {{w_1}t} \big),\cos \big( {{w_1}t} \big),\nonumber \\
	&\qquad\qquad \ldots,\sin \big( {{w_{\tfrac{{{c_{{\rm{time}}}}}}{2} - 1}}t} \big),\cos \big( {{w_{\tfrac{{{c_{{\rm{time}}}}}}{2} - 1}}t} \big)\Big],
\end{align}
where ${w_j} = {1 \mathord{\left/
		{\vphantom {1 {{{10000}^{{{2j} \mathord{\left/
									{\vphantom {{2j} {{c_{{\text{time}}}}}}} \right.
									\kern-\nulldelimiterspace} {{c_{{\rm{time}}}}}}}}}}} \right.
		\kern-\nulldelimiterspace} {{{10000}^{{{2j} \mathord{\left/
						{\vphantom {{2j} {{c_{{\rm{time}}}}}}} \right.
						\kern-\nulldelimiterspace} {{c_{{\text{time}}}}}}}}}}$. Leveraging \eqref{eq:50}, the embedding vectors for any given time ${{\mathbf{\Gamma }}}_{t + \Delta t}$ can be obtained through a linear transformation expressed as					
\begin{align}\label{eq：51}
	{{\mathbf{\Gamma }}}_{t + \Delta t}^T = \left[ {\begin{array}{*{20}{c}}
			{\sin \Big( {{w_0}\big( {t + \Delta t} \big)} \Big)} \\ 
			{\cos \Big( {{w_0}\big( {t + \Delta t} \big)} \Big)} \\ 
			...\\
			{\sin \Big( {{w_{\tfrac{{{c_{{\rm{time}}}}}}{2} - 1}}\big( {t + \Delta t} \big)} \Big)} \\
			{\cos \Big( {{w_{\tfrac{{{c_{{\rm{time}}}}}}{2} - 1}}\big( {t + \Delta t} \big)} \Big)} 
	\end{array}} \right] = {{\bf{M}}_{\Delta t}} \cdot {{\mathbf{\Gamma }}}_t^T.
\end{align}
${\bf{M}}_{\Delta t}$ is a linear transform matrix defined as 
\begin{align}
	\mathbf{M}_{\Delta t}=\begin{pmatrix}\mathbf{R}(w_0\Delta t)&\cdots&0\\\vdots&\ddots&\vdots\\0&\cdots&\mathbf{R}\left(w_{\frac{c_{\mathrm{time}}}{2}-1}\Delta t\right)\end{pmatrix},
\end{align}
where $\mathbf{R}(w_0\Delta t)=\begin{bmatrix}\cos(w_0\Delta t)&&\sin(w_0\Delta t)\\-\sin(w_0\Delta t)&&\cos(w_0\Delta t)\end{bmatrix}$. To enable the model to capture more intricate temporal features, the time embedding is further enhanced through two fully connected layers and an activation layer, expressed as ${{{{{\mathbf{\Gamma }}'}}}_t} = {f_{{\rm{Ful}}}}( {{f_{{\rm{Swi}}}}( {{f_{{\rm{Ful}}}}( {{{\mathbf{\Gamma }}}_t} )} )} )$, where ${f_{{\rm{Ful}}}}(  \cdot  )$ and ${f_{{\rm{Swi}}}}(  \cdot  )$ represent the fully connected layer and swish activation function layer, respectively. The components of the time embedding block are summarized in \figref{fig:model} (f).



\textit{2) Res$^+$ Block:} We design deeper feature extraction networks aimed at learning higher-level semantic information from the CF. Nonetheless, deep neural networks frequently experience model degradation as a result of challenges like vanishing and exploding gradients. To this end, we introduce residual connections as a means of alleviating these concerns. Specifically, let ${\bf{X}} \in {\mathbb{R}^{{h_{{\rm{in}}}} \times {w_{{\rm{in}}}} \times {c_{{\rm{in}}}}}}$, ${{\mathbf{\Gamma }}}_t$ be the feature map and time embedding vector inputs, respectively. The output ${\bf{X}}'\in {\mathbb{R}^{{h_{{\rm{in}}}} \times {w_{{\rm{in}}}} \times {c_{{\rm{out}}}}}}$ of Res$^+$ block is given by
\begin{align}\label{eq：}
	{\bf{X}}' = \left\{ \begin{gathered}
		\boldsymbol{\Omega }  + {{f}_{{\rm{Conv}},1}}\left( {\bf{X}} \right),\text{ if }{c_{{\rm{out}}}} \ne {c_{{\rm{in}}}} \hfill \\
		\boldsymbol{\Omega }  + {\bf{X}},\text{ else} \hfill \\ 
	\end{gathered}  \right.,
\end{align}
where ${f_{{\rm{Conv}},1}}( \cdot) $ denotes $1\times 1$ convolution operation, and $\boldsymbol{\Omega }  \in {\mathbb{R}^{{h_{{\rm{in}}}} \times {w_{{\rm{in}}}} \times {c_{{\rm{out}}}}}}$ is defined as
\begin{align}
  {\boldsymbol{\Omega}}  = g\left( {g({\mathbf{X}}) + {f_{{\text{Ful}}}}\left( {{f_{{\text{Swi}}}}\left( {{f_{{\text{Ful}}}}\left( {{{\mathbf{{{\Gamma }}}}_t}} \right)} \right)} \right)} \right).
\end{align}
Note that $g({\mathbf{X}}) = {f_{{\rm{Conv}},3}}( {{f_{{\rm{Dro}}}}( {{f_{{\text{Swi}}}}( {{f_{{\rm{Gn}}}}( {\mathbf{X}} )} )} )} )$, where ${f_{{\rm{Conv}},3}}(\cdot ) $ is $3\times3$ convolution operation. ${f_{{\rm{Dro}}}}(  \cdot )$, ${f_{{\rm{Gn}}}}(  \cdot )$ are the dropout and group normalization layers, respectively. The components of the Res$^+$ block are summarized in \figref{fig:model} (a).

\textit{3) Self-Attention Block:} To capture global structural information, we introduce a self-attention mechanism to improve the interaction between global and local features. Specifically, to implement the self-attention mechanism, a normalized attention matrix is introduced to represent varying degrees of attention to the input. Greater weights are assigned to more significant input components. The final output is generated by weighting the input according to the attention weights indicated in the attention matrix. Specifically, given the input $\mathbf{Z}\! =\! {[{\mathbf{z}_1},...,{\mathbf{z}_m}]^T} \in {\mathbb{R}^{{d_m} \times {d_n}}}$, ${{d_m}}$ denotes the number of image patches and ${{d_n}}$ is the feature dimension of each patch, three different linear transformations are applied to ${\mathbf{z}_j}$ \cite{9613212,vaswani2017attention}:
\begin{subequations}\label{eq:spdb}
	\begin{align}
		{\mathbf{k}_j} &= {\mathbf{z}_j}{\mathbf{W}^k},\quad j = 1,...,{d_n},\label{eq:dbso}\\
		{\mathbf{q}_j} &= {\mathbf{z}_j}{\mathbf{W}^q},\quad j = 1,...,{d_n},\label{eq:dbsc}\\
		{\mathbf{v}_j} &= {\mathbf{z}_j}{\mathbf{W}^v},\quad j = 1,...,{d_n},\label{eq:dbss} 
	\end{align}
\end{subequations}
where ${\mathbf{k}_j} \in {\mathbb{R}^{1 \times {d_k}}}$, ${\mathbf{q}_j} \in {\mathbb{R}^{1 \times {d_q}}}$, and ${\mathbf{v}_j} \in {\mathbb{R}^{1 \times {d_n}}}$ are the key, query, and value vector, respectively. ${\mathbf{W}^k} \in {\mathbb{R}^{{d_n} \times {d_k}}}$, ${\mathbf{W}^q} \in {\mathbb{R}^{{d_n} \times {d_q}}}$, and ${\mathbf{W}^v} \in {\mathbb{R}^{{d_n}\times {d_n}}}$ represent the respective trainable transformation matrices, with ${d_k} = {d_q}$. In detail, the weight allocation function is determined by ${\mathbf{k}_j}$ and ${\mathbf{q}_{j'}}$. A higher correlation ${\mathbf{q}_{j'}}\mathbf{k}_j^T$ implies that the features of the $j$-th input patch ${\mathbf{z}_j}$ hold greater importance for the ${j'}$-th output patch. Generally, this correlation can be adaptively adjusted based on the input $\mathbf{Z}$ and the matrices ${\mathbf{W}^k}$ and ${\mathbf{W}^q}$. For clarity, the matrix forms of \eqref{eq:dbso}-\eqref{eq:dbss} are presented as ${\mathbf{K}} = {\mathbf{Z}}{\mathbf{W}^k}$, ${\mathbf{Q}} = {\mathbf{Z}}{\mathbf{W}^q}$, ${\mathbf{V}} = {\mathbf{Z}}{\mathbf{W}^v}$,
%\begin{subequations}\label{eq:spd}
%	\begin{align}
	%		{\mathbf{K}} &= {\mathbf{Z}}{\mathbf{W}^k},\label{eq:bso}\\
	%		{\mathbf{Q}} &= {\mathbf{Z}}{\mathbf{W}^q},\label{eq:bsc}\\
	%		{\mathbf{V}} &= {\mathbf{Z}}{\mathbf{W}^v},\label{eq:bsc}
	%	\end{align}
%\end{subequations}
where $\mathbf{K} = {[{\mathbf{k}_1},...,{\mathbf{k}_m}]^T} \in {\mathbb{R}^{{d_m} \times {d_k}}}$, $\mathbf{Q} = {[{\mathbf{q}_1},...,{\mathbf{q}_m}]^T} \in {\mathbb{R}^{{d_m} \times {d_q}}}$ and $\mathbf{V} = {[{\mathbf{v}_1},...,{\mathbf{v}_m}]^T} \in {\mathbb{R}^{{d_m} \times {d_n}}}$.

Leveraging $\mathbf{K}$ and $\mathbf{Q}$, we can obtain the attention matrix $\mathbf{S}_{\rm{AM}}  \in {\mathbb{R}^{{d_m} \times {d_m}}}$, which is denoted as 
\begin{align}\label{eq:cchmd}
	\mathbf{S}_{\rm{AM}}  = \rm{Softmax} \left( {\frac{{\mathbf{Q}{\mathbf{K}^\textit{T}}}}{{\mathit{\sqrt \eta} }}} \right),
	%\mathbf{AM} = \rm Softmax \left( {\frac{{\mathbf{Q}{\mathbf{K}^T}}}{{\sqrt {\textit{d}} }}} \right),
\end{align}
where $\rm{Softmax} ( \mathbf{Z})  = {\exp ( \mathit{{z_j}}) }/{{\sum {\exp ( \mathit{{z_j}}) } }}$, and $\sqrt \eta >0$ is a scaling factor. Each column of the attention matrix is a vector of attention scores, i.e., each score is a probability, where all scores are non-negative and sum up to 1. Note that when the key vector $\mathbf{K}[j,:]$ and the query $\mathbf{Q}[j',:]$ has a better match, the corresponding attention score $\mathbf{S}_{\rm{AM}} [j',j]$ is higher. Thus, the output of the attention mechanism corresponding to the $r$-th component can be represented by the weighted sum of all inputs, i.e., ${\mathbf{z}'_r} = \sum\nolimits_j {\mathbf{S}_{\rm{AM}}  [r,j]{\mathbf{v}_j}}  = \mathbf{S}_{\rm{AM}}  [r,:] \cdot \mathbf{V}$, where ${\mathbf{z}'_r} \in {\mathbb{R}^{1 \times {d_n}}}$ represents the $r$-th output, which is computed by adaptively focusing on the inputs based on the attention score $\mathbf{S}_{\rm{AM}}[r,j]$. When the attention score $\mathbf{S}_{\rm{AM}}[r,j]$ is higher, the associated value vector ${\mathbf{v}_j}$ will have a more significant impact on the $r$-th output patch. Finally, the output ${\bf{Z}}'$ of the attention block is given by 
\begin{align}\label{eq:cmd}
	{\bf{Z}}' \!=\!\mathbf{S}_{\rm{AM}}[:,:]\cdot \mathbf{V}\!=\!\rm{Softmax}\mathit{\left( {\frac{{\mathbf{Z}{\mathbf{W}^q}{\mathbf{W}^{{k^T}}}{\mathbf{Z}^T}}}{{\sqrt \eta }}} \right)\mathbf{Z}{\mathbf{W}^v}},
\end{align}
where $\mathbf{O} = {[{\mathbf{o}_{1,...,}}{\mathbf{o}_m}]^T} \in {\mathbb{R}^{{d_m} \times {d_n}}}$. The components of the self-attention block are summarized in \figref{fig:model} (b). Notably, as illustrated in \figref{fig:model}, the network framework of the proposed CGDM consists of three primary stages: Dn, Mid, and Up. Each sub-stage within these stages comprises $N_{\rm{RA}}$ Res$^+$ blocks, along with their corresponding self-attention blocks.

\section{Lightweight CGDM for SR CF}\label{sec:}
Considering that the proposed CGDM trades off significant memory consumption and latency for outstanding performance, its deployment on personal computers and even mobile devices is highly constrained. Specifically, CGDM utilizes a variant of U-Net as their backbone framework, with most of the memory consumption and latency arising from this architecture. To this end, in this section, we leverage the additive property of network layers and design a one-shot pruning approach along with the corresponding knowledge distillation technique to obtain a lightweight CGDM (LiCGDM). 
%In this section, to further lightweight the CGDM, we leverage the additive property of network layers and design a one-shot pruning approach along with the corresponding knowledge distillation technique, 以获得一个轻量化的CGDM
%we propose one-shot layer pruning and normalized knowledge distillation to reduce the computational budget of CGDM and make it more lightweight, thereby mitigating this challenging practical constraint.
%However, the majority of the memory consumption and latency in these models originate from their U-Net architecture.

\begin{algorithm}[!b]
	\caption{Efficient Layer Pruning for LiCGDM}
	\label{alg:algtrhpf}
	\begin{algorithmic}[1]
		\STATE \textbf{Input:} A teacher (original) network with prunable layers ${\tilde L^{\tilde n}} = \left\{ {{{\tilde l}_1},...,{{\tilde l}_{\tilde n}}} \right\}$, a CF dataset $D$, the number of parameters $\mathcal{P}$ to be pruned
		\STATE \textbf{Initialize:} Arrays $values [\text{ }]=0$ and $weights [\text{ }]=0$, Knapsack capacity $\mathcal{C}=0$
		%\ENSURE Equivalent fully digital precoder $\bB\left[m\right],\ m=1,2,\cdots, M$
		%\STATE Initialize $\bW_{\rm RF}^{(0)}$, $\bW_{\rm BB}^{(0)}$, and $\bU^{(0)}$
		\FOR{${p_i}$ in ${\tilde L^{\tilde n}}$ }
		%\REPEAT
		\STATE
		Calculate the value of the objective function \eqref{eq:61a} on $D$, $values [i]=\mathbb{E}\left\|  {{{\boldsymbol{\varepsilon }}_{{\text{tea}}}} - {\boldsymbol{\varepsilon }}\left( {{p_i}} \right)} \right\|_2^2$ 
		\STATE
		Calculate the number of parameters at the $p_i$-th layer, $weights [i]={\rm{Params}}\left(p_i \right) $
		%\STATE Update $\bU$, $\bW_{\rm BB}$, and $\bW_{\rm RF}$, based on Eqs. \eqref{eq:optU}, \eqref{eq:optW}, and \eqref{eq:optV}
		%\STATE $c = c+1$
		%\UNTIL $c\geq c_{\rm max}$ or ${f^{(c)}-f^{(c-1)}}<\epsilon_2$
		\ENDFOR
		\STATE
		$\mathcal{C}=\mathcal{P}$
		\STATE
		Obtain $P^{\tilde m}$ by solving problem \eqref{eq:61} using the dynamic programming algorithm, given $values$, $weights$, $\mathcal{C}$.
		\STATE \textbf{Return} $P^{\tilde m}$
		\STATE \textbf{Output:} The set of layers to be pruned $P^{\tilde m} \in {\tilde L^{\tilde n}} $
	\end{algorithmic}
\end{algorithm}
\subsection{Efficient Layer Pruning for CGDM}
Given a specific pruning ratio, the objective of layer pruning is to eliminate a subset of prunable layers from the U-Net architecture in CGDM while minimizing the degradation in the model's performance. We define the set of all the ${\tilde n}$ prunable layers as ${\tilde L^{\tilde n}} = \{ {{{\tilde l}_1},...,{{\tilde l}_{\tilde n}}} \}$. Inspired by \cite{zhang2024laptop}, we also minimize the mean-squared-error (MSE) loss between the final output of the original network (referred to as the teacher) and that of the pruned network (referred to as the student) as the pruning objective. Specifically, let ${{{{{\boldsymbol{\varepsilon}}_{{\rm{tea}}}} }}}$ define the output of the original CGDM, $p_i \in {\tilde L^{\tilde n}} $ represent the $p$-th pruned layer, and ${{{{{\boldsymbol{\varepsilon}}} ( p_1,p_2,...,p_{\tilde m})  }}}$ denote the output of the network with layers $p_1$,$p_2$,..., $p_{\tilde m}$ pruned, where ${\tilde m}$ is an uncertain variable. Thus, this optimization problem can be formulated as
\begin{subequations}\label{eq:57}
	\begin{align}
		&\quad\mathop {\min }\limits_{{p_1},{p_2},...,{p_{\tilde m}}} \mathbb{E}\left\| {{{{{{\boldsymbol{\varepsilon}}_{{\rm{tea}}}} }}} - {{{{{\boldsymbol{\varepsilon}}} \left( p_1,p_2,...,p_{\tilde m}\right)  }}}} \right\|_2^2,\label{eq:57a}\\
		&{\rm{s.t.}}\left\lbrace {{p_1},{p_2},...,{p_{\tilde m}}} \right\rbrace  \subset {{\tilde L}^{\tilde n}},\sum\limits_{i = 1}^{\tilde m} {\rm{Params}} \left( {{p_i}} \right) \geq \mathcal{P},\label{eq:57b}
	\end{align}
\end{subequations}
where ${\rm{Params}} \left( {p_i} \right)$ represents the number of parameters in the $p_i$-th layer. Note that $\mathcal{P}$ denotes the number of parameters to be pruned, calculated by multiplying the total number of parameters in the teacher network by the pruning ratio. Solving the optimization problems \eqref{eq:57} is NP-hard; therefore, we need to find a surrogate objective. Capitalizing on the triangle inequality, we can obtain the upper bound of \eqref{eq:57a}:
\begin{align}\label{eq:}
	&\quad\mathbb{E}\left\| {{{\boldsymbol{\varepsilon }}_{{\text{tea}}}} - {\boldsymbol{\varepsilon }}\left( {{p_1},{p_2},...,{p_{\tilde m}}} \right)} \right\|_2^2 \leq \mathcal{L}_{{\rm{upper}}},
\end{align}
where $\mathcal{L}_{{\rm{upper}}}\!=\! \mathbb{E}\left\| {{{\boldsymbol{\varepsilon }}_{{\text{tea}}}} - {\boldsymbol{\varepsilon }}\left( {{p_1}} \right)} \right\|_2^2 + \mathbb{E}\left\| {{\boldsymbol{\varepsilon }}\left( {{p_1}} \right) - {\boldsymbol{\varepsilon }}\left( {{p_1},{p_2}} \right)} \right\|_2^2 + ... + \mathbb{E}\left\| {{\boldsymbol{\varepsilon }}\left( {{p_1},{p_2},...,{p_{\tilde m - 1}}} \right) - {\boldsymbol{\varepsilon }}\left( {{p_1},{p_2},...,{p_{\tilde m}}} \right)} \right\|_2^2$. Then, \eqref{eq:57} can be further transformed as
\begin{subequations}\label{eq:59}
	\begin{align}
	    &\qquad\qquad\qquad\quad\mathop {\min }\limits_{{p_1},{p_2},...,{p_{\tilde m}}} \mathcal{L}_{{\rm{upper}}},\label{eq:59a}\\
		&{\rm{s.t.}}\left\lbrace {{p_1},{p_2},...,{p_{\tilde m}}} \right\rbrace  \subset {{\tilde L}^{\tilde n}},\sum\limits_{i = 1}^{\tilde m} {\rm{Params}} \left( {{p_i}} \right) \geq \mathcal{P}.\label{eq:59b}
	\end{align}
\end{subequations}

However, solving the surrogate objective \eqref{eq:59a} also remains NP-hard. Note that each term in \eqref{eq:59a} represents the MSE between a pruned or unpruned network and the same network with an additional layer pruned. By leveraging the additive property of network layer, where the output distortion caused by multiple perturbations can be approximated as the sum of the distortions caused by each individual perturbation, this additivity is formulated as \cite{xu2023efficient,zhang2024laptop}
\begin{align}\label{eq:60}
	&\mathbb{E}\left\| {{\boldsymbol{\varepsilon }}\left( {{p_1},...,{p_{i - 1}},{p_i}} \right) - {\boldsymbol{\varepsilon }}\left( {{p_1},...,{p_{i - 1}}} \right)} \right\|_2^2 \nonumber \\
    &\!\!\approx \mathbb{E}\left\| {{\boldsymbol{\varepsilon }}\left( {{p_1},...,{p_{i - 2}},{p_i}} \right) - {\boldsymbol{\varepsilon }}\left( {{p_1},...,{p_{i - 2}}} \right)} \right\|_2^2 \nonumber \\
	&\!\!\approx ... \approx \mathbb{E}\left\| {{\boldsymbol{\varepsilon }}\left( {{p_1},{p_i}} \right) - {\boldsymbol{\varepsilon }}\left( {{p_1}} \right)} \right\|_2^2 \approx \mathbb{E}\left\| {{\boldsymbol{\varepsilon }}\left( {{p_i}} \right) - {{\boldsymbol{\varepsilon }}_{{\rm{tea}}}}} \right\|_2^2.
\end{align}
Leveraging \eqref{eq:60}, the surrogate objective in \eqref{eq:59} can be further approximated as 
\begin{subequations}\label{eq:61}
	\begin{align}
		&\quad\quad\quad\mathop {\min }\limits_{{p_1},{p_2},...,{p_{\tilde m}}} \sum\limits_{i = 1}^{\tilde m}\mathbb{E}\left\|  {{{\boldsymbol{\varepsilon }}_{{\text{tea}}}} - {\boldsymbol{\varepsilon }}\left( {{p_i}} \right)} \right\|_2^2,\label{eq:61a}\\
		&\quad{\rm{s.t.}}\left\lbrace {{p_1},{p_2},...,{p_{\tilde m}}} \right\rbrace  \subset {{\tilde L}^{\tilde n}},\sum\limits_{i = 1}^{\tilde m} {\rm{Params}} \left( {{p_i}} \right) \geq \mathcal{P}.\label{eq:61b}
	\end{align}
\end{subequations}
Based on this approximate objective in \eqref{eq:61}, the term $\mathbb{E}\|  {{{\boldsymbol{\varepsilon }}_{{\text{tea}}}} - {\boldsymbol{\varepsilon }}( {{p_i}})} \|_2^2$ acts as the criterion for pruning. Therefore, we only need to compute $\mathbb{E}\|  {{{\boldsymbol{\varepsilon }}_{{\text{tea}}}} - {\boldsymbol{\varepsilon }}( {{\tilde l_i}} )} \|_2^2$, the output loss between the original network and the network with only the ${\tilde l_i}$-th layer pruned, which has a time complexity of $\mathcal{O}( {\tilde n}) $ per layer ${\tilde l_i} \in {\tilde L^{\tilde n}} $, thereby transforming the problem into a variant of the 0-1 Knapsack problem. For a series of 0-1 Knapsack problems, the classical dynamic programming algorithm can be utilized for solving them. Finally, our designed one-shot layer pruning algorithm for the CGDM is summarized in \textbf{\alref{alg:algtrhpf}}. Then, the total time complexity of \textbf{\alref{alg:algtrhpf}} is $\mathcal{O}({{\tilde nU} \mathord{\left/
		{\vphantom {{\tilde n U} {\bar s}}} \right.
		\kern-\nulldelimiterspace} {\bar s}} + \tilde n \mathcal{C})$ and the storage complexity is $\mathcal{O}(\mathcal{C})$, where $U$ is the number of training samples, $\bar s$ is the number of parallel processing processes, and $\mathcal{C}$ is Knapsack capacity.

\subsection{Fine-Tuning LiCGDM with Multi-Objective Distillation}
Typically, the performance of the CGDM may degrade after certain layers are removed from the teacher network. To address this, for the pruned CGDM, referred to as LiCGDM, it is necessary to perform further weight readjustment to restore its performance. Therefore, we enhance the reconstruction performance of the LiCGDM by introducing a re-weighting strategy based on knowledge distillation. Specifically, the overall retraining of the LiCGDM is achieved by combining one task objective and two knowledge distillation objectives:
\begin{align}
  {\mathcal{L}_{\rm{KD} }} = {\mathcal{L}_{{\text{Task}}}} + {\lambda _{\text{O}}}{\mathcal{L}_{\text{OKD}}} + {\lambda _{\text{F}}}{L_{\text{FKD}}},
\end{align}
where
\begin{align}
	{\mathcal{L}_{{\text{Task}}}}=\mathbb{E}_{{ \boldsymbol{\dot{\mathsf{G}}}},{{\boldsymbol{\mathsf{G}}}_t},{{\boldsymbol{\varepsilon }}_t}}{\left\| {{{\boldsymbol{\varepsilon }}_t} - {{\boldsymbol{\varepsilon }}_{\boldsymbol{S }}}\left( {{ \boldsymbol{\dot{\mathsf{G}}}} ,{{\boldsymbol{\mathsf{G}}}_t},t} \right)} \right\|_2^2},
\end{align}
\begin{align}
	{\mathcal{L}_{\text{OKD}}}=\mathbb{E}_{{ \boldsymbol{\dot{\mathsf{G}}}},{{\boldsymbol{\mathsf{G}}}_t},t}{\left\| {{{\boldsymbol{\varepsilon }}_{\boldsymbol{T }}}\left( {{ \boldsymbol{\dot{\mathsf{G}}}} ,{{\boldsymbol{\mathsf{G}}}_t},t} \right)- {{\boldsymbol{\varepsilon }}_{\boldsymbol{S }}}\left( {{ \boldsymbol{\dot{\mathsf{G}}}} ,{{\boldsymbol{\mathsf{G}}}_t},t} \right)} \right\|_2^2},
\end{align}
\begin{align}
	{\mathcal{L}_{\text{FKD}}}\!=\!\sum\nolimits_{\text{i}}\mathbb{E}_{{ \boldsymbol{\dot{\mathsf{G}}}},{{\boldsymbol{\mathsf{G}}}_t},t}{\left\| {{{{\mathcal{F}}}^i_{\boldsymbol{T }}}\left( {{ \boldsymbol{\dot{\mathsf{G}}}} ,{{\boldsymbol{\mathsf{G}}}_t},t} \right)- {{{\mathcal{F}}}^i_{\boldsymbol{S }}}\left( {{ \boldsymbol{\dot{\mathsf{G}}}} ,{{\boldsymbol{\mathsf{G}}}_t},t} \right)} \right\|_2^2}.
\end{align}
Here ${{\boldsymbol{\varepsilon }}_{\boldsymbol{T }}}( {{ \boldsymbol{\dot{\mathsf{G}}}} ,{{\boldsymbol{\mathsf{G}}}_t},t})$ and ${{\boldsymbol{\varepsilon }}_{\boldsymbol{S }}}( {{ \boldsymbol{\dot{\mathsf{G}}}} ,{{\boldsymbol{\mathsf{G}}}_t},t})$ represent the outputs of the teacher model (the frozen CGDM) and the student model (the LiCGDM), respectively. ${{{\mathcal{F}}}^i_{\boldsymbol{T }}}( {{ \boldsymbol{\dot{\mathsf{G}}}} ,{{\boldsymbol{\mathsf{G}}}_t},t})$ and ${{{\mathcal{F}}}^i_{\boldsymbol{T }}}( {{ \boldsymbol{\dot{\mathsf{G}}}} ,{{\boldsymbol{\mathsf{G}}}_t},t} )$ denote the feature maps at the end of the $i$-th stage for the CGDM and LiCGDM, respectively. Without any hyperparameter tuning, we set the values of ${\lambda _{\text{O}}}$ and ${\lambda _{\text{F}}}$ to 1.
