\subsection{Full Query Reconstruction}
In this module \textit{FullRecover}, we leverage the \texttt{s-term} recovered in \textit{SRecover} and the new candidate keyword conjunctions pruned in \textit{CandiPrun} to further reconstruct the full queries. 

For all queries after the same \texttt{s-term} partition, recall that we have recovered the \texttt{s-term} token $\gamma_u$ with keyword $w_i$ in \textit{SRecover} and a new candidate set ${\Delta^i_c}^{'}$ has been obtained by filtering the keyword conjunctions in \textit{CandiPrun}. In this module, we try to recover all the full queries under each \texttt{s-term}, whose length is denoted as $\rho_u$. We look for the mapping $\textbf{P}_u$ that maximizes the likelihood of observing $\textbf{f}_u$, $\textbf{V}_u$, $\rho_u$ and $N_D$ given the auxiliary information $\widetilde{\textbf{f}_i}^{'}$ and $\widetilde{\textbf{V}_i}^{'}$. Formally, it solves the maximum likelihood problem
\begin{equation}
\textbf{P}_u=\underset{\textbf{P}_u\in\mathcal{P}_u}{\texttt{argmax}} \operatorname{Pr}(\textbf{f}_u,\rho_u, \textbf{V}_u, N_D \mid \widetilde{\textbf{f}_i},\widetilde{\textbf{V}_i},\textbf{P}_u).
\label{m3:argmax}
\end{equation}

We still transform this maximum likelihood problem into minimizing the negative log-likelihood. However, this optimization problem with respect to $\textbf{P}_u$ is not entirely linear, as it includes both linear and quadratic terms. For linear terms, we can use the Hungarian algorithm to solve our optimization problem. For quadratic terms, we can apply the iterative heuristic solution method for quadratic optimization problems proposed in~\cite{usenix22-ihop} to solve. Specifically, we first express the leakage that the attacker can obtain, then we explain how to combine them to fit our attack. 
\begin{algorithm}[htbp]
\small
\caption{Recovery for all the entire queries.}
\label{alg:3}
\KwIn{Encrypted database EDB, keyword universe $\Delta_k$, filtered candidate  universe with $i$-th \texttt{s-term} ${\Delta^i_c}^{'}$, a query list $Q_u$ of \texttt{s-term} token $\gamma_u$, volume matrix $\widetilde{\textbf{V}_i}^{'}$ and query frequency vector $\widetilde{\textbf{f}_i}^{'}$ of keyword combinations in ${\Delta^i_c}^{'}$}
\KwOut{A map from $Q_u$ to $z \in {\Delta^i_c}^{'}$}

$f_u,V_u\gets Q_u$.\\
Get the initial mapping $\textbf{P}_u$ by solving the linear assignment problem:\newline
$\textbf{P}_u=\underset{\textbf{P}_u\in\mathcal{P}_u}{\texttt{argmin}} \sum\limits_{z^i_g\in{\Delta^i_c}^{'}}\sum\limits_{\tau^u_j\in{\Delta^u_{\tau}}}(B^1_{V_u}+B^1_{f_u})_{g,j}\cdot ({\textbf{P}_u})_{g,j}$\\

\For{round from 1 to $n_{iter}$}{
    ${{\Delta^u_{\tau}}}^{\circ} \xleftarrow{\lceil p_{free}\rceil} {\Delta^u_{\tau}}$\\
    ${{\Delta^u_{\tau}}}^{\bullet}=\{\tau^u_j|\tau^u_j\in{\Delta^u_{\tau}},\tau^u_j\notin {\Delta^u_{\tau}}^{\circ}\}$\\
    ${{\Delta^i_c}^{'}}^{\bullet}=\{z^i_g|g=p_u(j), z^i_g\in{\Delta^i_c}^{'},\tau^u_j\in {\Delta^u_{\tau}}^{\bullet}\}$\\
    ${{\Delta^i_c}^{'}}^{\circ}=\{z^i_g|z^i_g\in {\Delta^i_c}^{'},z^i_g \notin {{\Delta^i_c}^{'}}^{\bullet}\}$\\
    $\textbf{P}_u^{\bullet}=\{\tau^u_j\to z^i_{p_u(j)}|\tau^u_j\in {\Delta^u_{\tau}}^{\bullet}\}$\\
    Get $\textbf{P}_u^{\circ}$ by solving the linear assignment problem:\newline $\textbf{P}_u^{\circ}=\underset{\textbf{P}_u^{\circ}\in\mathcal{P}_u^{\circ}}{\texttt{argmin}}\sum\limits_{z^i_g\in{{\Delta^i_c}^{'}}^{\circ}}\sum\limits_{\tau^u_j\in{{\Delta^u_{\tau}}}^{\circ}}(\sum\limits_{\tau^u_{j'}\in{\Delta^u_{\tau}}^{\bullet}}\sum\limits_{z^i_{g'}\in{{\Delta^i_c}^{'}}^{\bullet}}$\newline    $(B^2_{V_u})_{g,g',j,j'}\cdot ({\textbf{P}_u^{\circ}})_{g,j} \cdot ({\textbf{P}_u^{\bullet}})_{g',j'}+(B^1_{V_u}+B^1_{f_u})_{g,j}\cdot ({\textbf{P}_u^{\circ}})_{g,j})$\\
    $\textbf{P}_u \gets \text{combine}({\textbf{P}_u^{\circ}},{\textbf{P}_u^{\bullet}})$\\
    % \normalsize % \scriptsize 
}
\Return $\textbf{P}_u$
\BlankLine
\end{algorithm}

\noindent \textbf{Global search pattern leakage.}
Note that the correlations we consider are only between the keywords within the same conjunctive query, while each query is treated independently. As a result, the optimization term related to query frequency remains linear. 

Recall that $\textbf{f}_u$ is the vector of observed entire query token frequencies, $\rho_u$ is the number of queries with \texttt{s-term} token $\gamma_u$, and $\widetilde{\textbf{f}_i}^{'}$ is the vector of auxiliary candidate keyword combination frequencies with \texttt{s-term} $w_i$. We use a Poisson model to compute the attack coefficients. We assume that, when the keyword conjunction $z^i_g$ assigns to the query token $\tau^u_j$, the number of times the user sends token $\tau^u_j$ follows a Poisson distribution with rate $\rho_u\cdot \widetilde{\textbf{f}_i}^{'}_g$. Thus, the log-likelihood cost of assigning $z^i_g\to\tau^u_j$ is $(B_{f_u}^1)_{g,j}=-\operatorname{log Pr(Pois}(\rho_u\cdot \widetilde{\textbf{f}_i}^{'}_g)=\rho_u\cdot {\textbf{f}_u}_j)$. Expanding the expression and ignoring the additive terms
% that are not related to $g$ and $j$
, we get
\begin{equation}
(B^1_{f_u})_{g,j}=-\rho\cdot {\textbf{f}_u}_j \cdot \operatorname{log} \widetilde{\textbf{f}_i}^{'}_g.
\label{m3:fu}
\end{equation}

\noindent \textbf{Global access pattern leakage.}
We express global access pattern leakage in volume form, which is considered specifically the ratio of the number of files matched by two query tokens to the total number of documents. It takes into account both the cost allocation for identical tokens and the joint cost allocation for different query tokens, therefore, the optimization term related to query volume includes both linear and quadratic components. 

Recall that $\textbf{V}_u$ is the matrix of observed volumes of the entire tokens whose \texttt{s-term} token $\gamma_u$ has already assigned to the keyword $w_i$, and $\widetilde{\textbf{V}_i}^{'}$ is the matrix of corresponding auxiliary keyword conjunction volumes. We use a binomial model to get the coefficients $B_{V_u}^1$ and $B_{V_u}^2$. We assume that when keyword conjunction $z^i_g$ assign to query token $\tau^u_j$, the number of documents matching token $\tau^u_j$ follows a binomial distribution with $N_D$ trials and probability given by the auxiliary keyword conjunction volume $({\widetilde{\textbf{V}_i}^{'}})_{g,g}$. Thus, the log-likelihood cost of assigning $z^i_g\to\tau^u_j$ is $(B^1_{V_u})_{g,j}=-\operatorname{log Pr(Bino}(N_D,({\widetilde{\textbf{V}_i}^{'}})_{g,g})=N_D\cdot({\textbf{V}_u})_{j,j})$. Expanding the expression and ignoring the additive terms, we get 
\begin{equation}
\footnotesize
(B^1_{V_u})_{g,j}=-N_D[({\textbf{V}_u})_{j,j} \operatorname{log}({\widetilde{\textbf{V}_i}^{'}})_{g,g}-(1-({\textbf{V}_u})_{j,j})\operatorname{log}(1-{(\widetilde{\textbf{V}_i}^{'}})_{g,g})].
\label{m3:Vu1}
\end{equation}
When $z^i_g\to\tau^u_j$ and $z^i_{g'}\to\tau^u_{j'}$, the number of documents that match both tokens $\tau^u_{j}$ and $\tau^u_{j'}$ follows a Binominal distribution with $N_D$ trials and probability $({\widetilde{\textbf{V}_i}^{'}})_{g,g'}$, we get
\begin{equation}
\footnotesize
(B^2_{V_u})_{g,g',j,j'}=-N_D[({\textbf{V}_u})_{j,j'} \operatorname{log}({\widetilde{\textbf{V}_i}^{'}})_{g,g'}-(1-({\textbf{V}_u})_{j,j'})\operatorname{log}(1-{(\widetilde{\textbf{V}_i}^{'}})_{g,g'})].
\label{m3:Vu2}
\end{equation}

\noindent \textbf{Leakage combinations.}
We consider the scheme with both global search pattern and global access pattern. We combine them by adding their coefficients to fit our attack. The underlying idea is that with log-likelihoods, adding coefficients corresponds to multiplying probabilities. At this point, we can apply the iterative heuristic approach to solve quadratic optimization problems proposed by IHOP~\cite{usenix22-ihop} to address our modeled problem. We formally describe this module in Algorithm \ref{alg:3}.

