\section{Algorithmic Details}

\begin{algorithm}[H]
\caption{Histogram Update per Cursor \(c\) with Optional Copy Branch}
\label{alg:histogram}
\begin{algorithmic}[1]
\Require For each cursor \(c\in\{1,\dots,C\}\): current histogram 
  \(\bm h_{t}^{(c)}\in\Delta^{P-1}\)  \hfill(rows = positions \(0\ldots P-1\))
\Require Gate scalars 
  \(p_{\mathrm{reset}}^{(c)},\,p_{\mathrm{incr}}^{(c)},\,p_{\mathrm{decr}}^{(c)},\,p_{\mathrm{keep}}^{(c)}\in[0,1]^{B}\)
\Require (Optional) copy distribution 
  \(\bm p_{\mathrm{copy}}^{(c)}\in\Delta^{P+1}\) 
  (last entry = “no-copy”)
\Ensure Next histogram \(\bm h_{t+1}^{(c)}\)

\Statex \textbf{(1) Aggregate mass}
\[
  \text{total}^{(c)} \;=\;\sum_{i=0}^{P-1} h_{t}^{(c)}[i]
  \quad\in\mathbb{R}^{B}
\]
\State Initialize \(\bm h_{t+1}^{(c)}\gets\bm 0\in\mathbb{R}^{P\times B}\)

\Statex \textbf{(2) Reset branch}
\[
  \begin{aligned}
    h_{t+1}^{(c)}[1] &\mathrel{+}= \text{total}^{(c)}\;\,p_{\mathrm{reset}}^{(c)}\;\,p_{\mathrm{incr}}^{(c)},\\
    h_{t+1}^{(c)}[0] &\mathrel{+}= \text{total}^{(c)}\;\,p_{\mathrm{reset}}^{(c)}\;\bigl(p_{\mathrm{decr}}^{(c)}+p_{\mathrm{keep}}^{(c)}\bigr).
  \end{aligned}
\]

\Statex \textbf{(3) No–reset branch (shift / keep)}
\[
  \begin{aligned}
    w_{\mathrm{inc}}^{(c)}   &= (1 - p_{\mathrm{reset}}^{(c)})\;p_{\mathrm{incr}}^{(c)},\\
    w_{\mathrm{dec}}^{(c)}   &= (1 - p_{\mathrm{reset}}^{(c)})\;p_{\mathrm{decr}}^{(c)},\\
    w_{\mathrm{keep}}^{(c)}  &= (1 - p_{\mathrm{reset}}^{(c)})\;p_{\mathrm{keep}}^{(c)},\\
    %\text{/* broadcast over }i*/}
    h_{t+1}^{(c)}[i]   &\mathrel{+}= h_{t}^{(c)}[i]\;\,w_{\mathrm{keep}}^{(c)},\\
    h_{t+1}^{(c)}[i+1] &\mathrel{+}= h_{t}^{(c)}[i]\;\,w_{\mathrm{inc}}^{(c)}\quad(\text{clamp at }P-1),\\
    h_{t+1}^{(c)}[i-1] &\mathrel{+}= h_{t}^{(c)}[i]\;\,w_{\mathrm{dec}}^{(c)}\quad(\text{clamp at }0).
  \end{aligned}
\]

\If{\(\bm p_{\mathrm{copy}}^{(c)}\) provided}
  \Statex \textbf{(4) Copy branch}
  \State Split \(\bm p_{\mathrm{copy}}^{(c)} = \bigl(\bm p_{\mathrm{pos}}^{(c)},\,p_{\mathrm{no\text{-}copy}}^{(c)}\bigr)\)
  \State Scale normal flows: 
    \(\bm h_{t+1}^{(c)}\;\times=\;p_{\mathrm{no\text{-}copy}}^{(c)}\)
  \State Jump mass directly for all \(k=0,\dots,P-1\):
  \[
    h_{t+1}^{(c)}[k]\;\mathrel{+}=\;
    \text{total}^{(c)}\;\,p_{\mathrm{pos}}^{(c)}[k].
  \]
\EndIf

\Statex \textbf{(5) Sharpen \& renormalize}
\[
  \bm h_{t+1}^{(c)}
  \;\gets\;
  \frac{\bigl(\bm h_{t+1}^{(c)} + \varepsilon\bigr)^{\gamma_c}}
       {\sum_{i=0}^{P-1}\bigl(h_{t+1}^{(c)}[i]+\varepsilon\bigr)^{\gamma_c}},
  \quad
  \gamma_c>1
\]

\State \Return \(\bm h_{t+1}^{(c)}\)
\end{algorithmic}
\end{algorithm}

% \begin{algorithm}[H]
% \caption{\texttt{\_apply\_abs\_concat\_and\_ln\_optim}}
% \label{alg:abs‐ln‐optim}
% \begin{algorithmic}[1]
% \Require

\begin{algorithm}[H]
  %— Optional short caption for the “List of Algorithms” entry:
  \caption[Superposition Embedding per Cursor]
  {Efficient Superposition Embedding per Cursor:\\
   \texttt{\_get\_PE\_encoding\_vectors\_from\_scalar\_positions\_and\_norm}}
  \label{alg:superposition}
  \begin{algorithmic}[1]

\Require 
  Prob. tensors for queries \(\mathbf P^{(q)}\) and keys \(\mathbf P^{(k)}\)
  each of shape \(\R^{C\times B\times S\times r}\),
  where \(C = H\times O\) (number of cursors), \(r=\#\text{branches}\).\\
\Require Sinusoidal table \(\mathbf E\in\R^{r\times d}\).\\
\Ensure Embedded streams 
  \(\mathbf E_q,\mathbf E_k\in\R^{B\times H\times O\times S\times d}\).

% \For{\(X\) in \(\{\mathbf P^{(q)},\,\mathbf P^{(k)}\}\)}  
\For{\textbf{in parallel} $X\in\{\mathbf P^{(q)},\,\mathbf P^{(k)}\}$}

  \State {\footnotesize\(\triangleright\) Flatten out cursors, batch, sequence into one “row” dim}
  \[
    X_{\mathrm{flat}}
    \;\gets\;
    \mathrm{reshape}\bigl(X,\;[\,C\;B\;S,\;r\,]\bigr)
    \quad\in\R^{(C\,B\,S)\times r}
  \]
  \State {\footnotesize\(\triangleright\) One SIMD-style mat-mul over branches}\footnotemark
  \[
    Z_{\mathrm{flat}}
    \;\gets\;
    X_{\mathrm{flat}}\;\times\;\mathbf E
    \quad\in\R^{(C\,B\,S)\times d}
  \]
  \State {\footnotesize\(\triangleright\) Restore to \([C,B,S,d]\)}
  \[
    Z
    \;\gets\;
    \mathrm{reshape}\bigl(Z_{\mathrm{flat}},\;[\,C,\,B,\,S,\,d\,]\bigr)
  \]
  \State {\footnotesize\(\triangleright\) Turn \(C=H\times O\) back into head\,×\,cursor dims, then permute}
  \[
    Z
    \;\gets\;
    \mathrm{reshape}\bigl(Z,\;[\,H,\,O,\,B,\,S,\,d\,]\bigr)
    \;\xrightarrow{\;\mathrm{permute}(2,1,0,3,4)\;}
    \;\underbrace{\in\R^{\,B\times H\times O\times S\times d\,}}_{\mathbf E_{(\cdot)}}
  \]
  \State {\footnotesize\(\triangleright\) Exactly as in code’s \_apply\_abs\_concat\_and\_ln\_optim:}
  \[
    (\mathbf E_q,\mathbf E_k) 
      \;\gets\;
      \_apply\_abs\_concat\_and\_ln\_optim\bigl(
        Z,Z,\;B,H,O,S,d,\;\mathrm{abs\_enc},\;\mathrm{ablate\_abs\_pos\_enc}
      \bigr)
  \] 
  \If{$X = \mathbf P^{(q)}$}
    \State $\mathbf E_q \gets Z$
  \Else
    \State $\mathbf E_k \gets Z$
  \EndIf

\EndFor

\State \Return \(\mathbf E_q,\;\mathbf E_k\)
\end{algorithmic}
\end{algorithm}


\footnotetext{Instead of materializing $r$ separate $d_{\text{model}}$-dimensional
vectors for every branch and every token, we multiply once by the
$r\times d_{\text{model}}$ sinusoidal table (a single
\texttt{einsum}/GEMM).  The math is identical but the memory traffic is
$O(1/r)$ smaller, and the whole update stays in one SIMD-friendly
kernel.}

\subsection{Absolute-PE Concatenation \& Layer‐Norm Optimization}
\label{sec:abs‐ln‐optim}

This routine is called at the end of the superposition embedding to
(1) optionally concatenate an absolute positional embedding branch, and
(2) apply either a custom scaling or a projection‐free layer‐norm:

\begin{algorithm}[H]
\caption{\texttt{\_apply\_abs\_concat\_and\_ln\_optim}}
\label{alg:abs‐ln‐optim}
\begin{algorithmic}[1]
\Require
  Encodings \(\mathit{enc}_q,\mathit{enc}_k\in\R^{B\times H\times C\times S\times d}\),  \\
  absolute-PE table \(\mathit{abs\_enc}\in\R^{\ge S\times d}\),  
  flags \(\mathit{CONCAT\_ABS\_POSITION\_ENCODINGS},\linebreak\,\mathit{MHA\_USE\_CUSTOM\_LN}\),
  \(ablate\_flag \equiv False\)
\Ensure
  Updated \(\mathit{enc}_q,\mathit{enc}_k\) of same final shape.

\State \(C_{\text{base}}\gets C\)
\If{\(\mathit{CONCAT\_ABS\_POSITION\_ENCODINGS}\)}  
  \Comment{concatenate one extra absolute‐PE branch}
  \State \(C\gets C_{\text{base}}+1\)
  \State \(\mathit{abs\_pe}\gets \mathit{abs\_enc}[:S]\!\bigl[1,1,1,S,d\bigr]\!\to\!\mathrm{expand}(B,H,1,S,d)\)
  \If{ablate\_flag}
    \State \(\mathit{abs\_pe}\gets \mathbf{0}_{B\times H\times1\times S\times d}\)
  \EndIf
  \State \(\mathit{enc}_q\gets \mathrm{cat}(\mathit{enc}_q,\mathit{abs\_pe};\,\mathrm{dim}=2)\)
  \State \(\mathit{enc}_k\gets \mathrm{cat}(\mathit{enc}_k,\mathit{abs\_pe};\,\mathrm{dim}=2)\)
\EndIf

\If{\(\mathit{MHA\_USE\_CUSTOM\_LN}\)}  
  \Comment{global rescaling so norm = \(\sqrt d\)}
  \State \(\alpha\gets \texttt{sinusoidal\_encoding\_vector\_norm\_vs\_d\_model}(d)\)
  \State \(\mathit{scale}\gets \frac{\sqrt d}{\sqrt{C\cdot\alpha^2}}\)
  \State \(\mathit{enc}_q\;\boldsymbol\cdot=\;\mathit{scale},\quad  
         \mathit{enc}_k\;\boldsymbol\cdot=\;\mathit{scale}\)
\Else
  \Comment{mean-free LayerNorm across \([C,S]\) per head}
  \State assert \(\mathit{enc}_q,\mathit{enc}_k\text{ shaped }(B,H,C,S,d)\)
  \State \(\mathit{enc}_q\!\to\!\mathrm{permute}(0,1,3,2,4)\;[B,H,S,C,d]\)
  \State \(\mathit{enc}_k\!\to\!\mathrm{permute}(0,1,3,2,4)\;[B,H,S,C,d]\)
  \State 
    \(\mathit{enc}_q\gets
       \mathit{enc}_q/
       \bigl\|\mathit{enc}_q\bigr\|_{(-2,-1)}\times\sqrt d\)
  \State 
    \(\mathit{enc}_k\gets
       \mathit{enc}_k/
       \bigl\|\mathit{enc}_k\bigr\|_{(-2,-1)}\times\sqrt d\)
  \State 
    \(\mathit{enc}_q\!\to\!\mathrm{permute}(0,1,3,2,4),\quad
     \mathit{enc}_k\!\to\!\mathrm{permute}(0,1,3,2,4)\)
\EndIf

\State \Return \(\mathit{enc}_q,\;\mathit{enc}_k\)
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[H]
\caption{Position-Aware Attention Scores 
(\_\!findPositionScores)}
\label{alg:compute-position-scores}

\begin{algorithmic}[1]
\Require
  Encodings 
  \(\mathit{enc}_q,\mathit{enc}_k\in\R^{B\times H\times C\times S\times d}\)
  \Comment{\(C\)=cursors per head}
\Require
  Learned scaling factors 
  \(\alpha\in\R^{H\times C}\) 
  (in code: \(\alpha\equiv\)\texttt{POST\_QK\_SCALING\_FACTORS\_MULTIPLIER}),\\
  \(\texttt{NEGATIVE\_COEFFS\_ALLOWED}=\texttt{false}\)
\Ensure
  \(\mathit{scores},\,\mathit{position\_scores}\in\R^{B\times H\times S\times S}\)

\State \((B,H,C,S,d)\gets \mathrm{shape}(\mathit{enc}_q)\)
\Comment{cursor index \(c=1,\dots,C\)}

\ForAll{\(b=1,\dots,B;\;h=1,\dots,H;\;c=1,\dots,C;\;i,j=1,\dots,S\)}
  \[
    \mathit{scores_{3}}[b,h,c,i,j]
    \;\gets\;
    \bigl\langle
      \mathit{enc}_q[b,h,c,i,:],\,
      \mathit{enc}_k[b,h,c,j,:]
    \bigr\rangle
  \]
\EndFor

\Statex\Comment{\textbf{Post-scaling (always nonnegative):}}
\State \(\displaystyle
  \beta[h,c]\;\gets\;|\alpha[h,c]|
\)
\State \(\displaystyle
  \mathit{scores_{3}}[b,h,c,i,j]\;\;\boldsymbol\cdot=\;\beta[h,c]
\)

\Statex\Comment{\textbf{Sum out cursors:}}
\[
  \mathit{scores_{2}}[b,h,i,j]
    \;=\;\sum_{c=1}^{C}\mathit{scores_{3}}[b,h,c,i,j]
\]

\State \(N\;\gets\;C \times d\)

\Statex\Comment{\textbf{Final normalization:}}
\[
  \mathit{scores_{final}}[b,h,i,j]
    \;=\;
    \frac{\mathit{scores_{2}}[b,h,i,j]}{\sqrt{N}}
\]
\State \(\mathit{position\_scores}\gets \mathit{scores_{final}}\)

\State \Return \(\mathit{scores},\,\mathit{position\_scores}\)
\end{algorithmic}
\end{algorithm}

