\item $\dollarebwt({\cal M}) \same \mdollar(\lex({\cal M})) \same \mdollarE(\lex({\cal M}))$, where $\lex({\cal M})$ denotes the lexicographic order of the strings in ${\cal M}$. 
\end{enumerate}
\end{lemma}

