\begin{algorithm}[htbp]
\small
\caption{AutoLINC}
\label{alg:1}
\begin{algorithmic}
   \STATE {\bfseries Input:} Grammar $\mathcal{G}=(U, \Sigma, R, O)$, node feature matrix $X$, node label $Y$, GNN model $f_\theta$, measure\ $\sigma$, number of trails $P$, number of episode $EP$, number of simulation $B$, $t_{max}$\;
   \STATE {\bfseries Output:} Optimal loss function $\mathcal{L}^\star$\; 
   \STATE Initialize $M=\emptyset$\;
    \FOR{$p\leftarrow 1, P$}
        \FOR{$e \leftarrow 1, EP$}
        \STATE \textbf{Selection:} Initialize $s_0=\emptyset, t=0, NT=[O]$\;
            \WHILE {$s_t$ expandable and $t < t_{max}$}
           \STATE $a_{t+1} \leftarrow \arg \max_{a \in \mathcal{A}} UCT(s_t, a)$\; 
           \STATE Obtain $s_{t+1},NT$ after $a_{t+1}$; $t\leftarrow t+1$\;
            \ENDWHILE
         \STATE \textbf{Expansion:} Randomly take an unvisited path with $a$\;
        Obtain $s_{t+1},NT$ after $a$; $t\leftarrow t+1$\;
        \IF{$NT = \emptyset$}
           \STATE Validate the Legitimacy of $\mathcal{L}$ and check $\mathcal{L}$ via the Loss Check Strategy\;
           \STATE Train the proxy task with $\mathcal{L}$\;
           \STATE $r\leftarrow \sigma(f_\theta(X_{val},Y_{val}))$\;
           \STATE Record $\mathcal{L}, r$ in $ M$, \textbf{Backpropagate} and finish the episode\;
        \ENDIF
        \STATE \textbf{Simulation:} Fix the state $s_t$ and $NT$\;
        Initialize $r=0$\;
        \FOR{$b\leftarrow 1, B$}
        \WHILE {$s_t$ non-terminal and $t < t_{max}$}
       \STATE $a\leftarrow Random(\mathcal{A})$\;
       \STATE Obtain $s_{t+1},NT$ after $a_{t+1}$; $t\leftarrow t+1$\;
        \ENDWHILE
        \IF{$NT = \emptyset$}
           \STATE Validate the Legitimacy of $\mathcal{L}$ and check \STATE $\mathcal{L}$ via the Loss Check Strategy\;
           \STATE Train the proxy task with $\mathcal{L}$\;
           \STATE $r\leftarrow \sigma(f_\theta(X_{val}, Y_{val}))$\;
           \STATE Record $\mathcal{L}, r$ in $M$\;
        \ENDIF
        \ENDFOR
        \STATE \textbf{Backpropagate:} Back-update parent nodes based on simulation results all the way back to the root node\;
        \ENDFOR
    \ENDFOR
    \STATE Get the top-10 loss functions $M_{top}$ from $M$ based on reward\;
    \STATE Initialize $best=0$, $\mathcal{L}^{*}=\emptyset$\;
    \FOR{$l\leftarrow 1, 10$}
    \STATE $\mathcal{L}\leftarrow M_{top}(l)$\;
    \STATE Train the complete task with $\mathcal{L}$\;
    \STATE $r\leftarrow \sigma(f_\theta(X_{val}, Y_{val}))$\;
    \IF{$r>best$}
    \STATE $best\leftarrow r$;
    \STATE $\mathcal{L}^\star\leftarrow \mathcal{L}$\;
    \ENDIF
    \ENDFOR
    \end{algorithmic}
\end{algorithm}
