    \end{minipage}\;
    \begin{minipage}{0.51\textwidth}
        \begin{algorithm}[H]
            \scriptsize
            % \footnotesize
            \caption{\small $IMr$ algorithm}
            \label{IM-rules}
            \begin{algorithmic}
            \Function{$IMr$}{$L,sup,R$}
                 \LComment{$L {\in} {\mathcal{L}}$ is an event log, $sup \in [0,1]$ is a process discovery parameter and $R$ is the set of rules.}
                \State $base = checkBaseCase(L,sup)$
                \If {$checkBaseCase$ successful}
                    \State \Return $base$
                \EndIf
                \State $C=explore(\mathcal{G}(L),R)$
                \State $(\oplus,\Sigma_1,\Sigma_2)=\underset{c \in C}{\arg\min} \lbrace ov\_cost_{\mathcal{G}(L)}(c, sup) \rbrace$
                \State $L_1, L_2 = SPLIT(L,(\oplus,\Sigma_1,\Sigma_2))$
                \State \Return $\oplus(IMr(L_1,sup,R),IMr(L_2, sup,R))$
                \EndFunction
            \end{algorithmic}
        \end{algorithm}
