\subsubsection*{$existence(a)$} $a$ occurs at least once.
\begin{itemize}
    \item {\small $c{=}(\times,\Sigma_1,\Sigma_2) {\nvDash} existence(a)$} if $a {\in} \Sigma_1$ ($a {\in} \Sigma_2$), because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ which only has activities in $\Sigma_2$ ($\Sigma_1$).
    \item {\small $c{=}(\circlearrowleft,\Sigma_1,\Sigma_2) {\nvDash} existence(a)$} if $a {\in} \Sigma_2$, because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ which does not trigger the redo part of the process tree and consists of only activities in $\Sigma_1$.
    \vspace{-10pt}
\end{itemize}



\subsubsection*{$response(a,b)$} If $a$ occurs in the trace, then $b$ occurs as well.
\begin{itemize}
        \item {\small $c{=}(\times,\Sigma_1,\Sigma_2) {\nvDash} response(a,b)$} if $a \in \Sigma_1$ and $b \in \Sigma_2$ (or $a \in \Sigma_2$ and $b \in \Sigma_1$), because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ which has an occurrence of activity $a$ but $b$ cannot occur in this trace.
        \item {\small $c{=}(\wedge,\Sigma_1,\Sigma_2) {\nvDash} response(a,b)$} if $a \in \Sigma_1$ and $b \in \Sigma_2$ (or $a \in \Sigma_2$ and $b \in \Sigma_1$), because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ in which activity $b$ occurs before $a$ and $b$ does not occur again.
        \item {\small $c{=}(\circlearrowleft,\Sigma_1,\Sigma_2) {\nvDash} response(a,b)$} if $a \in \Sigma_1$ and $b \in \Sigma_2$, because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ in which $a$ occurs but $b$ does not occur because the redo part is optional.
        \item {\small $c{=}(\rightarrow,\Sigma_1,\Sigma_2) {\nvDash} response(a,b)$} if $b \in \Sigma_1$ and $a \in \Sigma_2$, because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ in which activity $b$ occurs first and then $a$ occurs and $b$ does not occur again.
         \vspace{-10pt}
    \end{itemize}


    \subsubsection*{$precedence(a,b)$}$b$ occurs only if preceded by $a$.
    \begin{itemize}
        \item {\small $c{=}(\times,\Sigma_1,\Sigma_2) {\nvDash} precedence(a,b)$} if $a \in \Sigma_1$ and $b \in \Sigma_2$ (or $a \in \Sigma_2$ and $b \in \Sigma_1$), because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ which has an occurrence of activity $b$ but $a$ cannot occur in this trace.
        \item {\small $c{=}(\wedge,\Sigma_1,\Sigma_2) {\nvDash} precedence(a,b)$} if $a \in \Sigma_1$ and $b \in \Sigma_2$ (or $a \in \Sigma_2$ and $b \in \Sigma_1$), because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ in which activity $b$ occurs before $a$.
        \item {\small $c{=}(\circlearrowleft,\Sigma_1,\Sigma_2) {\nvDash} precedence(a,b)$} if $b \in \Sigma_1$ and $a \in \Sigma_2$, because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ in which $b$ occurs but $a$ does not occur because the redo part is optional.
        \item {\small $c{=}(\rightarrow,\Sigma_1,\Sigma_2) {\nvDash} precedence(a,b)$} if $b \in \Sigma_1$ and $a \in \Sigma_2$, because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ in which activity $b$ occurs first and then $a$ occurs.
        \vspace{-10pt} 
    \end{itemize}


\subsubsection*{$co \mhyphen existence(a,b)$} $a$ and $b$ occur together.
\begin{itemize}
    \item {\small $c{=}(\times,\Sigma_1,\Sigma_2) {\nvDash} co \mhyphen existence(a,b)$ if $a \in \Sigma_1$} and $b \in \Sigma_2$ (or $a \in \Sigma_2$ and $b \in \Sigma_1$), because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ which has an occurrence of only activity $a$ or only activity $b$.
    \item {\small $c{=}(\circlearrowleft,\Sigma_1,\Sigma_2) {\nvDash} co \mhyphen existence(a,b)$ if $a \in \Sigma_1$} and $b \in \Sigma_2$ ($a \in \Sigma_2$ and $b \in \Sigma_1$), because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ in which only activity $a$ ($b$) occurs because the redo part is optional.
     \vspace{-10pt}
    \end{itemize}


\subsubsection*{$not \mhyphen co \mhyphen existence(a,b)$} $a$ and $b$ cannot occur together.
\begin{itemize}
        \item {\small $c{=}(\wedge,\Sigma_1,\Sigma_2) {\nvDash} not \mhyphen co \mhyphen existence(a,b)$} if $a \in \Sigma_1$ and $b \in \Sigma_2$ (or $a \in \Sigma_2$ and $b \in \Sigma_1$), because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ in which both activities $a$ and $b$ occur.
        \item {\small $c{=}(\circlearrowleft,\Sigma_1,\Sigma_2) {\nvDash} not \mhyphen co \mhyphen existence(a,b)$} if $a \in \Sigma_1$ and $b \in \Sigma_2$ (or $a \in \Sigma_2$ and $b \in \Sigma_1$), because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ in which $a$ and $b$ both occur because the redo part is optional and may occur. Also, if $a \in \Sigma_1$ and $b \in \Sigma_1$ (or $a \in \Sigma_2$ and $b \in \Sigma_2$), since the do part or redo part of the loop tree can occur multiple times and the repetitions are independent, then activities $a$ and $b$ may occur in different repeats of the loop process trees.
        \item {\small $c{=}(\rightarrow,\Sigma_1,\Sigma_2) {\nvDash} not \mhyphen co \mhyphen existence(a,b)$} if $a \in \Sigma_1$ and $b \in \Sigma_2$ (or $a \in \Sigma_2$ and $b \in \Sigma_1$), because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ in which both activities $a$ and $b$ occur.
        \vspace{-10pt} 
    \end{itemize}


\subsubsection*{$not\mhyphen succession(a,b)$} $b$ cannot occur after $a$.
\begin{itemize}
        \item {\small $c{=}(\wedge,\Sigma_1,\Sigma_2) {\nvDash} not\mhyphen succession(a,b)$} if $a \in \Sigma_1$ and $b \in \Sigma_2$ (or $a \in \Sigma_2$ and $b \in \Sigma_1$), because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ in which activity $a$ occurs first and then $b$ occurs after it.

         \item {\small $c{=}(\circlearrowleft,\Sigma_1,\Sigma_2) {\nvDash} not\mhyphen succession(a,b)$} if $\{a,b\} \subseteq \Sigma_1 \cup \Sigma_2$, because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ in which activity $b$ occurs after activity $a$. 
         Since the do part and redo part of the loop tree can occur multiple times and the repetitions are independent, then after the occurrence of activity $a$, activity $b$ can eventually occur.


        \item {\small $c{=}(\rightarrow,\Sigma_1,\Sigma_2) {\nvDash} not\mhyphen succession(a,b)$} if $a \in \Sigma_1$ and $b \in \Sigma_2$, because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ in which activity $a$ occurs first and then $b$ occurs.
        \vspace{-10pt} 
    \end{itemize}

\subsubsection*{$responded\mhyphen existence(a,b)$} If $a$ occurs in the trace, then $b$ occurs as well.
\begin{itemize}
    \item {\small $c{=}(\times,\Sigma_1,\Sigma_2) {\nvDash} responded\mhyphen existence(a,b)$} if $a \in \Sigma_1$ and $b \in \Sigma_2$ (or $a \in \Sigma_2$ and $b \in \Sigma_1$), because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ which has an occurrence of only activity $a$ and $b$ cannot occur in this trace.
    \item {\small $c{=}(\circlearrowleft,\Sigma_1,\Sigma_2) {\nvDash} responded\mhyphen existence(a,b)$} if $a \in \Sigma_1$ and $b \in \Sigma_2$, because for any process tree $M{\in}\mathcal{M}_{c}$, there is a trace $\sigma {\in} \phi(M)$ in which only activity $a$ occurs but $b$ does not occur since the redo part is optional.
    \end{itemize}


