%Select $n_\varepsilon$ vertices from $X$ (resp., $Y$) to from $X_\varepsilon$ (resp., $Y_\varepsilon$) such that $\delta_Y(X_\varepsilon)$ (resp., $\delta_X(Y_\varepsilon)$) is maximized. Note that the selection of $n_\varepsilon$ vertices from $X$ can be accomplished by choosing $x \in X$ based on the decreasing order of $\delta_Y(x)$, which takes $O(n^2)$ time.

\noindent\textbf{Step~2.} Generate a random permutation of the $md$ 3-paths in $\P_{X_\varepsilon}$ (resp., $\P_{Y_\varepsilon}$), and label them as $P_1,\dots,P_{md}$ (resp., $Q_1,\dots,Q_{md}$), respectively, where $P_i=x_{3i-3}x_{3i-2}x_{3i-1}$ and $Q_i=y_{3i-3}y_{3i-2}y_{3i-1}$.

\noindent\textbf{Step~3.} Take an arbitrary permutation of $l$ teams in $\overline{X_\varepsilon}$ (resp., $\overline{Y_\varepsilon}$), and label them as $x_{n_\varepsilon},\dots,x_{n-1}$ (resp., $y_{n_\varepsilon},\dots,y_{n-1}$), respectively.

%Label $\P_{X_\varepsilon}$ using $\{P_1,\dots,P_{md}\}$ uniformly at random.
