Note that {Step~1} can be done in $O(n^2)$ time, and {Step~2} and {Step~3} can be done in $O(n)$ time by using the Fisher–Yates shuffle~\cite{knuth1997art}. In {Step~2}, we assume that the two 3-path packings are given in advance. Moreover, when labeling a 3-path using $P_i=x_{3i-3}x_{3i-2}x_{3i-1}$, there are two choices based on the two opposite directions, and either of them is considered valid.

\begin{theorem}\label{res-construction}
For BTTP with $n\geq 108d^3$, given any 3-path packing $\P_{X_\varepsilon}$ (resp., $\P_{Y_\varepsilon}$) in $G[X_\varepsilon]$ (resp., $G[Y_\varepsilon]$), using the above randomized labeling method, our 3-path construction can generate a solution with an expected weight of at most $\delta_{Y_\varepsilon}(\P_{X_\varepsilon})+n_\varepsilon w(\P_{X_\varepsilon})+\delta_{X_\varepsilon}(\P_{Y_\varepsilon})+n_\varepsilon w(\P_{Y_\varepsilon})+\varepsilon\cdot\OPT$ in $O(n^2)$ time.
\end{theorem}
\begin{proof}
Clearly, our 3-path construction takes $O(n^2)$ time. 

Then, we make two assumptions for the sake of analysis, which do not decrease the weight of our schedule by the triangle inequality.
Firstly, we assume that every participant team returns home both before and after each day's game in left super-games and the last time slot. Secondly, we assume that all participant teams return home before the game on the first day and after the game on the last day in normal super-games.

By {Step~1} of our randomized labeling algorithm, since we select the top $n_\varepsilon$ vertices from $X$ with the highest costs to form $X_\varepsilon$, we get 
\begin{equation*}
\delta_Y(X_\varepsilon)=\sum_{x\in X_\varepsilon}\delta_Y(x)\geq \frac{n_\varepsilon}{n}\sum_{x\in X}\delta_Y(x)=\frac{n_\varepsilon}{n}\delta_Y(X).
\end{equation*}
Alternatively, since $l=n-n_\varepsilon\leq 9d$ by (\ref{eq0}), we have
\begin{equation}\label{eq1}
\delta_{\overline{X_\varepsilon}}(Y)=\delta_Y(\overline{X_\varepsilon})\leq \lrA{1-\frac{n_\varepsilon}{n}}\delta_Y(X)\leq\frac{9d}{n}\delta_Y(X).
\end{equation}
Similarly, we have 
\begin{equation}\label{eq2}
\delta_{\overline{Y_\varepsilon}}(X)=\delta_X(\overline{Y_\varepsilon})\leq \lrA{1-\frac{n_\varepsilon}{n}}\delta_X(Y)\leq\frac{9d}{n}\delta_X(Y).
\end{equation}

%By {Step~2}, since $\{Q_i\}_{i=1}^{md}=\P_{Y_\varepsilon}$, we get
%\begin{equation}
%\EE{w(Q_i)}=\frac{1}{md}w(\P_{Y_\varepsilon}).
%\end{equation}
%Since $\bigcup_{i=1}^{m} S_i=X_\varepsilon$ and $\bigcup_{i=1}^{m} T_i=Y_\varepsilon$, we can get
%\begin{equation}
%\EE{\delta_{S_i}(T_j)}=\frac{1}{m^2}\delta_{X_\varepsilon}(Y_\varepsilon).
%\end{equation}

Consider a team $x\in \overline{X_\varepsilon}$.
By assumptions, in our schedule the weight of its itinerary is $\sum_{y\in Y}2w(x,y)=2\delta_Y(x)$. The total weight of itineraries of teams in $\overline{X_\varepsilon}$ is $\sum_{x\in \overline{X_\varepsilon}}2\delta_Y(x)=2\delta_Y(\overline{X_\varepsilon})\leq \frac{18d}{n}\delta_Y(X)\leq\frac{1}{d}\delta_Y(X)$ by (\ref{eq1}) and $n\geq 108d^3$.

Fix a team $x\in S_i\subseteq X_\varepsilon$. We have three parts of its trips.
\begin{enumerate}
    \item The weight of its trips for playing teams in $\overline{Y_\varepsilon}$ is $\sum_{y\in \overline{Y_\varepsilon}}2w(x,y)=2\delta_{\overline{Y_\varepsilon}}(x)$ by assumptions since these games are in left super-games.
    \item In a left super-game between $S_i$ and $T_j$, the weight of its trips for playing teams in $T_j$ is $\sum_{y\in T_j}2w(x,y)=2\delta_{T_j}(x)$. We can get $\EE{\delta_{T_j}(x)}=\frac{1}{m}\delta_{Y_\varepsilon}(x)$ by {Step~2} of our randomized labeling algorithm. Since $S_i$ plays $l$ left super-games in total, the expected weight of its trips for playing teams in a super-team that plays a left super-game with $S_i$ is $\frac{2l}{m}\delta_{Y_\varepsilon}(x)\leq \frac{1}{d}\delta_{Y_\varepsilon}(x)$ due to $l\leq 9d$ and $m\geq18d^2$ by (\ref{eq0}).
    \item In a normal super-game between $S_i$ and $T_j$, it plays $d$ or $d+1$ trips along at least $d-1$ 3-paths in $\Q_j\coloneqq\{Q_{(j-1)d+1},\dots,Q_{jd}\}$ from one terminal to another (see Table~\ref{normal-example}). If it plays $d$ trips along $d$ 3-paths in $\Q_j$, the weight of these trips is $\delta_{x}(\Q_j)+w(\Q_j)$; if it plays $d+1$ trips along $d-1$ 3-paths in $\Q_j$, it does not follow a 3-path $y'_0y'_1y'_2$ in $\Q_j$, the weight of the two trips for playing teams in $\{y'_0,y'_1,y'_2\}$ is bounded by $2w(x,y'_0)+2w(x,y'_1)+2w(x,y'_2)$ by the triangle inequality (Note that, alternatively, here we can assume that each team returns home both before and after each day's game during trips where they visit only two teams.), and then the weight of the $d+1$ trips is bounded by $\delta_{x}(\Q_j)+w(\Q_j)+2w(x,y'_0)+2w(x,y'_1)+2w(x,y'_2)$. We have $\EE{\delta_{x}(\Q_j)}=\frac{1}{m}\delta_{x}(\P_{Y_\varepsilon})$, $\EE{w(\Q_j)}=\frac{1}{m}w(\P_{Y_\varepsilon})$, and $\EE{w(x,y'_0)+w(x,y'_1)+w(x,y'_2)}=\frac{1}{md}\delta_{Y_\varepsilon}(x)$ by {Step~2} of our randomized labeling algorithm. Since $S_i$ plays $m-l\leq m$ normal super-games, the expected weight of trips for playing teams in a super-team that plays a normal super-game with $S_i$ is at most $\delta_{x}(\P_{Y_\varepsilon})+w(\P_{Y_\varepsilon})+\frac{1}{d}\delta_{Y_\varepsilon}(x)$.
\end{enumerate}
So, the expected weight of the itinerary of team $x$ is at most $2\delta_{\overline{Y_\varepsilon}}(x)+\frac{2}{d}\delta_{Y_\varepsilon}(x)+\delta_{x}(\P_{Y_\varepsilon})+ w(\P_{Y_\varepsilon})$.
Hence, the total expected weight of itineraries of teams in $X_\varepsilon$ is at most 
\begin{align*}
&2\delta_{\overline{Y_\varepsilon}}(X_\varepsilon)+\frac{2}{d}\delta_{Y_\varepsilon}(X_\varepsilon)+\delta_{X_\varepsilon}(\P_{Y_\varepsilon})+n_\varepsilon w(\P_{Y_\varepsilon})\leq \frac{3}{d}\delta_X(Y)+\delta_{X_\varepsilon}(\P_{Y_\varepsilon})+n_\varepsilon w(\P_{Y_\varepsilon})
\end{align*}
%$2\delta_{\overline{Y_\varepsilon}}(X_\varepsilon)+\frac{2}{d}\delta_{Y_\varepsilon}(X_\varepsilon)+\delta_{X_\varepsilon}(\P_{Y_\varepsilon})+n_\varepsilon w(\P_{Y_\varepsilon})\leq \frac{3}{d}\delta_X(Y)+\delta_{X_\varepsilon}(\P_{Y_\varepsilon})+n_\varepsilon w(\P_{Y_\varepsilon})$ 
since we have $2\delta_{\overline{Y_\varepsilon}}(X_\varepsilon)\leq 2\delta_{\overline{Y_\varepsilon}}(X)\leq \frac{1}{d}\delta_{X}(Y)$ by (\ref{eq2}) and $n\geq 108d^3$, and $\delta_{Y_\varepsilon}(X_\varepsilon)\leq \delta_{Y}(X)=\delta_{X}(Y)$.

Therefore, the total expected weight of itineraries of teams in $X$ is bounded by $\frac{4}{d}\delta_X(Y)+\delta_{X_\varepsilon}(\P_{Y_\varepsilon})+n_\varepsilon w(\P_{Y_\varepsilon})$. 
Similarly, for teams in $Y$, the expected weight is bounded by $\frac{4}{d}\delta_Y(X)+\delta_{Y_\varepsilon}(\P_{X_\varepsilon})+n_\varepsilon w(\P_{X_\varepsilon})$.

Since $d=6\ceil{1/\varepsilon}\geq6/\varepsilon$ by our setting and $\delta_Y(X)=\delta_X(Y)\leq (3/4)\cdot\OPT$ by Lemma~\ref{lb1}, our schedule has an expected weight of at most $\varepsilon\cdot\OPT+\delta_{Y_\varepsilon}(\P_{X_\varepsilon})+n_\varepsilon w(\P_{X_\varepsilon})+\delta_{X_\varepsilon}(\P_{Y_\varepsilon})+n_\varepsilon w(\P_{Y_\varepsilon})$.
\end{proof}

