\begin{equation}\label{eq3}
\delta_{Y_\varepsilon}(X_\varepsilon)=\sum_{3\leq q\leq n_\varepsilon}\mu_q~~~\mbox{and}~~~n_\varepsilon w(\C_{X_\varepsilon})=\sum_{3\leq q\leq n_\varepsilon}\lambda_q.
