%\end{split}
%\end{equation}
%We consider two kinds of cycles: 3-cycles, and $q$-cycles with $q\geq5$. 
Let $\mu_{>3}\coloneqq\sum_{q=4}^{n_\varepsilon}\mu_q$ and $\lambda_{>3}\coloneqq\sum_{q=4}^{n_\varepsilon}\lambda_q$. By (\ref{eq3}), we have
\begin{equation}\label{d=D}
\delta_{Y_\varepsilon}(X_\varepsilon)=\mu_3+\mu_{>3}\quad\mbox{and}\quad n_\varepsilon w(\C_{X_\varepsilon})=\lambda_3+\lambda_{>3}.
\end{equation}

Next, we are ready to prove the lemma.


By {Step 2} of the algorithm, the contributions of cycles in $\B_3$ on $n_\varepsilon w(\C)$ are $n_\varepsilon w(\B_3)=\lambda_3$. 

%\begin{claim}
%It holds that $n_\varepsilon w(C)\leq\frac{1}{2}\mu_{>3}+\frac{3}{4}\lambda_{>3}$.
%\end{claim}

Then, we consider the cycles in $\C_{X_\varepsilon}\setminus\B_3$. By {Step 3}, the contributions of them on $n_\varepsilon w(\C)$ is 
$n_\varepsilon w(C)$, where $C$ is obtained by patching a set of paths, denoted by $\P$. The paths in $\P$ are patched into the cycle $C$ using a set of vertex-disjoint edges (see Figure~\ref{fig03}), denoted by $E'$.
By~(\ref{degree}), $\sum_{e\in E'}n_\varepsilon w(e)$ is bounded by the cost of terminals of paths in $\P$, i.e., $\delta_{Y_\varepsilon}(\P)$. Hence, we have 
\[
n_\varepsilon w(C)\leq n_\varepsilon w(\P)+\delta_{Y_\varepsilon}(\P).
\]
For each $q$-cycle in $\C_{X_\varepsilon}\setminus\B_3$, the contribution of the cycle on $n_\varepsilon w(\P)+\delta_{Y_\varepsilon}(\P)$ is $n_\varepsilon w(P_q)+\delta_{Y_\varepsilon}(P_q)$, where the $q$-path $P_q$ is obtained by deleting the edge $xx'\in C_q$ with $\delta_{Y_\varepsilon}(x)+\delta_{Y_\varepsilon}(x')-n_\varepsilon w(x,x')$ minimized by {Step 3}. Then, we have
\begin{align*}
\delta_{Y_\varepsilon}(x)+\delta_{Y_\varepsilon}(x')-n_\varepsilon w(x,x')&\leq \frac{1}{q}\sum_{x''x'''\in C_q}(\delta_{Y_\varepsilon}(x'')+\delta_{Y_\varepsilon}(x''')-n_\varepsilon w(x'',x'''))\\
&=\frac{2}{q}\sum_{x''\in C_q}\delta_{Y_\varepsilon}(x'')-\frac{1}{q}n_\varepsilon w(C_q).
\end{align*}
Hence, we have 
\begin{align*}
n_\varepsilon w(P_q)+\delta_{Y_\varepsilon}(P_q)&=n_\varepsilon w(C_q)+\delta_{Y_\varepsilon}(x)+\delta_{Y_\varepsilon}(x')-n_\varepsilon w(x,x')\\
&\leq \frac{2}{q}\sum_{x''\in C_q}\delta_{Y_\varepsilon}(x'')+\frac{q-1}{q}n_\varepsilon w(C_q)
\end{align*}
%$n_\varepsilon w(P_q)+\delta_{Y_\varepsilon}(P_q)=n_\varepsilon w(C_q)+\delta_{Y_\varepsilon}(x)+\delta_{Y_\varepsilon}(x')-n_\varepsilon w(x,x')\leq \frac{2}{q}\sum_{x''\in C_q}\delta_{Y_\varepsilon}(x'')+\frac{q-1}{q}n_\varepsilon w(C_q)$. 
Then, we have%the upper bound of the contributions of cycles in $\C_{X_\varepsilon}\setminus\B_3$ on $n_\varepsilon w(\C)$ are
\begin{align*}
n_\varepsilon w(\P)+\delta_{Y_\varepsilon}(\P)&=\sum_{P_q\in\P}\lrA{n_\varepsilon w(P_q)+\delta_{Y_\varepsilon}(P_q)}\\
&\leq\sum_{C_q\in\C_{X_\varepsilon}\setminus\B_3}\lrA{\frac{2}{q}\sum_{x''\in C_q}\delta_{Y_\varepsilon}(x'')+\frac{q-1}{q}n_\varepsilon w(C_q)}\\
&=\sum_{q=4}^{n_\varepsilon}\sum_{C_q\in\B_q}\lrA{\frac{2}{q}\sum_{x''\in C_q}\delta_{Y_\varepsilon}(x'')+\frac{q-1}{q}n_\varepsilon w(C_q)}\\
&=\sum_{q=4}^{n_\varepsilon}\lrA{\frac{2}{q}\mu_q+\frac{q-1}{q}\lambda_q}\\
&\leq \sum_{q=4}^{n_\varepsilon}\lrA{\frac{2}{4}\mu_q+\frac{3}{4}\lambda_q}=\frac{1}{2}\mu_{>3}+\frac{3}{4}\lambda_{>3},
\end{align*}
where the last inequality follows from $\frac{2}{q}\mu_q+\frac{q-1}{q}\lambda_q\leq \frac{2}{4}\mu_q+\frac{3}{4}\lambda_q$ for any $q\geq 4$ since $\lambda_q\leq2\mu_q$ for any $q\geq 4$ by (\ref{d<=2D}). 

Therefore, we have 
\begin{align*}
n_\varepsilon w(\C)&=n_\varepsilon w(\B_3)+n_\varepsilon w(C)\\
&\leq\lambda_3+\frac{1}{2}\mu_{>3}+\frac{3}{4}\lambda_{>3}\\
&\leq \frac{1}{2}\mu_3+\frac{1}{2}\mu_{>3}+\frac{3}{4}\lambda_3+\frac{3}{4}\lambda_{>3}\\
&=\frac{1}{2}\delta_{Y_\varepsilon}(X_\varepsilon)+\frac{3}{4}n_\varepsilon w(\C_{X_\varepsilon}),
\end{align*}
where the last inequality follows from $\lambda_3\leq \frac{1}{2}\mu_3+\frac{3}{4}\lambda_3$ since $\lambda_3\leq2\mu_3$ by (\ref{d<=2D}), and the last equality follows from (\ref{d=D}).
\end{proof}

%Next, we demonstrate how to use $\C$ to compute the 3-path packing $\P_{X_\varepsilon}$.
Next, we are ready to demonstrate the algorithm for $\P_{X_\varepsilon}$.

\medskip
\noindent\textbf{Step~1.} Compute in $O(n^3)$ time the cycle packing $\C$ in $G[X_\varepsilon]$ using the algorithm before Lemma~\ref{f1}.

\noindent\textbf{Step~2.} Initialize $\P_{X_\varepsilon}=\emptyset$.

\noindent\textbf{Step~3.} For each cycle $C\in\C$, orient it in an arbitrary direction, obtain a set of 3-paths $\P_C$ by deleting an edge every 2 edges along the oriented cycle starting from an initial vertex of $C$ to minimize $\delta_{Y_\varepsilon}(\P_C)+n_\varepsilon w(\P_C)$, and update $\P_{X_\varepsilon}\coloneqq \P_{X_\varepsilon}\cup \P_C$.
\medskip

Note that in Step 3, for each cycle $C\in\C$, there are $\size{C}$ ways to choose the initial vertex. By enumerating all $\size{C}$ cases and selecting the best one, we can find $\P_C$ in $O(\size{C}^2)$ time such that $\delta_{Y_\varepsilon}(\P_C)+n_\varepsilon w(\P_C)$ is minimized. 
This ensures that Step 3 takes $O(n^2)$ time. In fact, since $\size{C}\bmod 3=0$, it is sufficient to consider an initial vertex from only 3 consecutive vertices of $C$, reducing the number of cases to just 3.

Therefore, the algorithm for $\P_{X_\varepsilon}$ takes $O(n^3)$ time, dominated by computing $\C$ in Step 1.

\begin{theorem}\label{3-path}
The above algorithm takes $O(n^3)$ time to get a 3-path packing $\P_{X_\varepsilon}$ in $G[X_\varepsilon]$ such that $\delta_{Y_\varepsilon}(\P_{X_\varepsilon})+n_\varepsilon w(\P_{X_\varepsilon})\leq \delta_{Y_\varepsilon}(X_\varepsilon)+\frac{1}{2}n_\varepsilon w(\C_{X_\varepsilon})$. Similarly, there exists a $O(n^3)$-time algorithm to get a 3-path packing $\P_{Y_\varepsilon}$ in $G[Y_\varepsilon]$ with $\delta_{X_\varepsilon}(\P_{Y_\varepsilon})+n_\varepsilon w(\P_{Y_\varepsilon})\leq \delta_{X_\varepsilon}(Y_\varepsilon)+\frac{1}{2}n_\varepsilon w(\C_{Y_\varepsilon})$.
\end{theorem}
\begin{proof}
Consider the algorithm for $\P_{X_\varepsilon}$. As mentioned, its running time is $O(n^3)$. Then, we get an upper bound of $\delta_{Y_\varepsilon}(\P_{X_\varepsilon})+n_\varepsilon w(\P_{X_\varepsilon})$.

In Step 3, for each cycle $C\in\C$, if we choose the initial vertex uniformly at random, we can get a set of 3-paths $\P'_C$ such that $\EE{\delta_{Y_\varepsilon}(\P'_{C})}=\frac{2}{3}\sum_{x\in C}\delta_{Y_\varepsilon}(x)$, as there are $\frac{2}{3}\cdot\size{C}$ terminals in $\P'_C$ and the probability of each vertex of $C$ being one of the terminals is $\frac{2}{3}$. Moreover, since there are $\frac{2}{3}\cdot\size{C}$ edges in $\P'_C$, we also have $\EE{w(\P'_C)}=\frac{2}{3}w(C)$. Hence, we have 
\[
\EE{\delta_{Y_\varepsilon}(\P'_C)+n_\varepsilon w(\P'_C)} = \frac{2}{3}\sum_{x\in C}\delta_{Y_\varepsilon}(x)+\frac{2}{3}n_\varepsilon w(C).
\]

Since the algorithm selects the initial vertex to find $\P_C$ such that $\delta_{Y_\varepsilon}(\P_C)+n_\varepsilon w(\P_C)$ is minimized, it follows that 
\[
{\delta_{Y_\varepsilon}(\P_C)+n_\varepsilon w(\P_C)}\leq\EE{\delta_{Y_\varepsilon}(\P'_C)+n_\varepsilon w(\P'_C)}= \frac{2}{3}\sum_{x\in C}\delta_{Y_\varepsilon}(x)+\frac{2}{3}n_\varepsilon w(C).
\]
Recall that $\P_{X_\varepsilon}=\bigcup_{C\in\C} \P_C$. Thus, we have
\begin{align*}
\delta_{Y_\varepsilon}(\P_{X_\varepsilon})+n_\varepsilon w(\P_{X_\varepsilon})&\leq\sum_{C\in\C}\lrA{\frac{2}{3}\sum_{x\in C}\delta_{Y_\varepsilon}(x)+\frac{2}{3}n_\varepsilon w(C)}\\
&=\frac{2}{3}\delta_{Y_\varepsilon}(X_\varepsilon)+\frac{2}{3}n_\varepsilon w(\C)\\
&\leq\frac{2}{3}\delta_{Y_\varepsilon}(X_\varepsilon)+\frac{2}{3}\lrA{\frac{1}{2}\delta_{Y_\varepsilon}(X_\varepsilon)+\frac{3}{4}n_\varepsilon w(\C_{X_\varepsilon})}\\
&=\delta_{Y_\varepsilon}(X_\varepsilon)+\frac{1}{2}n_\varepsilon w(\C_{X_\varepsilon}),
\end{align*}
where the first equality follows from the fact that $\C$ is a cycle packing in $G[X_\varepsilon]$ and the second inequality follows from Lemma~\ref{f1}.

Similarly, there also exists a $O(n^3)$-time algorithm to get a 3-path packing $\P_{Y_\varepsilon}$ in $G[Y_\varepsilon]$ with $\delta_{X_\varepsilon}(\P_{Y_\varepsilon})+n_\varepsilon w(\P_{Y_\varepsilon})\leq \delta_{X_\varepsilon}(Y_\varepsilon)+\frac{1}{2}n_\varepsilon w(\C_{Y_\varepsilon})$.
\end{proof}

\begin{theorem}\label{main}
For BTTP with any $n$ and any constant $\varepsilon>0$, there is a randomized $(3/2+\varepsilon)$-approximation algorithm with a running time of $O(n^3)$.
\end{theorem}
\begin{proof}
By Theorem~\ref{3-path}, we can get 3-path packings $\P_{X_\varepsilon}$ in $G[X_\varepsilon]$ and $\P_{Y_\varepsilon}$ in $G[Y_\varepsilon]$ in $O(n^3)$ time with $\delta_{Y_\varepsilon}(\P_{X_\varepsilon})+n_\varepsilon w(\P_{X_\varepsilon})+\delta_{X_\varepsilon}(\P_{Y_\varepsilon})+n_\varepsilon w(\P_{Y_\varepsilon})\leq \delta_{Y_\varepsilon}(X_\varepsilon)+\frac{1}{2}n_\varepsilon w(\C_{X_\varepsilon})+\delta_{X_\varepsilon}(Y_\varepsilon)+\frac{1}{2}n_\varepsilon w(\C_{Y_\varepsilon})$. 

If $n\geq 108d^3$, by Lemma~\ref{lb2} and Theorem~\ref{res-construction}, we can obtain a solution in $O(n^2)$ time with an expected weight of at most $(3/2+\varepsilon)\cdot\OPT$ by applying $\P_{X_\varepsilon}$ and $\P_{Y_\varepsilon}$ to our 3-path construction and using the randomized labeling algorithm. Otherwise, as mentioned, we have $n< 108d^3=O_\varepsilon(1)$, and in this case, we can solve the problem optimally in constant time. Therefore, there is a randomized $(3/2+\varepsilon)$-approximation algorithm for BTTP, and the total running time is $O(n^3)$.
\end{proof}

Our algorithm is randomized because it uses a simple randomized labeling technique.
It can be derandomized in polynomial time using the well-known method of conditional expectations in~\cite{williamson2011design}, while preserving the approximation ratio. 
%See examples in~\cite{miyashiro2012approximation,zmor}. 
To show this, by the proof of Theorem~\ref{res-construction}, we only need to show how to derandomize the algorithm for $n\geq 108d^3$, i.e., how to find in polynomial time a labeling for 3-paths in $\P_{X_\varepsilon}$ and $\P_{Y_\varepsilon}$ such that using this labeling the 3-path construction generates a solution with a weight of at most 
\[
UB\coloneqq\delta_{Y_\varepsilon}(\P_{X_\varepsilon})+n_\varepsilon w(\P_{X_\varepsilon})+\delta_{X_\varepsilon}(\P_{Y_\varepsilon})+n_\varepsilon w(\P_{Y_\varepsilon})+\varepsilon\cdot\OPT.
\]

In the following, we demonstrate the main idea of the derandomization using the method of conditional expectations. Some detailed examples can be found in~\cite{miyashiro2012approximation,zmor}.

Recall that there are $md$ 3-paths in $\P_{X_\varepsilon}$ (resp., $\P_{Y_\varepsilon}$), which will be labeled using $\{P_1,..., P_{md}\}$ (resp., $\{Q_1,...,Q_{md}\}$). Previously, the algorithm uses a randomized labeling method such that for each $i\in\{1,...,$ $md\}$ each 3-path in $\P_{X_\varepsilon}$ (resp., $\P_{Y_\varepsilon}$ ) is labeled as $P_i$ (resp., $Q_i$) with the same probability of $\frac{1}{md}$. Now, we determine the \emph{random decision} on $P_1,..., P_{md}$ sequentially. 

Suppose that we have determined the labels $P_1,...,P_s$, where $0\leq s<md$, such that by randomly labeling the 3-paths in $\P_{X_\varepsilon}\setminus\{P_1,...,P_s\}$ (resp., $\P_{Y_\varepsilon}$) using $\{P_{s+1},..., P_{md}\}$ (resp., $\{Q_1,...,Q_{md}\}$) the 3-path construction generates a solution with an expected weight of $\EE{Sol\mid P_1,...,P_s}\leq UB$. Now, we want to determine the label of $P_{s+1}$ such that by randomly labeling the 3-paths in $\P_{X_\varepsilon}\setminus\{P_1,...,P_{s+1}\}$ (resp., $\P_{Y_\varepsilon}$) using $\{P_{s+2},$ $..., P_{md}\}$ (resp., $\{Q_1,...,Q_{md}\}$) the 3-path construction generates a solution with an expected weight of $\EE{Sol\mid P_1,...,P_{s+1}}\leq UB$. It can be done simply by letting 
\[
P_{s+1}=\text{arg min}_{P_{s+1}\in \P_{X_\varepsilon}\setminus\{P_1,...,P_s\}}\EE{Sol\mid P_1,...,P_{s+1}}.
\]

When calculating the conditional expected weight, we can still use the assumptions made in the proof of Theorem~\ref{res-construction}, since $UB$ is derived based on these assumptions. Thus, it is easy to check that the conditional expected weight can be computed in polynomial time, and then by recursion, the labels of 3-paths in $\P_{X_\varepsilon}$ can be determined in polynomial time.
Similarly, by sequentially determining the random decision on $Q_1,...,$ $Q_{md}$, the labels of 3-paths in $\P_{Y_\varepsilon}$ can also be determined in polynomial time.

\section{Application}\label{SC.5}
To test the performance of our algorithm, we introduce a new BTTP instance and apply our algorithm to it. 
Since the 3-path construction in Theorem~\ref{feasibility} requires $n$ to be sufficiently large, we instead use the 3-path construction in Theorem~\ref{feasibility+} for the experiments.
Additionally, we extend our 3-path construction to a \emph{3-cycle construction} by slightly modifying the design of normal super-games, which turns out to be more practical when $n$ is small.

\textbf{The New Instance.}
It is motivated by the real situation of NBA.
Since 2004, the number of teams in NBA has always been 30, where there are 15 teams in the Western Conference and 15 teams in the Eastern Conference. 
Thus, Hoshino and Kawarabayashi~\cite{Bipartite-conference} constructed an NBA instance with $n=15$ for BTTP.
%and motivated by the following reason.
%It was also considered as an instance of BTTP with $n=15$ in~\cite{Bipartite-conference}. 
In recent years, there have been rumors saying that NBA is poised to expand to 32 teams, with the potential inclusion of two new teams from Las Vegas and Seattle. Therefore, we create an instance, where we assume that two new teams from Las Vegas and Seattle join in the Western Conference, and also the Minnesota Timberwolves, originally from the Western Conference, are moved to join the Eastern Conference.
%Minnesota Timberwolves, one of teams in the previous Western Conference, is moved to join in the Eastern Conference.
There are 32 teams in total, and hence this is an instance for BTTP with $n=16$. 
Note that the strict conditions of BTTP are not part of the NBA scheduling requirement, as evidenced by the San Antonio Spurs playing 6 consecutive home games followed by 8 consecutive away games during the 2009-10 regular season~\cite{Bipartite-conference}, as well as the NBA scheduling games on nonconsecutive days.
