\begin{algorithm}[h]
	\caption{RBC-Based Energy Dispatch}
	\label{Alg_RBC}
	\small
	\SetKwInOut{Input}{Input}
	\SetKwInOut{Output}{Output}

	\Input{
		Time step $t$, load demand $P_{\text{load}}(t)$, PV generation $P_{\text{pv}}(t)$, wind generation $P_{\text{w}}(t)$, battery limits $P_{\text{bat}}^{\max}$, SOC limit $SOC(t)$, grid status $G_{\text{flag}}(t)$, grid capacity $P_{\text{grid}}^{\max}$, DG capacity $P_{\text{dg}}^{\max}$
	}
	\Output{
		Battery action, grid import/export, DG operation, SOC, cost metrics
	}

	\For{each time step $t$}{
		\uIf{$G_{\text{flag}}(t) = 1$ (grid available)}{
			\uIf{$P_{\text{load}}(t) < P_{\text{pv}}(t) + P_{\text{w}}(t)$}{
				Compute surplus: $P_{\text{sur}} = P_{\text{pv}} + P_{\text{w}} - P_{\text{load}}$ \\
				\uIf{$P_{\text{sur}} \leq P_{\text{bat}}^{\max,\text{ch}}$}{
					Charge battery with $P_{\text{sur}}$
				}
				\Else{
					Charge battery with $P_{\text{bat}}^{\max,\text{ch}}$ \\
					Export remaining power to grid
				}
				Record grid export
			}
			\Else{
				Compute deficit: $P_{\text{def}} = P_{\text{load}} - (P_{\text{pv}} + P_{\text{w}})$ \\
				\uIf{$P_{\text{def}} \leq P_{\text{bat}}^{\max,\text{dis}}$ and $SOC(t) > 0$}{
					Discharge battery
				}
				\Else{
					Import remaining deficit from grid (up to $P_{\text{grid}}^{\max}$)
				}
				Record SOC and grid import
			}
		}
		\Else{ % Grid outage
			\uIf{$P_{\text{load}} > P_{\text{pv}} + P_{\text{w}} + P_{\text{bat}}^{\max,\text{dis}}$}{
				Use DG to meet remaining demand (up to $P_{\text{dg}}^{\max}$)
			}
			\Else{
				Discharge battery to meet load
			}
			Record DG usage and cost
		}
	}
	Record overall performance metrics
\end{algorithm}


