\begin{algorithm}[h]
	\caption{Proposed DRL-PPO Framework for MG Energy Management.}
	\label{Alg_PPO}
	\small
	\SetKwInOut{Input}{Input}
	\SetKwInOut{Output}{Output}

	\Input{MG environment with system parameters and real-time data}
	\Output{Trained PPO policy $\pi_\theta^*$ for real-time energy management}

	\textbf{Initialize} PPO agent with policy network $\pi_\theta$ \\

	\For{each episode $e = 1, 2, \dots, E$}{
		Reset environment: $s_0 \gets \texttt{env.reset()}$ \\
		\For{each time step $t = 1, 2, \dots, T$}{
			Observe state: $s_t = [SOC_t, h_t, P_{pv}(t), P_w(t), P_{load}(t), G_{\text{flag}}(t)]$ \\
			Select action: $a_t = [P_{\text{bat}}(t), P_{\text{dg}}(t)] \sim \pi_\theta(s_t)$ \\
			Clip actions:
			\[
			P_{\text{bat}}(t) \in [-P_{\text{bat}}^{\max,\text{ch}}, P_{\text{bat}}^{\max,\text{dis}}],
			\quad
			P_{\text{dg}}(t) \in [0, P_{\text{dg}}^{\max}]
			\]
			Compute net power balance:
			\[
			P_{\text{net}}(t) = P_{pv}(t) + P_w(t) + P_{\text{bat}}(t) + P_{\text{dg}}(t) - P_{load}(t)
			\]
			Compute grid interaction cost:
			\[
			C_{\text{grid}}(t) =
			\begin{cases}
				- P_{\text{net}}(t) \cdot C_{\text{sell}}, & \text{if } P_{\text{net}}(t) > 0 \\
				P_{\text{net}}(t) \cdot C_{\text{grid}}, & \text{if } P_{\text{net}}(t) < 0
			\end{cases}
			\]
			Compute cost function and reward:
			\[
			r_t = - \left( C_{\text{grid}}(t) + C_{\text{dg}}(t) + C_{\text{deg}}(t) \right)
			\]
			Store transition $(s_t, a_t, r_t, s_{t+1})$ in buffer \\
			\If{episode ends or batch size threshold reached}{
				Estimate advantage using Generalized Advantage Estimation (GAE) \\
				Update policy $\pi_\theta$ via PPO clipped surrogate objective
			}
			Update state: $s_t \gets s_{t+1}$
		}
	}

	\textbf{End Training Phase} \\

	\textbf{Evaluation Phase:} \\
	Reset environment: $s_0 \gets \texttt{env.reset()}$ \\
	\For{each evaluation step $t = 1, 2, \dots, T$}{
		Observe state $s_t$ \\
		Select action: $a_t = \pi^*_\theta(s_t)$ using trained policy \\
		Execute action and record performance metrics (e.g., cost, reliability, renewable utilization)
	}
\end{algorithm}


\subsection{Proposed DRL Framework}
%A Deep Reinforcement Learning (DRL) approach based on Proximal Policy Optimization (PPO) is proposed to solve the energy management problem. 
To enhance the adaptability of MG EM, this study integrates PPO, a policy-gradient reinforcement learning algorithm, into the dispatch strategy. Unlike rule-based methods, PPO learns an optimal control policy through interactions with the environment, optimizing energy storage utilization, grid imports/exports, and DG usage dynamically. The proposed DRL-PPO energy management algorithm is designed to optimize and regulate the energy flows within a community MG incorporating diverse energy sources, including RESs, battery storage, and conventional power sources.  The details of the implemented energy-dispatch strategy are presented in Algorithm \ref{Alg_PPO}.


\subsubsection{State Space}
The state vector at time $t$ is defined as:
\[
s_t = [SOC(t), h(t), P_{pv}(t), P_{w}(t), P_{load}(t), G_{flag}(t)]
\]

\subsubsection{Action Space}
The action vector at time $t$ is defined as:
\[
a_t = [\Delta P_{bat}, P_{dg}]
\]

\subsubsection{Reward Function}
The reward function is designed to minimize operational costs:
\[
r_t = -(C_{grid} + C_{deg} + C_{dg})
\]

\subsubsection{Training Methodology} %The PPO agent is trained in a simulated environment with real-world MG data. After training, the learned policy is deployed to optimize real-time dispatch. 
The PPO agent is trained in a simulated environment using real-world MG data. Subsequently, the learned policy is deployed to optimize the real-time dispatch. The PPO training process comprises the following steps.

\begin{itemize}
	\item Collecting trajectories using the current policy.
	\item Computing advantage estimates using GAE.
	\item Updating the policy using stochastic gradient descent.
	\item Iterating until convergence.
\end{itemize}



\subsubsection{PPO Algorithm}

The PPO is selected owing to its stable policy updates, robustness in continuous action spaces, and sample efficiency. The optimization problem is addressed using the PPO clipped objective function, as defined in Eq. \ref{PPO_clipped}.
\begin{equation}\label{PPO_clipped}
	L(\theta) = \mathbb{E}_t \left[ \min \left( r_t(\theta) A_t, \text{clip} \left( r_t(\theta), 1 - \epsilon, 1 + \epsilon \right) A_t \right) \right]
\end{equation}
where $ r_t(\theta) $ represents %the probability ratio, which can be defined as shown in Eq. \ref{Eq.Pob_ratio}. 
the probability ratio between the current and previous policies:
\begin{equation}\label{Eq.Pob_ratio}
	r_t(\theta) = \frac{\pi_{\theta}(a_t \mid s_t)}{\pi_{\theta_{\text{old}}}(a_t \mid s_t)}
\end{equation}
where \( A_t \) denotes the advantage function, and \( \epsilon \) %signifies the clipping parameter to prevent large policy updates.
is the clipping threshold that constrains the policy update step. This formulation prevents excessively large policy shifts that could destabilize learning, especially in highly variable environments such as real-time microgrid dispatch.
