\subsection{Proof of \cref{thm:minit_vinit}}
\begin{lemma}
    \label{lem:minit_morphism}
    $\minit : \mathcalG \to \gGa^{A\times A}$ is a morphism
\end{lemma}
\begin{proof}
    Consider $\lambda,\lambda'\in \mathcalG$.
    For any $i\ne j$, $a\in \ldomA_i$ and $b\in \ldomA_j$, $\minit(\lambda\lambda')_{a,b} = \Id = (\minit(\lambda)_{a,b})(\minit(\lambda')_{a,b})$. 

    For $a,b\in \ldomA_i$,
    \begin{align*}
    \minit(\lambda\lambda')_{a,b} &= (\lambda\lambda')_a(\lambda\lambda')_b^{-1}\\
    &= \lambda_a\lambda'_a{\lambda'_b}^{-1}\lambda_b^{-1}\\
    \text{Since $\Gamma_i$ is abelian, }&= \lambda_a\lambda_b^{-1}\lambda'_a{\lambda'_b}^{-1}\\
    &= \minit(\lambda)_{a,b}\cdot \minit(\lambda')_{a,b}
    \end{align*}
\end{proof}
\begin{lemma}
    \label{lem:initMorph_correct}
    $\phiRepr(\pi\gGa) = \{ \lambda\in \mathcalG, \minit(\lambda) = \vinit\}$
\end{lemma}
\begin{proof}
For $\sigma\in\pi\gGa$ and $a,b\in \ldomA_i$, we have:
\begin{align*}
\minit(\phiRepr(\sigma))_{a,b} &= \phiRepr(\sigma)_a\phiRepr(\sigma)_b^{-1}\\
&=(\mapMa^i_a)^{-1}\sigma\sigma^{-1}\mapMa^i_b\\
&=(\vinit)_{a,b}
\end{align*}
We now show the other inclusion. Let $\lambda\in\mathcalG$ such that $\minit(\lambda) = \vinit$. Fix, for all $i$, some $a_i\in \ldomA_i$, and let $\sigma_i := \mapMa^i_{a_i}\lambda_{a_i}$. Then, for any $b\in \ldomA_i$,
\begin{align*}
    \mapMa^i_{b}\lambda_b &=\mapMa^i_b\lambda_b\lambda_{a_i}^{-1}\lambda_{a_i}\\
    &=\mapMa^i_b \minit(\lambda)_{b,a_i}\lambda_{a_i}\\
    &=\mapMa^i_b(\mapMa^i_b)^{-1}\mapMa^i_{a_i}\lambda_{a_i}\\
    &= \sigma_i
\end{align*}
Thus, for any $b$, $\lambda_b = (\mapMa^{i(b)}_b)^{-1}\sigma_{i(b)} = \phiRepr_{i(b)}(\sigma_{i(b)})_b$, which in turn implies that $\lambda = \phiRepr(\sigma_1\dots\sigma_m)$.
\end{proof}
