\subsection{Proof of \cref{thm:semi_local_morphisms}}
We introduce two intermediate lemmas.
First, we show that the membership to $\kDel_{i,j}$ is definable in $\FPC$:
\begin{lemma}
    There is a $\FPC$ formula $\intro*\aut(i,j,\mu,\nu)$ such that $\mathfrak A\models \aut(i,j,\alpha,\beta)$ iff $\gamma^i_\alpha\gamma^j_\beta\in \kDel_{i,j}$.
\end{lemma}
\begin{proof}
:
\[\reintro *\aut(i,j,\mu,\nu) := \forall a_i\in \ldomA_i, a_j\in \ldomA_j,\exists b_i,b_j, \begin{landcases}
    \PhiAB(i,\mu,a_i,b_i)\\
    \PhiAB(j,\nu,a_j,b_j)\\
    \Xi(a_i,a_j,b_i,b_j)
\end{landcases}
\]
where
\[\Xi(a_i,a_j,b_i,b_j) := E(a_i,a_j)\iff E(b_i,b_j)\qedhere\]
\end{proof}
This in turn enables us to check if two elements of $\lGa_i\lGa_j$ belong to the same coset of $\kDel_{i,j}$:
\begin{lemma}
    \label{lem:slmorph}
    There is a $\FPC$ formula $\intro* \coset(i,j,\mu,\nu,\mu',\nu')$ such that
    \[\mathfrak A\models \coset(i,j,\alpha,\beta,\alpha',\beta') \iff \gamma^i_{\alpha}\gamma^j_\beta\kDel_{i,j} = \gamma^i_{\alpha'}\gamma^j_{\beta'}\kDel_{i,j}\]
\end{lemma}
\begin{proof}
For $\alpha,\beta,\alpha',\beta'$,
$\gamma^i_\alpha\gamma^j_\beta\kDel_{i,j} = \gamma^i_{\alpha'}\gamma^j_{\beta'}\kDel_{i,j}$
iff $\chi := (\gamma^i_{\alpha'}\gamma^j_{\beta'})^{-1}\gamma^i_\alpha\gamma^j_\beta\in\kDel_{i,j}$. Because $\lGa_i$ and $\lGa_j$
act on disjoint sets, they commute, thus $\chi\in \lGa_i\lGa_j$
and there is a pair $(\alpha'',\beta'')$ such that $\chi = \gamma^i_{\alpha''}\gamma^j_{\beta''}$. Because $\chi\in\lGa_i\lGa_j$, $\chi\in\kDel_{i,j}$ is equivalent to $\chi\in\Aut(\slE_{i,j})$, which yields the following formula:
%TODO: slStrA
\[\coset(i,j,\mu,\nu,\mu',\nu'):= \exists\mu'',\nu'',\begin{landcases}
    \gamma^i_{\mu''} = (\gamma^i_{\mu'})^{-1}\gamma^i_\mu\\
    \gamma^j_{\nu''} = (\gamma^j_{\nu'})^{-1}\gamma^j_\nu\\
    \aut(i,j,\mu'',\nu'')
\end{landcases}
\]
To ease reading, we have included two clauses of the form $\sigma = \tau^{-1}\rho$ which are not $\FPC$ formulae per se. However, when the graphs of $\sigma$, $\tau$ and $\rho$ are defined by $R_\sigma,R_\tau$ and $R_\rho$, respectively, this equality can easily be defined in $\FPC$.
\end{proof}
We are now ready to prove \cref{thm:semi_local_morphisms}:
\begin{proof}[Proof of \cref{thm:semi_local_morphisms}]
We can  choose as a representative of the coset $\sigma\kDel_{i,j}$ the lexicographically smallest pair $(\alpha,\beta)$ such that $\gamma^i_{\alpha}\gamma^j_{\beta}\in\sigma\kDel_{i,j}$.
The following formula holds for $(i,j,\alpha,\beta)$ iff $(\alpha,\beta)$ is such a pair for some coset:
\[\mathsf{witness}(i,j,\mu,\nu) := \forall \mu',\nu',\begin{lorcases} 
    \mu\nu\le_{lex}\mu'\nu'\\
    \lnot\coset(i,j,\mu,\nu,\mu',\nu')
\end{lorcases}\]
%
This shows that $\reintro*\slOm_{i,j} := \mathsf{witness}(\mathfrak A,i,j)$ is definable in $\FPC$.

We aim to define $\slm_{i,j}(\LaTeXgamma)(\alpha,\beta)$ as the unique $(\alpha',\beta')\in\slOm_{i,j}$ such that $\LaTeXgamma\gamma^i_{\alpha}\gamma^j_{\beta}\in(\gamma^i_{\alpha'}\gamma^j_{\beta'})\kDel_{i,j}$, that is, such that $(\gamma^i_{\alpha'}\gamma^j_{\beta'})^{-1}\LaTeXgamma\gamma^i_{\alpha}\gamma^j_{\beta}\in \kDel_{i,j}$.
Note that, rather than keeping $\slm_{i,j}$ undefined on $(\oA)^2\setminus \slOm_{i,j}$, we simply set it to act trivially.
This indeed defines a morphism, as the action of $\slm_{i,j}(\LaTeXgamma)$ on $\slOm_{i,j}$ is, by construction, isomorphic to the action of $\LaTeXgamma$ on the set of cosets of $\kDel_{i,j}$ in $\lGa_i\lGa_j$ by left multiplication. For the same reason, $\ker({\slm_{i,j}}) = \kDel_{i,j}$.
\AP
\[\intro *\slMorph(i,j,R_\LaTeXgamma,\mu_s\nu_s,\mu_t\nu_t):= \begin{lorcases}
    \begin{landcases}\lnot\mathsf{witness}(i,j,\mu_s,\nu_s)\\ \mu_s = \mu_t \\ \nu_s = \nu_t\end{landcases}\\
    \begin{landcases}
        \mathsf{witness}(i,j,\mu_s,\nu_s)\\
        \mathsf{witness}(i,j,\mu_t,\nu_t)\\
        \Xi
    \end{landcases}
\end{lorcases}
\]
where
\[\Xi := \exists \mu',\nu',
\begin{landcases}
    \gamma^i_{\mu'}\gamma^j_{\nu'} = (\gamma^i_{\mu_t}\gamma^j_{\nu_t})^{-1}\LaTeXgamma\gamma^i_\mu\gamma^j_\nu \\
    \aut(i,j,\mu',\nu')
\end{landcases}
\]
This corresponds exactly to our definition of a definable morphism, in the sense that for any $\LaTeXgamma\in \lGa_i\lGa_j$,
\[\slMorph(\mathfrak A,i,j,\graph(\gamma)) = \graph(\slm_{i,j}(\gamma))\]
Note that, while we usually prefer to keep second order variables on the left-most side, we did not do so this time to underline the fact that $\slMorph$ actually defines a family of morphisms, one for each pair of colors.

Finally, let us justify our use of permutations equalities in the definition of $\Xi$. As the graph $R_\LaTeXgamma$ of $\LaTeXgamma$ is a parameter of $\slMorph$, and for all $i,\mu$, the graph of $\gamma^i_\mu$ is given by $\PhiAB(i,\mu)$, the subformula $\gamma^i_{\mu'}\gamma^j_{\nu'} = (\gamma^i_{\mu_t}\gamma^j_{\nu_t})^{-1}$ is in $\FPC$, following the same idea as in \cref{lem:perm_equalities}.
\end{proof}
\section{Proof of \cref{thm:ext_semi_local_morphisms}}
\begin{lemma}
    \label{lem:vartheta_morphism}
    For all $i< j\le m$, $\vartheta_{i,j}$ is a morphism.
\end{lemma}
\begin{proof}
Consider $\lambda,\lambda'\in \mathcalG$ and $(a,b)\in A\times A$. We aim to show that
\[(\vartheta_{i,j}(\lambda)\vartheta_{i,j}(\lambda'))_{(a,b)} =
\vartheta_{i,j}(\lambda\lambda')_{(a,b)}\]
If $(a,b)\not\in \ldomA_i\times \ldomA_j$, both sides of this equation evaluate to $\Id$. Otherwise,
\begin{align*}
    (\vartheta_{i,j}(\lambda)\vartheta_{i,j}(\lambda'))_{(a,b)} &=
    \slm_{i,j}(\lambda_a\lambda_b)\slm_{i,j}(\lambda'_a\lambda'_b)&\\
    &= \slm_{i,j}(\lambda_a\lambda_b\lambda'_a\lambda'_b)&\text{$m_{i,j}$ morph.}\\
    &= \slm_{i,j}(\lambda_a\lambda'_a\lambda_b\lambda'_b) &\text{ $\lGa_i\lGa_j$ ab.}\\
    &= \vartheta_{i,j}(\lambda\lambda')_{(a,b)}&\qedhere
\end{align*}
\end{proof}

\begin{lemma}
    \label{lem:vartheta_correct}
For any $i< j$, $(a_i,a_j)\in \ldomA_i\times \ldomA_j$, and $\sigma\in\pi\gGa$,
\[\vartheta_{i,j}(\phiRepr(\sigma)) = \gslv_{i,j}(a_i,a_j)\iff \slE_{i,j}^{\sigma} = \slE_{i,j}^{\mapMa^i_{a_i}\oplus\mapMa^j_{a_j}}\]
\end{lemma}
\begin{proof}
    First, notice that, for any $i<j$ and $a_i\in \ldomA_i, a_j\in \ldomA_j$, $\gslv_{i,j}(a_i,a_j) = \vartheta_{i,j}(\phiRepr(\sigma))$, where $\sigma$ is any element of $\pi\gGa$ such that $\sigma_{\restriction \ldomA_i\cup \ldomA_j} = \mapMa^i_{a_i}\oplus\mapMa^j_{a_j}$.

    It is thus only left to prove that, for two labellings $\sigma,\tau\in\pi\gGa$, $\vartheta_{i,j}(\phiRepr(\sigma)) = \vartheta_{i,j}(\phiRepr(\tau))$ iff $\sigma$ and $\tau$ yield the same encoding of $\slE_{i,j}$.
    \Cref{eqn:global_repr_coset} implies that
    \[\vartheta_{i,j}(\phiRepr(\sigma)) = \vartheta_{i,j}(\phiRepr(\tau)) \iff \vartheta_{i,j}(\psiRepr(\sigma^{-1}\tau)) = 1\]
    so that it is only left to show that, $\psiRepr(\LaTeXgamma) \in \ker(\vartheta_{i,j})\iff \LaTeXgamma\in\Aut(\slE_{i,j})$.
    And indeed:
    \begin{align*}
        \vartheta_{i,j}(\psiRepr(\LaTeXgamma)) \!=\! 1\!&\iff\! \forall a\in\ldomA_i,b\in\ldomA_j, \slm_{i,j}(\psiRepr(\LaTeXgamma)_a\psiRepr(\LaTeXgamma)_b)\!=\! 1\\
        \text{by def. of }\psiRepr,\!&\iff\! \forall a\in\ldomA_i,b\in\ldomA_j,\slm_{i,j}(\LaTeXgamma_{\restriction \ldomA_i}\LaTeXgamma_{\restriction \ldomA_j}) = 1\\
        &\iff\! \LaTeXgamma_{\restriction \ldomA_i\cup\ldomA_j}\in\ker(\slm_{i,j})\\
        \text{by def. of }\slm_{i,j},\!&\iff\! \LaTeXgamma_{\restriction \ldomA_i\cup\ldomA_j} \in\Aut(\slm_{i,j})
    \end{align*}
%     Let $i\ne j$, $(a_i,a_j)\in \ldomA_i\times \ldomA_j$, and $\sigma\in\pi\gGa$. First, note that \cref{lem:OAi_coset} implies that \[\sigma^{-1}_{\restriction \ldomA_i\cup \ldomA_j}\mapMa^i_{a_i}\mapMa^j_{a_j}\in\lGa_i\lGa_j.\]
%     Moreover, because $\vartheta_{i,j}(\sigma)$ and $\gslv_{i,j}(a_i,a_j)$ have the same value on each $(a,b)\in A^2\setminus \ldomA_i\times \ldomA_j$, we can study only their values on $\ldomA_i\times \ldomA_j$. For $(a,b)\in \ldomA_i\times\ldomA_j$,
%     \begin{align*}
