\subsubsection{Decoupling of the gain factor $\kappa_n$} The concepts of \emph{Rabi sum-square} and \emph{Rabi attentions} are introduced to decouple the gain factor $\kappa_n$.  
% introduce the 
% variables of \emph{Rabi sum-square} and \emph{Rabi attentions} to . 
\begin{definition} \textbf{\emph{(Rabi sum-square and Rabi attentions)}} We define the Rabi sum-square as the sum square of the Rabi frequencies of the reference signals, denoted as  
    \begin{align}
 \mathcal{A} \overset{\Delta}{=} \sum_{n = 1}^N \Omega_{r,n}^2.
\end{align}
Additionally, we introduce the variables, {referred to as the Rabi attention, as}
\begin{align}
    \alpha_n\overset{\Delta}{=}\frac{\Omega_{r,n}^2}{\sum_{m = 1}^N\Omega_{r,m}^2}, \forall n,
\end{align}
to characterize the ratio of $\Omega_{r,n}^2$ to the Rabi sum-square {$\mathcal{A}$}.
% This ratio is referred to as the Rabi attention for band $n$. 
The sum of all Rabi attentions equals 1 as 
% $\sum_{n = 1}^N\alpha_n = \frac{\sum_{n=1}^N\Omega_{r,n}^2}{\sum_{m=1}^N\Omega_{r,m}^2} = 1$. 
{$\sum_{n = 1}^N\alpha_n = 1$}. 
\end{definition}
One can observe that the optimization of the Rabi frequencies $\{\Omega_{r,1}, \Omega_{r, 2}, \cdots, \Omega_{r, N}\}$ is equivalent to the optimization of the Rabi sum-square and all Rabi attentions. This is attributed to the one-to-one mapping 
\begin{align}
    \Omega_{r,n} = \sqrt{\mathcal{A}\alpha_n},\:\forall n. 
\end{align}
Utilizing this equivalence, the DC bias, $\mathcal{P}_r$, can be reformulated as a function of the Rabi sum-square:
\begin{align}\label{eq:laserpower2}
    \mathcal{P}_r = \mathcal{P}(\boldsymbol{\Omega}_r) = P_{\rm in}\exp\left(-\frac{\chi_0\mathcal{A}}{\mathcal{A} + \Gamma^2}\right).
\end{align} 
Moreover, the gain factor, $\kappa_n$, for band $n$ can be recast as 
\begin{align}\label{eq:decoupling_kappa}
    \kappa_n &= \mathcal{P}_r\frac{2\chi_0\Gamma^2\Omega_{r,n}}{(\sum_{m=1}^N\Omega_{r,m}^2 + \Gamma^2)^2}\frac{\mu_n}{\hbar} =\mathcal{P}_r\frac{2\chi_0\Gamma^2\sqrt{\mathcal{A}\alpha_n}}{(\mathcal{A} + \Gamma^2)^2}\frac{\mu_n}{\hbar}, \notag \\
    & =\frac{2\chi_0\Gamma^2}{\hbar}\mathcal{P}_r\frac{\sqrt{\mathcal{A}}}{(\mathcal{A}+\Gamma^2)^2}\sqrt{\alpha_n}\mu_n \overset{\Delta}{=} \varrho_0\sqrt{\alpha_n}\mu_n,
\end{align}
where 
% $\varrho_0\overset{\Delta}{=}\frac{2\chi_0\Gamma^2}{\hbar}\mathcal{P}_r\frac{\sqrt{\mathcal{A}}}{(\mathcal{A}+\Gamma^2)^2}$. 
\begin{equation}\label{eq:Global_gain}
    \varrho_0\overset{\Delta}{=}\frac{2\chi_0\Gamma^2}{\hbar}\mathcal{P}_r\frac{\sqrt{\mathcal{A}}}{(\mathcal{A}+\Gamma^2)^2}.
\end{equation}
The relationship in \eqref{eq:decoupling_kappa} reveals that the gain factor for band $n$ is composed of three parts: the transition dipole moment $\mu_n$, the parameter $\varrho_0$ termed as the \emph{global gain}, and the Rabi attention $\sqrt{\alpha_n}$\footnote{\color{black}Without causing confusion, we will term both $\alpha_n$ and $\sqrt{\alpha_n}$ as the ``Rabi attention" in subsequent discussions.}. This structure allows {for} the decoupling of the multi-band atomic amplifier in Fig.~\ref{img:decoupling}, which is elaborated in Remark 3.

