{Multi-band RAREs can enable multi-granularity wireless sensing by exploiting the frequency-dependent phase sensitivity of multi-band signals.} In this scenario, 
our objective is to recover the displacements, $\{d_n\}$, of all sensing targets from the received signal, $\{y_n\}$, formulated as 
\begin{align}\label{eq:yn_sense}
    y_n = \varrho_0^\star \sqrt{\alpha_n}\mu_n h_n\sqrt{P_{{\rm t},n}}e^{j\frac{\omega_n}{c}d_n} +z_n.
\end{align}
To this end, we use the ML detector to estimate $d_n$ as 
\begin{align}
    \hat{d}_n = \frac{c}{\omega_n}\angle\left(\frac{y_n}{\varrho_0^\star\sqrt{\alpha}_n\mu_nh_n\sqrt{P_{{\rm t},n}}}\right), \forall n.
\end{align}

The sensing accuracy of $\hat{d}_n$ can be assessed using the NCLRB, defined as the CRLB of $d_n$ normalized by the variance of $d_n$. The NCLRB offers a theoretical lower bound of the normalized mean square error when estimating $d_n$. To be specific, we assume $d_n$ a uniform distribution, $d_n \sim \mathcal{U}[-\frac{\pi c}{\omega_n}, \frac{\pi c}{\omega_n}]$, yielding $\mathbb{E}(|d_n|^2) = \frac{\pi^2 c^2}{3\omega_n^2}$. Following the derived signal model in \eqref{eq:yn_sense}, the NCRLB of $d_n$ is formulated as 
\begin{align}
   {\rm NCRLB}(d_n) &= \frac{{\rm CRLB}(d_n)}{\mathbb{E}(|d_n|^2)}
    = \frac{1}{\mathbb{E}(|d_n|^2)}
   \frac{c^2}{\omega_n^2}\frac{1}{2{\rm SNR}_n},\\
   &= \frac{3B_nC_2}{2\pi^2|h_n|^2P_{{\rm t}, n}} + \frac{ 3\mathcal{P}_rB_nC_1}{2\pi^2\alpha_n\mu_n^2{\varrho_0^\star}^2 |h_n|^2P_{{\rm t}, n}}. \notag
\end{align}
% % We now focus on the optimal design of Rabi attentions in this multi-band sensing application. 
% To eliminate the discrepancies of CRLBs caused by the distinct feasible ranges of $d_n$, i.e., $d_n \in [-\frac{\pi c}{\omega_n}, \frac{\pi c}{\omega_n}]$, we use 
% % $E(|d_n|^2)$
% {$\mathbb{E}[|d_n|^2]$}
% to normalize the CRLB. 
% Assuming $d_n$ a uniform distribution, $d_n \sim \mathcal{U}[-\frac{\pi c}{\omega_n}, \frac{\pi c}{\omega_n}]$, 
% % we find that $E(|d_n|^2) = \frac{\pi^2}{3\omega^2}$, which results in the normalized CRLB (NCRLB) expressed as 
% {we normalize the CRLB by $\mathbb{E}(|d_n|^2) = \frac{\pi^2 c^2}{3\omega_n^2}$, yielding the normalized CRLB (NCRLB):}
% \begin{align}
%     {\rm NCRLB}(d_n) = \frac{3B_nC_2}{2\pi^2|E_{s,n}|^2} + \frac{ 3\mathcal{P}_rB_nC_1}{2\pi^2\alpha_n\mu_n^2{\varrho_0^\star}^2 |E_{s,n}|^2}. 
% \end{align}
The sum of all NCRLBs is adopted as a performance metric to evaluate the overall sensing error, which is minimized by optimizing the Rabi attentions. 
The notation $\xi_n \overset{\Delta}{=} \frac{ 3\mathcal{P}_rB_nC_1}{2\pi^2\mu_n^2{\varrho_0^\star}^2 |h_n|^2P_{{\rm t}, n}}$ is introduced to simplify the expression of the formulated problem as 
\begin{align}
    \min_{{\{\alpha_n\}_{n=1}^N}} \:\:&\sum_{n=1}^N\frac{\xi_n}{\alpha_n}, \label{eq:CRLB} \\
    {\rm s.t.}\:\:&\sum_{n=1}^N\alpha_n = 1, \tag{\ref{eq:CRLB}a} \label{eq:CRLBa} \\
    &\alpha_n \ge 0, \forall n. \tag{\ref{eq:CRLB}b}  \label{eq:CRLBb}
\end{align}
The term $\frac{3B_nC_2}{2\pi^2 |h_n|^2P_{{\rm t}, n}}$ in ${\rm NCRLB}(d_n)$ is omitted in problem \eqref{eq:CRLB} as it is irrelevant to $\alpha_n$. 
This optimization problem is shown to be convex, and its global optimal solution can be readily derived 
% using the Lagrange multiplier method 
{by solving KKT conditions}
as 
\begin{align}\label{eq:alpha2}
    \alpha_n^\star = \frac{\sqrt{\xi_n}}{\sum_{m = 1}^N\sqrt{\xi_m}}. 
\end{align}

As a result, by configuring the Rabi frequencies as $\Omega_{r,n}^\star = \sqrt{\mathcal{A}^\star {\alpha}^\star_n}$ using the optimal Rabi sum-square in Theorem 2 and the optimal Rabi attentions in \eqref{eq:alpha2}, the maximal sensing accuracy averaged over multiple frequency bands is achieved. 


