\subsection{Proof of Theorem 2}\label{app:proof_sumsquare}
Problem \eqref{eq:P0} is equivalent to maximizing the function $f(\mathcal{A}) = \exp\left(-\frac{\chi_0\mathcal{A}}{\mathcal{A} + \Gamma^2}\right)\frac{\mathcal{A}}{(\mathcal{A} + \Gamma^2)^4}$ with $\mathcal{A} > 0$. To solve it, we introduce the variable transformation $x = \frac{\mathcal{A}}{\mathcal{A} + \Gamma^2}$. Then, we get $0\le x < 1$ and $\mathcal{A} = \frac{x}{1-x}\Gamma^2$. The function $f(\mathcal{A})$ can thus be rewritten as 
\begin{align}
    f(\mathcal{A}) = \frac{1}{\Gamma^6} e^{-\chi_0 x}x(1 - x)^3\overset{\Delta}{=} g(x). 
\end{align}
The gradient of $g(x)$ is given as 
\begin{align}
    \frac{{\rm d} g(x)}{{\rm d} x} = \frac{1}{\Gamma^6}e^{-\chi_0 x}(1 - x^2)(\chi_o x^2 - (\chi_0 + 4)x + 1).
\end{align}
By setting $\frac{{\rm d} g(x)}{{\rm d} x} = 0$ and doing some tedious calculations, we can obtain the optimal $x$ that maximizes $g(x)$ in the range $x\in[0,1)$ as 
\begin{align}
x^\star = \frac{\chi_0 + 4 - \sqrt{\chi_0^2 + 4\chi_0 + 16}}{2\chi_0}.
\end{align}
When $0\le x < x^\star $, the gradient $\frac{{\rm d} g(x)}{{\rm d} x}$ is greater than 0 and thus $g(x)$ monotonically increases, while when $x^\star< x < 1 $, the gradient $\frac{{\rm d} g(x)}{{\rm d} x}$ is smaller than 0 and thus $g(x)$ monotonically decreases,

By further invoking the relationship $\mathcal{A} = \frac{x}{1 - x}\Gamma^2$. The optimal Rabi sum-square is thus given as
\begin{align}
    \mathcal{A}^\star = \frac{\chi_0+4 - \sqrt{\chi_0^2 + 4\chi_0 + 16}}{\chi_0 -4 + \sqrt{\chi_0^2 + 4\chi_0 + 16}}\Gamma^2.
\end{align}
This completes the proof.

\subsection{Proof of Theorem 3}\label{app:proof_rabiattention}
The Lagrange function of problem \eqref{eq:ASE} is given as 
\begin{align}
    \mathcal{L} = \sum_{n=1}^N\gamma_n\log_2\left(1 + \frac{\beta_n\alpha_n}{\alpha_n + \epsilon_n}\right) + \frac{1}{\nu}\left(1 - \sum_{n = 1}^N\alpha_n\right).
\end{align}
Here, $\nu$ is the Lagrange multiplier and we adopt its reciprocal form $1/\nu$ for ease of later expression. The KKT conditions are given as 
\begin{align}
        \frac{\partial \mathcal{L}}{\partial \mathcal{\alpha}_n} &= \frac{\gamma_n\beta_n\epsilon_n}{((1+\beta_n)\alpha_n + \epsilon_n)(\alpha_n + \epsilon_n)} - \frac{1}{\nu} = 0, \forall n,\label{eq:C1}\\
        \sum_{n = 1}^N\alpha_n &= 1. 
        % \\ \alpha_n&\ge 0. 
\end{align}
The condition in \eqref{eq:C1} follows a quadratic form. As $\alpha_n \ge 0$, we have $\frac{\gamma_n\beta_n\epsilon_n}{((1+\beta_n)\alpha_n + \epsilon_n)(\alpha_n + \epsilon_n)} > 0$. Therefore, the Lagrange multiplier $\nu$ must greater than 0 as well. Otherwise there will be no feasible solutions to \eqref{eq:C1} for all $n$. Given $\nu \ge 0$, the solutions of these quadratic equations should obey 
\begin{align}
    \alpha_n = \frac{-(2+\beta_n)\epsilon_n \pm \sqrt{\beta_n^2\epsilon_n^2 + 4\nu\gamma_n\beta_n(1+\beta_n)\epsilon_n}}{2(1+\beta_n)}. 
\end{align}
By further considering the requirement $\alpha_n \ge 0$, the solution of $\frac{-(2+\beta_n)\epsilon_n - \sqrt{\beta_n^2\epsilon_n^2 + 4\nu\gamma_n\beta_n(1+\beta_n)\epsilon_n}}{2(1+\beta_n)}$ should be discarded as it is always smaller than 0 for all $n$. Besides, the other one needs to be modified as 
\begin{align}
        \alpha_n^\star = \left(\frac{-(2+\beta_n)\epsilon_n + \sqrt{\beta_n^2\epsilon_n^2 + 4\nu^\star\gamma_n\beta_n(1+\beta_n)\epsilon_n}}{2(1+\beta_n)} \right)^+,
\end{align}
where $(x)^+ \overset{\Delta}{=}\max(0, x)$. The optimal Lagrange multiplier $\nu^\star$ is properly selected to satisfy the constraint $\sum_{n=1}^N\alpha_n^\star = 1$. This completes the proof. 

