\section{Conclusion} \label{sec6}
 This study introduces a new data-driven approach to address the finite horizon LQ problem in LTV systems. The proposed methodology entails the non-iterative solution of data-dependent semi-definite programs, 
 by an ensemble of input-state trajectories
 from a minimum of $m+n$ experiments. Additionally, it is shown that, in the case of LTI systems, the direct data-driven finite-horizon problem can be solved using a single trajectory of length $m+n+1$. Simulation results on LTV systems demonstrate clear superiority over LTV Q-function approximation in terms of both optimality and sample efficiency. Additional simulations on nonlinear systems suggest that the method may also aid stabilization in more complex settings. This is enabled by the LTV framework’s ability to approximate nonlinear dynamics with surrogate models, marking a step toward data-driven control of nonlinear systems using linear constructs.\\
While the proposed framework ensures global optimality under nominal conditions, it does not explicitly guarantee robustness to measurement noise. Extending it to robust settings is a promising direction, given its natural alignment with LMI-based robust control methods. Another key avenue is developing an informativity-based framework for LTV systems, analogous to the LTI theory in~\cite{van2020data}, by incorporating time-local data conditions and time-varying dynamics. Moreover, as LTV models can approximate a wide range of nonlinear systems via local linearization or surrogate modeling, the approach also lays groundwork for sample-efficient, data-driven control of nonlinear systems.







\section*{Appendix A: The KKT condition for Problem 2} \label{sec7}

The Lagrangian function corresponding to Problem 2 is,

\begin{align} \label{eq:38}
  \nonumber      &\mathcal{L}(G,W,M_1,M_2,M_3)=-\text{trace}(ZW)\\
      \nonumber    &-\sum_{k=0}^{N-1}\text{trace}\big(M_1(k)G_{22}(k)\big)\\
      \nonumber    &-\text{trace}\Big(M_2\big(G_{11}(0)-W-G_{12}(0)G_{22}^{-1}(0)G_{12}^T(0)\big)\Big)\\
     \nonumber     &-\sum_{k=0}^{N-2}\text{trace}\bigg(M_3(k)\Big(E^T(k)\big(G_{11}(k+1)-G_{12}(k+1)\\
     \nonumber     &\times G_{22}^{-1}(k+1)G_{12}^T(k+1)\big)E(k)-G(k)+\Lambda(k)\Big)\bigg)\\
      \nonumber    &-\text{trace}\Big(M_3(N-1)\big(E^{T}(N-1)Q_{f}E(N-1)\\
        &-G(N-1)+\Lambda(N-1)\big)\Big).
\end{align}
To derive the KKT conditions, first note that according to dual feasibility constraints, we have,
\begin{align}
    &  M_1(k)\succeq0~~ k=0,1,...,N-1, \label{eq:39}\\
    & M_2\succeq0, \label{eq:40}\\
    &  M_3(k)\succeq0 ~~ k=0,1,...,N-1,  \label{eq:41}
\end{align}
Next, the Complementary slackness requires that,
\begin{equation}
  \text{trace}\left(  M_1(k){G}_{22}(k)\right)=0,
    \label{eq:42}
\end{equation}
\begin{equation}
  \text{trace}\left(  M_2\Big[{G}_{11}(0)-{W}-{G}_{12}(0){G}_{22}^{-1}(0){G}_{12}^T(0)\Big]\right)=0,
    \label{eq:43}
\end{equation}
\begin{align}\label{eq:44}
\nonumber & \text{trace}\left(  M_3(k)\Big[E^T(k )\big({G}_{11}(k+1)-{G}_{12}(k+1){G}_{22}^{-1}(k+1)\right.\\
   & \left.\times {G}_{12}^T(k+1)\big)E(k)-{G}(k)+\Lambda(k)\Big]\right)=0,
\end{align}
\begin{align}\label{eq:45}
\nonumber & \text{trace}\left(  M_3(N-1)\Big[E^{T}(N-1)Q_{f}E(N  -1)-{G}(N-1)\right.\\
    &\left. +\Lambda(N-1)\Big]\right)=0.
    \end{align}

Since the complementary slackness condition \eqref{eq:42} yields $ M_1(k) = 0 $ for all $ k \in \{0, 1, \dots, N-1\} $, the associated terms vanish and are thus omitted in the expressions for the stationarity conditions.

Next, the Stationarity conditions require that,
\begin{equation*} 
\nabla_W\mathcal{L}=0, \quad
\nabla_{G(0)}\mathcal{L}=0, \quad \nabla_{G(k)}\mathcal{L}=0.
\end{equation*}
To interpret these stationarity conditions, we can rewrite ${G}(k)$ for \(k=0,1,...,N-1\) as, \begin{equation*}
    \begin{split}
    {G}(k)=&T_1{G}_{11}(k)T^T_1+T_1{G}_{22}(k)T^T_2+T_2{G}^T_{12}(k)T^T_1\\
    &+T_2{G}_{22}(k)T^T_2,
    \end{split}
\end{equation*}
with $ T_1=\begin{bmatrix}
    I_{n}\\
    0
    \end{bmatrix}\in\mathbb{R}^{(n+m)\times n},\;\;
    T_2=\begin{bmatrix}
    0\\
    I_{m}
    \end{bmatrix}\in\mathbb{R}^{(n+m)\times m}
    \label{eq:47}$.
Thus, the stationarity conditions are described as, \eqref{eq:49}-\eqref{eq:55}:
\begin{equation}
    \nabla_W\mathcal{L}=-Z+M_2=0,~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
    \label{eq:49}
\end{equation}
\begin{equation}
    \nabla_{G_{11}(0)}\mathcal{L}=-M_2
    +T^T_1M_3(0)T_1=0,~~~~~~~~~~~~~~~~~~~~~
    \label{eq:50}
\end{equation}
\begin{align}\label{eq:51}
  &  \nabla_{G_{12}(0)}\mathcal{L}=M_2{G}_{12}(0)\hat{G}^{-1}_{22}(0)
    +T^T_1M_3(0)T_2=0,
\end{align}
\begin{equation}
    \begin{split}
    \nabla_{G_{22}(0)}\mathcal{L}=&-{G}^{-1}_{22}(0){G}^T_{12}(0)M_2{G}_{12}(0){G}^{-1}_{22}(0)~~~~~~~~~~\\
    &+T^T_2M_3(0)T_2=0,
    \end{split}
    \label{eq:52}
\end{equation}
and for \(k=1,2,...,N-1\),
\begin{equation}
    \begin{split}
    \nabla_{G_{11}(k)}\mathcal{L}=&-E(k-1)M_3(k-1)E^T(k-1)~~~~~~~~~~~~~~~~~~~~\\
    &+T^T_1M_3(k)T_1=0,
    \end{split}
    \label{eq:53}
\end{equation}
\begin{equation}
    \begin{split}
    \nabla_{G_{12}(k)}\mathcal{L}=&E(k-1)M_3(k-1)E^T(k-1)\\
    &\times {G}_{12}(k){G}^{-1}_{22}(k)+T^T_1M_3(k)T_2=0,~~~~~~~~~~~
    \end{split}
    \label{eq:54}
\end{equation}
\begin{equation}
    \begin{split}
    \nabla_{G_{22}(k)}\mathcal{L}&=-{G}^{-1}_{22}(k)\hat{G}^T_{12}(k)E(k-1)M_3(k-1)\\
    &\times E^T(k-1){G}_{12}(k){G}^{-1}_{22}(k)+T^T_2M_3(k)T_2=0.
    \end{split}
    \label{eq:55}
\end{equation}
