	\section{A Continuous-Time RL Algorithm with Data-driven Exploration}
	\label{sec_rl_algo}

	This section presents the development of continuous-time RL algorithms with data-driven exploration. We discuss the policy evaluation and policy improvement steps, followed by a projection technique, time discretization, and the final pseudocode.



	\subsection{Policy Evaluation}
	\label{sec_policy_evaluation}

	To update the critic parameter \(\bm\theta\), we employ policy evaluation (PE), a fundamental component of RL that focuses on learning the value function of a given policy.

	Based on the parameterizations of the value function and policy in \eqref{eq_value_parametrization} and \eqref{eq_policy_parametrization} respectively, we update \(\bm{\theta}\) by applying  the general continuous-time PE algorithm introduced by \cite{jia2021policy} along  with stochastic approximation:

	\begin{equation}
		\begin{aligned}
			\label{eq_theta_update_without_projection}
			\bm{\theta}_{n+1}& \leftarrow \bm\theta_n + a^{(\bm\theta)}_n\int_0^T \frac{\partial J}{\partial \bm\theta}(t, x_n(t); \bm\theta_n,\gamma_n) \biggl[ - \frac{1}{2} Qx_n(t)^2 \mathrm{d}t +\mathrm{d}J(t, x_n(t); \bm\theta_n, \gamma_n) - \gamma_n {p}(t; \bm{\phi}_n, \Gamma_n) \mathrm{d}t \biggr],
		\end{aligned}
	\end{equation}
	where \(a^{(\bm\theta)}_n\) is the corresponding learning rate.

	% \change{move to regret or numerical part. }A striking outcome of our theoretical analysis is that the convergence properties and regret performance depend solely on the boundedness of the functions \(k_1\) and \(k_3\), quantified by the constants \(c_1\), \(c_2\), and \(c_3\), rather than their specific functional forms. This insight highlights the inherent flexibility of our framework, allowing \(k_1(t)\) and \(k_3(t)\) to take various forms—ranging from intricate structures like neural networks with smooth, bounded activation functions (e.g., sigmoid and tanh) to simple constant values. This characteristic is a unique feature of the class of LQ problems we consider. As a result, in our numerical experiments, we maintain \(k_1\) and \(k_3\) as fixed values without requiring iterative updates. However, in practical implementations, policy evaluation techniques can still be leveraged to refine the value function adaptively, enhancing policy performance over time.




	\subsection{Policy Improvement}
	\label{sec_policy_gradient}

	The remaining learnable parameter  is the mean of the stochastic Gaussian policy, \(\bm\phi\). We employ policy gradient (PG) established in  \cite{jia2021policypg} and utilize stochastic approximation to generate the update rule:

	\begin{equation}
		\label{eq_phi_updates_without_projections}
		\bm\phi \leftarrow \bm\phi + a^{(\bm\phi)}_n Y_n(T),
	\end{equation}
	where $a^{(\bm\phi)}_n$ is the learning rate and
	\begin{equation}
		\label{eq_y_def}
		\begin{aligned}
			Y_n(s) =\int_{0}^{s}\biggl\{&\frac{\partial \log \pi}{\partial \bm\phi}\left(u_n(t) \mid t, x_n(t); \bm\phi_n, \Gamma_n\right) \biggl[- \frac{1}{2}Q x_n(t)^2 \mathrm{d} t \\
			&+ \mathrm{d} J\left(t, x_n(t); \bm\theta_n, \gamma_n \right) + \gamma_n p\left(t; \bm\phi_n, \Gamma_n\right) \mathrm{d} t\biggr] + \gamma_n \frac{\partial p}{\partial \bm\phi}\left(t; \bm\phi_n, \Gamma_n \right) \mathrm{d} t \biggl\},
		\end{aligned}
	\end{equation}
	where $0 \leq s \leq T$.




	\subsection{Projections}
	\label{sec_projections}

	The parameter updates for \(\bm\theta\), \(\bm\phi\), and \(\Gamma\) follow stochastic approximation (SA), a foundational method introduced by \cite{robbins1951stochastic} and extensively studied in subsequent works \cite{lai2003stochastic, borkar2009stochastic, chau2014overview}. However, directly applying SA in our setting presents challenges such as extreme state values and unbounded estimation errors, which can destabilize the learning process. To address these issues, we incorporate the projection technique proposed by \cite{andradottir1995stochastic}, ensuring that parameter updates remain in a bounded region at every iteration. %This adjustment mitigates instability while preserving the adaptability of our model-free learning approach.

	Define \(\Pi_K(x) := \arg \min_{y \in K} |y-x|^2\),  the projection of a point \(x\) onto a set \(K\). We now introduce the projection sets for all the critic and actor parameters.

	First, we define the projection sets for the critic parameter \(\bm\theta\) and the temperature parameter \(\gamma\):
	\begin{equation}
		\label{eq_projection_sets_critic}
		K^{(\bm\theta)}=\left\{ \bm\theta\in \mathbb{R}^d \mid |\bm\theta| \leq c^{(\bm\theta)} \right\}, K^{(\gamma)}=\left\{ \gamma\in \mathbb{R} \mid |\gamma| \leq c^{(\gamma)} \right\},
	\end{equation}
	which are employed to enforce the boundedness conditions in \eqref{eq_k_bounds}. The update rules incorporating projection  for \(\bm\theta\) and \(\gamma\) are modified to
	\begin{equation}
		\label{eq_theta_update}
		\begin{split}
			\bm\theta_{n+1} \leftarrow \Pi_{K^{(\bm\theta)}}\biggl( & \bm\theta_n + a^{(\bm\theta)}_n\int_0^T \frac{\partial J}{\partial \bm\theta}(t,x_n(t); \bm\theta_n, \gamma_n) \\
			& \biggl[\mathrm{d} J\left(t, x_n(t); \bm\theta_n, \gamma_n \right) - \frac{1}{2}Qx_n(t)^2 \dd t  + \gamma_n {p}\left(t; \bm\phi_n,\gamma_n\right) \mathrm{d} t\biggr] \biggl),
		\end{split}
	\end{equation}
	\begin{equation}
		\label{eq_gamma_update}
		\begin{split}
			\gamma_{n+1} \leftarrow \Pi_{K^{(\gamma)}}\biggl( \frac{c_\gamma \int_0^T k_1(t; \bm\theta_n) \dd t}{b_n T} \biggl).
		\end{split}
	\end{equation}


	Next, we define the projection sets for the actor parameters \(\bm\phi\) and \(\Gamma\):
	\begin{equation}
		\label{eq_projection_sets_actor}
		\begin{aligned}
			&K^{(\bm\phi)}_n=\left\{ \bm\phi_n \in \mathbb{R}^l \Big| |\bm\phi_n|\leq c^{(\bm\phi)}_n  \right\}, \\
			&K^{(\Gamma)}_n=\left\{ \Gamma_n \in \mathbb{S}^{l}_{++} \Big| |\Gamma_n| \leq c^{(\Gamma)}_n, \Gamma_n - \frac{1}{b_n}I \in \mathbb{S}^l_{++}  \right\},
		\end{aligned}
	\end{equation}
	where \(\{c^{(\bm\phi)}_n \uparrow \infty\}\), \(\{c^{(\Gamma)}_n \uparrow \infty\}\), and \(\{b_n \uparrow \infty\}\) are positive, monotonically increasing sequences, with \(b_n\) the same deterministic sequence in \eqref{eq_gamma_definition}. The specifics of these sequences are given in Theorem \ref{thm_convergence_and_rate_gamma}. Clearly, the sequences of sets \(K^{(\bm\phi)}_n\) and \(K^{(\Gamma)}_n\) expand over time, eventually covering the entire spaces \(\mathbb{R}^l\) and \(\mathbb{S}^{l}_{++}\), respectively. This ensures that our algorithm remains model-free without needing to have prior knowledge of the model parameters. The update rules with projection for \(\bm\phi\) and \(\Gamma\) are now
	\begin{equation}
		\label{eq_phi_update}
		\begin{split}
			\bm\phi_{n+1} \leftarrow& \Pi_{K^{(\bm\phi)}_{n+1}} \biggl( \bm\phi_n+a^{(\bm\phi)}_n Y_{n}(T) \biggl),
		\end{split}
	\end{equation}
	\begin{equation}
		\label{eq_Gamma_update}
		\begin{split}
			\Gamma_{n+1} \leftarrow& \Pi_{K^{(\Gamma)}_{n+1}} \biggl( \Gamma_n-a^{(\Gamma)}_n Z_{n}(T) \biggl),
		\end{split}
	\end{equation}
	where \(Y_{n}(T)\) and \(Z_{n}(T)\) are respectively determined by \eqref{eq_y_def} and \eqref{eq_z_def}.




	\subsection{Discretization}
	\label{sec_discretization}

	While our RL framework is continuous-time in both formulation and analysis, numerical implementation requires discretization at the final stage. %Since some operations, such as integral computations in update rules, cannot be directly computed in a continuous environment.
To facilitate this, we divide the time horizon \([0, T]\) into uniform intervals of size \(\Delta t_n\) at the \(n\)-th iteration, resulting in discretized rules:\footnote{Analysis on discretization errors is covered and discussed in Theorems \ref{thm_Gamma_convergence} - \ref{thm_convergence_and_rate_phi}, and Remark \ref{remark_discretization_error}.}

	\begin{equation}
		\label{eq_theta_update_discrete}
		\begin{aligned}
			\bm\theta_{n+1} \leftarrow \Pi_{K^{(\bm\theta)}}\biggl(& \bm\theta_n+a^{(\bm\theta)}_n \sum_{k=0}^{\left\lfloor \frac{T}{\Delta t_n} -1 \right\rfloor} \frac{\partial J}{\partial \bm\theta}(t_k,x_n(t_k); \bm\theta_n, \gamma_n)\biggl[ J\left(t_{k+1}, x_n(t_{k+1}); \bm\theta_n, \gamma_n \right) - J\left(t_k, x_n(t_k); \bm\theta_n, \gamma_n \right) \\
			&- \frac{1}{2}Qx_n(t_k)^2 \Delta t_n + \gamma_n {p}\left(t_k; \bm\phi_n, \Gamma_n\right) \Delta t_n\biggl] \biggl),
		\end{aligned}
	\end{equation}

	\begin{equation}
		\label{eq_gamma_update_discrete}
		\begin{split}
			\gamma_{n+1} \leftarrow \Pi_{K^{(\gamma)}}\biggl( \frac{c_\gamma}{b_n T} \sum_{k=0}^{\left\lfloor \frac{T}{\Delta t_n} -1 \right\rfloor} k_1(t_k; \bm\theta_n) \Delta t_n \biggl).
		\end{split}
	\end{equation}
Moreover, 	\(Y_n(T)\) and \(Z_n(T)\) in the update rules \eqref{eq_phi_update} and \eqref{eq_Gamma_update} are approximated by
	\begin{equation}
		\label{eq_phi_update_discrete}
		\begin{aligned}
			\hat{Y}_n(T) = \sum_{k=0}^{\left\lfloor \frac{T}{\Delta t_n} -1 \right\rfloor} \Delta t_n \biggl\{&\frac{\partial \log \pi}{\partial \bm\phi}\left(u_n(t_k) \mid t_k, x_n(t_k); \bm\phi_n, \Gamma_n\right)\\
			&\biggl[ (J\left(t_{k+1}, x_n(t_{k+1}); \bm\theta_n, \gamma_n \right)  - J\left(t_k, x_n(t_k); \bm\theta_n, \gamma_n \right)) \frac{1}{\Delta t_n} \\
			&- \frac{1}{2}Qx_n(t_k)^2 + \gamma_n {p}\left(t_k; \bm\phi_n, \Gamma_n\right)\biggl]+\gamma_n \frac{\partial {p}}{\partial \bm\phi}\left(t_k; \bm\phi_n, \Gamma_n \right) \biggl\} ,
		\end{aligned}
	\end{equation}

	\begin{equation}
		\label{eq_Gamma_update_discrete}
		\begin{aligned}
			\hat{Z}_n(T) = \sum_{k=0}^{\left\lfloor \frac{T}{\Delta t_n} -1 \right\rfloor} \Delta t_n \biggl\{&\frac{\partial \log \pi}{\partial \Gamma^{-1}}\left(u_n(t_k) \mid t_k, x_n(t_k); \bm\phi_n, \Gamma_n\right)\\
			&\biggl[ (J\left(t_{k+1}, x_n(t_{k+1}); \bm\theta_n, \gamma_n \right) - J\left(t_k, x_n(t_k); \bm\theta_n, \gamma_n \right)) \frac{1}{\Delta t_n} \\
			&- \frac{1}{2}Qx_n(t_k)^2 + \gamma_n {p}\left(t_k; \bm\phi_n,\Gamma_n\right) \biggl]+
			\gamma_n \frac{\partial {p}}{\partial \Gamma^{-1}}\left(t_k; \bm\phi_n, \Gamma_n \right) \biggl\} .
		\end{aligned}
	\end{equation}




