		% \label{eq_dynamics_app}
		% \mathrm{d}x_n(t) = (A x_n(t) + B^\top u_n(t)) \mathrm{d}t + \sum_{j} (C_j x_n(t) + D_j^\top u_n(t)) \mathrm{d}W_n^{(j)}(t),
		% \end{equation}
	% where \(W_n=\{(W_n^{(1)}(t),\cdots,W_n^{(m)}(t))^\top \in \mathbb{R}^m : 0 \leq t \leq T\}\) represents a standard Brownian motion specific to the \(n\)-th iteration. The control policy follows \(u_n(t) \mid x_n(t) \sim \mathcal{N}(\cdot|\bm\phi_n x_n(t), \Gamma_n)\), independent of \(W_n\).

	Define the conditional expectation of \(Z_n(T)\) given the current parameter iterates as
	\[
	h^{(\Gamma)}(\bm\phi_n, \Gamma_n; \bm\theta_n, \gamma_n) = \mathbb{E}[Z_n(T) \mid \bm\theta_n, \bm{\phi}_n, \gamma_n, \Gamma_n],
	\]
	as well as  the deviation %term associated with \(Z_n(T)\) is expressed as
	\[
	\xi^{(\Gamma)}_{n} = Z_n(T) - h^{(\Gamma)}(\bm\phi_n, \Gamma_n; \bm\theta_n, \gamma_n).
	\]
	The update rule \eqref{eq_Gamma_update} can be rewritten as
	\begin{equation}
		\label{eq_Gamma_update_app}
		\Gamma_{n+1} = \Pi_{K^{(\Gamma)}_{n+1}} \left(\Gamma_n - a^{(\Gamma)}_n[h^{(\Gamma)}(\bm\phi_n, \Gamma_n; \bm\theta_n, \gamma_n) + \xi^{(\Gamma)}_{n}]\right).
	\end{equation}

	For reader's convenience, we break the proof of  Theorem \ref{thm_convergence_and_rate_gamma} into several steps, most of which adapt the general stochastic approximation methodology (e.g., \cite{andradottir1995stochastic} and \cite{broadie2011general}) to the specific setting here.



	\subsubsection{A Variance Upper Bound}

	The following result establishes  an upper bound on the variance of the increment \(Z_n(T)\).

	\begin{lemma}
		\label{lemma_nosie_Gamma_app}
		There exists a constant \(c > 0\) depending solely on the model parameters such that
		\begin{equation}
			\label{eq_noise_upper2}
			\begin{aligned}
				&\operatorname{Var}\left( Z_n(T) \Big| \bm\theta_n, \bm\phi_n, \gamma_n, \Gamma_n \right) \leq c \left( 1 + |\bm\phi_n|^{8} + |\Gamma_n|^{8} + (\log b_n)^8 + \gamma_n^8 \right) \exp{\{c|\bm\phi_n|^4\}}.
			\end{aligned}
		\end{equation}
	\end{lemma}

	\begin{proof} The proof is similar to that of \cite[Lemma B.2]{huang2024sublinear} except that we need to account for the estimates on $\Gamma_n$; so we will be brief here.
		%We first calculate \(\mathrm{d}Y_n(T)\).
	It follows from \eqref{eq_z_def} together with Ito's lemma (applied to \(J\left(t, x_n(t); \bm\theta_n, \gamma_n \right)\)) that
		\begin{equation}
			\label{eq_dz2_app}
			\begin{aligned}
				\dd Z_n(t) \triangleq& Z_n^{(1)}(t) \dd t + \Sj Z_n^{(2, j)}(t) \dd W_n^{(j)}(t),
			\end{aligned}
		\end{equation}
for which we have the following estimates
		\[
		\begin{aligned}
			\E[|Z_n^{(1)}(t)|^2 |& \bm\theta_n, \bm\phi_n, \gamma_n, \Gamma_n, x_n(t)] \leq c (1+|\Gamma_n|^4)(1+x_n(t)^4+|\bm\phi_n|^4x_n(t)^4+\gamma_n^2+\gamma_n^2(\log( \det (\Gamma_n)))^2),
		\end{aligned}
		\]
		\[
		\begin{aligned}
			\E&[|Z_n^{(2,j)}(t)|^2 | \bm\theta_n, \bm\phi_n, \gamma_n, \Gamma_n, x_n(t)] \leq c (1+|\Gamma_n|^3)(1+x_n(t)^4+|\bm\phi_n|^2x_n(t)^4+|\Gamma_n|^2x_n(t)^4+|\bm\phi_n|^2|\Gamma_n|^2x_n(t)^2).
		\end{aligned}
		\]
		Taking expectations in the above conditional on  $x_n(t)$ and applying \cite[Lemma B.1]{huang2024sublinear},  we get
		\begin{equation}
			\label{eq_Z2_square_app}
			\begin{aligned}
				&\E[|Z_n^{(1)}(t)|^2 + \Sj|Z_n^{(2,j)}(t)|^2 | \bm\theta_n, \bm\phi_n, \gamma_n, \Gamma_n] 
				%\leq& c \E \biggl[(1+|\Gamma_n|^4)(1+x_n(t)^4+|\Gamma_n|^4+|\bm\phi_n|^4x_n(t)^4+|\Gamma_n|^2x_n(t)^4+\gamma_n^2+\gamma_n^2(\log( \det (\Gamma_n)))^2)\biggl]\\
				% \leq& c \biggl[(1+|\Gamma_n|^4)\biggl(1+|\Gamma_n|^4+(1+|\bm\phi_n|^4+|\Gamma_n|^2)(1+|\Gamma_n|^2t)\\
