	Given that \(h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n)\) is quadratic in \(\Gamma_n\), we apply \eqref{eq_k_bounds} to establish the bound:
	\begin{equation}
		\label{eq_h2n_upper_app}
		\left| h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n) \right| \leq c (1 + |\Gamma_n|^2 + \gamma_n^2).
	\end{equation}

