	\subsubsection{Almost Sure Convergence of $\gamma_n$ and $\Gamma_n$}
	\label{sec_convergence_Gamma_app}

	We now prove Part (a) of Theorem \ref{thm_convergence_and_rate_gamma}. Indeed we will present and prove a more general result that involves  a bias term \(\beta^{(\Gamma)}_n = \mathbb{E}[ \xi^{(\Gamma)}_{n} \mid \mathcal{G}_n]\), which captures implementation errors such as the discretization error (see Remark \ref{remark_discretization_error}). When \(\beta^{(\Gamma)}_n = \mathbf{0}\), the result simplifies to Theorem \ref{thm_convergence_and_rate_gamma}-(a).

	\begin{theorem}
		\label{thm_Gamma_convergence}
		Assume $\xi^{(\Gamma)}_{n}$ satisfies $\E\left[ \xi^{(\Gamma)}_{n} \Big|\g_n\right] = \beta^{(\Gamma)}_n$ and
		\begin{equation}\label{eq_Gamma_noise_assumption}
			\begin{aligned}
				&\E\left[ \left|\xi^{(\Gamma)}_{n} - \beta^{(\Gamma)}_n \right|^2 \Big| \g_n \right] 
				\leq c (1 + |\bm\phi_n|^8 + |\Gamma_n|^8 + (\log b_n)^8 + \gamma_n^8) \exp{\{c|\bm\phi_n|^4\}}, \\
			\end{aligned}
		\end{equation}
		where $c>0$ is a constant independent of $n$, and $\{\g_n\}$ is the filtration generated by $\{\bm\theta_m, \bm\phi_{m}, \gamma_m, \Gamma_m; m=0,1,2,...,n\}$.
		Moreover, assume
		\begin{equation} \label{eq_Gamma_assumption_app}
			\begin{aligned}
				(i)&  0<a^{(\Gamma)}_n\leq1 \text{ } \forall n,  \sum_n a^{(\Gamma)}_n = \infty,  \sum_n a^{(\Gamma)}_n |\beta^{(\Gamma)}_n| < \infty; \\
				(ii)&  c^{(\bm\phi)}_n\uparrow \infty,  c^{(\Gamma)}_n\uparrow \infty, \text{ and for } 0\leq q_1, q_2, q_3 , 0\leq q_4 \leq 4,\\
				&\sum (a^{(\Gamma)}_n)^2 (c^{(\Gamma)}_n)^ {q_1} (c^{(\bm\phi)}_n)^ {q_2} (\log b_n)^{q_3}   e^{c(c^{(\bm\phi)}_n)^{q_4}} < \infty; \\
				(iii)&  b_n\geq1,  b_n\uparrow \infty,  \sum \frac{a^{(\Gamma)}_n}{b_n}=\infty,  \sum |\frac{1}{b_n}-\frac{1}{b_{n+1}}|<\infty.
			\end{aligned}
		\end{equation}

		Then, $\gamma_n \xrightarrow{a.s.} 0$ and $\Gamma_n \xrightarrow{a.s.} \bm{0}$.
	\end{theorem}



	\begin{proof}
		It is straightforward to see that \(\gamma_n\) almost surely converges to \(0\).
		To prove the almost sure convergence of \(\Gamma_n\), the key idea  is to establish inductive upper bounds on \(|\Gamma_n|^2\), namely to  bound \(|\Gamma_{n+1}|^2\) by  a function of \(|\Gamma_n|^2\).

		%Consider a closed, convex set \(K \subset \mathbb{R}\) and points \(x \in K, y \in \mathbb{R}\). By the projection property, the function \(f(t) = |t \Pi_K(y) + (1 - t) x - y|^2\) achieves its minimum at \(t = 1\). The first-order optimality condition gives:
%		\[
%		2 |\Pi_K(y) - y|^2 - 2\langle \Pi_K(y) - y, x - y \rangle = 0.
%		\]
%		Rearranging, we obtain:
%		\[
%		|\Pi_K(y) - x|^2 = |y - x|^2 - |\Pi_K(y) - y|^2 \leq |y - x|^2.
%		\]

		Define the deviation term \(U^{(\Gamma)}_n = \Gamma_n - \Gamma_n^*\), where \(\Gamma_n^*\) is given by:
		\begin{equation}
			\label{eq_phi_2n_star0}
			\Gamma_n^* = \frac{\gamma_n T}{\int_0^T k_1(t; \bm\theta_n) \dd t} \Mj.
		\end{equation}

		By the adaptive temperature parameter \(\gamma_n\) in \eqref{eq_gamma_definition}, \(\Gamma_n^*\) can be rewritten as:
		\begin{equation}
			\label{eq_phi_2n_star}
			\Gamma_n^* = \frac{c_\gamma}{b_n} \Mj,
		\end{equation}
		where we recall \(c_\gamma > 0\) is such that  \(\frac{1}{c_\gamma}\) is smaller than the minimum eigenvalue of \(\Mj\), denoted as \(\lambda_{\min}(\Mj)\). Thus \(\Gamma_n^* > \frac{1}{b_n} I\). Since \(b_n \uparrow \infty\), \(\Gamma_n^*\) decreases in $n$, leading to the positive matrix difference:
		\(
		G_n = \Gamma_n^* - \Gamma_{n+1}^* > 0.
		\)

		We now show the almost sure convergence of \(U^{(\Gamma)}_n\) to 0.  Consider sufficiently large \(n\) such that \(\Gamma_n^* \in K^{(\Gamma)}_{n+1}\). By applying the general projection inequality $|\Pi_K(y) - x|^2 \leq |y - x|^2$, we have

		\[\begin{aligned}
			& \E\left[|U^{(\Gamma)}_{n+1}|^2 \Big| \g_n \right] \\
			\leq & \E\left[| U^{(\Gamma)}_n -  a^{(\Gamma)}_n[ h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n) + \xi^{(\Gamma)}_n] + G_n |^2 \Big| \g_n \right] \\
			% = & \E\left[| U^{(\Gamma)}_n -  a^{(\Gamma)}_n[ h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n) + \xi^{(\Gamma)}_n + \frac{G_n}{a^{(\Gamma)}_n}] |^2 \Big| \g_n \right] \\
			% = & |U^{(\Gamma)}_n|^2 - 2a^{(\Gamma)}_n \langle U^{(\Gamma)}_n,  h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n) +  \beta^{(\Gamma)}_n + \frac{G_n}{a^{(\Gamma)}_n} \rangle + (a^{(\Gamma)}_n)^2 \E\left[ | h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n) + \xi^{(\Gamma)}_n + \frac{G_n}{a^{(\Gamma)}_n} |^2 \Big| \g_n \right] \\
			% = & |U^{(\Gamma)}_n|^2 - 2a^{(\Gamma)}_n \langle U^{(\Gamma)}_n,  h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n) +  \beta^{(\Gamma)}_n + \frac{G_n}{a^{(\Gamma)}_n} \rangle \\
			% &+ (a^{(\Gamma)}_n)^2 \E\left[ | h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n) + (\xi^{(\Gamma)}_n-\beta^{(\Gamma)}_n) + \beta^{(\Gamma)}_n + \frac{G_n}{a^{(\Gamma)}_n} |^2 \Big| \g_n \right] \\
			% \leq & |U^{(\Gamma)}_n|^2 - 2a^{(\Gamma)}_n \langle U^{(\Gamma)}_n,  h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n) \rangle + 2 a^{(\Gamma)}_n | \beta^{(\Gamma)}_n| |U^{(\Gamma)}_n| + 2|G_n||U^{(\Gamma)}_n| \\
			% &+ 4(a^{(\Gamma)}_n)^2 \left( |h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n)|^2 + | \beta^{(\Gamma)}_n|^2 + |\frac{G_n}{a^{(\Gamma)}_n}|^2 + \E\left[ \left|\xi^{(\Gamma)}_n -  \beta^{(\Gamma)}_n \right|^2 \Big| \g_n\right] \right)  \\
			\leq & |U^{(\Gamma)}_n|^2 - 2a^{(\Gamma)}_n \langle U^{(\Gamma)}_n,  h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n) \rangle + (1 + |U^{(\Gamma)}_n|^2)(a^{(\Gamma)}_n | \beta^{(\Gamma)}_n| + |G_n|) \\
			& + 4(a^{(\Gamma)}_n)^2 \biggl( |h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n)|^2 + | \beta^{(\Gamma)}_n|^2 + |\frac{G_n}{a^{(\Gamma)}_n}|^2 + \E\left[ \left|\xi^{(\Gamma)}_n -  \beta^{(\Gamma)}_n \right|^2 \Big| \g_n\right] \biggr).
		\end{aligned}\]

		Recall that $\frac{1}{b_n}| \leq |\Gamma_n| \leq c^{(\Gamma)}_n$ almost surely. By \eqref{eq_projection_sets_critic}, \eqref{eq_projection_sets_actor}, \eqref{eq_h2n_upper_app}, and \eqref{eq_Gamma_noise_assumption}, we can further derive that
		\[\begin{aligned}
			& \E\left[|U^{(\Gamma)}_{n+1}|^2 \Big| \g_n \right] \leq (1 + \kappa^{(\Gamma)}_n) |U^{(\Gamma)}_n|^2  - \zeta^{(\Gamma)}_n + \eta^{(\Gamma)}_n,
		\end{aligned}\]
		where
		$\kappa^{(\Gamma)}_n = a^{(\Gamma)}_n | \beta^{(\Gamma)}_n| + |G_n|$, \\
		$\zeta^{(\Gamma)}_n = 2a^{(\Gamma)}_n \langle U^{(\Gamma)}_n,  h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n) \rangle$, and
		\[
		\begin{aligned}
			\eta^{(\Gamma)}_n = a^{(\Gamma)}_n | \beta^{(\Gamma)}_n| + |G_n| + 4(a^{(\Gamma)}_n)^2\biggl\{& c (1 + (c^{(\Gamma)}_n)^4) + c (1 + (c^{(\bm\phi)}_n)^8 + (c^{(\Gamma)}_n)^8 + (\log b_n)^8)\exp{\{c(c^{(\bm\phi)}_n)^4\}} \\
			&+ | \beta^{(\Gamma)}_n|^2 + |\frac{G_n}{a^{(\Gamma)}_n}|^2 \biggl\}.
		\end{aligned}
		\]

		Next, we prove that \(\sum |G_n| < \infty\) and \(\sum |G_n|^2 < \infty\). By the assumption (iii) in \eqref{eq_Gamma_assumption_app} along with \eqref{eq_phi_2n_star}, we obtain
		\begin{equation}
			\label{eq_g_n}
			\begin{aligned}
				\sum_{n=0}^{\infty} |G_n| &= \sum_{n=1}^{\infty} |\Gamma_n^* - \Gamma_{n+1}^*| < c \Sj |\frac{1}{b_n} - \frac{1}{b_{n+1}}| < \infty.\\
			\end{aligned}
		\end{equation}

		Furthermore, since $b_n \uparrow \infty$, $n_0 = \inf{\{n^\prime \in \mathbb{N}: |G_n|<1 \text{ for all } n\geq n^\prime\}}<\infty$.
		Therefore, \eqref{eq_g_n} yields
		\begin{equation}
			\label{eq_g_n2}
			\begin{aligned}
				\sum_{n=1}^{\infty} |G_n|^2 < \sum_{n=1}^{n_0-1} |G_n|^2 + \sum_{n=n_0}^{\infty} |G_n| < \infty.
			\end{aligned}
		\end{equation}
	%	confirming that both \(\sum |G_n|\) and \(\sum |G_n|^2\) are finite.

		% Recall the calculation of $\gamma$ in \eqref{eq_gamma_definition}, we have
		% \[
		% \gamma = \frac{c_\gamma\int_0^Tk_1(t; \bm\theta_n)\dd t}{b_n T} \leq \frac{c_\gamma \Bar{c}_k}{b_n}.
		% \]
		By the assumptions (i)-(ii) of \eqref{eq_Gamma_assumption_app}, as well as \eqref{eq_g_n} and \eqref{eq_g_n2}, we know $\sum \kappa^{(\Gamma)}_n<\infty$ and $\sum \eta^{(\Gamma)}_n<\infty$. It then follows from \cite[Theorem 1]{robbins1971convergence} that $\left|U^{(\Gamma)}_n\right|^2$ converges to a finite limit and $\sum \zeta^{(\Gamma)}_n<\infty$ almost surely.

		It suffices to show $|U^{(\Gamma)}_n| \to 0$ almost surely. The equations \eqref{eq_projection_sets_actor} and \eqref{eq_h2_app} imply
		% $Tr(AB)\geq\lambda_{\min}(A)Tr(B)$, since it is equivalent to $Tr((A-\lambda_{\min}(A)I)B)>0$ and if $A-\lambda_{\min}(A)I$ and $B$ are PSD.
		\[
		\begin{aligned}
			\zeta^{(\Gamma)}_n \geq& \frac{a^{(\Gamma)}_n T}{b_n c_2} \lambda_{\min}(\Sj D_j D_j^\top) |U^{(\Gamma)}_n|^2.
		\end{aligned}
		\]

		Now, suppose $|U^{(\Gamma)}_n|^2 \rightarrow c$ almost surely, where \(0<c<\infty\) is a constant. Then there exists a set $Z\in \f$ with $\p(Z) > 0$ so that for every $\omega\in Z$, there exists a measurable set $Z \in \mathcal{F}$ with $\mathbb{P}(Z) = 1$ such that, for every $\omega \in Z$, there exists a constant $0<\delta(\omega)<c$ satisfying
		\[
		|U^{(\Gamma)}_n|^2 = |\Gamma_n - \Gamma_n^*|^2 \geq c-\delta(\omega) > 0 \quad \text{for sufficiently large } n.
		\]

		Thus, by the assumption (iii) of \eqref{eq_Gamma_assumption_app},
		\[
		\sum \zeta^{(\Gamma)}_n \geq  \frac{T}{c_2} (c-\delta(\omega)) \lambda_{\min}(\Sj D_j D_j^\top) \sum \frac{a^{(\Gamma)}_n}{b_n} =\infty.
		\]
		This is a contradiction, proving that  $\Gamma_n \xrightarrow{a.s.} \Gamma_n^*$.
		However, $\Gamma_n^*$ converges to $\bm{0}$ almost surely. Hence, $\Gamma_n \xrightarrow{a.s.} \bm{0}$ as well.

	\end{proof}


	\begin{remark}
		\label{remark_example_gamma}
		A case satisfying the assumptions in \eqref{eq_Gamma_assumption_app} is when $a^{(\Gamma)}_n =1\wedge\frac{\alpha^{\frac{3}{4}}}{(n+\beta)^{\frac{3}{4}}}$ and $b_n = 1\vee\frac{(n+\beta)^{\frac{1}{4}}}{\alpha^{\frac{1}{4}}}$, where constants $\alpha>0$, $\beta>0$. $c^{(\bm\phi)}_n = 1\vee (\log \log n)^{\frac{1}{6}}, c^{(\Gamma)}_n = 1\vee \log n, \beta^{(\bm\phi)}_n=0$. %or $\beta^{(\bm\phi)}_n=n^{-\frac{3}{8}}$.
		This is because $\sum \frac{1}{n} = \infty$; $\sum \frac{(\log n)^{p} (\log \log n)^{q}}{n^{r}} <\infty$, for any $p, q  > 0$ and $r > 1$; and $\sum |n^{-\frac{1}{4}} - (n+1)^{-\frac{1}{4}}| < \frac{1}{4} \sum n^{-\frac{5}{4}} < \infty$ (by the mean--value theorem).
				Additionally, it is interesting to note that the assumptions \(\sum \frac{a^{(\Gamma)}_n}{b_n} = \infty\) and \(\sum |\frac{1}{b_n}-\frac{1}{b_{n+1}}|<\infty\) are new compared to \cite{huang2024sublinear}. This is due to the implementation of data-driven exploration.
	\end{remark}



	\subsubsection{Convergence Rate of $\Gamma_n$}
	\label{sec_convergence_rate}
	% This subsection rigorously explores the convergence rates of the parameter \(\Gamma_n\) within the framework of the adaptive exploration RL algorithm detailed in Algorithm \ref{algo_rl_lq}. Specifically, the analysis will focus on the mean-squared error (MSE) between $\Gamma_n$ and $\bm 0$.

	We need the following lemmas.
	\begin{lemma}
		\label{lemma_an_app}
		For any $W > 0$ and any $0<q<1$, there exist positive numbers $\alpha > \frac{1}{W}$ and $\beta \geq \max(\frac{1}{W \alpha -1}, W^{\frac{2q-1}{1-q}}\alpha^\frac{q}{1-q})$ such that the sequences $\hat{a}_n = \frac{\alpha}{n + \beta}$ and $a_n=\frac{\alpha^q}{(n+\beta)^q}$ satisfy $\hat{a}_n \leq \hat{a}_{n+1}(1 + W \hat{a}_{n+1})$ and $a_n \leq a_{n+1}(1 + W a_{n+1})$ for all $n \geq 0$.
	\end{lemma}

	\begin{proof}
		First,
		\[
		\begin{aligned}
			\hat{a}_n \leq \hat{a}_{n+1}(1 + W \hat{a}_{n+1})\Leftrightarrow n + 1 + \beta \leq W \alpha n + W \alpha \beta,\\
			% \Leftrightarrow \qquad \frac{\alpha}{n + \beta} & \leq \frac{\alpha}{n + 1 + \beta} (1 + W \frac{\alpha}{n + 1 + \beta})\\
			% \Leftrightarrow \qquad \frac{\alpha}{n + \beta} & \leq \frac{\alpha}{n + 1 + \beta} + W (\frac{\alpha}{n + 1 + \beta})^2\\
			% \Leftrightarrow \qquad n + 1 + \beta &\leq W \alpha n + W \alpha \beta.
		\end{aligned}
		\]
		the latter being  true for any $n$ when $\alpha > \frac{1}{W}>0$, $\beta \geq \frac{1}{W \alpha -1}>0$.

		Next, we have
		\begin{equation}
			\label{eq_lemma_an}
			\begin{aligned}
				&a_n \leq a_{n+1}(1 + W a_{n+1})\\
				\Leftrightarrow &(n+\beta+1)^q - (n+\beta)^q \leq W \alpha^q \biggl( \frac{n+\beta}{n+\beta+1} \biggl)^q.
				% \Leftrightarrow \frac{\alpha^q}{(n + \beta)^q} \leq& \frac{\alpha^q}{(n + 1 + \beta)^q} + W (\frac{\alpha}{n + 1 + \beta})^{2q}\\
				% \Leftrightarrow (n+\beta+1)^q - (n+\beta)^q \leq& W \alpha^q \biggl( \frac{n+\beta}{n+\beta+1} \biggl)^q.
			\end{aligned}
		\end{equation}
For the latter inequality in \eqref{eq_lemma_an}, notice that the left-hand side decreases in $n$ while the right-hand side increases in $n$. So to show that this inequality is true for all $n$, it is sufficient to show that it is true when $n=0$, which is
		$(\beta+1)^q - \beta^q \leq W\alpha^q \frac{\beta^q}{(\beta+1)^q}$.

		Now, for $\beta \geq \frac{1}{W \alpha -1}$, we have $\beta+1 \leq W\alpha\beta$. On the other hand, the mean--value theorem yields $(\beta+1)^q-\beta^q \leq q\beta^{q-1}$. Hence, %noticing that $\alpha > \frac{1}{W}$,
		\[
		\begin{aligned}
			W^{\frac{2q-1}{1-q}}\alpha^\frac{q}{1-q}\leq&\beta \Rightarrow (\beta+1)^q - \beta^q \leq W\alpha^q \frac{\beta^q}{(\beta+1)^q}.\\
			% \Rightarrow W^q\alpha^q\beta^q \leq& W^{1-q} \beta\\
			% \Rightarrow (\beta+1)^q \leq& W^{1-q} \beta\\
			% \Rightarrow q\beta^{q-1} \leq& W^{1-q} \frac{\beta^q}{(\beta+1)^q}\\
			% \Rightarrow (\beta+1)^q - \beta^q \leq& W\alpha^q \frac{\beta^q}{(\beta+1)^q}.\\
		\end{aligned}
		\]
	\end{proof}



	\begin{lemma}
		\label{lemma_gn_bound}
		Let the sequence $\hat{G}_n = n^{-q} - (n+1)^{-q}>0$ for some $q > 0$. Then $\hat{G}_n^2 = O(n^{-2q-2})$.
	\end{lemma}

	\begin{proof}
		We have
		\[
		\hat{G}_n^2 = \left[\frac{(n+1)^{q} - n^{q}}{(n+1)^{q} n^{q}}\right]^2 < \left[\frac{(n+1)^{q} - n^{q}}{n^{2q}}\right]^2.
		\]
Applying the mean--value theorem to the function $f(x) = x^q$ and noting that $f'(x) = qx^{q-1}$ is a decreasing function for $x > 0$, we conclude

		\[
		\left[\frac{(n+1)^{q} - n^{q}}{n^{2q}}\right]^2 < \frac{(qn^{q-1})^2}{n^{4q}} = q^2 n^{-2q-2}.
		\]
	\end{proof}


	The following theorem specializes to Theorem \ref{thm_convergence_and_rate_gamma}-(b) when the bias term \(\beta^{(\Gamma)}_n = 0\).

	\begin{theorem}
		\label{thm_Gamma_rate}
		Under the same setting of Theorem \ref{thm_Gamma_convergence}, if the sequence \(\{\hat{a}_n\}\), defined as \(\{\frac{a^{(\Gamma)}_n}{b_n}\}\), satisfies
		\[
		\hat{a}_n \leq \hat{a}_{n+1}(1 + w \hat{a}_{n+1})
		\]
		for some sufficiently small constant \(w>0\), and  the sequences \(\{\frac{b_n^3}{a^{(\Gamma)}_n} |\beta^{(\Gamma)}_n|^2\}\) and \(\{\frac{b_n^3 |G_n|^2}{(a^{(\Gamma)}_n)^3}\}\) are non-decreasing in $n$, then there exists an increasing sequence \(\{\hat{\eta}^{(\Gamma)}_n\}\) and a constant \(c'>0\) such that
		\[
		\E[|\Gamma_{n+1} - \Gamma_{n+1}^*|^2] \leq c' \hat{a}_n \hat{\eta}^{(\Gamma)}_n.
		\]
		In particular, if the parameters \(b_n, a^{(\Gamma)}_n, c^{(\bm\phi)}_n, c^{(\Gamma)}_n, \beta^{(\Gamma)}_n\) are set as in Remark \ref{remark_example_gamma}, then
		\[
		\E[|\Gamma_{n+1}|^2] \leq c \frac{(e \vee \log n)^{p_2} (1 \vee \log\log n)^{\frac{4}{3}}}{n^{\frac{1}{2}}}
		\]
		where \(p_2\) is the same constant appearing in Theorem \ref{thm_Gamma_convergence}.
	\end{theorem}

	\begin{proof}
		First, it follows from  \eqref{eq_projection_sets_actor} and \eqref{eq_h2_app} that

		\begin{equation}
			\begin{aligned}
				&\langle U^{(\Gamma)}_n,  h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n) \rangle %=& \frac{1}{2} \int_0^Tk_1(t; \bm\theta_n) \dd t \langle U^{(\Gamma)}_n,  U^{(\Gamma)}_n (\Sj D_j D_j^\top) \Gamma_n\rangle \\
				\geq \frac{T}{2 b_n c_2} \lambda_{\min}(\Sj D_j D_j^\top) |U^{(\Gamma)}_n|^2 := \frac{\Tilde{c}}{b_n} |U^{(\Gamma)}_n|^2,
			\end{aligned}
		\end{equation}
		where $\Tilde{c} =  \frac{T}{2 c_2} \lambda_{\min}(\Sj D_j D_j^\top) > 0$.

		Define \(n_1 = \inf \{n \in \mathbb{N} : \Gamma_n^* \in K^{(\Gamma)}_{n+1}\}\). For \(n \geq n_1\), we follow a similar reasoning as in the proof of Theorem \ref{thm_Gamma_convergence} to get
		\begin{equation}
			\label{eq_phi_rate_temp}
			\begin{aligned}
				\E\left[|U^{(\Gamma)}_{n+1}|^2 \Big| \g_n \right] \leq (1-\Tilde{c}\frac{a^{(\Gamma)}_n}{b_n})|U^{(\Gamma)}_n|^2 + 4\frac{(a^{(\Gamma)}_n)^2}{b_n^2}b_n^2 \biggl(& |h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n)|^2 + (1+|\frac{b_n}{2\Tilde{c}a^{(\Gamma)}_n}|)|\beta^{(\Gamma)}_n|^2 \\
				& + |\frac{b_nG_n^2}{2\Tilde{c}(a^{(\Gamma)}_n)^3}| + |\frac{G_n}{a^{(\Gamma)}_n}|^2 + \E\left[ \left|\xi^{(\Gamma)}_{n+1} -  \beta^{(\Gamma)}_n \right|^2 \Big| \g_n\right] \biggl).
			\end{aligned}
		\end{equation}
		% Now, by the proof of Theorem \ref{thm_Gamma_convergence},
		% \[
		% \begin{aligned}
			% &|h^{(\Gamma)}(\Gamma_n; \bm\theta_n, \gamma_n)|^2 + \E\left[ \left|\xi^{(\Gamma)}_{n+1} -  \beta^{(\Gamma)}_n \right|^2 \Big| \g_n\right]
			% \leq& c (1 + (c^{(\bm\phi)}_n)^8 + (c^{(\Gamma)}_n)^8 + (\log b_n)^8) \exp{\{c(c^{(\bm\phi)}_n)^4\}}.
			% \end{aligned}
		% \]
		Moreover, the assumptions in \eqref{eq_Gamma_assumption_app} imply that  $(1+|\frac{b_n}{2\Tilde{c}a^{(\Gamma)}_n}|)|\beta^{(\Gamma)}_n|^2 \leq c(\frac{b_n}{a^{(\Gamma)}_n}|\beta^{(\Gamma)}_n|^2)$ and $\frac{|G_n|^2}{(a^{(\Gamma)}_n)^2} \leq c (\frac{b_n|G_n|^2}{(a^{(\Gamma)}_n)^3})$  for some constant $c>0$.
		When $n \geq n_1$, in view of  \eqref{eq_projection_sets_critic}, \eqref{eq_projection_sets_actor}, \eqref{eq_h2n_upper_app}, and \eqref{eq_Gamma_noise_assumption}, it follows from \eqref{eq_phi_rate_temp} that
		\[ \E\left[|U^{(\Gamma)}_{n+1}|^2 \Big| \g_n \right] \leq (1-\Tilde{c} \hat{a}_n)|U^{(\Gamma)}_n|^2 + 4\hat{a}_n^2 \hat{\eta}^{(\Gamma)}_n \],
		where
		\begin{equation}
			\begin{aligned}
				\hat{\eta}^{(\Gamma)}_n =& c b_n^2 \biggl(1 + (c^{(\bm\phi)}_n)^8 + (c^{(\Gamma)}_n)^8 + (\log b_n)^8 + \frac{b_n|\beta^{(\Gamma)}_n|^2}{a^{(\Gamma)}_n} + \frac{b_n|G_n|^2}{(a^{(\Gamma)}_n)^3}\biggr) \exp{\{c(c^{(\bm\phi)}_n)^4\}},
			\end{aligned}
		\end{equation}
		which is monotonically increasing because $c^{(\bm\phi)}_n$, $c^{(\Gamma)}_n$, $b_n$ are monotonically increasing and $\frac{b_n^3}{a^{(\Gamma)}_n}|\beta^{(\Gamma)}_n|^2$, $\frac{b_n^3|G_n|^2}{(a^{(\Gamma)}_n)^3}$ are non-decreasing by the assumptions. Taking expectations on both sides of the above and
		denoting $\rho_n = \E[|U^{(\Gamma)}_n|^2]$, we get
		\begin{equation}
			\label{eq_Gamma_rate_induction}
			\rho_{n+1} \leq (1-\Tilde{c} \hat{a}_n)\rho_n + 4\hat{a}_n^2 \hat{\eta}^{(\Gamma)}_n
		\end{equation}
		when $n\geq n_1$.

		Next, we show \(\rho_{n+1} \leq c^\prime \hat{a}_n \hat{\eta}^{(\Gamma)}_n\) for all \(n \geq 0\), where \(c' = \max\{ \frac{\rho_1}{\hat{a}_0 \hat{\eta}^{(\Gamma)}_0},  \frac{\rho_2}{\hat{a}_1 \hat{\eta}^{(\Gamma)}_1}, \cdots,  \frac{\rho_{n_1+1}}{\hat{a}_{n_1} \hat{\eta}^{(\Gamma)}_{n_1}}, \frac{4}{\Tilde{c}} \} + 1\). Indeed, it is true when $n\leq n_1$.  Assume that $\rho_{k+1} \leq c'a_k \hat{\eta}^{(\Gamma)}_n$ is true for $n_1 \leq k \leq n-1$.
		Then \eqref{eq_Gamma_rate_induction} yields
		\[
		\begin{aligned}
			\rho_{n+1} &\leq (1-\Tilde{c} \hat{a}_n)\rho_n + 4\hat{a}_n^2 \hat{\eta}^{(\Gamma)}_n\\
			&\leq (1-\Tilde{c}\hat{a}_n)c'\hat{a}_{n-1} \hat{\eta}_{1,n-1} + 4\hat{a}_n^2 \hat{\eta}^{(\Gamma)}_n \\
			&\leq (1-\Tilde{c} \hat{a}_n)c'\hat{a}_{n}(1 + w \hat{a}_n) \hat{\eta}^{(\Gamma)}_n + 4\hat{a}_n^2 \hat{\eta}^{(\Gamma)}_n \\
			%&\leq (1-c_l \hat{a}_n)\check{c}_1a_{n}(1 + W \hat{a}_n) \hat{\eta}^{(\Gamma)}_n + 3\hat{a}_n^2 \hat{\eta}^{(\Gamma)}_n \\
			&=c'\hat{a}_n\hat{\eta}^{(\Gamma)}_n + c'\hat{\eta}^{(\Gamma)}_n\hat{a}_n^2 \biggl(w - \Tilde{c} - \Tilde{c} w\hat{a}_n + \frac{4}{c'} \biggl).
		\end{aligned}
		\]
		Consider the function
		\[
		{f}(x) = c'\hat{\eta}^{(\Gamma)}_n x^2 \biggl(w - \Tilde{c} - \Tilde{c} w x + \frac{4}{c'} \biggl),
		\]
		which has two roots at $x_{1,2}=0$ and one root at $x_3=\frac{w - (\Tilde{c} - \frac{4}{c'})}{cw}$.
		Because  $\Tilde{c} - \frac{4}{c'} > 0$, we can  choose $0<w < \Tilde{c} - \frac{4}{c'}$ so that $x_3 < 0$.
		So ${f}(x) < 0$ when $x > 0$, leading to
		\[ c'\hat{\eta}^{(\Gamma)}_n\hat{a}_n^2 \biggl(w- \Tilde{c} - \Tilde{c}w\hat{a}_n + \frac{4}{c'} \biggl) < 0, \;\;\forall n
		\]
		because $\hat{a}_n>0$. We have now proved $\E [|U^{(\bm\phi)}_{n+1}|^2] \leq c' \hat{a}_n \hat{\eta}^{(\Gamma)}_n$.

		In particular, under the setting of Remark \ref{remark_example_gamma} and by Lemma \ref{lemma_gn_bound}, we can verify that $\frac{b_n^3}{a^{(\Gamma)}_n}|\beta^{(\Gamma)}_n|^2$ and $\frac{b_n^3|G_n|^2}{(a^{(\Gamma)}_n)^3}$ are non-decreasing sequences of $n$, and  $\hat{a}_n=\Theta(n^{-1})$. Then
		\begin{equation}
			\begin{aligned}
				\hat{\eta}^{(\Gamma)}_n\leq c n^{\frac{1}{2}} (e \vee \log n)^{p_2} (1 \vee \log \log n)^{\frac{4}{3}},
			\end{aligned}
		\end{equation}
		where $c$ and $p_2$ are positive constants. Thus it follows that
		\[
		\E[|\Gamma_{n+1} - \Gamma_n^*|^2] \leq c \frac{(e \vee \log n)^{p_2} (1 \vee \log\log n)^{\frac{4}{3}}}{n^{\frac{1}{2}}}.
		\]

		Finally, noting that $\Gamma_n^*$ converges to $\bm0$ with the rate of $\frac{1}{b_n}$ by \eqref{eq_phi_2n_star}, we have

		\[
		\begin{aligned}
			\E[|\Gamma_n|^2] =&\E[|\Gamma_n-\Gamma_n^* + \Gamma_n^*|^2]\leq \E[|\Gamma_n-\Gamma_n^* |^2] + \E[|\Gamma_n^*|^2]\\
			\leq& c' \frac{(e \vee \log n)^{p_2} (1 \vee \log\log n)^{\frac{4}{3}}}{n^{\frac{1}{2}}} + c' \frac{\alpha^{\frac{1}{2}}}{(n+\beta)^{\frac{1}{2}}}\\
			\leq& c \frac{(e \vee \log n)^{p_2} (1 \vee \log\log n)^{\frac{4}{3}}}{n^{\frac{1}{2}}}.
		\end{aligned}
		\]

		The proof is complete.

	\end{proof}


	\subsection{Convergence Analysis of $\bm\phi_n$}
	\label{sec_convergence_phi}

	In this sebsection, we  investigate the convergence properties of the actor parameter \(\bm\phi_n\) for both cases $x_0 \neq 0$ and $x_0=0$.

	\begin{theorem}
		\label{thm_convergence_and_rate_phi}
		Under the same setting of Theorem \ref{thm_convergence_and_rate_gamma}, we have

		\begin{enumerate}[label=(\alph*)]
			\item As \(n \to \infty\), \(\bm\phi_n\) converges almost surely to
			\(
			\bm\phi^* =  -\Bigg(\sum_{j=1}^{m} D_j D_j^\top\Bigg)^{-1}\Bigg(B + \sum_{j=1}^{m}C_jD_j\Bigg).
			\)
			\item The expected squared error satisfies
			\[
			\mathbb{E} [|\bm\phi_n - \bm\phi^*|^2] \leq c \frac{(\log n)^{p_1} (\log \log n)^{\frac{4}{3}}}{n^{\frac{1}{2}}}, \quad \text{if } x_0 \neq 0,
			\]
			\[
			\mathbb{E} [|\bm\phi_n - \bm\phi^*|^2] \leq c \frac{(\log n)^{p_1'} (\log \log n)^{\frac{4}{3}}}{n^{\frac{1}{4}}}, \quad \text{if } x_0 = 0,
			\]
where \(c\), \(p_1\), and \(p_1'\) are positive constants only dependent on the model parameters.
		\end{enumerate}
	\end{theorem}

	\begin{proof}
		When \(x_0 \neq 0\), the proof is similar to that of \cite[Theorem 4.1]{huang2024sublinear} with only minor modifications needed. When \(x_0 = 0\), the proof becomes more delicate as the convergence behavior of \(\bm\phi\) now depends explicitly on the actor exploration parameter \(\Gamma\). Here, we  highlight the differences needed.

		Denoted
		\[
		h^{(\bm\phi)}(\bm\phi_n, \Gamma_n; \bm\theta_n, \gamma_n) = \E[Y_n(T) \mid \bm\theta_n, \bm{\phi}_n, \gamma_n, \Gamma_n],
		\]
		and the noise
		\[
		\xi^{(\bm\phi)}_{n} = Y_n(T) - h^{(\bm\phi)}(\bm\phi_n, \Gamma_n; \bm\theta_n, \gamma_n).
		\]
The updating rule \eqref{eq_phi_update} for \(\bm\phi\) is now
		\begin{equation}
			\label{eq_phi_update_app}
			\bm\phi_{n+1} = \Pi_{K^{(\bm\phi)}_{n+1}} (\bm\phi_n + a^{(\bm\phi)}_n[h^{(\bm\phi)}(\bm\phi_n, \Gamma_n; \bm\theta_n. \gamma_n) + \xi^{(\bm\phi)}_{n}]).
		\end{equation}

		Similar to \cite[Section B]{huang2024sublinear}, we obtain
		% \begin{equation}
			% \label{eq_noise_upper1}
			% \begin{aligned}
				% &\operatorname{Var}\left( Y_n(T) \Big| \bm\theta_n, \bm\phi_n, \gamma_n, \Gamma_n \right)  \\
				% \leq& c b_n\left( 1 + |\bm\phi_n|^{8} + |\Gamma_n|^{6} + (\log b_n)^8 + \gamma_n^8\right) \exp{\{c|\bm\phi_n|^6\}}.\\
				% \end{aligned}
			% \end{equation}
		\begin{equation}
			\label{eq_h1_app}
			\begin{aligned}
				h^{(\bm\phi)}(\bm\phi_n, \Gamma_n; \bm\theta_n, \gamma_n) = -l(\bm\phi_n, \Gamma_n; \bm\theta_n, \gamma_n)(\bm\phi_n - \bm\phi^*),
			\end{aligned}
		\end{equation}
		where
		\begin{equation}
			\label{eq_l_definition}
			l(\bm\phi_n, \Gamma_n; \bm\theta_n, \gamma_n) = (\Sj D_j D_j^\top) \int_0^T k_1(t; \bm\theta_n)\mathbb{E} [x_n(t)^2] \dd t.
		\end{equation}

		When \(x_0 \neq 0\), we have \(l(\bm\phi_n, \Gamma_n; \bm\theta_n, \gamma_n) \geq \bar{c} I\), where \(0 < \bar{c}' < 1\) is independent of \(\Gamma_n\). The same proof of \cite[Theorem 4.1]{huang2024sublinear} then applies.

		However, when \(x_0 = 0\),
		\begin{equation}
			\label{eq_h1_l_lower_bound_eq0_app}
			\begin{aligned}
				l(\bm\phi_n, \Gamma_n; \bm\theta_n, \gamma_n) &\geq (\Sj D_j D_j^\top) \int_0^T \frac{c' |\Gamma_n| t}{c_2}  \dd t = \frac{(\Sj D_j D_j^\top) T^2 c'}{2 c_2} |\Gamma_n| \geq \bar{c}' |\Gamma_n| I.
			\end{aligned}
		\end{equation}
Thus \(l\) no longer admits a uniform lower bound strictly away from \(\bm{0}\) because \(\Gamma_n\rightarrow \bm{0}\). %To address these difficulties, we employ two key techniques.
To get around, for establishing part (a), we make use of the condition \(\sum \frac{a^{(\bm\phi)}_n}{b_n} = \infty\), which ensures that the argument  in proving \cite[Theorem B.3]{huang2024sublinear} remains valid. (Notice that the hyperparameters \(a^{(\bm\phi)}_n\) and \(b_n\) specified in Theorem \ref{thm_convergence_and_rate_gamma} also satisfy this condition.) On the other hand, for proving part (b), we reinterpret \(\hat{a}_n = \frac{a^{(\bm\phi)}_n}{b_n}\) as the effective learning rate and follow the strategy outlined in the proof of Theorem \ref{thm_Gamma_rate}. This adjustment allows the analysis in \cite[Appendix B.6]{huang2024sublinear} to be carried over to our setting.
	\end{proof}



	The established convergence of the learned policy underpins the regret analysis of Algorithm \ref{algo_rl_lq}. Theorem \ref{thm_convergence_and_rate_phi} posits that the MSE of \(\bm\phi_n\) depends on whether the initial state \(x_0\) is zero or nonzero; yet both cases ultimately lead to the same sublinear regret bound, which will be shown in the next subsection.



	\subsection{Regret Bound}
	\label{sec_regret}

	The regret quantifies the (average) difference between the value function of the learned policy and that of the oracle optimal policy in the long run. 	
	For a stochastic Gaussian policy \(\pi = \mathcal{N}(\cdot|\bm\phi x, \Gamma)\), we denote
	\begin{equation}
		\begin{aligned}
			\label{jbar}
			\Bar{J}(\bm\phi, \Gamma) = \mathbb{E} \biggl[& \int_0^T \left(-\frac{1}{2}Qx^\pi(s)^2  \right) \mathrm{d}s - \frac{1}{2}Hx^\pi(T)^2 \Big| x^\pi(0)=x_0 \biggr].
		\end{aligned}
	\end{equation}

	This function evaluates policy \(\mathcal{N}(\cdot|\bm\phi x, \Gamma)\) under the original objective \textit{without} entropy regularization. The oracle value of the original problem is \(\Bar{J}(\bm\phi^*, \bm{0})\).


	\begin{theorem}
		\label{thm_regret}
		Under the same setting of Theorem \ref{thm_convergence_and_rate_gamma}, Algorithm \ref{algo_rl_lq} leads to the following regret bounds over \(N\) iterations:
		\[
		\begin{aligned}
			&\sum_{n=1}^{N}\mathbb{E} \big[\Bar{J}(\bm\phi^*, \bm{0}) - \Bar{J}(\bm\phi_n, \Gamma_n)\big] 
			\leq c + c N^{\frac{3}{4}}(\log N)^{\frac{p_1+p_2}{2}+1} (\log\log N), \quad \text{if } x_0\neq0,\\
			&\sum_{n=1}^{N}\mathbb{E} \big[\Bar{J}(\bm\phi^*, \bm{0}) - \Bar{J}(\bm\phi_n, \Gamma_n)\big] 
			\leq c+c N^{\frac{3}{4}} (\log N)^{\frac{p_1'+p_2}{2} \vee (p_1'+\frac{3}{2})} (\log\log N), \quad \text{if } x_0= 0,
		\end{aligned}
		\]
		where \(c > 0\) is a constant independent of \(N\), and \(p_1, p_1', p_2\) are the same constants given in Theorems \ref{thm_convergence_and_rate_gamma} and \ref{thm_convergence_and_rate_phi}.
	\end{theorem}



