$ i_{1}=a_{3}(a_{1}'+a_{2})+a_{2}(a_{1}\oplus a_{0}),$\vspace{0.1cm}

$ i_{2}=a_{1}(a_{2}+a_{0}')+a_{0}(a_{3}\odot a_{2})(a_{2}a_{3}+a_{1}')$\vspace{0.1cm}

$ i_{3}=a_{1}(a_{3}'+a_{0})+a_{0}(a_{3}\oplus a_{2}).$\vspace{0.3cm}

