operations of addition and scalar multiplication with special properties. 
On any both binary vectors $\textbf{x}=(x_{1}, \cdots,x_{n})$ and $\textbf{y}=(y_{1}, \cdots,y_{n})$ in $\mathbb{F}_{2}^{n}=GF(2^{n})$, we define binary addition with $\textbf{x} \oplus \textbf{y}=(x_{1} \oplus y_{1}, \cdots, x_{n} \oplus y_{n} )$ and dot product with $<\textbf{x} \ldotp \textbf{y}>=x_{1}y_{1}+ \cdots +x_{n}y_{n}$. 
%Sometimes in the representation of a binary vector, it is considered as the binary representation of an integer, such as
%\begin{equation}
%	\textbf{x}=(x_{1}, \cdots,x_{n})=\sum_{i=1}^{n}x_{i}2^{n-i}
%\end{equation}
\begin{definition} 
	The number of ones in $\textbf{x} \in \mathbb{F}_{2}^{n}$ is called the Hamming weight of $\textbf{x}$ and is represented by $Hw(\textbf{x})$. Also for each  $\textbf{x} \in \mathbb{F}_{2}^{n}$, the set $supp(\textbf{x})$ contains the position of ones in $\textbf{x}$.
\end{definition}
\begin{definition}\label{bf:def} %(Boolean Function)
	A Boolean function $f$ of $n$ variables is a function of the form $f:\mathbb{F}_{2}^{n} \mapsto  \mathbb{F}_{2}$ (i.e. $F \in \mathcal{B}_{n}$) . Its value vector is the binary vector $v_{f}$ of length $2^{n}$ composed of all $f (\textbf{x})$ when $\textbf{x} \in \mathbb{F}_{2}^{n}$.
\end{definition}
\begin{definition} %( TT of a Boolean function) 
	For an $n$-variable Boolean function $f:\mathbb{F}_{2}^{n} \mapsto  \mathbb{F}_{2}$, the Truth Table (TT) consists of $2^{n}$ rows, used to represent the output of $f$ for all possible input $\mathbf{x}$. 
	So it can be represented in the form of a binary column vector with dimension  $2^{n}$ as form \ref{BF-TT},
	\begin{equation} \label{BF-TT}
	\begin{pmatrix}
	f(0) \\
	\vdots \\
	f(2^{n}-1) \\
	\end{pmatrix}
	\end{equation}
\end{definition}
\begin{definition}
	The number of ones in the TT of a Boolean function $f$ is called the Hamming weight of $f$ and is represented by $Hw(f)$. Obviousely For each Boolean function, $Hw(f)=|supp(f)|$.
\end{definition}
%\begin{definition} \label{bf:hw_f_and_ g}
%	The Hamming distance between two Boolean functions $f_{1}, f_{2}$ is measured by the definition \cite{carlet2007nonlinearities},
%	\begin{equation}
%		Hw(f_{1},f_{2})=2^{n-1} - \frac{1}{2} \sum_{\textbf{x} \in \mathbb{F}_{2}^{n}} (-1)^{f_{1}(\textbf{x}) \oplus f_{2}(\textbf{x})}
%	\end{equation} 

%\end{definition}
\begin{definition}\label{bf:ANF}%( ANF of a Boolean function)
	For any Boolean function $f$, one of the most commonly representations is the multivariate polynomial representation also called the Algebraic Normal Form (ANF) of $f$ that is,
	\begin{equation} 
	f(\textbf{x})=f(x_{1},x_{2},\ldots,x_{n})\!=\!\bigoplus _{I\subseteq \{1,\ldots,n\}}c_{I}\left({\prod _{i\in I}x_{i}}\right),\hspace {0.2cm} c_{I}\in \mathbb {F}_{2}.
	\end{equation}

	where the sums include all monomials formed by the variables \cite{van2014encyclopedia}.
\end{definition}
\begin{definition}
	The derivative function of an $n$-variable Boolean function $f$ respect to $\textbf{u} \in \mathbb{F}_{2}^{n}$, is defined as $D_{\textbf{u}}f=f(\textbf{x}) \oplus f(\textbf{x}+ \textbf{u})$ \cite{van2014encyclopedia}.
\end{definition}
Walsh-Hadamard Transform (WHT)\footnote{some authors also call it Walsh transform or Hadamard transform} is a powerful tool for analyzing Boolean functions. It transforms a Boolean function into a different domain where its properties can be analyzed more easily. 
\begin{definition}\label{bf:WHT} %(WHT of a Boolean function)
	A Boolean function $f$ is uniquely determined by its Walsh transform, which is an integer-valued function that can be defined for all $\mathbf{u} \in \mathbb{F}_{2}^{n}$
	\begin{equation}
	W_{f}(\textbf{u}) = \sum_{\textbf{x} \in \mathbb{F}_{2}^{n}} (-1)^{f(\textbf{x}) \oplus <\textbf{u} , \textbf{x}>}
	\end{equation}
\end{definition}
\begin{definition} %(Vectorial Boolean Function) 
	A Vectorial Boolean Function (VBF) is an extended form of a Boolean function and is a function of the form $F:\mathbb{F}_{2}^{n} \mapsto \mathbb{F}_{2}^{m}$ ( for $m>1$) which maps $n$ binary input vectors to $m$ binary output vectors and sometimes called an $(n,m)$-function (i.e. $F \in \mathcal{B}_{n}^{m}$).
\end{definition}
%We denote the set of all $(n,m)$-functions by $\mathcal{B}_{n}^{m}$.
\begin{definition}\label{vbf:S-def} %(S-box)  
	Any S-box $S \in \mathcal{B}_{n}^{m}$ is a VBF. 
\end{definition}
For any VBF, each output bit can be seen as a Boolean function of the input bits, so $S$ can be defined at every $\textbf{x} \in \mathbb{F}_{2}^{n}$ by $S(\textbf{x})=(f_{1}(\textbf{x}),f_{2}(\textbf{x}),\cdots,f_{m}(\textbf{x}))$. In this case, each $f_{j}(\textbf{x})$ for $j=1, \cdots,m$ is called $j$-th component (or coordinate) function of $S$. 
\begin{definition}%(S-box TT)
	The TT of $S=(f_{1}, \cdots,f_{m})$ can be shown in the form of a matrix with dimensions $2^{n} \times m$, and its $j$-th column represents the TT of $j$-th component function for $1 \leq j \leq m$. 
	The TT consists of $2^{n}$ rows, used to represent the output of S-box for all possible combinations of its input values. So it can be represented in the form of a matrix as form \ref{S-TT},
	\begin{equation} \label{S-TT}
	\begin{pmatrix}
	f_{1}(v_{0}) \cdots \cdots f_{m}(v_{0}) \\
	\cdots \\
	\cdots  \\
	f_{1}(v_{2^{n}-1}) \cdots  f_{m}(v_{2^{n}-1})\\
	\end{pmatrix}
	\end{equation}
\end{definition}
The ANF of an S-box 
%(as an $n$-variable Boolean vector function) is another form to express how the input bits of the S-box are combined to produce output bits. It 
shows which input bits contribute to each output bit through simple operations like XOR. This representation helps in understanding the S-box’s behavior and how it transforms data, which is essential for analyzing its security.
\begin{definition}\label{vbf:ANF} %(S-box ANF)
	The ANF of an S-box can be expressed as a vector of the $m$ Boolean functions $f_{k}$ as follows:
	\begin{equation} \tiny
	f_{k}(x_{1},\cdots,x_{n})=c_{0}^{(k)}	 \bigoplus_{1 \leq i \leq n} c_{i}^{(k)}x_{i} \bigoplus_{1 \leq i , j \leq n} c_{ij}^{(k)}x_{i}x_{j}\bigoplus_{\cdots} \cdots \bigoplus_{\cdots} c_{12\cdots n}^{(k)}x_{1}x_{2}\cdots x_{n}
	\end{equation}
	where all coefficients belong to $\mathbb{F}_{2}$.
\end{definition}
%The WHT of an S-box can be thought of as a way to measure how “flat” or “balanced” the output of the S-box is when inputs are varied. Intuitively, it tells us how much the output of the S-box deviates from being uniformly distributed. If an S-box has a high WHT value for a specific input pattern, it indicates that changing that input pattern significantly influences the output, which is a desirable property for cryptographic strength as it ensures unpredictability. In other words, 
The WHT of an S-box  quantifies the degree of nonlinearity of the S-box and is defined as a mathematical transformation that measures the correlation between the output of the S-box and all possible linear functions over the binary field. 

\begin{definition}\label{vbf:WHT} %(S-box WHT)
	%for a given input vector $ \textbf{x} \in \mathbb{F}_2^n$ , 
	The WHT of an S-box $S \in \mathcal{B}_{n}^{m}$ is defined as:
	\begin{equation}
	W_{S}(\textbf{u},\textbf{v}) = \sum_{\textbf{x} \in \mathbb{F}_{2}^{n}} (-1)^{<\textbf{v} \ldotp S(\textbf{x})> \oplus <\textbf{u} \ldotp \textbf{x}>}
	\end{equation}
	where $\textbf{u} \in \mathbb{F}_{2}^{n}$ and $\textbf{v} \in \mathbb{F}_{2}^{m}$ \cite{claude_carlet_2020}.
\end{definition}
