\subsubsection{Transparency Order}
%\subsubsection{Boolean function}
The notion of transparency order, proposed by Prouff \cite{prouff2005dpa} and then redefined by Chakraborty et al. \cite{chakraborty2017redefining}, is a property that attempts to characterize the resilience of cryptographic algorithms against DPA attacks. A lower transparency order indicates better resistance, meaning that the function's output does not reveal much information about the input or the key used.
\begin{definition}\label{bf:TO}%(Transparency Order) 
	Suppose  $f \in \mathcal{B}_{n}$.
	%	and $D_{\textbf{u}}f=\{\textbf{x} \in \mathbb{F}_{2}^{n} | f(\textbf{x}) \oplus f(\textbf{x} \oplus \textbf{u})=0\}$. 
	The transparency order of $f$ denoted by $To_{f}$ is defined as \cite{chakraborty2017redefining}:
	\begin{equation}\label{To_f}
	To_{f}=\max_{\beta \in \mathbb{F}_{2}^{n}} \left(  \left| 1- 2 Hw(\beta) \right| - \dfrac{1}{2^{2n}-2^{n}} 
	\sum_{\alpha \in \mathbb{F}_{2}^{n}} \left|   W_{D_{\textbf{a}}f(\textbf{0},\textbf{v})}	\right| \right)
	\end{equation}
	%	For a Boolean function $f \in \mathcal{B}_{2}^{n}$ \cite{wang2019transparency}, 
	%	\begin{equation}
	%		To_{_{f}} \leq 1-\dfrac{(2^{n}-2Nl_{_{f}})^{2}}{2^{n}(2^{n}-1)}+\dfrac{1}{2^{n}-1}.
	%	\end{equation}	
	%	Also, if for a positive constant $C$,  $Nl_{_{f}} \geq 2^{n-1} -C . 2^{\frac{n}{2}} \geq 0$ then,
	%	\begin{equation}
	%		To_{_{f}} \geq 1-\dfrac{\sqrt{16 C^{4}-1}}{\sqrt{2^{n}-1}}.
	%	\end{equation}
\end{definition}
Transparency order is a relatively new metric that quantifies an S-box's resistance against differential power analysis (DPA) attacks by measuring the predictability of power consumption differences \cite{10.1088/1402-4896/adadab}. In simpler terms, it gauges an S-box’s ability to keep its secrets even when adversaries eavesdrop on its power consumption or electromagnetic radiation. 
%Figure \ref{TO-security} shows that lower transparency order values indicate better resistance against SCAs \cite{prouff2005dpa}, as it indicates that the output does not reveal much information about the input or the key used.
%In contrast, a higher transparency order suggests that the S-Box is more transparent, meaning it is easier for an attacker to identify correlations between input and output, potentially compromising the security of the cryptographic system. 
%Intuitively, it reflects how "hidden" the output is from potential attackers \cite{picek2016evolutionary}.

\begin{definition}\label{vbf:TO}
	Suppose  $S \in \mathcal{B}_{n}^{m}$.
	% and $D_{\textbf{u}}S=\{\textbf{x} \in \mathbb{F}_{2}^{n} | S(\textbf{x}) \oplus S(\textbf{x} \oplus \textbf{u})=0\}$. 
	The transparency order TO of $S$ denoted by $TO_{S}$ is defined as \cite{chakraborty2017redefining}:
	\begin{equation} \tiny
	TO_{S}=\max_{\beta \in \mathbb{F}_{2}^{n}} \left(  \left| m- 2 Hw(\beta) \right| - \dfrac{1}{2^{2n}-2^{n}} \sum_{\alpha \in \mathbb{F}_{2}^{n}} \left|  \sum_{\textbf{v} \in \mathbb{F}_{2}^{m}, Hw(\textbf{v})=1} (-1)^{<\textbf{v},\beta>} W_{D_{\textbf{a}}S}(\textbf{0},\textbf{v})	\right| \right)
	\end{equation}

