The adaptive PIR scheme must satisfy the following two constraints.
\begin{itemize}
    \item \textbf{Correctness:} The user must be able to correctly decode $\mathbf{W}^{(\theta)}$ 
    %from the local sub-queries and the available first $F_S$ sub-responses of each of the $N-S$ non-straggler servers, for all $0\leq S\leq S_{\max}$, i.e.,
    after collecting the first $F_S$ responses from each of the fastest $N-S$ servers for all $0\leq S\leq S_{\max}$, i.e.,
    %from the local sub-queries and the available sub-responses from any $N-S$ non-straggler servers for all $0\leq S\leq S_{\max}$, i.e.,
\begin{IEEEeqnarray}{c}\notag
H(\mathbf{W}^{(\theta)}|\mathcal{A}_{[0:N)\backslash\mathcal{S},[0:F_S)}^{(\theta)},\mathcal{Q}_{[0:N),[0:F)}^{(\theta)})=0,\quad\forall\,\mathcal{S}\subseteq[0:N),|\mathcal{S}|=S.
\end{IEEEeqnarray}
%where $\mathcal{A}_{[0:N)\backslash\mathcal{S},[0:F_S)}^{(\theta)}$ represents the assemble of the first $F_S$ sub-responses received from each of the $N-S$ servers.
    \item \textbf{Privacy:} The strategies for retrieving any two files $\mathbf{W}^{(\theta)}$ and $\mathbf{W}^{(\theta')}$ must be indistinguishable from the perspective of any up to $T$ colluding servers, i.e.,
\begin{IEEEeqnarray}{c}
(\mathcal{Q}_{\mathcal{T},[0:F)}^{(\theta)},\mathcal{A}_{\mathcal{T},[0:F)}^{(\theta)},\mathcal{Y}_{\mathcal{T}})\sim (\mathcal{Q}_{\mathcal{T},[0:F)}^{(\theta')},\mathcal{A}_{\mathcal{T},[0:F)}^{(\theta')},\mathcal{Y}_{\mathcal{T}}),\quad\forall\, \theta,\theta'\in[0:M), \forall\, \mathcal{T}\subseteq[0:N), |\mathcal{T}|\leq T,\notag
\end{IEEEeqnarray}
where $X\sim Y$ indicates that the random variables $X$ and $Y$ have identical distributions. Equivalently, all possible  information available to any $T$ colluding servers is independent of the index $\theta$ of the desired file, i.e.,
\begin{IEEEeqnarray}{c}\label{Infor:priva cons}
I(\theta;\mathcal{Q}_{\mathcal{T},[0:F)}^{(\theta)},\mathcal{A}_{\mathcal{T},[0:F)}^{(\theta)},\mathcal{Y}_{\mathcal{T}})=0, \quad \forall\, \mathcal{T}\subseteq[0:N), |\mathcal{T}|\leq T.
\end{IEEEeqnarray}
\end{itemize}


