\subsubsection*{Query Phase}
To privately retrieve the partial file $\widetilde{\mathbf{W}}^{(\theta)}(\mathcal{R},:)$, we choose the random noises $\widetilde{z}_{i,k,0}^{(m,\mathcal{R})},\widetilde{z}_{i,k,1}^{(m,\mathcal{R})}$ and design the query function $\widetilde{q}_{i,k}^{(m,\mathcal{R})}(x)$ using $\{v_{i,k,0}^{(\mathcal{R})}(x),v_{i,k,1}^{(\mathcal{R})}(x),v_{i,k,2}^{(\mathcal{R})}(x)\}$
for any $m\!\in\![0:3),i\!\in\!\mathcal{R}$, and $k\!\in\![0:2)$, given by
\begin{IEEEeqnarray}{c}\label{Example:framework:query:polynomial}
\widetilde{q}_{i,k}^{(m,\mathcal{R})}(x)=
\widetilde{z}_{i,k,0}^{(m,\mathcal{R})}\cdot v_{i,k,0}^{(\mathcal{R})}(x)+
\widetilde{z}_{i,k,1}^{(m,\mathcal{R})}\cdot v_{i,k,1}^{(\mathcal{R})}(x)
+\left\{
\begin{array}{@{}l@{\;\;}l}
v_{i,k,2}^{(\mathcal{R})}(x),
&\mathrm{if}\,\, m=\theta \\
0, & \mathrm{otherwise}
\end{array} \right..
\end{IEEEeqnarray}
Then the query sent to the server $n,n\in[0:8)$ is given by
\begin{IEEEeqnarray}{c}
\widetilde{\mathcal{Q}}_n^{(\theta,\mathcal{R})}=\left\{\widetilde{q}_{i,k}^{(m,\mathcal{R})}(\alpha_n):m\in[0:3),i\in\mathcal{R},k\in[0:2)\right\}.\notag
\end{IEEEeqnarray}
%Here, we omit the index of the desired file to simplify the notation.

\subsubsection*{Answer Phase}
The server $n,n\in[0:8)$ will generate the response
\begin{IEEEeqnarray}{c}\label{Example:PIR:answer:1}
\widetilde{\mathcal{A}}_n^{(\theta,\mathcal{R})}=\left\{\widetilde{A}_{n,k}^{(\theta,\mathcal{R})}:k\in[0:2)\right\},
\end{IEEEeqnarray}
where $\widetilde{A}_{n,k}^{(\theta,\mathcal{R})}$ is given by 
\begin{IEEEeqnarray}{c}\label{Example:PIR:answer:2}
\widetilde{A}_{n,k}^{(\theta,\mathcal{R})}=\sum\limits_{m\in[0:3)}\sum\limits_{i\in\mathcal{R}}\widetilde{q}_{i,k}^{(m,\mathcal{R})}(\alpha_n)\cdot \tilde{f}_{i}^{(m)}(\alpha_n).
\end{IEEEeqnarray}

\subsubsection*{Decoding Phase}
Since the \emph{feasible PIR coding framework} satisfies the conditions $\widetilde{\mathrm{F}}$2 and $\widetilde{\mathrm{F}}$3, 
the user can decode the partial file $\widetilde{\mathbf{W}}^{(\theta)}(\mathcal{R},:)$ from any $5+r-d$ out of the $8$ responses $\widetilde{\mathcal{A}}_{0}^{(\theta,\mathcal{R})},\widetilde{\mathcal{A}}_{1}^{(\theta,\mathcal{R})},\ldots,\widetilde{\mathcal{A}}_{7}^{(\theta,\mathcal{R})}$ after obtaining any $d$ rows of $\widetilde{\mathbf{W}}^{(\theta)}(\mathcal{R},:)$, for any subset $\mathcal{R}\subseteq[0:3)$ of size $1\leq r\leq 3$ and any $d\in[0:r)$.
\end{Example}


\subsection{Implementation of Feasible PIR Coding Framework}\label{subsection:implementation:PIR}

%This PIR framework can be specifically implemented using either Lagrange codes \cite{zhu2022symmetric,zhu2022multi} or cross subspace alignment codes \cite{jia2019cross,jia2020x,jia2022xFSL,jia2020asymptotic}.

Lagrange codes \cite{yu2019lagrange,zhu2022generalized,zhu2024generalized} and cross subspace alignment codes \cite{jia2019cross,jia2020x,jia2022xFSL,jia2020asymptotic} are two distinct types of codes that can effectively address various PIR problems, such as the multi-user blind PIR problem \cite{lu2021double,zhu2022multi} and the private function computation problem \cite{zhu2022symmetric,raviv2019private222,jia2024asymptotic}. Both types of codes can be used to separately implement the \emph{feasible PIR coding framework}. Here, to simplify the discussion, we only provide the construction of a \emph{feasible PIR coding framework} based on Lagrange codes, following the ideas from \cite[Section III]{zhu2022symmetric} and \cite[Section III]{zhu2022multi}.
%The PIR coding framework can be implemented using Lagrange codes or cross subspace alignment codes. 

%constructing the \emph{feasible PIR coding framework}. % the coding parameters of the distributed storage codes and the proposed adaptive PIR scheme in the subsequent subsections.


Before proceeding, we identify a group of elements from the finite field $\mathbb{F}_q$ that will serve as the encoding parameters for the \emph{feasible PIR coding framework} implemented using Lagrange codes.

%\subsection{Encoding Parameters}\label{section:coding:parameters}

Let $\{\beta_{i,k}:i\in[0:\lambda),k\in[0:K+X)\}$ be the elements from the finite field $\mathbb{F}_q$ of size $q$. These elements can be denoted by a matrix $\boldsymbol{\beta}$ with dimensions $\lambda\times(K+X)$, given by
\begin{IEEEeqnarray}{rCl}\notag
\boldsymbol{\beta}\triangleq\left[
  \begin{array}{ccc;{2pt/2pt}ccc}
    \beta_{0,0} & \cdots & \beta_{0,K-1} & \beta_{0,K} & \cdots & \beta_{0,K+X-1}  \\
    \vdots & \vdots & \vdots & \vdots & \vdots & \vdots \\
    \beta_{\lambda-1,0} & \cdots &\beta_{\lambda-1,K-1} & \beta_{\lambda-1,K} & \cdots &\beta_{\lambda-1,K+X-1} \\
\end{array}
\right].
\end{IEEEeqnarray}
%The group of elements needs to satisfy the following constraints in P0-P3, which will be utilized to ensure the achievability of the distributed storage codes and the proposed adaptive PIR scheme.

In order to ensure the feasibility of the PIR coding framework constructed using Lagrange codes, we require that the elements $\{\beta_{i,k}\!:\!i\!\in\![0\!:\!\lambda),k\!\in\![0\!:\!K\!+\!X)\}$, along with $\{\alpha_n\!:\!n\!\in\![0\!:\!N)\}$, satisfy the following four constraints.
\begin{enumerate}
  \item[P0.] All elements in each row of the matrix $\boldsymbol{\beta}$ are pairwise distinct, i.e., for any given $i\in[0:\lambda)$, $\beta_{i,k}\neq\beta_{i,k'}$ for all $k, k'\in[0:K+X)$ with $k\neq k'$;
  \item[P1.] Each column in the first $K$ columns of the matrix $\boldsymbol{\beta}$ is composed of distinct elements, i.e., for any given $k\in[0:K)$, $\beta_{i,k}\neq\beta_{i',k}$ for all $i,i'\in[0:\lambda)$ with $i\neq i'$;
  \item[P2.] The elements $\alpha_0,\ldots,\alpha_{N-1}$ are distinct of each other, i.e., $\alpha_n\neq\alpha_{n'}$ for all $n,n'\in[0:N)$ with $n\neq n'$;
  \item[P3.] The elements $\alpha_0,\ldots,\alpha_{N-1}$ are distinct from the elements in the first $K$ columns of the matrix $\boldsymbol{\beta}$, i.e., $\{\alpha_n:n\in[0:N)\}\cap\{\beta_{i,k}:i\in[0:\lambda),k\in[0:K)\}=\emptyset$.%\footnote{\red{There is no need to protect data security if $X$-security is not considered (i.e., $X=0$), thus this constraint can be eliminated.} %This constraint is alleviated if $X$-security is not considered (i.e., $X=0$).
      %}
\end{enumerate}

There exists a group of elements $\{\beta_{i,k},\alpha_n:i\!\in\![0:\lambda),k\!\in\![0:K+X),n\!\in\![0:N)\}$ that satisfies the constraints P0--P3 in a finite field $\mathbb{F}_q$, for any prime power $q$ with size $q\geq N+\max\{K, \lambda\}$. In particular, the optimal size of the finite field $\mathbb{F}_q$ that satisfies the constraints P0--P3 is $N+\max\{K,\lambda\}$. We summarize this result in the following lemma, and its proof is placed in Appendix-\ref{Proof:finite:field:size}.
\begin{Lemma}\label{theorem:tield size}
%There must exist a group of elements $\{\beta_{i,k},\alpha_n:i\in[0:\lambda),k\in[0:K+X),n\in[0:N)\}$ that satisfies the constraints P0-P3 in a finite field $\mathbb{F}_q$ for any prime power $q$ of size $q\geq N+\max\{K, N-(K+X+T-1)\}$. In particular, 
The optimal size of the finite field $\mathbb{F}_q$ that satisfies the constraints P0--P3 is $q=N+\max\{K,\lambda\}$.
\end{Lemma}


