\subsubsection*{Query Phase} 
To design private queries that provide the adaptive guarantee simultaneously for all $S=0,1,2$ stragglers,
%In the query phase, to provide the adaptive guarantee, 
we construct a query array of dimensions $3\times 18$, composed of three subarrays $\mathbf{U}^{0},\mathbf{U}^{1}$, and $\mathbf{U}^2$, given by
\begin{IEEEeqnarray}{c}\label{Example2:query:array}
\mathbf{U}=\left[
  \begin{array}{c;{2pt/2pt}c;{2pt/2pt}c}
  \underbrace{
  \begin{array}{cccccc}
   0 & 3 & 6 & 9 &  12 & 15 \\
   1 & 4 & 7 & 10 & 13 & 16 \\
   2 & 5 & 8 & 11 & 14 & 17 \\
  \end{array}
  }_{=\mathbf{U}^{0}} & 
    \underbrace{
  \begin{array}{ccc}
  * & 0 & 9 \\
  4 & * & 13 \\
  8 & 17 & * \\
   \end{array}
  }_{=\mathbf{U}^{1}}
   &
   \underbrace{
  \begin{array}{ccccccccc}
  * & * & 3 & * & * & 12 & * & * & 0 \\
  7 & * & * & 16 & * & * & 13 & * & * \\
  * & 2 & * & * & 11 & * & * & 8 & * \\
  \end{array}
  }_{=\mathbf{U}^{2}}
 \end{array}
\right].    
\end{IEEEeqnarray}

For convenience, let $\Gamma^h$ denote the number of columns in the subarray $\mathbf{U}^{h}$ for any $h\in[0:3)$, then we have $\Gamma^0=6,\Gamma^1=3$, and $\Gamma^2=9$. 
% For any given $h\in[0:3)$ and $j\in[0:\Gamma^h)$, let $\mathcal{R}^{h}_j$ denote the set consisting of the integer elements in the $j$-th column of the subarray $\mathbf{U}^{h}$, and $\widetilde{\mathcal{R}}^{h}_j$ denote the set consisting of the integer elements in $\mathcal{R}^{h}_j$ modulo $\lambda$.
Clearly, the integer elements in each column of the query array form a subset of $[0:18)$, and under the modulo $\lambda=3$ operation, they form a subset of $[0:3)$, i.e., ${\mathcal{R}}^{h}_j\subseteq[0:18)$ and $\widetilde{\mathcal{R}}^{h}_j\subseteq[0:3)$ for any $h\in[0:3)$ and $j\in[0:\Gamma^h)$, where $\mathcal{R}^{h}_j$ denotes the set consisting of the integer elements in the $j$-th column of the subarray $\mathbf{U}^{h}$, and $\widetilde{\mathcal{R}}^{h}_j$ denotes the set consisting of the integer elements in $\mathcal{R}^{h}_j$ modulo $\lambda$.
Moreover, for any $h\in[0:3)$ and $j\in[0:\Gamma^h)$, we observe from \eqref{Example:framework:storage:1}--\eqref{Example:framework:storage:3} and \eqref{Aexample:storage:1}--\eqref{Aexample:storage:2} that the partial file $\mathbf{W}^{(m)}(\mathcal{R}_j^h,:)$ is encoded in exactly the same way as $\widetilde{\mathbf{W}}^{(m)}(\widetilde{\mathcal{R}}^{h}_j,:)$ in \eqref{example:files} and the only difference between them lies in the values of the files $\mathbf{W}^{(m)}(\mathcal{R}_j^h,:)$ and $\widetilde{\mathbf{W}}^{(m)}(\widetilde{\mathcal{R}}^{h}_j,:)$, for any $m\in[0:3)$. Recall that the \emph{feasible PIR coding framework} is constructed regardless of the values of the data files $\widetilde{\mathbf{W}}^{(0)}(\widetilde{\mathcal{R}}^{h}_j,:),\widetilde{\mathbf{W}}^{(1)}(\widetilde{\mathcal{R}}^{h}_j,:),\widetilde{\mathbf{W}}^{(2)}(\widetilde{\mathcal{R}}^{h}_j,:)$.
This ensures that the user can privately retrieve the desired partial file $\mathbf{W}^{(\theta)}(\mathcal{R}_j^h,:)$ by following the query, response, and decoding steps similar to those in Example \ref{Flexible:example}.


%We will utilize the query array and the \emph{feasible PIR coding framework} to construct an adaptive PIR scheme that can simultaneously tolerate the presence of $S=0,1,2$ stragglers.



More precisely, to privately retrieve the partial file $\mathbf{W}^{(\theta)}(\mathcal{R}_j^h,:)$ for any $h\in[0:3)$ and $j\in[0:\Gamma^h)$, similar to \eqref{Example:framework:query:polynomial}, the user chooses the random noises $z_{(i)_{\lambda},k,0}^{(m,\widetilde{\mathcal{R}}^{h}_j)},z_{(i)_{\lambda},k,1}^{(m,\widetilde{\mathcal{R}}^{h}_j)}$ and designs the query function $q_{i,k}^{(m,\mathcal{R}^{h}_j)}(x)$ using the encoding functions $v_{(i)_{\lambda},k,0}^{(\widetilde{\mathcal{R}}^{h}_j)}(x),v_{(i)_{\lambda},k,1}^{(\widetilde{\mathcal{R}}^{h}_j)}(x),v_{(i)_{\lambda},k,2}^{(\widetilde{\mathcal{R}}^{h}_j)}(x)$
for any $m\in[0:3),i\in\mathcal{R}^{h}_j$, and $k\in[0:2)$, given by
\begin{IEEEeqnarray}{c}
q_{i,k}^{(m,\mathcal{R}^{h}_j)}(x)=
z_{(i)_{\lambda},k,0}^{(m,\widetilde{\mathcal{R}}^{h}_j)}\cdot v_{(i)_{\lambda},k,0}^{(\widetilde{\mathcal{R}}^{h}_j)}(x)+
z_{(i)_{\lambda},k,1}^{(m,\widetilde{\mathcal{R}}^{h}_j)}\cdot v_{(i)_{\lambda},k,1}^{(\widetilde{\mathcal{R}}^{h}_j)}(x)
+\left\{
\begin{array}{@{}l@{\;\;}l}
v_{(i)_{\lambda},k,2}^{(\widetilde{\mathcal{R}}^{h}_j)}(x),
&\mathrm{if}\,\, m=\theta \\
0, & \mathrm{otherwise}
\end{array} \right.. \notag
\end{IEEEeqnarray}
Then, the query sent to the server $n,n\in[0:8)$ for retrieving the partial file $\mathbf{W}^{(\theta)}(\mathcal{R}_j^h,:)$ is given by
\begin{IEEEeqnarray}{c}
\mathcal{Q}_n^{(\theta,{\mathcal{R}}_j^h)}=\left\{q_{i,k}^{(m,\mathcal{R}^{h}_j)}(\alpha_n):m\in[0:3),i\in\mathcal{R}^{h}_j,k\in[0:2)\right\}. \notag
\end{IEEEeqnarray}

%In the query phase of the adaptive PIR scheme,
In order to adaptively retrieve the desired file, 
the user combines the queries across all the columns of the query array in \eqref{Example2:query:array} and sends the following query $\mathcal{Q}^{(\theta)}_n$ to the server $n,n\in[0:8)$: 
\begin{IEEEeqnarray}{c}\label{Example2:query}
\mathcal{Q}_n^{(\theta)}=\left\{
  \begin{array}{@{}lll@{}}
\mathcal{Q}_n^{(\theta,\{0,1,2\})}, & \mathcal{Q}_n^{(\theta,\{3,4,5\})}, & \mathcal{Q}_n^{(\theta,\{6,7,8\})} \\
\mathcal{Q}_n^{(\theta,\{9,10,11\})}, & \mathcal{Q}_n^{(\theta,\{12,13,14\})}, & \mathcal{Q}_n^{(\theta,\{15,16,17\})} \\
\mathcal{Q}_n^{(\theta,\{4,8\})}, & \mathcal{Q}_n^{(\theta,\{0,17\})}, & \mathcal{Q}_n^{(\theta,\{9,13\})} \\
\mathcal{Q}_n^{(\theta,\{7\})}, & \mathcal{Q}_n^{(\theta,\{2\})}, & \mathcal{Q}_n^{(\theta,\{3\})} \\
\mathcal{Q}_n^{(\theta,\{16\})}, & \mathcal{Q}_n^{(\theta,\{11\})}, & \mathcal{Q}_n^{(\theta,\{12\})} \\
\mathcal{Q}_n^{(\theta,\{13\})}, & \mathcal{Q}_n^{(\theta,\{8\})}, & \mathcal{Q}_n^{(\theta,\{0\})}
\end{array}
\right\}.
\end{IEEEeqnarray}
