\begin{algorithm}[httb]
\caption{Construction of Query Array}
\label{Query:array}
\begin{algorithmic}[1] % display linenumber
\REQUIRE System parameters $N,K,X,T$
\ENSURE Query array $\mathbf{U}$ of dimensions $\lambda\times P$ with $\lambda=N-(K+X+T-1)$ and $P=\lambda\cdot\mathrm{lcm}(1,2,\ldots,\lambda)$.
\STATE Let $\mathbf{U}^{0}$ denote a subarray of dimensions $\lambda\times\frac{P}{\lambda}$ and $\mathbf{U}^{h}$ denote another subarray of dimensions $\lambda\times\frac{P}{(\lambda-h)(\lambda-h+1)}$ for all $h\in[1:\lambda)$. Then set  $\mathbf{U}=\big[
  \begin{array}{@{}c;{2pt/2pt}c;{2pt/2pt}c;{2pt/2pt}c@{}}
    \mathbf{U}^{0} & \mathbf{U}^{1} & \cdots & \mathbf{U}^{\lambda-1}  \\
\end{array}
\big]$.
\FORALL{$i\in[0:\lambda ),j\in[0:\frac{P}{\lambda})$}
\STATE $u_{i,j}^{0}=i+j\cdot\lambda$,
\ENDFOR
\FORALL{$h=1,2,\ldots,\lambda-1$}
\FORALL{$i\in[0:\lambda),r\in[0:\lambda),s\in[0:\frac{P}{\lambda(\lambda-h)(\lambda-h+1)})$}
\IF{$r\in[0:h)$}
\STATE $u_{i,(i+r)_{\lambda}+s\cdot\lambda}^{h}=*$,
\ELSE
%\ENDIF
%\IF{$r\in[h:\lambda)$}
\STATE $u_{i,(i+r)_{\lambda}+s\cdot\lambda}^{h}=u_{i,(i+h-1)_{\lambda}+(r-h+s(\lambda-h))\lambda}$,
\ENDIF
\ENDFOR
\ENDFOR
\RETURN Array $\mathbf{U}=\big[
  \begin{array}{@{}c;{2pt/2pt}c;{2pt/2pt}c;{2pt/2pt}c@{}}
    \mathbf{U}^{0} & \mathbf{U}^{1} & \cdots & \mathbf{U}^{\lambda-1}  \\
\end{array}
\big]$.
\end{algorithmic}
\end{algorithm}






