\left\{ \widetilde{\mathcal{A}}_{\Delta}^{(\theta,\mathcal{R})},\widetilde{\mathbf{W}}^{(\theta)}(\mathcal{D},:) \right\}
=\left\{ \widetilde{A}_{n,k}^{(\theta,\mathcal{R})},\widetilde{w}^{(\theta)}_{i,k}:n\in\Delta,k\in[0:2),i\in\mathcal{D} \right\}, 
