For any given $h\in[1:\lambda)$,
\begin{IEEEeqnarray}{rCl}
\bigcup\limits_{j\in[0:\Gamma^h)}\mathcal{R}^h_j&\overset{(a)}{=}&\Big\{u^{h}_{(j-t)_{\lambda},j}:t\in[h:\lambda),j\in[0:\Gamma^h)\Big\} \notag\\
% &=&\Big\{u^{h}_{(j-t)_{\lambda},j}:t\in[h:\lambda),j\in[0:\Gamma^h)\Big\}\bigcup\Big\{u^{h}_{(j-t)_{\lambda},j}:t\in[0:h),j\in[0:\Gamma^h)\Big\}\Big\backslash\Big\{*\Big\} \notag\\
% &=&\Big\{u^{h}_{i,j}:i\in[0:\lambda),j\in[0:\Gamma^{h})\Big\}\backslash\Big\{u_{(j-r)_{\lambda},j}^{h}:r\in[0:h),j\in[0:\Gamma^{h})\Big\}\notag\\
% &\overset{(a)}{=}&\Big\{u^{h}_{i,j}:i\in[0:\lambda),j\in[0:\Gamma^{h})\Big\}\backslash\Big\{u_{i,(i+r)_{\lambda}+s\cdot\lambda}^{h}:i\in[0:\lambda),r\in[0:h),s\in[0:\frac{\Gamma^{h}}{\lambda})\Big\}\notag\\
&\overset{(b)}{=}&\Big\{u^{h}_{i,(i+r)_{\lambda}+s\cdot\lambda}:i\in[0:\lambda),r\in[h:\lambda),s\in[0:\frac{\Gamma^{h}}{\lambda})\Big\} \notag\\
&\overset{(c)}{=}&\Big\{u_{i,(i+h-1)_{\lambda}+s\cdot\lambda}^{h'}:i\in[0:\lambda),s\in[0:\frac{\Gamma^{h'}}{\lambda}),h'\in[0:h)\Big\},\notag
\end{IEEEeqnarray}
% \begin{IEEEeqnarray}{rCl}
% \mathcal{U}^{h}
% %&=&\{u^{h}_{(j-r)_{\lambda},j}:r\in[h:\lambda),j\in[0:\Gamma^{h})\}\\
% &=&\big\{u^{h}_{i,j}:i\in[0:\lambda),j\in[0:\Gamma^{h})\big\}\backslash\big\{u_{(j-r)_{\lambda},j}^{h}:r\in[0:h),j\in[0:\Gamma^{h})\big\}\notag\\
% &\overset{(a)}{=}&\big\{u^{h}_{i,j}:i\in[0:\lambda),j\in[0:\Gamma^{h})\big\}\backslash\big\{u_{i,(i+r)_{\lambda}+s\cdot\lambda}^{h}:i\in[0:\lambda),r\in[0:h),s\in[0:\frac{\Gamma^{h}}{\lambda})\big\}\notag\\
%     &=&\big\{u^{h}_{i,(i+r)_{\lambda}+s\cdot\lambda}:i\in[0:\lambda),r\in[h:\lambda),s\in[0:\frac{\Gamma^{h}}{\lambda})\big\} \notag\\
% &\overset{(b)}{=}&\big\{u_{i,(i+h-1)_{\lambda}+s\cdot\lambda}^{h'}:h'\in[0:h),i\in[0:\lambda),s\in[0:\frac{\Gamma^{h'}}{\lambda})\big\},\notag
% \end{IEEEeqnarray}
where $(a)$ follows from \eqref{Array:integer:element}, $(b)$ is due to the fact that the set
$\{u^{h}_{(j-t)_{\lambda},j}:t\in[0:h),j\in[0:\Gamma^h)\}$
is equivalent to
$\{u^{h}_{i,(i+r)_{\lambda}+s\cdot\lambda}:i\in[0:\lambda),r\in[0:h),s\in[0:\frac{\Gamma^{h}}{\lambda})\}$ by \eqref{U0:cons}-\eqref{array:h:1},
%is similar to \eqref{U0:cons}-\eqref{array:h:1} such that the equations on both sides of $(a)$ are equivalent, 
and $(c)$ follows by \eqref{Proof:C1}.
In other words, for any given $h\in[0:\lambda-1)$ and $r\in[h+1:\lambda)$,
\begin{IEEEeqnarray}{c}
\bigcup\limits_{j\in[0:\Gamma^r)}\mathcal{R}^r_j=\Big\{u_{i,(i+r-1)_{\lambda}+s\cdot\lambda}^{h'}:i\in[0:\lambda),s\in[0:\frac{\Gamma^{h'}}{\lambda}),h'\in[0:r)\Big\}.\notag
\end{IEEEeqnarray}
Then, for any $j\in[0:\Gamma^{h})$ and $r\in[h+1:\lambda)$, the integer element $u^{h}_{(j-r+1)_{\lambda},j}$ in the $j$-th column of the subarray $\mathbf{U}^{h}$ satisfies
\begin{IEEEeqnarray}{c}
u^{h}_{(j-r+1)_{\lambda},j}\in\left\{u_{i,(i+r-1)_{\lambda}+s\cdot\lambda}^{h'}:i=(j-r+1)_{\lambda},s=\big\lfloor \frac{j}{\lambda}\big\rfloor,h'=h\right\}\subseteq\bigcup\limits_{j\in[0:\Gamma^r)}\mathcal{R}^r_j.\notag
\end{IEEEeqnarray}
%where $u^{h}_{(j-r+1)_{\lambda},j}$ is an integer elements in the $j$-th column of the subarray $\mathbf{U}^{h}$ for any $h\in[0:\lambda-1)$ and $j\in[0:\Gamma^h)$ by \eqref{Array:integer:element}. 
This completes the proof of C3.
Consequently, the constructed query array satisfies the conditions C0--C3.

