\subsection{Invariance Properties of CKA}
\label{appendix:CKA}

The Centered Kernel Alignment (CKA) similarity metric exhibits several desirable invariance properties that make it particularly suitable for comparing neural network representations~\cite{DBLP}:

\subsubsection{Scale invariance}
\
We consider the representation matrix of each layer denoted as $O_{e}\in \mathbb{R}^{n\times d}$, where nn is the sequence length and dd is the hidden dimension. Let 
\begin{equation}
	O_{c}^{\left ( l \right )}=\alpha O_{e}^{\left ( l \right )}, \ \ \alpha \in \mathbb{R} 
\end{equation}

This indicates that all sample representations are scaled by a shared constant factor $\alpha$, which is commonly observed in operations such as LayerNorm and residual connections. 

Then,  the kernel matrices can be computed as follows:
\begin{equation} \label{scale}
	\begin{aligned}
		S_{c}=O_{c}O_{c}^{T}=\alpha ^{2}O_{e}O_{e}^{T} =\alpha ^{2}S_{e}
	\end{aligned}
\end{equation}

The following formulation can be derived by combining Eqs.~\ref{HSIC} and ~\ref{scale} :
\begin{equation} \label{scale_kernel}
	\begin{aligned}
	HSIC\left ( S_{e},S_{c}\right ) &=\frac{1}{\left ( N-1 \right )^{2} } tr\left ( H_{N}S_{e}H_{N}\alpha^{2} S_{e} \right ) \\
	&=\alpha ^{2}\cdot HSIC\left ( S_{e},S_{e}\right ) 
	\end{aligned}
\end{equation}

By substituting the above formulation into the normalization Eqs.~\ref{CKA}, we have
\begin{equation}
	\begin{aligned}
		m_{CKA} \left (  S_{e},S_{c}\right ) &=\frac{\alpha ^{2}\cdot HSIC\left ( S_{e},S_{e}\right ) }{\sqrt{ HSIC\left ( S_{e},S_{e}\right )\cdot \alpha^{4} \cdot HSIC\left ( S_{e},S_{e} \right )  } } \\
		&=1
	\end{aligned}
\end{equation}

Hence, we have 
\begin{equation}
	m_{CKA} \left (  O_{e},\alpha O_{e}\right ) = m_{CKA} \left (  O_{e},O_{c}\right ) 
\end{equation}

\subsubsection{Orthogonal invariance}
\
Let the layer representation matrix be $O_{e} \in \mathbb{R}^{n \times d}$. After applying an orthogonal transformation, it becomes:
\begin{equation}\label{Oc}
	O_{c}=O_{e}Q
\end{equation}
where  $Q^{T}Q=I$.

Subsequently, the kernel matrix can be expressed as:
\begin{equation}
	\begin{aligned}
		S_{e}=O_{e}O_{e}^{T} 
	\end{aligned}
\end{equation}

Since orthogonal transformations do not alter the inner product structure between samples, it follows that:
\begin{equation}
	\begin{aligned}
		S_{c}=O_{c}O_{c}^{T}=(O_{e}Q)(O_{e}Q)^{T}=O_{e}QQ^{T}O_{e}^{T}=S
	\end{aligned}
\end{equation}

Finally, it can be verified that
\begin{equation}\label{Ssi}
	\begin{aligned}
	HSIC\left(S_{e}, S_{c}\right)&=HSIC\left(S_{e}, S_{e}\right) \\
	m_{CKA}\left(S_{e}, S_{c}\right)&=1
	\end{aligned}	
\end{equation}

\subsubsection{Permutation invariance}
\
Given a layer representation matrix $O_{e}\in \mathbb{R}^{n\times d}$, after a permutation of the feature dimensions, that is,
\begin{equation}
	O_{c}=O_{e}P
\end{equation}
where $P$ is a permutation matrix.

Accordingly, the kernel matrix can be expressed as
\begin{equation}
	S_{e}=O_{e}O_{e}^{T}
\end{equation}

The permutation matrix satisfies $P^{\top} = P^{-1}$ and $PP^{\top} = I$, thus the inner product remains unchanged, and can be expressed as
\begin{equation}
  S_{c}=O_{c}O_{c}^{T}=(O_{e}P)(O_{e}P)^{T}=O_{e}PP^{T}O_{e}^{T}=S
\end{equation}

Thus, CKA can be defined as
Taking the logarithm of both sides of the above equation yields:
\begin{equation}\label{Ssi}
		m_{CKA}\left(S_{e}, S_{c}\right)=m_{CKA}\left(S_{e}, S_{e}\right)=1
\end{equation}


