\section{Time splitting approximation}\label{SectionFOM}
In this section, we introduce the proposed Full Order Model (FOM) for the incompressible Navier-Stokes Equations (NSE), and describe both its time discretization and the spatial approximation.

We consider the incompressible evolution NSE problem:
\begin{equation}\label{NavierStokesProblem}
\left\{ \begin{array}{rll}
    \bm{u}_t + (\bm{u} \cdot \nabla) \bm{u} - \nu \Delta \bm{u}  + \nabla p  & = \bm{f} & \text{ in } \Omega \times (0,T], \\
    \nabla \cdot \bm{u}  & = 0 & \text{ in } \Omega \times (0,T], \\
    \bm{u} & = \bm{0} & \text{ on } \Gamma_D\times (0,T], \\
    (\nu \nabla \bm{u} - p\bm{I}) \cdot\bm{n} & = \bm{0} & \text{ on } \Gamma_N\times (0,T], \\
    \bm{u}(x,0) & = \bm{u}_0(x) & \text{ in } \Omega,
\end{array} \right.
\end{equation}
where $\Omega \subset \mathbb{R}^{d}, \, d \in \{2,3\},$ is a bounded polyhedral domain with a Lipschitz-continuous boundary $ \Gamma = \partial \Omega = \overline{\Gamma}_D \cup \overline{\Gamma}_N,$ $[0,T]$ the time interval, and $\bm{u}_0(x)$ be the initial condition. In the above equations \eqref{NavierStokesProblem}, $\bm{u}$ is the velocity field, $p$ is the pressure of the incompressible fluid, $\nu > 0$ is the kinematic viscosity, and $\bm{f}$ is the forcing term. For the sake of simplicity, we impose homogeneous Dirichlet boundary conditions on $\Gamma_D $ and do-nothing (open) boundary conditions on $\Gamma_N.$ More general inflow boundary conditions may be taken into account by standard lifting techniques for NSE.

\subsection{Time splitting scheme for open boundary conditions}\label{SectionTimeSplit}

In this section, we describe the time discretization of problem \eqref{NavierStokesProblem} by time splitting scheme that includes a a non-standard pressure-correction scheme for open boundary conditions, already introduced in \cite{MejdiTimeSplit} for a finite volume FOM. We assume that $\Omega$ is a $2D$ channel-like flow, with inflow boundary $\Gamma_D$ and outflow boundary $\Gamma_N.$ This boundary is assumed to be a vertical straight segment of height $2L$ from $x_2 = -L$ to $x_2 = L$. Extension to a more general definition of $\Gamma_N$ can be found in \cite{MejdiTimeSplit}, Section 4.1. This is a  semi-discrete (in time) approximation of \eqref{NavierStokesProblem} that we describe formally, without explicit mention of the regularity needed by the different unknowns that appear in it.\\



Denoting $\bm{u}^n \approx \bm{u}(\cdot,t^n)$ and $p^n \approx p(\cdot,t^n)$ approximations of the solution of \eqref{NavierStokesProblem} at a certain time $t^n = n \Delta t, \,  n \in \{1, \ldots, N\},$ with $\Delta t = {T}/{N},$ The time splitting scheme that we consider in this work operates in two stages. We obtain $\bm{u}^{n+1}$ and $p^{n+1}$ by solving: 

\begin{comment}
\begin{equation}\label{SemiDiscreteNavierStokes}
\left\{ \begin{array}{rll}
    \dfrac{\bm{u}^{n+1} - \bm{u}^n}{\Delta t} + (\bm{u}^n \cdot \nabla) \bm{u}^{n+1} - \nu \Delta \bm{u}^{n+1}  + \nabla p^{n+1}  & = \bm{f}^{n+1} & \text{ in } \Omega, \\
    \nabla \cdot \bm{u}^{n+1}  & = 0 & \text{ in } \Omega, \\
    \bm{u}^{n+1} & = \bm{0} & \text{ on } \Gamma_D, \\
    (\nu \nabla \bm{u}^{n+1} - p^{n+1}\bm{I})\cdot\bm{n} & = \bm{0} & \text{ on } \Gamma_N. \\
\end{array} \right.
\end{equation}
\end{comment}


\noindent \textbf{Step 1.} Convection-diffusion problem:
\emph{find $\bm{\tilde{u}}^{n+1}$ such that} 
\begin{equation}\label{FinalStep1}
    \begin{array}{rll}
        \dfrac{\bm{\tilde{u}}^{n+1}-\bm{u}^n}{\Delta t} + (\bm{u}^{n} \cdot \nabla) \bm{\tilde{u}}^{n+1} - \nu \Delta \bm{\tilde{u}}^{n+1} + \nabla p^n & = \bm{f}^{n+1} & \text{ in } \Omega,  \\
         \bm{\tilde{u}}^{n+1} & = \bm{0} & \text{ on }  \Gamma_D, \\
         (\nu \nabla \bm{\tilde{u}}^{n+1} - p^{n}\bm{I})\cdot\bm{n} & = \bm{0}& \text{ on } \Gamma_N.
\end{array}
\end{equation}

\noindent \textbf{Step 2.} Open boundary pressure BC problem: 
\emph{find $\hat{\phi}^{n+1}$ defined on $\Gamma_N$ such that}
\begin{equation}\label{FinalStep1.5}
\left \{\begin{array}{rll}
    \left( \Delta t \partial_{x_2}^2 - \dfrac{1}{\nu}\right)  \hat{\phi}^{n+1} & = \nabla \cdot \bm{\tilde{u}}^{n+1} & \text{ on } \Gamma_N, \\
    \partial_{\bm{n}} \hat{\phi}^{n+1}(\pm L) & = 0.&  \\
\end{array} \right. 
\end{equation}

\noindent \textbf{Step 3.} Pressure-continuity correction problem: 
\emph{find $\phi^{n+1}$ such that }
\begin{equation}\label{FinalStep2}
    \begin{array}{rll}
        \Delta t \Delta \phi^{n+1}  & = \nabla \cdot \bm{\tilde{u}}^{n+1} & \text{ in } \Omega,  \\
        \partial_{\bm{n}} \phi^{n+1} & = 0 & \text{ on } \Gamma_D, \\
        \phi^{n+1} & = \hat{\phi}^{n+1} & \text{ on } \Gamma_N.
    \end{array}
\end{equation}


\medskip

\noindent \textbf{Step 4.} Updating velocity and pressure problem: 
\emph{find $\bm{u}^{n+1}$ and $p^{n+1}$ such that}
\begin{equation}\label{FinalStep3pres}
    p^{n+1} = p^{n} + \phi^{n+1} \text{ in } \Omega,
\end{equation}
\begin{equation}\label{FinalStep3vel}
\bm{u}^{n+1} = \bm{\tilde{u}}^{n+1} - \Delta t \nabla \phi^{n+1} \text{ in } \Omega.
\end{equation}



\begin{comment}
\noindent \textbf{Step 1.} Convection-diffusion problem:  
\emph{find $\bm{\tilde{u}}^{n+1}$ such that} 
\begin{equation}\label{Step1}
    \begin{array}{rll}
        \dfrac{\bm{\tilde{u}}^{n+1}-\bm{u}^n}{\Delta t} + (\bm{u}^{n} \cdot \nabla) \bm{\tilde{u}}^{n+1} - \nu \Delta \bm{\tilde{u}}^{n+1} + \nabla p^n & = \bm{f}^{n+1} & \text{ in } \Omega,  \\
         \bm{\tilde{u}}^{n+1} & = \bm{0} & \text{ on }  \Gamma_D, \\
         (\nu \nabla \bm{\tilde{u}}^{n+1} - p^{n}\bm{I})\cdot\bm{n} & = \bm{0}& \text{ on } \Gamma_N.
\end{array}
\end{equation}

\medskip 

\noindent\textbf{Step 2.} Pressure-continuity correction problem: 
\emph{find $(\bm{u}^{n+1},\phi^{n+1})$ such that }
\begin{equation}\label{Step2}
\begin{array}{rrl}
     \dfrac{1}{\Delta t} (\bm{u}^{n+1}-\bm{\tilde{u}}^{n+1}) + \nabla \phi^{n+1}& = \bm{0} & \text{  in } \Omega, \\
      \nabla \cdot \bm{u}^{n+1} &= 0 & \text{ in } \Omega, \\
      \bm{u}^{n+1} \cdot \bm{n} & = 0 & \text{ on } \Gamma_D, \\
     & \text{Suitable }B.C.^{n+1}  & \text{ on } \Gamma_N,
\end{array}
\end{equation}
and the  pressure is updated via: $p^{n+1} = \phi^{n+1} + p^n$ in $\Omega,$ where the Boundary Condition (BC) on $\Gamma_N$ are determined below. \newline
Note that Step 2 implies that $\phi^{n+1}$ satisfies the following Poisson problem: \emph{find $\phi^{n+1}$ such that }
\begin{equation}\label{Step2Correct}
    \begin{array}{rll}
        \Delta t \Delta \phi^{n+1}  & = \nabla \cdot \bm{\tilde{u}}^{n+1} & \text{ in } \Omega,  \\
        \partial_{\bm{n}} \phi^{n+1} & = 0 & \text{ on } \Gamma_D, \\
       & \text{Suitable }BC^{n+1}  & \text{ on } \Gamma_N,
    \end{array}
\end{equation}
completed by the final step:

\medskip 

\noindent\textbf{Step 3. } Updating velocity and pressure problems: 
\emph{find $\bm{u}^{n+1}$ and $p^{n+1}$ such that}
\begin{eqnarray}
p^{n+1} &=& p^{n} + \phi^{n+1} \text{ in } \Omega,\\
\bm{u}^{n+1} &=& \bm{\tilde{u}}^{n+1} - \Delta t \nabla \phi^{n+1} \text{ in } \Omega.
\end{eqnarray}

\end{comment}

\subsubsection*{Pressure outflow boundary conditions}
The boundary condition for
$\phi^{n+1}$ on $\Gamma_N$ is deduced in \cite{MejdiTimeSplit} by derivation of the Helmholtz-Hodge decomposition of
$\tilde{u}^{n+1}$ in \eqref{FinalStep2}, as also used \cite{jin1993nonreflecting,kirkpatrick2008open}  for other kinds of outlet boundary conditions
(non-reflecting or Neumann). As mentioned in \cite{guermond}, the natural choice to impose $\phi^{n+1}$ = 0 on $\Gamma_N$ would lead to numerical issues, as it constrains the pressure increment and can
prevent its proper evolution near the boundary. The extension to boundaries $\Gamma_N$ with non-zero curvatures can be found in Section $4.1$ of \cite{MejdiTimeSplit}.

\begin{comment}
The main objective in \cite{MejdiTimeSplit} has been the derivation of the pressure boundary condition on $\Gamma_N$ in \eqref{Step2Correct}. As mentioned in \cite{guermond}, the natural choice to impose $\phi^{n+1}=0$ on $\Gamma_N$ would lead to numerical issues, as it constrains the pressure increment and can prevent its proper evolution near the boundary. Hence, the boundary condition for $\phi$ on $\Gamma_N$ is induced  in \cite{MejdiTimeSplit} by derivation of the Helmholtz-Hodge decomposition of $\bm{\tilde{u}}^{n+1}$ in \eqref{Step2}, as also used in \cite{jin1993nonreflecting,kirkpatrick2008open} for other kinds of outlet boundary conditions (non-reflecting or Neumann). Following \cite{MejdiTimeSplit}, assuming for simplicity $\Omega$ as a $2D$ channel and fixing $\Gamma_N$ at its right boundary of height $2L,$ the $BC^{n+1}$ on $\Gamma_N$ in \eqref{Step2Correct} is found as the solution of the following $1D$ problem: 

\emph{find $\hat{\phi}^{n+1}$ defined on $\Gamma_N$ such that}
\begin{equation}\label{1Dproblem}
\left \{\begin{array}{rll}
    \left( \Delta t \partial_{x_2}^2 - \dfrac{1}{\nu}\right)  \hat{\phi}^{n+1} & = \nabla \cdot \bm{\tilde{u}}^{n+1} & \text{ on } \Gamma_N, \\
    \partial_{\bm{n}} \hat{\phi}^{n+1}(\pm L) & = 0,&  \\
\end{array} \right. 
\end{equation}
where $\pm L$ are the limits of the outflow boundary along the $x_2$ (vertical)-direction. The solution $\hat{\phi}^{n+1}$ of \eqref{1Dproblem} gives the non-homogeneous Dirichlet boundary condition to be imposed in \eqref{Step2Correct} on $\Gamma_N,$ i.e. $\phi^{n+1} = \hat{\phi}^{n+1}$ on $\Gamma_N$. The extension to boundaries $\Gamma_N$ with non-zero curvatures can be found in Section $4.1$ of \cite{MejdiTimeSplit}.\\
\end{comment}

\subsection{FE space approximation}\label{FETimeSplit}
In this section, we state the variational formulation of the considered time-splitting method and its Finite Element (FE) discretization. This will be the FOM to solve NSE \eqref{NavierStokesProblem} that we consider in this paper.

Let us consider the following spaces: 
\begin{itemize}
\item $ \bm{H}^1_D(\Omega) = \{ \bm{\tilde{v}} \in \bm{H}^1(\Omega) : \bm{\tilde{v}} = \bm{0} \text{ on } \Gamma_D \}.$
   \item $ \bm{H}(div,\Omega) =  \{ \bm{v} \in \bm{L}^2(\Omega) : \, \nabla \cdot \bm{v} \in L^2(\Omega),\bm{v}\cdot\bm{n}=0 \text{ on } \Gamma_D \}. \, $
   \item $H^1_N(\Omega) = \{ q \in H^1(\Omega) : q = 0 \text{ on } \Gamma_N \}.$
\end{itemize}

The variational formulation of the FOM scheme described in Section \ref{SectionTimeSplit} reads:

\noindent \textbf{Step 1.} Prediction-diffusion problem:  \emph{given $\bm{u}^n \in \bm{H}(div,\Omega), p^n \in L^2(\Omega)$ and $\bm{f}^{n+1} \in \bm{H}^{-1},$ find $\bm{\tilde{u}}^{n+1} \in \bm{H}^1_D(\Omega)$ such that, for all $\bm{\tilde{v}} \in \bm{H}^1_D(\Omega) $}
\begin{equation}\label{Step1FV}
        \dfrac{1}{\Delta t}(\bm{\tilde{u}}^{n+1}-\bm{u}^n,\bm{\tilde{v}}) + (\bm{u}^{n}\cdot\nabla\bm{\tilde{u}}^{n+1},\bm{v}) + \nu (\nabla \bm{\tilde{u}}^{n+1}, \bm{\tilde{v}}) - (p^n,\nabla \cdot \bm{\tilde{u}}^{n+1}) = \langle \bm{f}^{n+1},\bm{\tilde{v}} \rangle.
\end{equation}

\noindent \textbf{Step 2.} Open Boundary pressure BC problem:  
\emph{find $\hat{\phi}^{n+1} \in H^1(\Gamma_N)$ such that} 
\begin{equation}\label{Step15FV}
\nu \Delta t(\partial_{x_2} \hat{\phi}^{n+1},\partial_{x_2}\hat{q})_{\Gamma_N} + (\hat{\phi}^{n+1},\hat{q})_{\Gamma_N} = -\nu (\nabla \cdot \bm{\tilde{u}}^{n+1},\hat{q})_{\Gamma_N} \hspace{0.5cm} \forall \hat{q} \in H^1(\Gamma_N).
\end{equation}


\noindent  \textbf{Step 3.} Pressure-continuity correction problem: \emph{find $\phi^{n+1} \in H^1_N(\Omega)$ such that}
\begin{equation}\label{Step2FV}
    (\nabla \phi^{n+1}, \nabla \tilde{q}) = -\dfrac{1}{\Delta t} (\nabla \cdot \bm{\tilde{u}}^{n+1},\tilde{q}) - (\nabla \tilde{\phi}^{n+1}, \nabla \tilde{q}) \hspace{0.5cm} \forall \tilde{q} \in H^1_N(\Omega),
\end{equation}
where $\tilde{\phi}^{n+1} \in H^1(\Omega)$ is an extension of the solution of \eqref{Step15FV} to $\Omega,$ then  $\phi^{n+1}$ verifies homogeneous Dirichlet boundary condition in $\Gamma_{N}.$\\

\noindent \textbf{Step 4. } Updating velocity and pressure problem:  
\emph{find $p^{n+1} \in L^2(\Omega)$ such that}
\begin{equation}\label{Step3PresFV}
    p^{n+1} = p^n + \overline{\phi}^{n+1},
\end{equation}
\emph{and $\bm{u}^{n+1} \in  \bm{H}(div,\Omega)$ such that}
\begin{equation}\label{Step3VelFV}
    (\bm{u}^{n+1},\bm{v}) = (\bm{\tilde{u}}^{n+1},\bm{v}) - \Delta t(\nabla \overline{\phi}^{n+1},\bm{v}), \hspace{0.5cm} \forall \bm{v} \in \bm{H}(div,\Omega), 
\end{equation}
where $\overline{\phi}^{n+1} = \phi^{n+1} + \tilde{\phi}^{n+1}.$ 

\begin{comment}

In order to give a FE approximation of \eqref{Step1FV}-\eqref{Step3VelFV}, let $\{\mathcal{T}_h\}_{h>0}$ be a family of affine-equivalent, conforming (i.e., without hanging nodes) and regular triangulations of $\overline{\Omega},$ formed by triangles or quadrilaterals $(d=2),$ tetrahedra or hexahedra $(d=3).$ For any mesh cell $K \in \mathcal{T}_h,$ the diameter will be denoted by $h_K$ and $h = \max_{K \in \mathcal{T}_h} h_K.$ We consider suitable F.E. spaces $\bm{X}_h \subset \bm{H}(div,\Omega), \bm{\tilde{X}}_h \subset \bm{H}^1_D(\Omega), \tilde{Q}_h \subset H^1_N(\Omega), \hat{Q}_h \subset H^1(\Gamma_N), Q_h \subset L^2(\Omega),$ to approximate the unknown fields and functions.\\

Following the previous presentation,  the FE approximation can be written step by step as follows:\\


\noindent \textbf{Step 1.} Prediction-diffusion FE approximation:  \emph{given $\bm{u}^n_h \in \bm{X}_h$ and $p_h^n \in Q_h,$ find $\bm{\tilde{u}}^{n+1}_h \in \bm{\tilde{X}}_h$ such that, for all $\bm{\tilde{v}}_h \in \bm{\tilde{X}}_h$ }
\begin{equation}\label{Step1FE}
        \dfrac{1}{\Delta t}(\bm{\tilde{u}}^{n+1}_h-\bm{u}^n,\bm{\tilde{v}}_h) + b(\bm{u}^{n}_h,\bm{\tilde{u}}^{n+1}_h,\bm{v}_h) + \nu (\nabla \bm{\tilde{u}}^{n+1}_h, \bm{\tilde{v}}_h) - (p^n_h,\nabla \cdot \bm{\tilde{u}}_h) = \langle \bm{f},\bm{\tilde{v}}_h \rangle .
\end{equation}
\textbf{Step 2} Open Boundary pressure BC FE approximation:  
\emph{find $\hat{\phi}^{n+1}_h \in \hat{Q}_h$ such that} 
\begin{equation}\label{Step15FE}
\nu \Delta t(\partial_{x_2} \hat{\phi}^{n+1}_h,\partial_{x_2}\hat{q}_h)_{\Gamma_N} + (\hat{\phi}^{n+1}_h,\hat{q}_h)_{\Gamma_N} = -\nu (\nabla \cdot \bm{\tilde{u}}_h,\hat{q}_h)_{\Gamma_N} \hspace{0.5cm} \forall \hat{q}_h \in \hat{Q}_h.
\end{equation}
\textbf{Step 3.} Pressure-continuity correction FE approximation: 
\emph{find $\phi^{n+1}_h \in \tilde{Q}_h$ such that}
\begin{equation}\label{Step2FE}
    (\nabla \phi^{n+1}_h, \nabla \tilde{q}_h) = -\dfrac{1}{\Delta t} (\nabla \cdot \bm{\tilde{u}}^{n+1}_h,\tilde{q}_h) - (\nabla \tilde{\phi}^{n+1}_h, \nabla \tilde{q}_h) \hspace{0.5cm} \forall \tilde{q}_h \in \tilde{Q}_h,
\end{equation}
where $\tilde{\phi}^{n+1}_h$ is a FE approximation of $\tilde{\phi}^{n+1}$ in \eqref{Step2FV}. \newline
\textbf{Step 4. } Updating velocity and pressure FE approximation: 
\emph{find $p^{n+1}_h \in Q_h$ such that}
\begin{equation}\label{Step3PresFE}
    (p^{n+1}_h,q_h) = (\phi^{*}_h,q_h) + (p^n_h,q_h) \hspace{0.5cm} \forall q_h \in Q_h
\end{equation}
\newline
\emph{and  $\bm{u}_h^{n+1} \in  \bm{X}_h$ such that}
\begin{equation}\label{Step3VelFE}
    (\bm{u}^{n+1}_h,\bm{v}_h) = (\bm{\tilde{u}}^{n+1}_h,\bm{v}_h) - \Delta t(\nabla \phi^{*}_h,\bm{v}_h) \hspace{0.5cm} \forall \bm{v}_h \in \bm{X}_h,
\end{equation}
where $\phi^*_h = \phi^{n+1}_h + \tilde{\phi}^{n+1}_h.$
\end{comment}

To derive a FE approximation of the variational scheme \eqref{Step1FV}-\eqref{Step3VelFV}, we apply a Galerkin projection onto a suitable finite-dimensional subspaces of the corresponding functional spaces,
\begin{equation}\label{FES}
    \bm{X}_h \subset \bm{H}(div,\Omega), \hspace{0.25cm} \bm{\tilde{X}}_h \subset \bm{H}^1_D(\Omega),  \hspace{0.25cm} \tilde{Q}_h \subset H^1_N(\Omega), \hspace{0.25cm} \hat{Q}_h \subset H^1(\Gamma_N),\hspace{0.25cm}  Q_h \subset L^2(\Omega).
\end{equation}

The fully discrete scheme is then obtained by seeking, at each time step, the approximate solutions $\bm{u}_h^{n+1}, \bm{\tilde{u}}_h^{n+1}, p_h^{n+1},\phi^{n+1}_h$ and $\hat{\phi}^{n+1}_h$ in the above FE spaces that satisfy the weak formulation \eqref{Step1FV}--\eqref{Step3VelFV} in a Galerkin sense. For brevity we do not make explicit this discretization as it is straighforward. It follows by changing every space in \eqref{Step1FV}-\eqref{Step3VelFV} by its discrete counterpart, following \eqref{FES}.


\section{POD-ROM method}\label{ROMtimesplit}

In this section, we present the POD-ROM approximation to the fully discrete time-splitting method  introduced in Section \ref{SectionFOM}.
\begin{comment}
First, we briefly review the POD method \cite{kunisch2001galerkin}, which we use to construct the ROM. POD provides a low-dimensional, orthonormal basis that represents a given dataset in an optimal least-squares sense. The most common variant is the ''method of snapshots'',  which has been successfully applied across various fields, including pattern recognition, structural mechanics, and geophysical fluid dynamics.\\ 

A key requirement for a computationally efficient ROM is the complete separation of offline and online phases. In the offline phase, the computationally expensive FOM is solved to construct the necessary POD bases and corresponding matrices. In the online phase, the ROM is efficiently solved for the desired parameter of interest at a significantly reduced computational cost. \\
In the following, we describe the application of these phases to the fully discrete FOM introduced in Section \eqref{SectionFOM}. 
In particular, we compare a standard POD-ROM, which is fully projection-based (intrusive) at every step, with a hybrid POD-ROM. The hybrid approach combines projection-based (intrusive) methods for Steps 1 and 3—computation of the predicted velocity and updating of velocity and pressure—with data-driven (non-intrusive) techniques for Steps 1.5 and 2—computation of the pressure-continuity correction boundary condition and pressure-continuity correction. Actually, for the hybrid POD-ROM, we will consider a data-driven interpolation technique by means of Radial Basis Functions (RBF) \cite{giovanni-gianluigi} to approximate $\phi^{n+1}$ and $\hat{\phi}^{n+1}$. In this way, we get a generic and flexible formulation that does not strictly depend on the specifi model emplyed at the full order level to compute the pressure, which is usually preferable for industrial engineering applications that uses black-box commercial codes.\\ 
\end{comment}

We describe the offline phase for the standard POD-ROM projection-based method and then, the online phase. 

\subsection{Offline Phase}\label{OfflinePhase}
We start from the solution of the FOM problem, that provides snapshots for velocity $\{ \bm{u}_h^{t_i} \}_{i=1}^N,$ predicted velocity $\{ \bm{\tilde{u}}_h^{t_i} \}_{i=1}^N,$ pressure $\{p_h^{t_i} \}_{i=1}^N,$ pressure-continuity correction $\{ \phi_{h}^{t_i}\}_{i=1}^N$ and outflow pressure BC $\{ \hat{\phi}_{h}^{t_i}\}_{i=1}^N.$
\begin{comment}
    By solving the FOM problem, we get the following set of snapshots:
\begin{itemize}
    \item $S_{\bm{u}} = \{\bm{u}_h^{t_1}, \ldots, \bm{u}^{t_{N}}_h\}\,\, \text{(Velocity snapshots)}$
    \item $S_{\bm{\tilde{u}}} = \{\bm{\tilde{u}}_h^{t_1}, \ldots, \bm{\tilde{u}}^{t_{N}}_h\}\,\, \text{(Predicted velocity snapshots)}$
    \item $S_p =  \{p^{t_1}_h, \ldots, p^{t_{N}}_h\}\,\, \text{(Pressure snapshots)}$
    \item $S_{\phi} =  \{\phi^{t_1}_h, \ldots, \phi^{t_{N}}_h\}\,\, \text{(Pressure-continuity correction snapshots)}$
    \item $S_{\hat{\phi}} =  \{\hat{\phi}^{t_1}_h, \ldots, \hat{\phi}^{t_{N}}_h\}\,\, \text{(Outflow pressure BC snapshots)}$
\end{itemize}

\end{comment}

%\subsubsection{POD bases construction}\label{PODprocess}

The POD method constructs low-dimensional spaces to approximate each variable of the scheme, whose bases we respectively denoted as $\{\bm{\varphi}_1, \ldots, \bm{\varphi}_{r_{\bm{u}}}  \},$ $ \{ \bm{\tilde{\varphi}}_1, \ldots, \bm{\tilde{\varphi}}_{r_{\bm{\tilde{u}}}} \},$ $\{ \psi_1, \ldots, \psi_{r_p} \}, $ $\{ \gamma_1, \ldots, \gamma_{r_{\phi}}\} $ and $\{ \hat{\gamma}_1, \ldots, \hat{\gamma}_{r_{\hat{\phi}}}\}$. These spaces are designed to optimally approximate the given snapshots sets in a least-squares sense with respect to Hilbertian norms \cite{kunisch2001galerkin}. In what follows, we consider POD spaces computed using $L^2$ scalar products for velocity and predicted velocity fields, while pressure spaces are constructed using $H^1$   scalar products to account for their inherent continuity and smoothness requirements. We assume that the selected POD basis retains a high percentage of the total energy carried by the initial snapshots. We thus consider the following  reduced spaces for the POD setting: 

\begin{comment}
Now, we are going to describe briefly how to build the POD basis. First, by solving the Finite Element of the scheme described in Section \ref{FETimeSplit}, we consider the FE solution $(\tilde{u}^i_h,\phi^{i}_h,u^i_h,p^i_h), \, t_0 \leq i \leq t_{M-1},$ so the  snapshots from the velocity field, intermediate velocity field, pressure and $\phi$ are:
\begin{equation*}
    S_u = \text{span} \{u_h^{t_0},u^{t_1}_h, \ldots, u^{t_{M-1}}_h\},
\end{equation*}
\begin{equation*}
    S_{\tilde{u}} = \text{span} \{\tilde{u}_h^{t_0},\tilde{u}^{t_1}_h, \ldots, \tilde{u}^{t_{M-1}}_h\},
\end{equation*}
\begin{equation*}
    S_p = \text{span} \{p_h^{t_0},p^{t_1}_h, \ldots, p^{t_{M-1}}_h\},
\end{equation*}
\begin{equation*}
    S_{\phi} =\text{span}  \{\phi_h^{t_0},\phi^{t_1}_h, \ldots, \phi^{t_{M-1}}_h\}.
\end{equation*}
Once we collect the snapshots for all the fields, we can build the POD basis.
\begin{nota}
The procedure to obtain the POD basis is done only by the velocity field, because is the same procces for the rest of POD basis and it is not neccesary to include all of them. 
\end{nota}
The POD method, as we mentioned before, seeks low-dimensional basis $ \mathcal{U}_r = \text{ span } \{\varphi_1, \ldots, \varphi_{r_u}\}$ for velocity in a real Hilbert Space $\mathcal{H}_u$. This low-dimensional basis that we call $\mathcal{U}$, approximate the snapshots in the following optimal sense: 

\begin{equation}\label{minPOD}
\min \Delta t \sum_{m=1}^M \| u_h^m - \sum_{i=1}^{r_u} (u_h^n,\varphi_i)_{\mathcal{H}_u} \varphi_i \|^2_{\mathcal{H}_u}
\end{equation}

where $(\varphi_i,\varphi_j) = \delta_{ij} \, 1\leq i,j\leq r_u,$ where $\delta_{ij}$ is the Kronecker delta. Now, in order to solve the \eqref{minPOD}, we can consider as an eigenvalues problem: 
\begin{equation*}
K^u a_i = \lambda_i a_i, \, \text{ for } 1,\ldots,r_u,
\end{equation*}
where $K^u \in \mathbb{R}^{M\times M}$ is the velocity correlation matrix, with the following entries: 
\begin{equation*}
    K^u_{ij} = (u_h^i,u_h^j)_{\mathcal{H}_u}, \, \text{ for } 1\leq i,j\leq M.
\end{equation*}

The vectors $a_i$ are the eigenvectors and $\lambda_i$ are the eigenvalues asociated. These eigenvalues are positive and sorted in descendir order as: $\lambda_1 \geq \cdots \geq \lambda_{r_u} \geq 0.$
Thanks to this eigenvalues problem, it can be show that the solution of the optimization problem \eqref{minPOD} is:
\begin{equation}
    \varphi_i = \dfrac{1}{\sigma_i}\sqrt{\Delta t} \sum_{m=1}^M (a_i)_m u_h^m, \, \text{ for } i = 1,\ldots,r_u,
\end{equation}
where $\sigma_i$ is the singular value of $\lambda_i$ and $(a_i)_m$ is the m-th component of the eigenvector $a_i.$

\begin{nota}
We remark that $\mathcal{H}_u$ it can be any real Hilbert space, but in our case we are going to take $\mathcal{H}_u = L^2$ for simplicity. 
\end{nota}
\end{comment}



\begin{itemize}
    \item $\bm{\mathcal{U}}_{r_{\bm{u}}} = \text{ span } \{\bm{\varphi}_1, \ldots, \bm{\varphi}_{r_{\bm{u}}}  \}$ \,\,(reduced velocity  space)
    \item $\bm{\tilde{\mathcal{U}}}_{r_{\bm{\tilde{u}}}} = \text{ span } \{ \bm{\tilde{\varphi}}_1, \ldots, \bm{\tilde{\varphi}}_{r_{\bm{\tilde{u}}}} \}$ \,\,(reduced predicted velocity  space)
    \item $\mathcal{Q}_{r_p} = \text{ span } \{ \psi_1, \ldots, \psi_{r_p} \},$ \,\,(reduced pressure  space)
    \item $\tilde{\mathcal{Q}}_{r_\phi} = \text{ span } \{ \gamma_1, \ldots, \gamma_{r_{\phi}} \}$ \,\,(reduced pressure-continuity correction  space)
    \item  $\hat{\mathcal{Q}}_{r_{\hat{\phi}}} = \text{ span } \{ \hat{\gamma}_1, \ldots, \hat{\gamma}_{r_{\hat{\phi}}} \}$\,\, (reduced pressure-continuity correction boundary  space)
\end{itemize}

\subsection{Online Phase }

\begin{comment}
 The Standard Galekin projection-based POD-ROM uses both Galerkin truncation and Galerkin projection. The former yields an approximation of the unknown fields by a linear combination of the corresponding truncated POD basis: 

\end{comment}

In this section, we propose a ROM approximation of the FE approximation of the splitting method \eqref{Step1FV}-\eqref{Step3PresFV} using Galerkin projection. We approximate the FE solution $(\bm{\tilde{u}}_h^{n+1}, \hat{\phi}_h^{n+1}, \phi_h^{n+1}, \bm{u}_h^{n+1}, p_h^{n+1})$  by its reduced-order counterpart $(\bm{\tilde{u}}_r^{n+1}, \hat{\phi}_r^{n+1}, \phi_r^{n+1}, $ $ \bm{u}_r^{n+1}, p_r^{n+1})$ by 
\begin{equation}
    \bm{u}(x,t) \approx \bm{u}_{r_{\bm{u}}}(x,t) = \sum_{i=1}^{r_{\bm{u}}} a_i(t) \bm{\varphi}_i(x) \in \bm{\mathcal{U}}_{r_{\bm{u}}},
\end{equation}

\begin{equation} 
    \bm{\tilde{u}}(x,t) \approx \bm{\tilde{u}}_{r_{\bm{\tilde{u}}}} (x,t) 
    = \sum_{i=1}^{r_{\bm{\tilde{u}}}} \tilde{a}_i(t)\bm{\tilde{\varphi}}_i(x) \in \bm{\tilde{\mathcal{U}}}_{r_{\bm{\tilde{u}}}},
\end{equation}

\begin{equation}
    p(x,t) \approx p_{r_p}(x,t) = \sum_{i=1}^{r_p} b_i(t)\psi_i(x) \in \mathcal{Q}_{r_{p}},
\end{equation}

\begin{equation}
    \phi(x,t) \approx \phi_{r_\phi}(x,t) = \sum_{i=1}^{r_\phi} c_i(t)\gamma_i(x) \in \tilde{\mathcal{Q}}_{r_{\phi}},
\end{equation}

\begin{equation}
    \hat{\phi}(x,t) \approx \hat{\phi}_{r_{\hat{\phi}}}(x,t) = \sum_{i=1}^{r_{\hat{\phi}}} \hat{c}_i(t)\hat{\gamma}_i(x) \in \hat{\mathcal{Q}}_{r_{\hat{\phi}}},
\end{equation}

\noindent where $\{a_i(t)\}_{i=1}^{r_u},\{\tilde{a}_i(t)\}_{i=1}^{r_{\tilde{u}}}, \{b_i(t)\}_{i=1}^{r_p} $, $\{c_i(t)\}_{i=1}^{r_{\phi}}$ and $\{\hat{c}_i(t)\}_{i=1}^{r_{\hat{\phi}}} $are the sought time-varying coefficients for each field, respectively. Note that the dimension of the corresponding vectors is much smaller than the number of degrees of freedom in a full order simulation.

Projecting the equations of the FOM splitting method \eqref{Step1FV}-\eqref{Step3VelFV} onto their respective POD spaces and assuming that we know an approximation of the velocity $\bm{u}_h$ and the pressure $p_h$ at time $t=t_1,$ the fully discrete space-time formulation of the Galerkin POD-ROM is derived as follows:\\

\noindent \textbf{Step 0.} Initialization. 
\begin{itemize}
    \item  $\bm{u}^1_r = \sum_{i=1}^{r_{\bm{u}}} (u^{t_1}_h,\bm{\varphi_i})\bm{\varphi}_i,$
    \item $p^1_r = \sum_{i=1}^{r_p} (p^{t_1}_h,\psi_i)\psi_i.$
\end{itemize}

For $n=1,\ldots,N:$ \\

\noindent \textbf{Step 1.} Prediction-diffusion reduced order problem:  
given $\bm{u}_n^r \in \bm{\mathcal{U}}_{r_u}$ and $p_r^n \in \mathcal{Q}_{r_p}$, find $\bm{\tilde{u}}_r^{n+1} \in \bm{\tilde{\mathcal{U}}}_{r_{\tilde{u}}}$ such that, for all $  \bm{\tilde{\varphi}} \in \bm{\tilde{\mathcal{U}}}_{r_{\bm{u}}}$
\begin{equation}\label{ROMStep1}
    \begin{array}{rl}
        (\dfrac{\bm{\tilde{u}}_r^{n+1}-\bm{u}_r^n}{\Delta t},\bm{\tilde{\varphi}}) + (\bm{u}_r^n \cdot \nabla \bm{\tilde{u}}^{n+1}_r,\bm{\tilde{\varphi}})  + \nu (\nabla \bm{\tilde{u}}_r^{n+1}, \nabla \bm{\tilde{\varphi}}) - (p_r^n, \nabla \cdot \bm{\tilde{\varphi}}) & = \langle \bm{f}^{n+1},\bm{\tilde{\varphi}} \rangle.  \\
    \end{array}
\end{equation}

\noindent \textbf{Step 2.} Open Boundary pressure BC reduced order problem:  
given $\bm{\tilde{u}}_r^{n+1} \in \bm{\tilde{\mathcal{U}}}_{r_{\tilde{u}}}, $ find $\hat{\phi}_r^{n+1} \in \hat{\mathcal{Q}}_{r_{\hat{\phi}}}$ such that
\begin{equation}\label{ROMStep15}
\nu \Delta t(\partial_{x_2} \hat{\phi}^{n+1}_r,\partial_{x_2}\hat{\gamma})_{\Gamma_N} + (\hat{\phi}^{n+1}_r,\hat{\gamma})_{\Gamma_N} = -\nu (\nabla \cdot \bm{\tilde{u}}_r,\hat{\gamma})_{\Gamma_N} \hspace{0.5cm} \forall \hat{\gamma} \in \hat{\mathcal{Q}}_{r_{\hat{\phi}}}.
\end{equation}


\noindent \textbf{Step 3.} Pressure-continuity correction reduced order problem: 
given $\bm{\tilde{u}}_r^{n+1} \in \bm{\tilde{\mathcal{U}}}_{r_{\tilde{u}}}$ and $\hat{\phi}_r^{n+1} \in \hat{\mathcal{Q}}_{r_{\hat{\phi}}},$ find $\phi_r^{n+1} \in \tilde{\mathcal{Q}}_{r_{\phi}}$ such that
\begin{equation}\label{ROMStep2}
    (\nabla \phi^{n+1}_r, \nabla \gamma) = -\dfrac{1}{\Delta t} (\nabla \cdot \bm{\tilde{u}}^{n+1}_r,\gamma) - (\nabla \tilde{\phi}^{n+1}_r, \nabla \tilde{q}_h) \hspace{0.5cm} \forall \gamma \in \tilde{\mathcal{Q}}_{r_{\gamma}},
\end{equation}
where $\tilde{\phi}^{n+1}_r$ is the extension (constant with respect $y$) of the solution of \eqref{ROMStep15} to the full domain.\\


\noindent \textbf{Step 4.} Updating pressure and velocity   reduced order problem: 
 given $p^n_r \in \mathcal{Q}_{r_p},$ $\phi^{n+1}_r \in \tilde{\mathcal{Q}}_{r_{\phi}}$ and $ \tilde{\phi}_r^{n+1} \in \hat{\mathcal{Q}}_{r_{\hat{\phi}}},$ find $p_r^{n+1} \in \mathcal{Q}_{r_p}$ such that 
\begin{equation}\label{ROMStep3Pres}
    \begin{array}{rl}
         (p^{n+1}_r, \psi) & = (p^n_r,\psi) + (\overline{\phi}^{n+1}_r,\psi)\quad  \forall \psi \in \mathcal{Q}_{r_p}.  
    \end{array}
\end{equation}
And given $\bm{\tilde{u}}^n_r \in \bm{\tilde{\mathcal{U}}}_{r_{\tilde{u}}}$, $\phi^{n+1}_r \in \tilde{\mathcal{Q}}_{r_{\phi}} $ and $\tilde{\phi}_r^{n+1} \in \hat{\mathcal{Q}}_{r_{\hat{\phi}}}$, find $\bm{u}_r^{n+1} \in \bm{\mathcal{U}}_{r_{\bm{u}}}$ such that:
\begin{equation}\label{ROMStep3Vel}
    \begin{array}{rl}
         (\bm{u}^{n+1}_r,\bm{\varphi}) & = (\bm{\tilde{u}}^{n+1}_r,\bm{\varphi}) - \Delta t (\nabla \overline{\phi}^{n+1}_r, \bm{\varphi}) \quad\forall \bm{\varphi} \in \bm{\mathcal{U}}_{r_{\bm{u}}}, 
    \end{array}
\end{equation}
where $\overline{\phi}^{n+1}_r = \phi^{n+1}_r + \tilde{\phi}_r^{n+1}.$

\begin{comment}
\medskip

The POD-ROM \eqref{ROMStep1} - \eqref{ROMStep3Vel} yields the following reduced autonomous dynamical systems for the unknown vectors of time coefficients:\\


\noindent \textbf{Step 0.} Initialization: 
\begin{itemize}
    \item $a_i^1 = (\bm{u}^{t_1}_h,\bm{\varphi}_i) \hspace{0.5cm} i = 1,\ldots,r_{\bm{u}},$
\item $b_i^1 = (p^{t_1}_h,\psi_i) \hspace{0.5cm}\, i = 1,\ldots,r_{p}.$
\end{itemize}

\noindent \textbf{Step 1.} Prediction-diffusion reduced autonomous dynamical system: compute  the vector of time coefficient $\bm{\tilde{a}}(t)$
\begin{equation}\label{CoefROM1}
(\dfrac{1}{\Delta t}\tilde{M} + \nu \tilde{S} + (\bm{a}^{n})^T\tilde{D})\bm{\tilde{a}}^{n+1} = \dfrac{1}{\Delta t}\tilde{M}\bm{a}^{n} + Bb^{n},
\end{equation}
where the terms in \eqref{CoefROM1} are evaluated by: 
\begin{equation}\label{MatrixStep1}
    \begin{array}{rll}
        \tilde{M}_{ji} & = (\bm{\tilde{\varphi}}_i,\bm{\tilde{\varphi}}_j) & \text{for } i,j = 1,\ldots, r_{\bm{\tilde{u}}},\\
        \tilde{S}_{ji} & =  (\nabla \bm{\tilde{\varphi}}_i, \nabla \bm{\tilde{\varphi}}_j) &\text{for } i,j = 1,\ldots, r_{\bm{\tilde{u}}}, \\
        \tilde{D}_{kji} & = (\varphi_k \cdot \nabla \tilde{\varphi}_i,\tilde{\varphi}_j) & \text{for } i,j = 1,\ldots, r_{\bm{\tilde{u}}} \text{ and } k = 1,\ldots,r_{\bm{u}}, \\
        B_{ji} & = (\psi_i,\nabla \cdot \tilde{\varphi}_j) & \text{for } i = 1,\ldots,r_p \text{ and } j = 1,\ldots,r_{\bm{\tilde{u}}}, 
    \end{array}
\end{equation}
where $\tilde{M}$ is the matrix associated to the velocity and corrected velocity, $\tilde{S}$ is the stiffness matrix, $\tilde{D}$ is the trilinear tensor corresponding to the convective term and $B$ is the matrix associated to the pressure term.\\

\noindent \textbf{Step 1.5.} Pressure-continuity correction boundary reduced autonomous dynamical system : compute  the vector of time coefficient $\bm{\hat{c}}(t):$
\begin{equation}\label{CoefROM15}
        (\dfrac{1}{\nu}\hat{P} + \Delta t \hat{S}) \bm{\hat{c}}^{n+1} = \hat{R} \bm{\tilde{a}}^{n+1},
\end{equation}
where the terms in \eqref{CoefROM15} are evaluated by:
\begin{equation}\label{MatrixStep15}
    \begin{array}{rll}
        \hat{P}_{ji}  & = (\hat{\gamma}_i,\hat{\gamma}_j)_{\Gamma_N} & \text{for } i,j = 1,\ldots,r_{\hat{\phi}},  \\
        \hat{S}_{ji}  & = (\nabla \hat{\gamma}_i, \nabla \hat{\gamma}_j)_{\Gamma_N} & \text{for } i,j = 1,\ldots,r_{\hat{\phi}},  \\
        \hat{R}_{ji}  & = (\hat{\gamma}_i, \nabla \cdot \bm{\tilde{\varphi}}_j)_{\Gamma_N} & \text{for } i =  1,\ldots,r_{\hat{\phi}} \text{ and } j = 1, \ldots, r_{\bm{\tilde{u}}},  
    \end{array}
\end{equation}
where $\hat{P}$ is the mass matrix associated to the pressure-continuity correction boundary, $\hat{S}$ is the stiffnes matrix and $\hat{R}$ the matrix associated to the corrected velocity term. \\

\noindent \textbf{Step 2.} Pressure-continuity correction reduced autonomus dynamical system: compute the vector of time coefficient $\bm{c}(t):$
\begin{equation}\label{CoefROM2}
        \tilde{S}\bm{c}^{n+1} = \dfrac{-1}{\Delta t}\tilde{R} \bm{\tilde{a}}^{n+1} - \tilde{P}\bm{\hat{c}}^{n+1},
\end{equation}
where the terms in \eqref{CoefROM2} are evaluated by:
\begin{equation}\label{MatrixStep2}
    \begin{array}{rll}
        \tilde{S}_{ji}  & = (\nabla {\gamma}_i, \nabla {\gamma}_j) & \text{for } i,j = 1,\ldots,r_{{\phi}},  \\
        \tilde{R}_{ji}  & = (\gamma_i, \nabla \cdot \bm{\tilde{\varphi}}_j) & \text{for } i =  1,\ldots,r_{{\phi}} \text{ and } j = 1, \ldots, r_{\bm{\tilde{u}}},  \\
        \tilde{P}_{ji}  & = (\nabla {\gamma}_i, \nabla {\tilde{\gamma}}_j) & \text{for } i =  1,\ldots,r_{{\phi}} \text{ and } j = 1,\ldots,r_{{\hat{\phi}}},  
    \end{array}
\end{equation}
where $\tilde{\gamma}$ is the extension (by constant) of the pressure-continuity correction POD space. Moreover, $\tilde{S}$ is the stiffness matrix associated to the pressure-continuity correction, $\tilde{R}$ the matrix associated to the corrected velocity term and $\tilde{P}$ is the stiffness matrix associated to the pressure diference and pressure diference boundary term. \\ 



\noindent \textbf{Step 3.} Updating velocity and pressure autonomous dynamical system: compute  the vector of time coefficient $\bm{b}(t):$
\begin{equation}\label{CoefROM3Pres}
    P\bm{b}^{n+1} = P\bm{b}^n + Q\bm{c}^{n+1} + \tilde{Q}\bm{\hat{c}}^{n+1},
\end{equation}
where the terms in \eqref{CoefROM3Pres} are evaluated by:
\begin{equation}\label{MatrixStep3Pres}
    \begin{array}{rll}
        P_{ji}  & = (\psi_i,\psi_j) & \text{for } i,j = 1,\ldots,r_p,  \\
        Q_{ji} &  = (\gamma_i,\psi_j). & \text{for } i = 1,\ldots,r_{\phi} \text{ and } j = 1,\ldots,r_p, \\
        \tilde{Q}_{ji} &  = (\tilde{\gamma}_i,\psi_j). & \text{for } i = 1,\ldots,r_{\hat{\phi}} \text{ and } j = 1,\ldots,r_p,
    \end{array}
\end{equation}
where $P$ is the mass matrix, $Q$ is the matrix associated to the difference pressure term and $\tilde{Q}$ is the matrix associated to the difference pressure boundary term. \newline
For the vector of time coefficient $\bm{a}(t):$
\begin{equation}\label{CoefROM3Vel}
    M\bm{a}^{n+1} = \hat{M}\bm{\tilde{a}}^{n+1} - \Delta t Y \bm{c}^{n+1} - \Delta t \tilde{Y} \bm{\hat{c}}^{n+1},
\end{equation}
where the terms in \eqref{CoefROM3Vel} are evaluated by:
\begin{equation}\label{MatrixStep3Vel}
\begin{array}{rll}
    M_{ji} & = (\bm{\varphi_i},\bm{\varphi_j}) & \text{for } i,j = 1,\ldots, r_{\bm{u}},   \\
    \hat{M}_{ji} & = (\bm{\tilde{\varphi}}_i,\bm{\varphi}_j) & \text{for } i=1,\ldots,r_{\bm{\tilde{u}}} \text{ and } j = 1,\ldots,r_{\bm{u}}, \\
    Y_{ji} & = (\nabla \gamma_i,\bm{\varphi}_j) & \text{for } i = 1,\ldots,r_{\phi} \text{ and } j = 1,\ldots,r_{\bm{u}}, \\
    \tilde{Y}_{ji} & = (\nabla \tilde{\gamma}_i,\bm{\varphi}_j) & \text{for } i = 1,\ldots,r_{\hat{\phi}} \text{ and } j = 1,\ldots,r_{\bm{u}}.
\end{array}    
\end{equation}
In  \eqref{MatrixStep3Vel}, $M$ is the mass matrix, $\tilde{M}$ is the matrix associated to the velocity and corrected velocity, $Y$ is the matrix associated to the difference pressure term and $\tilde{Y}$ is the matrix associated to the difference pressure boundary term.

    If we use the $L^2$ inner product to construct the POD bases, as we have done, the mass matrix is the identity. Moreover, the matrix associated to the velocity and corrected velocity is approximate the mass matrix because the corrected velocity converges to the velocity.
\end{comment}

\medskip 

Note that all the involved matrices corresponding to the reduced problems are   precomputed during the offline stage. 

