\section{Problem Formulation}
\label{sec: formulation}
This section presents our problem formulation and some preliminary background knowledge in network coding.

\subsection{System Model}\label{sec: sub-sysmodel}
\begin{figure}[tbp]
        \centering
        \includegraphics[width=0.4\linewidth]{Ring-SysModel2.pdf}
        %\includegraphics[width=0.5\linewidth]{fig/Ring-SysModel2.pdf}
        \caption{Ring network with $\sN$ nodes, computation load $r=1$ and broadcast distance $d=2$.}
        \label{fig: sysmodel}
\end{figure}
% The problem is motivated by a distributed computing framework over a communication network of ring topology.
Consider a ring network where $\sN\in\mathbb{N}^{+}$ nodes are placed at equal distances on a circle, and each node can successfully broadcast information to some other nodes within a certain distance along the ring.\footnote{We refer to the sending method of nodes as \emph{broadcasting} following \cite{fragouli2008efficient}. However, only a subset of nodes in the network can receive the signals directly transmitted by a given node.} Specifically, the \emph{broadcast distance} $d$ means that each node $n_i$ can broadcast its message to $2d$ neighboring nodes: $\{n_{i-d}, n_{i-d+1}, \ldots, n_{i-1}, n_{i+1}, \ldots, n_{i+d-1}, n_{i+d}\}_{\bmod \sN}$. %Specifically, for node $i$, its broadcast message can be received by $2d$ nodes $\{n_{i-d}, n_{i-d+1}, \ldots, n_{i-1}, n_{i+1}, \ldots, n_{i+d-1}, n_{i+d}\}_{\bmod \sN}$, where we say the \emph{broadcast distance} of node $i$ is $d\in\mathbb{N}$.
For example, as shown in Fig.~\ref{fig: sysmodel}, the messages broadcast by node $n_4$ can be successfully received by nodes $\{n_2,n_3,n_5,n_6\}$ when the broadcast distance is $d=2$.  Since $d\geq \lfloor\frac{\sN}{2}\rfloor$ implies full connection topology, we mainly focus on $d\in\{1,\ldots,\lfloor\frac{\sN}{2}\rfloor\}$. 

The $\sN$ nodes are assigned some computing tasks over $\sN$ input files $w_1, \ldots, w_{\sN}\in\mathbb{F}_q^{\sF}$ for some $\sF\in\mathbb{N}^{+}$, where $\mathbb{F}_q$ denotes a finite field of order $q$. Each node $n_k$ initially caches a set of the files $\cM_k\subseteq\{w_1,\ldots,w_\sN\}$. We assume that each input file is at least cached by one node, i.e., $\bigcup\limits_{k=1,\ldots, \sN}\cM_k= \{w_1,\ldots, w_\sN\}$. Node $n_k$ first locally computes the functions that map the files in the set $\cM_k$ into some  IVs, then exchanges IVs with neighboring nodes to compute its output function.  
We define the computation load as follows.
\begin{definition}[\emph{Computation Load}]
        Define the \emph{computation load}, denoted by $r$, $1\leq r\leq \sN$, as the total number of input files initially stored by the $\sN$ nodes, normalized by the number of input file $\sN$, i.e., $r=\frac{\sum_{i=1}^{\sN}|\cM_i|}{\sN}$. The computation load $r$ can be interpreted as the average number of nodes that map each input file.
\end{definition}


Suppose the network is clocked during the exchanging of IVs, i.e., a universal clock ticks $\sTe$ times.
As shown in Fig.~\ref{fig: allgather and all2all}, we consider the two computing scenarios: 1) all-gather computing and 2) all-to-all computing, where the goals in the two scenarios are decomposed as follows:

\subsubsection{All-Gather}
Each file $w_i$, $i\in[\sN]$ is first mapped into IVs
$$V_i = g_{1,i}(w_i),$$ 
where $g_{1,i}$ is a map function $\mathbb{F}_q^{\sF}\to \mathbb{F}_q^{\sB_{1}}$ for file $w_i$.
After clock tick $t-1$ and before clock tick $t$ for $t=1, \ldots, \sTe$,
node $n_k$ creates a coding symbol $X_k^{(t)} \in\mathbb{F}_{q}^{l_k^{(t)}}$, for some $l_k^{(t)}\in\mathbb{N}$, as a function of IVs computed locally and the received messages from pastime clock $Y_k^{(t-1)}, \ldots, Y_k^{(1)}$, i.e.,
% \begin{align}\label{eq: EncXi_s}
%         X_k^{(t)} = \phi_{s,k}^{(t)}\left( \{g^{1}_i: w_i\in\cM_k \}, \{Y_k^{(t-1)}, \ldots, Y_k^{(1)}\}\right),
% \end{align}
\begin{align}\label{eq: EncXi_s}
        X_k^{(t)} = \phi_{1,k}^{(t)}\left( \left( V_i: w_i \!\in\! \cM_k \right), \left( Y_k^{(t-1)}\!\!, \ldots, Y_k^{(1)} \right) \right),
\end{align}
where $\phi_{1,k}^{(t)}$ is an encoding function and $Y_k^{(i)}$ is the collection of messages received by node $n_k$ at clock $i\in[t-1]$. Having generated the messages $X_k^{(t)}$, node $n_k$ broadcasts them and nodes located within the broadcast distance, i.e., nodes in $\{n_{k-d}, n_{k-d+1}, \ldots, n_{k-1}, n_{k+1}, \ldots, n_{k+d-1}, n_{k+d}\}_{\bmod \sN}$ receive $X_k^{(t)}$ at clock tick $t$.
By the end of the clock tick $\sTe$, node $n_k\in[\sN]$ uses the received messages $\left(Y_k^{(1)}, \ldots, Y_k^{(\sTe)}\right)$ and the IVs computed locally to construct the desired IVs, i.e., 
\begin{align}\label{eq: Dec-alltoall}
        \!\!\!(V_1, \ldots, V_\sN) \!=\! \psi_{1,k} \!\left(\! \left(V_i\!:\! w_i\in\cM_k \right)\!,\!  \left(Y_k^{(1)}, \ldots, Y_k^{(\sTe)}\right) \!\right),
\end{align}  
where $\psi_{1,k}$ is an appropriate decoding function at node $n_k$. 
Finally, the node $n_k$ is responsible for computing output function $h_{1,k}$, which take all IVs as inputs, i.e., 
\begin{align*}
        D_{1,k} = h_{1,k}(V_1, \ldots, V_\sN), \qquad k\in[\sN].
\end{align*}

\subsubsection{All-to-All}
Each file $w_i$, $i\in[\sN]$ is first mapped into IVs 
$$(v_i^1, \ldots, v_i^{\sN}) = g_{2,i}(w_i),$$
where $g_{2, i}$ is a map function $\mathbb{F}_q^{\sF}\to (\mathbb{F}_q^{\sB_{2}})^{\sN}$ for file $w_i$.\footnote{We can think of $V_i$, $v_i^j$, $\forall i,j\in[\sN]$ as symbols, or as packets of symbols of the same size, with the operation applied to each packet being symbol-wise. In the following, we will use the terms 'symbol' and 'packet' interchangeably. }
The transmission process of IVs for all-to-all computing is similar to all-gather computing, while the communication messages, desired IVs, and output functions of the nodes are replaced by the following.
Node $n_k$ generates the message 
\begin{align}\label{eq: EncXi_m}
       \!\!\!\! X_k^{(t)}\! = \phi_{2,k}^{(t)}\left( \!\left(v^{j}_i\!:\! j\!\in\![\sN], w_i\!\in\!\cM_k \right), \left(Y_i^{(t\!-\!1)}, \ldots, Y_i^{(1)}\right)\!\right),
\end{align}
and desires the IVs
\begin{align}\label{eq: Dec-allunicast}
        &(v^k_1, \ldots, v^k_\sN)  = \psi_{2,k}\! \left(\left(v^{j}_i: j\!\in\![\sN], w_i\in\cM_k \right)\!, \left(Y_k^{(1)}, \ldots, Y_k^{(\sTe)}\right) \right).
\end{align} 
Finally, node $n_k$ is responsible for computing output function $h_{2,k}$, which take specific IVs as inputs, i.e., 
\begin{align*}
        D_{2,k} = h_{2,k}(v_1^{k}, \ldots, v_{\sN}^{k}), \qquad k\in[\sN].
\end{align*}

