%     \end{array} \right. 
% \end{align}
% {\red SEE MY PREVIOUS COMMENTS ON Y}
The packets $v_{i-j}^{i}$ and $v_{i+r+j-1}^{i}$ finally reach their destined node $n_i$ and are successfully decoded. In this scheme, $\sTe = \lceil\frac{\sN-r}{2}\rceil$ round of transmissions are required, with $j$ steps in $j^{\textnormal{th}}$ round. Therefore, we can calculate the NCL as 
\begin{align}
        \sT_{\tn{2-cyc}}(r,1) &= \left(1 + 2 + \ldots + \Big\lceil\frac{\sN-r}{2}\Big\rceil \right)\cdot \frac{\sN\sB_{2}}{\sN\sB_{2}} \nonumber\\
        % &= O\left(\frac{(\sN-r)^2}{8}+\frac{\sN-r}{4}\right). \label{eq: T(r,1)}
        &= O\left(\frac{\sN}{4}(\frac{\sN}{2}\!\!-\!\!r) \!+\! \frac{(\sN-r)}{4}\!+\! \frac{r^2}{8}\right). \label{eq: T(r,1)}
        % \frac{\sN}{4}(\frac{\sN}{2}\!\!-\!\!r) \!+\! \frac{(\sN-r)}{4}\!+\! \frac{r^2}{8}
\end{align}
