    \section{A Lower Bound on NCL for all-gather Computing}
    % \subsection{Proof of the lower bound in Theorem \ref{Theo: aa_uplow}}
    \label{sec: sub-prof_sintasks_lb}
    The main idea follows Lemma 1 in \cite{fragouli2008efficient}. For each IV, there are $\sN-r$ receivers to cover, and it can reach $2d$ receivers through one broadcast transmission. Formally, we have the information-theoretic representation as follows.
        From \eqref{eq: Dec-alltoall} we have 
        \begin{align}
                H\left(\left( V_1,\ldots,V_{\sN}\right) \Big| \cM_i, \left(Y_{i}^{(1)},\ldots,Y_{i}^{(\sT^{e})}\right)\right) = 0.
        \end{align}
        From the definition of mutual information, we have
        \begin{align}
                H\left(V_1,\ldots,V_{\sN}\right)  &= I\left( \left(V_1,\ldots,V_{\sN}\right) ; \cM_i, \left( Y_{i}^{(1)},\ldots,Y_{i}^{(\sT^{e})}\right)\right) \nonumber\\
                &= H\left( \cM_i, \left(Y_{i}^{(1)},\ldots,Y_{i}^{(\sT^{e})}\right) \right) - H\left( \cM_i, \left(Y_{i}^{(1)},\ldots,Y_{i}^{(\sT^{e})}\right) \Big| \left(V_1,\ldots,V_{\sN}\right)\right) \nonumber\\
                &\leq H\left(\cM_i\right) + H\left( Y_{i}^{(1)},\ldots,Y_{i}^{(\sT^{e})} \right)
        \end{align}
        Then, we have
        \begin{align}\label{eq: entropyY}
               %&\lefteqn{H\left( \{Y_{i}^{(1)},\ldots,Y_{i}^{(\sT^{e})}\} \right) } \nonumber\\
                H\left( Y_{i}^{(1)},\ldots,Y_{i}^{(\sT^{e})} \right) &\geq H\left( V_1,\ldots,V_{\sN} \right) - H\left(\cM_i\right) \nonumber \\
                & = (\sN-|\cM_i|)\sB_{1}
        \end{align}
        Besides, 
        \begin{align}\label{eq: bitsY}
                H\left( Y_{i}^{(1)},\ldots,Y_{i}^{(\sT^{e})} \right) \leq \sum_{t=1}^{\sT^{e}}\sum_{k=i-d}^{i+d}l_{k}^{(t)}
        \end{align}
        Combining \eqref{eq: entropyY} and \eqref{eq: bitsY}, we have
        \begin{align}
                \sum_{t=1}^{\sT^{e}}\sum_{k=i-d}^{i+d}l_{k}^{(t)} \geq (\sN-|\cM_i|)\sB_{1}
        \end{align}
        Summing up the above inequality over $i\in \{1,\ldots,\sN\}$, we obtain
        \begin{align}
                \sum_{i=1}^{\sN}\sum_{t=1}^{\sT^{e}}\sum_{k=i-d}^{i+d}l_{k}^{(t)} \geq (\sN^2-\sum_{i=1}^{\sN}|\cM_i|)\sB_{1},
        \end{align} 
        i.e., 
        \begin{align}
                2d\sum_{t=1}^{\sT^{e}}\sum_{k=1}^{\sN}l_{k}^{(t)} \geq \sN(\sN-r)\sB_{1}.
        \end{align}
        Then it is readily shown that 
        \begin{align}
                \frac{\sum_{t=1}^{\sT^{e}}\sum_{k=1}^{\sN}l_{k}^{(t)}}{\sN\sB_{1}} \geq \frac{\sN-r}{2d}.
        \end{align}
        This completes the proof.

