            \cM_{\cal R} = \{v_i^j: i\in{\cal M}_k, k\in{\cal R}, j\in[\sN]\},
    \end{align} 
    and denote $\{X_{k-d}^{\sTe}, \ldots, X_{k}^{\sTe}\}$ and $\{X_{j-d}^{\sTe}, \ldots, X_{j}^{\sTe}\}$ as $X_{kd}^{\sTe}$ and $X_{jd}^{\sTe}$, respectively.
