    We have the following relations
    \begin{align}
        % \lefteqn{H(V_{\cal L}^{\cal R})}
        H(V_{\cal L}^{\cal R}) &= H(V_{\cal L}^{\cal R}| {\cal M}_{\cal R}) \label{eq: ConP-inde}\\
        &= I(X_{kd}^{\sTe}, X_{jd}^{\sTe}; V_{\cal L}^{\cal R}| {\cal M}_{\cal R}) + H( V_{\cal L}^{\cal R}| X_k^{\sTe}, X_j^{\sTe}, {\cal M}_{\cal R} ) \label{eq: ConP-DeMI}\\
        &= I(X_{kd}^{\sTe}, X_{jd}^{\sTe}; V_{\cal L}^{\cal R}| {\cal M}_{\cal R}) + \sTe\epsilon_{\sTe} \label{eq: ConP-Fano}\\
        &= H(X_{kd}^{\sTe}, X_{jd}^{\sTe}|{\cal M}_{\cal R} ) - H(X_{kd}^{\sTe}, X_{jd}^{\sTe}|V_{\cal L}^{\cal R}, {\cal M}_{\cal R} ) + \sTe\epsilon_{\sTe} \nonumber \\
        &\leq H(X_{kd}^{\sTe}, X_{jd}^{\sTe} ) + \sTe\epsilon_{\sTe} \\
        &= \sum_{i=1}^{d}\sum_{t=1}^{\sTe}(l_{k+1-i}^{(t)} + l_{j+1-i}^{(t)}) + \sTe\epsilon_{\sTe},
    \end{align}
    where \eqref{eq: ConP-inde} holds because of the independence between packets, \eqref{eq: ConP-DeMI} follows the definition of the mutual information, $\epsilon_\sTe$ is a function vanishing as $\sTe\to\infty$,  \eqref{eq: ConP-Fano} comes from that $H( V_{\cal L}^{\cal R}| Y_{\cal R}^{\sTe}, {\cal M}_{\cal R} ) = \sTe\epsilon_{\sTe}$ holds because of Fano's inequality and $Y_{\cal R}^{\sTe}$ are functions of $(X_{kd}^{\sTe}, X_{jd}^{\sTe}, {\cal M}_{\cal R})$.
    Besides, 
    \begin{align}
            H(V_{\cal L}^{\cal R}) = \sum_{t=1}^{|{\cal L}|} \sum_{k\in{\cal R}} a_{t, {\cal L}}^{\{k\}} \sB_{2},
    \end{align}
    which implies that 
    \begin{align}
            \sum_{i=1}^{d}\sum_{t=1}^{\sTe}(l_{k+1-i}^{(t)} + l_{j+1-i}^{(t)}) \geq \sum_{t=1}^{|{\cal L}|} \sum_{k\in{\cal R}} a_{t, {\cal L}}^{\{k\}}\sB_{2} - \sTe\epsilon_{\sTe} \label{eq: ConP-lgeqa}.
    \end{align}

    Taking the partitions $\{{\cal L}, {\cal R}\}$ as the original version, which is referred to as $\{{\cal L}_1, {\cal R}_1\}$, we can generate the new cut by moving some nodes. We move the node $n_{k+1}$ from ${\cal R}_1$ to ${\cal L}_1$, and the node $n_{j}$ from ${\cal L}_1$ to ${\cal R}_1$,  leading to the new cut $\{{\cal L}_2, {\cal R}_2\}$.
    %For each partition ${\cal L}$ and ${\cal R}$, we can replace the node $n_i$ with $n_{i+1}$ for $i\in[\sN]$, which provides %a new partition ${\cal L}'$ and ${\cal R}'$. 
    There are $\sN$ cuts like this, and the above arguments hold for every new cut. Summing up the \eqref{eq: ConP-lgeqa} over all these cuts, we have 
    \begin{align}
            2d \sum_{i=1}^{\sN} \sum_{t=1}^{\sTe} l_i^{(t)}/\sB_{2} \geq \sum_{i=1}^{\sN} \sum_{t=1}^{|{\cal L}_i|} \sum_{k\in{\cal R}_i} a_{t, {\cal L}_i}^{\{k\}} - \epsilon^{\prime}, \label{eq: ConP-nlgeqa}
    \end{align}
    where $|{\cal L}_1| = \ldots = |{\cal L}_{\sN}|$ and $\epsilon^{\prime}$ is a function vanishing as $\sTe\to\infty$.
    Note that \eqref{eq: ConP-nlgeqa} holds for $({\cal L}_1, {\cal R}_1, \ldots, {\cal L}_{\sN}, {\cal R}_{\sN})$ of arbitrary size $|{\cal L}_1| = |{\cal L}|$. Recall that $a_{t, {\cal L}_i}^{\{k\}}$ denotes the number of the IVs that are exclusively cached by $t$ nodes in set ${\cal L}_i$ and intended for node $n_k$.
    Among these IVs, define the number of IVs that cached by nodes in set ${\cal G}$ of size $|{\cal G}|=t$ as $b_{{\cal G}, {\cal L}_i}$, which implies that $\sum_{\substack{ {\cal G}\subseteq {\cal L}_i \\ |{\cal G}|=t}} b_{{\cal G}, {\cal L}_i}= a_{t, {\cal L}_i}^{\{k\}}$.
    %Define $ b_{{\cal G}, {\cal L}_i}= a_{t, {\cal L}_i}^{\{k\}}$ with $|{\cal G}|=t$, which does not depend on the index $\{k\}$. 
    We have
    \begin{align}
            \sum_{i}^{\sN} \sum_{t=1}^{\sTe} l_i^{(t)}/\sB_{2} + \frac{\epsilon'}{2d} &\geq \frac{1}{2d}\cdot\max_{|{\cal L}|} \left\{ \sum_{i}^{\sN} \sum_{t=1}^{|{\cal L}|} \sum_{k\in{\cal R}_i} a_{t, {\cal L}_i}^{\{k\}} \right\} \nonumber\\
            &\geq \frac{1}{2d}\sum_{i}^{\sN} \sum_{t=1}^{|{\cal L}|=\frac{\sN}{2}} |{\cal R}_i| a_{t, {\cal L}_i}^{\{k\}} \\
            &= \frac{\sN}{4d}\sum_{i}^{\sN} \sum_{t=1}^{|{\cal L}|=\frac{\sN}{2}} a_{t, {\cal L}_i}^{\{k\}} \\
            &= \frac{\sN}{4d}\sum_{i}^{\sN} \sum_{t=1}^{|{\cal L}|=\frac{\sN}{2}} \sum_{\substack{ {\cal G}\subseteq {\cal L}_i \\ |{\cal G}|=t}} b_{{\cal G}, {\cal L}_i}
            % &= \frac{\sN}{4d}\sum_{i}^{\sN} a_{t=r, {\cal L}_i}^{\{k\}} (cyclic)\\
            % &= \frac{\sN}{4d}\sum_{i=1}^{\sN}\sum_{g\subseteq {\cal L}_i} b_{{\cal G}, {\cal L}_i}.
    \end{align}
    For the cyclic placement, 
    \begin{align}
            \sum_{t=1}^{|{\cal L}|=\frac{\sN}{2}} \sum_{\substack{ {\cal G}\subseteq {\cal L}_i \\ |{\cal G}|=t}} b_{{\cal G}, {\cal L}_i} = \sum_{\substack{ {\cal G}\subseteq {\cal L}_i \\ |{\cal G}|=r}} b_{{\cal G}, {\cal L}_i} = \frac{\sN}{2}-r+1
    \end{align}
    when $r< \frac{\sN}{2}$,
    which implies that
    \begin{align}
            % (\text{Cyclic placement }r<\frac{\sN}{2})&\nonumber\\ 
            \sum_{i}^{\sN} \sum_{t=1}^{\sTe} l_i^{(t)} / (\sN\sB_{2}) &\geq \frac{\sN}{4d} (\frac{\sN}{2}-r+1) - \epsilon' \nonumber\\
            &=\frac{(\sN-r)^2}{8d}+ \frac{\sN-\frac{r^2}{2}}{4d}- \epsilon'.
    \end{align}
    This completes the proof.

     \section{ The optimal NCL for All-to-all When $r\geq \frac{\sN}{2}$ and $d=1$}\label{sec: allunicast-arb}
    If the file placement can be arbitrarily designed, the optimal NCL can be achieved when $r\geq \lceil\frac{\sN}{2}\rceil$ and $d=1$ as:
    \begin{align}
        %     \sT_{2}(r,1) = \left\lceil \frac{\sN-r}{2} \right\rceil.
            \sT_{2}(r,1) = \frac{\sN-r}{2} .
    \end{align}
    For integer-valued computation load $r\in \{\lceil\frac{\sN}{2}\rceil, \ldots, \sN\}$, a file placement of the node $n_i$ as 
    \begin{align}
            \cM_i =& \{w_{i+4(t-1)}: t\in[\lceil\frac{\sN}{4}\rceil]\} \nonumber\\
            &\cup \{w_{i+1+4(t-1)}: t\in[\min((r-\lceil\frac{\sN}{4}\rceil),\lceil\frac{\sN}{4}\rceil)]\} \nonumber\\
            &\cup \{w_{i+2+4(t-1)}: t\in[\min((r-\lceil\frac{\sN}{2}\rceil),\lceil\frac{\sN}{4}\rceil)]\} \nonumber\\
            &\cup \{w_{i+3+4(t-1)}: t\in[r-\lceil\frac{3\sN}{4}\rceil]\},
    \end{align}
    achieve the NCL of $\left\lceil \frac{\sN-r}{2} \right\rceil.$ 
   % For general $r\geq \lceil\frac{\sN}{2}\rceil$, the lower convex envelop of the achievable points $\{(r, \sT_{2}(r,1)): \frac{\sN-r}{2}\in\mathbb{N}^{+}\}$ is achievable using the memory sharing approach discussed in Section \ref{sec: all-to-alls_general}.
    The proposed transmission strategy for the problem is straightforward. We provide an example to illustrate it. 
    The file placement for $\sN=8$, $r=4$ is shown as Table~\ref{tab:arbseg-N8r4d1}. The symbol $*$ at the row $n_i$ and column $w_j$ where $i\in[8]$ and $j\in[8]$ means that the node $n_i$ compute the IVs from $w_j$. Node $n_i$ broadcast $X_{i}^{(1)} = v_i^{i+1}\oplus v_{i+1}^{i-1}$ and $X_{i}^{(2)} = v_{i+4}^{i+1} \oplus v_{i+5}^{i-1}$. For example, node $n_4$ broadcasts
        $$ X_{4}^{(1)} = v_4^{5}\oplus v_{5}^{3} \text{ and } X_{4}^{(2)} = v_{8}^{5} \oplus v_{1}^{3},$$ 
    and receives 
        \begin{align*}
            Y_4^{(1)}  = \left(
                    X_{3}^{(1)} = v_{3}^{4} \oplus v_{4}^{2},
                    X_{5}^{(1)} = v_{5}^{6} \oplus v_{6}^{4} \right)  
                \text{ and } Y_4^{(2)} = \left( X_{3}^{(2)} = v_{7}^{4} \oplus v_{8}^{2} 
                    X_{5}^{(2)} = v_{1}^{6} \oplus v_{2}^{4}\right) . 
    \end{align*}
    We can observe that node $n_4$ can get desired packets $\{v_3^4, v_7^4\}$ and $\{v_6^4, v_2^4\}$ from nodes $n_3$ and $n_5$, respectively. The other nodes can similarly obtain desired packets. It is clear that the NCL is $\sT_{2}(4,1) = 2 =\left\lceil \frac{8-4}{2} \right\rceil$.
