    The proof of the lower bound is presented as follows.
    From the definition of the mutual information and Fano's inequality, we have
        \begin{align}
                H(v_{[\sN]}^{i} | {\cal M}_i) &= I(v_{[\sN]}^{i}; Y_{i}^{\sTe}|{\cal M}_i) + H(_{[\sN]}^{i}, Y_{i}^{\sTe} | {\cal M}_i) \nonumber \\
                &= H( Y_{i}^{\sTe}|{\cal M}_i) - H( Y_{i}^{\sTe}|v_{[\sN]}^{i}, {\cal M}_i) + \sTe\epsilon_{\sTe}\nonumber\\
                &\leq H(Y_{i}^{\sTe}),
        \end{align}
        where $\epsilon_{\sTe}$ vanishes as $\sTe\to\infty$. This implies that
        \begin{align}
                H(Y_{i}^{\sTe}) &\geq H(v_{[\sN]}^{i} | {\cal M}_i) - \sTe\epsilon_{\sTe} \nonumber\\
                & = (\sN-|{\cal M}_i|)\sB_{2} - \sTe\epsilon_{\sTe}.
        \end{align}
        Summing the above inequality over all $i\in[\sN]$ yields
        \begin{align}
                2\sum_{i}^{\sN} \sum_{t=1}^{\sTe} l_i^{(t)}
                &= \sum_{i=1}^{\sN} H(Y_{i}^{\sTe}) \nonumber\\
                &\geq \sum_{i=1}^{\sN} (\sN-|{\cal M}_i|)\sB_{2} - \epsilon' \nonumber\\
                & = \sN(\sN-r)\sB_{2}- \epsilon',
        \end{align}
        i.e., 
        \begin{align}
                \sT^{\star}_{2}(r,1) = \sum_{i}^{\sN} \sum_{t=1}^{\sTe} l_i^{(t)} / (\sN\sB_{2}) &\geq \frac{\sN-r}{2} - \epsilon',
        \end{align}
        where $\epsilon_{\prime}$ vanishes as $\sTe\to\infty$.
        This completes the proof.

